// ══════════════════════════════════════════════════════════════════════
// ── SMART ICON SYSTEM ─────────────────────────────────────────────────
// wi(lucideName, emoji, size?, color?)
// Renders SVG icon on desktop, emoji on mobile (hover:none / touch).
// Usage: wi('home', '🏠') → dual-mode icon HTML string
// ══════════════════════════════════════════════════════════════════════
const _isMobile = (()=>{
  const coarse = window.matchMedia('(hover: none) and (pointer: coarse)').matches;
  const narrow = window.matchMedia('(max-width: 480px)').matches;
  return coarse || narrow;
})();

function wi(lucideName, emoji, size=16, color='currentColor') {
  // Convert lucide camelCase to kebab-case (e.g. 'mapPin' → 'map-pin')
  const slug = lucideName.replace(/([A-Z])/g, m => '-' + m.toLowerCase());
  const emojiSpan = `<span class="wi-emoji" aria-hidden="true">${emoji}</span>`;
  const svgSpan   = `<span class="wi-svg" aria-hidden="true" data-lucide="${slug}" style="width:${size}px;height:${size}px;color:${color};"></span>`;
  return `<span class="wi">${emojiSpan}${svgSpan}</span>`;
}

// After DOM updates that inject wi() HTML, call this to activate SVG icons
function wiRender() {
  if (typeof lucide !== 'undefined') {
    lucide.createIcons();
  }
}

// Auto-render icons on every showPage / modal open / renderHamburgerMenu
