// ── DATA STORE (_LS-based) ──────────────────────────────────
const LS_USERS  = 'pom_users';
const LS_PROPS  = 'pom_properties';
const LS_VISITS = 'wampac_site_visits';

function getUsers()  { try { return JSON.parse(_LS.getItem(LS_USERS)  || '[]'); } catch(e){ return []; } }
function saveUsers(u){ _LS.setItem(LS_USERS,  JSON.stringify(u)); }

// ── SITE VISITOR COUNTER ──────────────────────────────────────────────
// Counts unique browsing sessions (tenants/visitors looking for
// properties), not page views. One tally per browser session — reloads,
// filter taps, and page navigation within the same visit don't inflate
// it. Admin sessions are never counted, so the number reflects real
// people browsing the platform.
function getSiteVisits() {
  try { return parseInt(_LS.getItem(LS_VISITS) || '0', 10) || 0; }
  catch(e) { return 0; }
}
function trackSiteVisit() {
  try {
    if (adminSession) return;
    if (_SS.getItem('wampac_visit_counted') === '1') return;
    const count = getSiteVisits() + 1;
    _LS.setItem(LS_VISITS, String(count));
    _SS.setItem('wampac_visit_counted', '1');
  } catch(e) {}
}

// ── IMAGES: stored in _SS, not _LS ──────────────
// Key: 'wampac_imgs_<listingId>' → JSON array of base64 strings
const IMG_PREFIX = 'wampac_imgs_';

function saveListingImages(listingId, images) {
  if (!images || images.length === 0) return;
  try {
    _SS.setItem(IMG_PREFIX + listingId, JSON.stringify(images));
  } catch(e) {
    // _SS full — compress further and retry once
    try {
      const smaller = images.map(img => {
        const c = document.createElement('canvas');
        const image = new Image(); image.src = img;
        c.width = Math.min(image.naturalWidth || 400, 400);
        c.height = Math.min(image.naturalHeight || 300, 300);
        c.getContext('2d').drawImage(image, 0, 0, c.width, c.height);
        return c.toDataURL('image/jpeg', 0.5);
      });
      _SS.setItem(IMG_PREFIX + listingId, JSON.stringify(smaller));
    } catch(e2) { console.warn('Could not store images for', listingId); }
  }
}

function getListingImages(listingId) {
  try {
    const raw = _SS.getItem(IMG_PREFIX + listingId);
    return raw ? JSON.parse(raw) : [];
  } catch(e) { return []; }
}

function deleteListingImages(listingId) {
  try { _SS.removeItem(IMG_PREFIX + listingId); } catch(e) {}
}

// ── PROPS: save WITHOUT images; rehydrate images on read ─────────────
function saveProps(props) {
  try {
    // Strip image data from the metadata record before saving to _LS.
    // Top-level images → _SS under IMG_PREFIX + id
    const lean = props.map(p => {
      const { images, ...rest } = p;
      if (images && images.length > 0) saveListingImages(p.id, images);
      return { ...rest };
    });
    _LS.setItem(LS_PROPS, JSON.stringify(lean));
    // Verify the write actually landed (guards against silent quota failures)
    const verify = _LS.getItem(LS_PROPS);
    if (!verify) throw new Error('Write verification failed — data not found after save');
    return true;
  } catch(e) {
    console.error('saveProps failed:', e);
    // Last resort: strip absolutely everything image-related and retry
    try {
      const minimal = props.map(p => {
        const { images, ...rest } = p;
        return rest;
      });
      _LS.setItem(LS_PROPS, JSON.stringify(minimal));
      const verify2 = _LS.getItem(LS_PROPS);
      if (!verify2) throw new Error('Minimal write also failed verification');
      return true;
    } catch(e2) {
      console.error('saveProps minimal also failed:', e2);
      return false; // caller must handle this
    }
  }
}

function getProps() {
  try {
    const lean = JSON.parse(_LS.getItem(LS_PROPS) || '[]');
    // Rehydrate all images from _SS for each listing
    return lean.map(p => ({ ...p, images: getListingImages(p.id) }));
  } catch(e) { return []; }
}

