// Merge DEFAULT_AREAS with any admin-added areas from _LS
function getAREAS() {
  try {
    const extra    = JSON.parse(_LS.getItem('wampac_extra_areas') || '[]');
    const hidden   = JSON.parse(_LS.getItem('wampac_hidden_default_areas') || '[]');
    const overrides= JSON.parse(_LS.getItem('wampac_area_overrides') || '{}');
    const hiddenSet= new Set(hidden.map(n => n.toLowerCase()));

    // Start with DEFAULT_AREAS, skip hidden, apply overrides
    const merged = DEFAULT_AREAS
      .filter(a => !hiddenSet.has(a.name.toLowerCase()))
      .map(a => {
        if (overrides[a.name]) {
          return { ...a, name: overrides[a.name].name, icon: overrides[a.name].icon };
        }
        return a;
      });

    // Append custom extras (avoid duplicates)
    const mergedNames = new Set(merged.map(a => a.name.toLowerCase()));
    extra.forEach(a => { if (!mergedNames.has(a.name.toLowerCase())) merged.push(a); });
    return merged;
  } catch(e) { return DEFAULT_AREAS; }
}
