// ── INIT ──────────────────────────────────────────────────────────────
function checkStorageHealth() {
  try {
    // Estimate used _LS bytes
    let used = 0;
    var _lsKeys = _LS._isMemory ? Object.keys(_LS._data||{}) : Object.keys(_LS);
    _lsKeys.forEach(function(k){ try { used += ((_LS.getItem(k)||'').length + k.length) * 2; } catch(e){} });
    const usedKB = Math.round(used / 1024);
    const limitKB = 5120; // 5MB typical limit
    if (usedKB > 4000) {
      console.warn('_LS nearly full:', usedKB + 'KB / ' + limitKB + 'KB');
      // If admin is logged in, warn them
      if (adminSession) {
        showToast('⚠️ Storage nearly full (' + usedKB + 'KB). Consider clearing old listings.', 'error');
      }
    }
  } catch(e) {}
}

function init() {
  checkStorageHealth();
  AREAS = getAREAS();
  renderCountryGrid(getAllowedCountries());
  populatePostCountries();
  populateAreaSelects();
  restoreAdminSession();
  trackSiteVisit();
  // Restore session
  const saved = _SS.getItem('pom_session');
  if (saved) {
    try {
      currentUser = JSON.parse(saved);
      // Legacy migration: hospitality accounts no longer exist — fold them
      // into residential so existing users aren't left with a broken/empty
      // Property Type dropdown.
      if (currentUser.accountType === 'hospitality') {
        currentUser.accountType = 'residential';
        _SS.setItem('pom_session', JSON.stringify(currentUser));
        const users = getUsers();
        const idx = users.findIndex(u => u.id === currentUser.id);
        if (idx > -1 && users[idx].accountType === 'hospitality') {
          users[idx].accountType = 'residential';
          saveUsers(users);
        }
      }
      setLoggedInNav();
      if (!currentUser.accountType) {
        // Re-check against the stored user record in case it was set elsewhere
        const u = getUsers().find(x => x.id === currentUser.id);
        if (u && u.accountType) {
          // Found it in _LS — sync it to the session
          currentUser.accountType = u.accountType;
          _SS.setItem('pom_session', JSON.stringify(currentUser));
        } else if (u && !u.accountType) {
          // User record exists but genuinely has no accountType — ask them to pick
          openAccountTypeMigration();
        }
        // If u is null (_LS empty / cleared), don't force migration —
        // the user is still valid via _SS; let them use the app normally.
      }
    } catch(e){}
  }
  renderHamburgerMenu();
  seedDemoData();

  // Initialise Lucide SVG icons for static HTML
  setTimeout(wiRender, 100);

  // If the visitor already tapped "I am looking for…" earlier this
  // session, don't restart the attention-grabbing animation.
  try {
    if (_SS.getItem('lf_btn_seen') === '1') {
      const btn = document.getElementById('looking-for-btn');
      const finger = document.getElementById('lf-tap-finger');
      if (btn) btn.classList.add('lf-paused');
      if (finger) finger.style.display = 'none';
    }
  } catch(e) {}

  // Show country splash on first visit
  // NOTE: splashMaybeShow() is deferred to after WORLD_COUNTRIES is defined (see bottom of script)
}

// ══════════════════════════════════════════════════════════════════
//  COUNTRY SELECTOR SPLASH  v1.0
//  Fullscreen overlay shown on first visit.
//  Visitor picks their country → dismissed → browse context set.
//  Key stored in _LS so it only fires once per device.
// ══════════════════════════════════════════════════════════════════
const SPLASH_KEY = 'wampac_visitor_country_v1';

function splashMaybeShow() {
  try {
    const stored = _LS.getItem(SPLASH_KEY);
    if (stored) {
      const saved = JSON.parse(stored);
      const allowedList = getAllowedCountries();
      // Only honour the saved country if it is still admin-allowed
      const country = allowedList.find(c => c.code === saved.code);
      if (country) {
        const ov = document.getElementById('country-splash-overlay');
        if (ov) ov.style.display = 'none';
        splashApplyCountry(country, false);
        return;
      }
      // Saved country no longer allowed — clear it and show splash afresh
      try { _LS.removeItem(SPLASH_KEY); } catch(e) {}
    }
  } catch(e) {}
  // First visit (or cleared) — show splash with only admin-allowed countries
  splashRenderGrid(getAllowedCountries(), '');
  // No back button on first visit — there is nothing to go back to
  const backBar = document.getElementById('splash-back-bar');
  if (backBar) backBar.style.display = 'none';
}

function splashRenderGrid(list, q) {
  const grid = document.getElementById('splash-country-grid');
  if (!grid) return;
  const props = getProps();
  const filtered = q ? list.filter(c => c.name.toLowerCase().includes(q.toLowerCase())) : list;

  if (filtered.length === 0) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:rgba(255,255,255,0.5);padding:40px 20px;font-size:0.9rem;">No countries found — try a different search.</div>';
    return;
  }

  // PNG always first, then alphabetical
  const sorted = [...filtered].sort((a,b) => {
    if (a.code === 'PG') return -1;
    if (b.code === 'PG') return 1;
    return a.name.localeCompare(b.name);
  });

  grid.innerHTML = sorted.map(c => {
    const count = props.filter(p =>
      (p.country || 'Papua New Guinea') === c.name &&
      (p.status === 'approved' || !p.status)
    ).length;
    return `<div class="splash-country-card ${count>0?'has-listings':''}"
      data-country-code="${c.code}"
      onclick="splashSelectCountry('${c.code}')">
      <div class="scc-flag">${flagImg(c.code,{width:34,emoji:c.icon})}</div>
      <div class="scc-name">${escHtml(c.name)}</div>
      ${count > 0 ? `<div class="scc-count">${count} Listing${count>1?'s':''}</div>` : ''}
    </div>`;
  }).join('');
}

function splashFilterCountries(q) {
  splashRenderGrid(getAllowedCountries(), q);
}

function splashSelectCountry(code) {
  const country = WORLD_COUNTRIES.find(c => c.code === code);
  if (!country) return;

  // Instant visual feedback — highlight the tapped card orange
  const grid = document.getElementById('splash-country-grid');
  if (grid) {
    grid.querySelectorAll('.splash-country-card.is-selected').forEach(el => el.classList.remove('is-selected'));
    const tapped = grid.querySelector(`.splash-country-card[data-country-code="${code}"]`);
    if (tapped) tapped.classList.add('is-selected');
  }

  // Persist choice
  try { _LS.setItem(SPLASH_KEY, JSON.stringify({ code: country.code, name: country.name })); } catch(e) {}

  // Animate dismiss
  const ov = document.getElementById('country-splash-overlay');
  if (ov) {
    ov.style.transition = 'opacity 0.35s ease, transform 0.35s ease';
    ov.style.opacity = '0';
    ov.style.transform = 'scale(0.96)';
    setTimeout(() => {
      ov.style.display = 'none';
      // Reset back button for next time
      const backBar = document.getElementById('splash-back-bar');
      if (backBar) backBar.style.display = 'none';
    }, 360);
  }

  splashApplyCountry(country, true);
}

function splashApplyCountry(country, scroll) {
  // Guard: if this country isn't in allowedCountries, block entirely
  const allowed = getSettings().allowedCountries || ['PG'];
  if (!allowed.includes(country.code)) {
    return; // do not set browseCountry — country is disabled by admin
  }
  // Simulate selectCountry() without requiring the user to tap it again
  browseCountry = country;
  const stepCountry  = document.getElementById('step-country');
  const stepProvince = document.getElementById('step-province');
  const stepArea     = document.getElementById('step-area');
  const provinces    = WORLD_PROVINCES[country.code] || [];

  if (provinces.length > 0) {
    // Go to province step
    if (stepCountry)  stepCountry.style.display  = 'none';
    if (stepProvince) stepProvince.style.display = 'block';
    if (stepArea)     stepArea.style.display     = 'none';
    const bc = document.getElementById('breadcrumb-province');
    if (bc) bc.innerHTML = flagImg(country.code,{width:22,emoji:country.icon}) + ' ' + escHtml(country.name + ' — Select Province / State');
    renderProvinceGrid();
    if (scroll) {
      setTimeout(() => {
        if (stepProvince) stepProvince.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 420);
    }
  } else {
    // No provinces — go straight to area step
    browseProvince = 'All';
    if (stepCountry)  stepCountry.style.display  = 'none';
    if (stepProvince) stepProvince.style.display = 'none';
    if (stepArea)     stepArea.style.display     = 'block';
    const bc = document.getElementById('breadcrumb-area');
    if (bc) bc.innerHTML = flagImg(country.code,{width:22,emoji:country.icon}) + ' ' + escHtml(country.name);
    showAreaStep();
    if (scroll) {
      setTimeout(() => {
        if (stepArea) stepArea.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 420);
    }
  }

  // Update hero hint text — now shows province/state prompt for selected country
  const hint = document.getElementById('hero-search-hint-el') || document.querySelector('.hero-search-hint');
  if (hint) hint.innerHTML = flagImg(country.code,{width:22,emoji:country.icon}) + ' ' + escHtml(country.name + ' — Select your province or state below');

  // Update hero h1 to show the selected country name
  const heroH1 = document.getElementById('hero-h1-el');
  if (heroH1) heroH1.innerHTML = 'Find your next place<br>anywhere in<br><em>' + country.name + '</em>';

  // Update hero subtext
  const heroP = document.getElementById('hero-p-el');
  if (heroP) heroP.textContent = 'Browse apartments, houses, offices and more — across ' + country.name + '.';

  // Update hero tag badge
  const heroTag = document.getElementById('hero-tag-el');
  if (heroTag) heroTag.innerHTML = flagImg(country.code,{width:22,emoji:country.icon}) + ' ' + escHtml(country.name) + ' Real Estate Platform';

  // Always hide step-country so browsing starts at province
  const scEl = document.getElementById('step-country');
  if (scEl) scEl.style.display = 'none';

  // Update footer + hero badge branding
  _updateFooterBranding(country);
}

function splashReset() {
  // "Change Country" → back to the general landing with the country list
  homeShowGeneral(true);
}

function splashGoBack() {
  // Dismiss splash and restore the previous country context
  const ov = document.getElementById('country-splash-overlay');
  if (ov) {
    ov.style.transition = 'opacity 0.25s ease';
    ov.style.opacity = '0';
    setTimeout(() => { ov.style.display = 'none'; ov.style.opacity = '1'; }, 260);
  }
  const backBar = document.getElementById('splash-back-bar');
  if (backBar) backBar.style.display = 'none';
  const input = document.getElementById('splash-search');
  if (input) input.value = '';
}

