// Province filter now handled by 3-step browse flow

function populateAreaGrid(areas) {
  // FIX #2+#3: refresh ALL visible grids — country, province, area — and admin stats
  refreshAllGrids();
}

function refreshAllGrids() {
  AREAS = getAREAS();
  // Always refresh the country grid (step 1 — what visitor sees first)
  renderCountryGrid(getAllowedCountries());
  // If province step is visible, refresh it
  if (browseCountry && document.getElementById('step-province') &&
      document.getElementById('step-province').style.display !== 'none') {
    renderProvinceGrid();
  }
  // If area step is visible, refresh it
  if (browseProvince && document.getElementById('step-area') &&
      document.getElementById('step-area').style.display !== 'none') {
    showAreaStep();
  }
  // If the public listings page is open, refresh it so newly published
  // properties (or Go-Live toggles) appear immediately without a reload.
  if (document.getElementById('page-listings') &&
      document.getElementById('page-listings').classList.contains('active')) {
    renderListings();
  }
  // Refresh admin stats if admin panel is open
  if (adminSession && document.getElementById('adm-stat-listings')) {
    renderAdminStats();
  }
}

