// ── PAGES ─────────────────────────────────────────────────────────────
function updateFooterAdminAccess(pageId) {
  const el = document.getElementById('footer-admin-access');
  if (el) el.style.display = (pageId === 'home') ? 'block' : 'none';
}
function showPage(id) {
  if (id === 'admin') {
    if (!adminSession) { openAdminLogin(); return; }
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('page-admin').classList.add('active');
    window.scrollTo(0,0);
    renderAdminDashboard();
    updateFooterAdminAccess(id);
    // ── Wallpaper: admin panel must never show the listings/sales wallpaper ──
    document.body.style.backgroundImage = '';
    document.body.classList.remove('listings-wallpaper-active', 'sales-wallpaper-active', 'bubbles-tile-bg');
    return;
  }
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-' + id).classList.add('active');
  window.scrollTo(0,0);
  updateFooterAdminAccess(id);
  // ── Wallpaper: clear body bg then apply for the correct page ──
  document.body.style.backgroundImage = '';
  document.body.classList.remove('listings-wallpaper-active', 'sales-wallpaper-active', 'bubbles-tile-bg');
  if (id === 'listings') {
    const lwp = window._listingsWallpaperUrl || getListingsWallpaper() || DEFAULT_WALLPAPER;
    window._listingsWallpaperUrl = lwp;
    document.body.style.backgroundImage = wallpaperCss(lwp);
    document.body.classList.add('listings-wallpaper-active');
  }
  if (id === 'sales') {
    const swp = window._salesWallpaperUrl || getSalesWallpaper() || DEFAULT_WALLPAPER;
    window._salesWallpaperUrl = swp;
    document.body.style.backgroundImage = wallpaperCss(swp);
    document.body.classList.add('sales-wallpaper-active');
  }
  if (id === 'home') {
    // Only reset browse steps when user isn't mid-browse (e.g. tapping logo from a non-browse page).
    // goBackFromListings handles its own step restoration, so we must not overwrite it here.
    if (!browseCountry && !browseProvince) {
      renderCountryGrid(getAllowedCountries());
      document.getElementById('step-country').style.display  = 'block';
      document.getElementById('step-province').style.display = 'none';
      document.getElementById('step-area').style.display     = 'none';
    }
  }
  if (id === 'dashboard') { renderDashboard(); }
  wiRender();
}

// ── LISTINGS ──────────────────────────────────────────────────────────
function showListings(area, freeText) {
  currentArea   = area || null;
  _areaFreeText = !!(area && freeText);
  currentFilter = 'All';
  currentCategory = 'All';
  // Reset search filters for new area
  const _slAppPer = (getAppearance().rentPeriod || '/ week').includes('month') ? 'month'
                  : (getAppearance().rentPeriod || '/ week').includes('fortnight') ? 'fortnight'
                  : 'week';
  _searchFilters = { minPrice:null, maxPrice:null, period:_slAppPer, beds:'', type:'', keyword:'' };
  _sheetTemp = { ..._searchFilters };

  document.querySelectorAll('.filter-chip, .tchip').forEach(c => c.classList.remove('active'));
  const allCatChip = document.querySelector('.type-chips-scroll .tchip[data-cat="All"]');
  if (allCatChip) allCatChip.classList.add('active');
  const subRow = document.getElementById('type-chips-sub');
  if (subRow) { subRow.style.display = 'none'; subRow.innerHTML = ''; }
  document.getElementById('listings-area-title').textContent = area ||
    ((browseProvince && browseProvince !== 'All') ? browseProvince : (browseCountry ? browseCountry.name : 'All areas'));
  document.getElementById('listings-area-subtitle').textContent = 'Loading…';
  showPage('listings');
  renderListings(true);
}

// Property types grouped by category, with their own label/icon — used
// to build the sub-type row whenever a category chip is tapped.
const CATEGORY_SUBTYPES = {
  residential: [
    ['Apartment','🏢 Apartment'], ['House','🏠 House'], ['Room','🛏️ Room'], ['Transit','🚇 Transit']
  ],
  commercial: [
    ['Office','🏢 Office'], ['Shop','🏪 Shop'], ['Restaurant','🍽️ Restaurant'],
    ['Salon','💈 Salon'], ['Medical','🏥 Medical'], ['Training','🏫 Training'],
    ['Warehouse','🏭 Warehouse'], ['Industrial','🏗️ Industrial'], ['Land','🌾 Land'], ['Parking','🅿️ Parking']
  ]
};
const CATEGORY_TYPE_LISTS = { residential: RESIDENTIAL_TYPES, commercial: COMMERCIAL_TYPES };

// Tapping a top-level category chip (Residential / Commercial):
// shows every listing in that category AND reveals its specific types as a
// second row of chips underneath. Tapping the same category again collapses
// the sub-row and goes back to showing all categories.
function selectCategory(cat, el) {
  const subRow = document.getElementById('type-chips-sub');
  const alreadyActive = currentCategory === cat && el && el.classList.contains('active');

  document.querySelectorAll('.type-chips-scroll:not(.type-chips-sub) .tchip').forEach(c => c.classList.remove('active'));

  if (cat === 'All' || alreadyActive) {
    // Collapse back to "All"
    currentCategory = 'All';
    currentFilter = 'All';
    const allChip = document.querySelector('.type-chips-scroll .tchip[data-cat="All"]');
    if (allChip) allChip.classList.add('active');
    if (subRow) { subRow.style.display = 'none'; subRow.innerHTML = ''; }
  } else {
    currentCategory = cat;
    currentFilter = 'category:' + cat; // matches every type in this category
    if (el) el.classList.add('active');
    if (subRow) {
      const _known = CATEGORY_SUBTYPES[cat].map(([v]) => v);
      const _customSeen = {};
      try {
        getProps().forEach(p => {
          if (!p || !p.type || _known.includes(p.type) || p.type === 'Other' || p.type === 'OtherCommercial') return;
          if (!isListingPubliclyVisible(p)) return;
          const comm = !!p.isCommercial || COMMERCIAL_TYPES.includes(p.type);
          if ((cat === 'commercial') !== comm) return;
          _customSeen[p.type] = true;
        });
      } catch (e) {}
      const _customSubs = Object.keys(_customSeen).sort().map(t => [t, '\uD83C\uDFE0 ' + t]);
      subRow.innerHTML = CATEGORY_SUBTYPES[cat].concat(_customSubs).map(([val,lab]) =>
        `<button class="tchip" onclick="selectSubType('${escAttr(val)}',this)">${escHtml(lab)}</button>`
      ).join('');
      subRow.style.display = 'flex';
    }
  }

  _searchFilters.type = '';
  renderListings();
  updateFilterPills();
}

// Tapping a specific type inside an expanded sub-row (e.g. "Office" after
// tapping "Commercial") narrows the listings down to just that type, while
// keeping the parent category expanded and highlighted.
function selectSubType(type, el) {
  currentFilter = type;
  document.querySelectorAll('#type-chips-sub .tchip').forEach(c => c.classList.remove('active'));
  if (el) el.classList.add('active');
  _searchFilters.type = '';
  renderListings();
  updateFilterPills();
}

// Builds the price block markup for a listing card. Two cases:
// Transit/Short Stay (daily/weekly/monthly toggle — renters pick whichever
// suits their stay), and the standard single-rent display used by
// everything else. Shared by every place a listing card is rendered so
// the two stay in sync.
function buildPriceBlockHTML(p) {
  if (p.transitRates) {
    const r = p.transitRates;
    return `
      <span class="transit-rate-toggle">
        <button type="button" class="trt-btn active" onclick="switchTransitRate(event,'${escAttr(p.id)}','daily',this)">Day</button>
        <button type="button" class="trt-btn" onclick="switchTransitRate(event,'${escAttr(p.id)}','weekly',this)">Week</button>
        <button type="button" class="trt-btn" onclick="switchTransitRate(event,'${escAttr(p.id)}','monthly',this)">Month</button>
      </span>
      <div class="transit-price-amount" id="transit-price-${escAttr(p.id)}">K${Number(r.daily).toLocaleString()}<span>/ day</span></div>
    `;
  }
  return `${p.country && p.country !== 'Papua New Guinea' ? '' : 'K'}${Number(p.rent).toLocaleString()}<span>${p.rentPeriod === 'month' ? '/ month' : (getAppearance().rentPeriod || '/ week')}</span>`;
}

// Renter taps Day/Week/Month on a Transit/Short Stay card — swap the
// displayed price and the active pill, no full card re-render needed.
function switchTransitRate(event, propId, period, btnEl) {
  if (event) event.stopPropagation();
  const p = getProps().find(x => x.id === propId);
  if (!p || !p.transitRates) return;
  const labelMap = { daily: '/ day', weekly: '/ week', monthly: '/ month' };
  const amountEl = document.getElementById('transit-price-' + propId);
  if (amountEl) amountEl.innerHTML = 'K' + Number(p.transitRates[period]).toLocaleString() + '<span>' + labelMap[period] + '</span>';
  const group = btnEl.closest('.transit-rate-toggle');
  if (group) group.querySelectorAll('.trt-btn').forEach(b => b.classList.remove('active'));
  btnEl.classList.add('active');
}

// ── SALES PROPERTY VIEW COUNTER ───────────────────────────────────────
// Mirrors trackListingViews() for sales properties. Counts a "view" when
// a buyer opens a sales property's photos or contacts the seller — never
// on a simple grid render, and never for an admin session.
function trackSalesViews(propIds) {
  if (adminSession) return;
  if (!propIds || !propIds.length) return;
  const all = getSalesProps();
  let changed = false;
  propIds.forEach(id => {
    const p = all.find(x => x.id === id);
    if (!p) return;
    p.views = (p.views || 0) + 1;
    changed = true;
  });
  if (changed) {
    saveSalesProps(all);
    // Live-refresh the admin panel's views badges if it's currently open
    propIds.forEach(id => {
      const countEl = document.getElementById('sales-views-count-' + id);
      if (!countEl) return;
      const prop = all.find(p => p.id === id);
      if (!prop) return;
      const vc = prop.views || 0;
      countEl.textContent = vc.toLocaleString();
      const badge = document.getElementById('sales-views-badge-' + id);
      if (badge) {
        badge.classList.remove('views-zero');
        const labelEl = badge.querySelector('.views-label');
        if (labelEl) labelEl.textContent = vc === 1 ? 'view' : 'views';
      }
    });
  }
}

// ── LISTING VIEW COUNTER ──────────────────────────────────────────────
// Counts a "view" once per fresh navigation into the listings results
// page (browsing an area, a province-wide search, or the "I'm looking
// for…" wizard) — NOT on every filter/category-chip tap, since those
// just narrow a set the visitor has already seen, which would otherwise
// inflate the count every time someone taps a chip. Landlords viewing
// their own listing, and admin sessions, are never counted.
function trackListingViews(propIds) {
  if (adminSession) return;
  if (!propIds || !propIds.length) return;
  const all = getProps();
  let changed = false;
  propIds.forEach(id => {
    const p = all.find(x => x.id === id);
    if (!p) return;
    if (currentUser && p.landlordId === currentUser.id) return; // owner viewing own listing doesn't count
    p.views = (p.views || 0) + 1;
    changed = true;
  });
  if (changed) {
    saveProps(all);
    // Refresh dashboard view counter live if landlord dashboard is currently open
    if (document.getElementById('page-dashboard') &&
        document.getElementById('page-dashboard').classList.contains('active') &&
        currentUser) {
      const myProps = getProps().filter(p => p.landlordId === currentUser.id);
      const el = document.getElementById('stat-views');
      if (el) el.textContent = myProps.reduce((s,p) => s + (p.views||0), 0).toLocaleString();
      // Live-refresh each per-listing view badge + re-trigger entrance anim
      propIds.forEach(id => {
        const badge = document.getElementById('views-badge-' + id);
        if (!badge) return;
        const prop = myProps.find(p => p.id === id);
        if (!prop) return;
        const vc = prop.views || 0;
        // Update count text
        const countEl = badge.querySelector('.views-count');
        if (countEl) countEl.textContent = vc.toLocaleString();
        // Update label
        const labelEl = badge.querySelector('.views-label');
        if (labelEl) labelEl.textContent = vc === 1 ? 'view' : 'views';
        // Switch from zero state if first ever view
        badge.classList.remove('views-zero');
        // Re-trigger entrance anim
        badge.classList.remove('do-entrance');
        void badge.offsetWidth;
        badge.classList.add('do-entrance');
        // Mini confetti burst — 3 waves
        const liveColors = ['#ffd700','#ff6b6b','#4ecdc4','#45b7d1','#ff9ff3'];
        function spawnLiveBurst(waveDelay) {
          setTimeout(() => {
            for (let c = 0; c < 5; c++) {
              const dot = document.createElement('span');
              dot.className = 'views-confetti-dot';
              dot.style.background = liveColors[c % liveColors.length];
              dot.style.left = (8 + c * 18) + '%';
              dot.style.animationDelay = (c * 70) + 'ms';
              dot.style.animationDuration = (600 + Math.random() * 300) + 'ms';
              badge.appendChild(dot);
              setTimeout(() => dot.remove(), 1100);
            }
          }, waveDelay);
        }
        spawnLiveBurst(0);
        spawnLiveBurst(550);
        spawnLiveBurst(1100);
      });
    }
  }
}

// ═══ WAMPAC PROPERTY CARDS v2 — shared builder for rental + sales ═══
const WP_ICONS = {
  bed:  '<path d="M2 4v16"/><path d="M2 8h18a2 2 0 0 1 2 2v10"/><path d="M2 17h20"/><path d="M6 8v9"/>',
  bath: '<path d="M9 6 6.5 3.5a1.5 1.5 0 0 0-1-.5C4.7 3 4 3.7 4 4.5V17a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/><path d="M10 5 8 7"/><path d="M2 12h20"/>',
  area: '<path d="M15 3h6v6"/><path d="M9 21H3v-6"/><path d="m21 3-7 7"/><path d="m3 21 7-7"/>',
  car:  '<path d="M19 17h2c.6 0 1-.4 1-1v-3c0-.9-.7-1.7-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3c-.5-.4-1.1-.7-1.8-.7H5c-.6 0-1.1.4-1.4.9l-1.4 2.9A3.7 3.7 0 0 0 2 12v4c0 .6.4 1 1 1h2"/><circle cx="7" cy="17" r="2"/><path d="M9 17h6"/><circle cx="17" cy="17" r="2"/>',
  pin:  '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',
  heart:'<path d="M19 14c1.5-1.5 3-3.2 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.8 0-3 .5-4.5 2-1.5-1.5-2.7-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4 3 5.5l7 7Z"/>',
  cam:  '<path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/>',
  nav:  '<polygon points="3 11 22 2 13 21 11 13 3 11"/>',
  phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.7 2Z"/>'
};
function wpIco(n) {
  return '<svg class="wp-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (WP_ICONS[n] || '') + '</svg>';
}

// Saved (♥) properties — per device, stored locally
function wpSavedList() { try { return JSON.parse(_LS.getItem('wampac_saved') || '[]'); } catch (e) { return []; } }
function wpToggleSave(event, id) {
  event.stopPropagation();
  let list = wpSavedList();
  const on = !list.includes(id);
  list = on ? list.concat(id) : list.filter(x => x !== id);
  try { _LS.setItem('wampac_saved', JSON.stringify(list)); } catch (e) {}
  event.currentTarget.classList.toggle('on', on);
  event.currentTarget.setAttribute('aria-pressed', on ? 'true' : 'false');
  if (typeof showToast === 'function') showToast(on ? '♥ Saved to your favourites' : 'Removed from favourites', 'success');
}

// Swipe photos left/right on touch screens (reuses the existing nav functions)
var _wpSwipe = { x: 0, y: 0, t: 0, done: 0 };
function wpSwipeGuard() { return Date.now() - _wpSwipe.done < 350; }
document.addEventListener('touchstart', function (e) {
  const m = e.target.closest && e.target.closest('.wp-media[data-nav]');
  if (!m || !e.touches[0]) return;
  _wpSwipe.x = e.touches[0].clientX; _wpSwipe.y = e.touches[0].clientY; _wpSwipe.t = 1;
}, { passive: true });
document.addEventListener('touchend', function (e) {
  if (!_wpSwipe.t) return; _wpSwipe.t = 0;
  const m = e.target.closest && e.target.closest('.wp-media[data-nav]');
  if (!m || !e.changedTouches[0]) return;
  const dx = e.changedTouches[0].clientX - _wpSwipe.x, dy = e.changedTouches[0].clientY - _wpSwipe.y;
  if (Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy) * 1.3) return;
  _wpSwipe.done = Date.now();
  const fn = window[m.dataset.nav];
  if (typeof fn === 'function') fn({ stopPropagation: function () {} }, m.dataset.id, dx < 0 ? 1 : -1);
}, { passive: true });

// c = { mode:'rent'|'sale', id, title, images[], imgPrefix, countPrefix, navFn, mediaClick, detailCall,
//       type, emoji, priceHTML, ts, pending, location, feats[], availHTML, dirUrl, contactCall, contactLabel, idx }
function wpCardHTML(c) {
  const id = escAttr(c.id), imgs = c.images || [], n = imgs.length;
  const isNew = c.ts && (Date.now() - new Date(c.ts).getTime()) < 3 * 86400000;
  const saved = wpSavedList().includes(c.id);
  const eagerFirst = (c.idx || 0) < 2;
  // Every photo is a slide in a native scroll-snap track: swipe sideways to browse photos,
  // swipe up/down to move to the next listing (no tap needed).
  const slides = n
    ? imgs.map((src, i) => `<div class="wp-slide"><img src="${escAttr(src)}" alt="${escHtml(c.title)}${n > 1 ? ' – photo ' + (i + 1) : ''}" ${(i === 0 && eagerFirst) ? '' : 'loading="lazy"'} decoding="async" draggable="false"></div>`).join('')
    : `<div class="wp-slide">${c.placeholderHTML || `<div class="wp-ph">${c.emoji}<small>Photos coming soon</small></div>`}</div>`;
  const arrows = n > 1
    ? `<button class="sc-nav-arrow sc-nav-left" onclick="wpSlide(event,this,-1)" aria-label="Previous photo">‹</button>
       <button class="sc-nav-arrow sc-nav-right" onclick="wpSlide(event,this,1)" aria-label="Next photo">›</button>`
    : '';
  // Only two quick facts on the card (beds / baths). Everything else lives in Details.
  const mini = (c.feats || []).slice(0, 2).map(f => `<span class="wp-mini">${f}</span>`).join('');
  // Show an availability flag only when it's NOT the normal "vacant" state (e.g. Fully Booked)
  const am = String(c.availHTML || '').match(/<div class="avail-badge[\s\S]*?<\/div>/);
  const flag = am ? am[0] : '';
  return `
  <article class="${c.mode === 'rent' ? 'listing-card' : 'sales-card'} wp-card" style="--i:${Math.min(c.idx || 0, 8)}">
    <div class="wp-media" data-id="${id}"
         onclick="if(event.target.closest('button,a'))return;${c.mediaClick}" title="Tap to view photos">
      <div class="wp-track" id="${c.imgPrefix}${id}" data-n="${n}">${slides}</div>
      <div class="wp-badges">
        <span class="wp-chip ${c.mode === 'rent' ? 'rent' : 'sale'}">${c.mode === 'rent' ? 'For Rent' : 'For Sale'}</span>
        ${isNew ? '<span class="wp-chip new">New</span>' : ''}
        ${c.pending ? '<span class="wp-chip pend">⏳ Pending approval</span>' : ''}
      </div>
      ${c.mediaExtra || ''}
      ${c.hideSave ? '' : `<button class="wp-save ${saved ? 'on' : ''}" aria-label="Save property" aria-pressed="${saved}" onclick="wpToggleSave(event,'${id}')">${wpIco('heart')}</button>`}
      <span class="wp-type">${c.emoji} ${escHtml(c.type || 'Property')}</span>
      ${n > 1 ? `<span class="wp-count">${wpIco('cam')}<span class="wp-count-n" id="${c.countPrefix}${id}">1 / ${n}</span></span>` : ''}
      ${arrows}
    </div>
    <div class="wp-body" onclick="if(event.target.closest('button,a'))return;${c.detailCall}">
      <h3 class="wp-title">${escHtml(c.title)}</h3>
      <div class="wp-row1">
        ${c.priceHTML}
        ${mini ? `<div class="wp-minis">${mini}</div>` : ''}
      </div>
      <div class="wp-row2">
        <div class="wp-loc">${wpIco('pin')}<span>${c.location}</span></div>
        <span class="wp-ago">${c.ago}</span>
      </div>
      ${flag}
    </div>
    <div class="wp-actions">
      ${c.dirUrl ? `<a class="wp-btn icon" href="${c.dirUrl}" target="_blank" rel="noopener" aria-label="Directions" title="Directions">${wpIco('nav')}</a>` : ''}
      <button class="wp-btn ghost" onclick="${c.detailCall}">Details</button>
      ${c.contactCall ? `<button class="wp-btn primary" onclick="${c.contactCall}">${wpIco('phone')} ${c.contactLabel}</button>` : ''}
    </div>
  </article>`;
}

// ── Photo carousel helpers (cards + details sheet) ──
// Keeps the "1 / 5" counter in sync while the person swipes.
document.addEventListener('scroll', function (e) {
  const t = e.target;
  if (!t || !t.classList || !(t.classList.contains('wp-track') || t.classList.contains('pdm-track'))) return;
  if (t._raf) return;
  t._raf = requestAnimationFrame(function () {
    t._raf = 0;
    const w = t.clientWidth || 1, n = t.children.length;
    const i = Math.min(n - 1, Math.max(0, Math.round(t.scrollLeft / w)));
    const box = t.parentElement;
    const lbl = box && box.querySelector('.wp-count-n, .pdm-count-n');
    if (lbl) lbl.textContent = (i + 1) + ' / ' + n;
    t.dataset.i = i;
  });
}, true);
// Desktop arrows: scroll the track by one photo
function wpSlide(event, btn, dir) {
  event.stopPropagation();
  const track = btn.closest('.wp-media').querySelector('.wp-track');
  if (!track) return;
  const w = track.clientWidth, n = track.children.length;
  const cur = Math.round(track.scrollLeft / w);
  const next = (cur + dir + n) % n;
  track.scrollTo({ left: next * w, behavior: 'smooth' });
}
function wpTrackIndex(root) {
  const t = root && root.querySelector && root.querySelector('.wp-track, .pdm-track');
  if (!t) return 0;
  return Math.round(t.scrollLeft / (t.clientWidth || 1)) || 0;
}

// ── Single source of truth for the RENTAL card: browse grid, landlord dashboard and
// the Full Preview modal all render through this, so they can never drift apart.
function rentCardFromProp(p, i, o) {
  const _ap = getAppearance();
  const _cLabel = String(_ap.contactBtn || 'Contact').replace(/^[^\p{L}\p{N}]+/u, '').trim() || 'Contact';
    const locationLine = [p.area, p.province, (p.country && p.country !== 'Papua New Guinea') ? p.country : null]
      .filter(Boolean).map(escHtml).join(' · ');
    const feats = [];
    if (p.beds)  feats.push(wpIco('bed')  + (/^\d+$/.test(String(p.beds)) ? p.beds + ' Bed' + (String(p.beds) === '1' ? '' : 's') : escHtml(p.beds)));
    if (p.baths) feats.push(wpIco('bath') + p.baths + ' Bath' + (String(p.baths) === '1' ? '' : 's'));
    if (p.floorArea) feats.push(wpIco('area') + Number(p.floorArea).toLocaleString() + ' m²');
    if (p.carParks && p.carParks !== 'None') feats.push(wpIco('car') + escHtml(p.carParks) + (/^\d+$/.test(String(p.carParks)) ? ' Park' + (String(p.carParks) === '1' ? '' : 's') : ''));
    const hasPin = p.address || (p.lat != null && p.lng != null);
    return wpCardHTML(Object.assign({
      mode: 'rent', idx: i, id: p.id, title: p.title, images: p.images || [],
      imgPrefix: 'scimg-', countPrefix: 'sccount-', navFn: 'simpleCardNav',
      mediaClick: `lbOpenFromCard(event,'${escAttr(p.id)}')`,
      detailCall: `openPropDetail('${escAttr(p.id)}')`,
      type: p.type, emoji: TYPE_EMOJI[p.type] || '🏠',
      priceHTML: `<div class="listing-price wp-price">${buildPriceBlockHTML(p)}</div>`,
      ago: timeAgo(p.publishedAt || p.date), ts: p.publishedAt || p.date,
      pending: p.status === 'pending' && currentUser && p.landlordId === currentUser.id,
      location: locationLine, feats,
      availHTML: availBadgeHTML(p.availability, p.type),
      dirUrl: hasPin ? buildMapsUrl(p.address, p.area, p.lat, p.lng) : '',
      contactLabel: escHtml(_cLabel),
      contactCall: `showContact('${escAttr(p.landlordName)}','${escAttr(p.landlordPhone)}','${escAttr(p.landlordEmail||'')}','${escAttr(p.title)}','${escAttr(p.address||'')}','${escAttr(p.area)}',${p.lat!=null?p.lat:'null'},${p.lng!=null?p.lng:'null'},'${escAttr(p.id)}')`
    }, o || {}));
}

// Owner-side photo viewer: opens the lightbox WITHOUT counting a tenant view
function dashOpenPhotos(id) {
  const p = getProps().find(x => x.id === id);
  if (p && p.images && p.images.length) openLightbox(p.images, 0, p.title);
  else openEditImagesModal(id);
}

// ── Sorting shared by Rent + Sales browse ──
let _browseSort = 'new';
function browseSortList(arr, priceFn) {
  const a = arr.slice();
  if (_browseSort === 'new') return a.sort((x, y) => y.date - x.date);
  const dir = _browseSort === 'low' ? 1 : -1;
  return a.sort((x, y) => {
    const px = priceFn(x), py = priceFn(y);
    if (!px && !py) return y.date - x.date;
    if (!px) return 1; if (!py) return -1;      // unpriced always last
    return (px - py) * dir;
  });
}
function browseResetAll() {
  const all = document.querySelector('.tchip[data-cat="All"]');
  if (all && typeof selectCategory === 'function') selectCategory('All', all);
  clearSearchFilters();
}
function setBrowseSort(v, mode) {
  _browseSort = v;
  document.querySelectorAll('.browse-sort-select').forEach(e => e.value = v);
  if (mode === 'sales') renderSalesListingsPage(); else renderListings();
}

function renderListings(freshNav) {
  const grid = document.getElementById('listings-grid');
  // Base filter: area + country + status
  const filterCountry = browseCountry ? browseCountry.name : null;
  let props = getProps().filter(p => {
    // currentArea === null means "search the whole province" (used by the
    // "I am looking for…" wizard when the area/suburb step is skipped) —
    // match every listing in that province instead of one exact area.
    // Some listings don't have province saved directly (older posts, demo
    // data), so fall back to looking it up from the area name via AREAS.
    const listingProvince = p.province || (AREAS.find(a => a.name === p.area) || {}).province || '';
    const _na = v => String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    const areaMatch = currentArea
      ? (p.area === currentArea ||
         (_areaFreeText && [p.area, p.suburb, p.city, p.address].some(v => _na(v).includes(_na(currentArea)))))
      : ((browseProvince && browseProvince !== 'All') ? listingProvince === browseProvince : true);
    // Landlords always see their own pending; public tenants only see publicly-visible listings.
    const ownPending = currentUser && p.landlordId === currentUser.id && p.status === 'pending';
    const publicOk   = isListingPubliclyVisible(p);
    return areaMatch && (ownPending || publicOk) &&
      (!filterCountry || (p.country || 'Papua New Guinea') === filterCountry);
  });

  // Type filter (filter bar chips) — either an exact type, a whole
  // category ("category:commercial" matches every commercial type), or 'All'
  if (currentFilter !== 'All') {
    if (currentFilter.startsWith('category:')) {
      const cat = currentFilter.slice('category:'.length);
      const _isCommP = p => !!p.isCommercial || COMMERCIAL_TYPES.includes(p.type);
      props = props.filter(p => cat === 'commercial' ? _isCommP(p) : !_isCommP(p));
    } else {
      props = props.filter(p => p.type === currentFilter);
    }
  }

  // Apply search filters (price, beds, type, keyword)
  const totalBeforeSearch = props.length;
  const { filtered: searchFiltered, hasFilter } = applySearchFilterToProps(props);
  props = searchFiltered;
  props = browseSortList(props, p => Number(p.rent) || 0);

  // Views are now tracked individually per property — when a tenant taps
  // Contact or opens the photo lightbox — NOT on bulk page-load.

  // Update filter result count in pill bar
  updateFilterResultCount(props.length, totalBeforeSearch);
  updateFilterPills();

  document.getElementById('listings-area-subtitle').textContent =
    props.length + ' propert' + (props.length===1?'y':'ies') + ' available';

  // City/province photo stays put with zero listings; once there's at
  // least one property, switch to the repeating water-bubbles wallpaper.
  setBubblesBackgroundActive(props.length > 0);

  if (props.length === 0) {
    const _where = currentArea || ((browseProvince && browseProvince !== 'All') ? browseProvince : (browseCountry ? browseCountry.name : '')) || 'this area';
    if (totalBeforeSearch > 0 || currentFilter !== 'All') {
      grid.innerHTML = `<div class="empty-state">
        <span class="empty-icon">🔍</span>
        <h3>No matches for your filters</h3>
        <p>Nothing in ${escHtml(_where)} fits these filters. Try widening your budget or showing all property types.</p>
        <button class="btn btn-gold btn-lg" style="border-radius:24px;" onclick="browseResetAll()">Clear all filters</button>
      </div>`;
    } else {
      grid.innerHTML = `<div class="empty-state">
        <span class="empty-icon">🏚️</span>
        <h3>No listings yet in ${escHtml(_where)}</h3>
        <p>Be the first landlord to post a property here. Create a free account to get started — it only takes a minute.</p>
        <button class="btn btn-gold btn-lg" style="border-radius:24px;" onclick="closeModal('post-modal');openModal('auth-modal')">+ List Your Property Free</button>
      </div>`;
    }
    return;
  }

  const _ap = getAppearance();
  const _cLabel = String(_ap.contactBtn || 'Contact').replace(/^[^\p{L}\p{N}]+/u, '').trim() || 'Contact';
  grid.innerHTML = props.map((p, i) => {
    return rentCardFromProp(p, i);
  }).join('');

}


// ── Expand/collapse the secondary details on a listing card ───────────
function toggleListingDetails(event, propId) {
  event.stopPropagation();
  const panel = document.getElementById('ldet-' + propId);
  if (!panel) return;
  const btn = event.currentTarget;
  const isOpen = panel.style.display !== 'none';
  panel.style.display = isOpen ? 'none' : 'block';
  const label = btn.querySelector('.let-label');
  const arrow = btn.querySelector('.let-arrow');
  if (label) label.textContent = isOpen ? 'Tap to view more' : 'Show less';
  if (arrow)  arrow.textContent = isOpen ? '▾' : '▴';
  btn.classList.toggle('expanded', !isOpen);
}

// ── Open lightbox from listing card click ─────────────────
// Looks up the property by ID from current rendered props
// so we never embed large base64 arrays inline in HTML attrs
function lbOpenFromCard(event, propId) {
  // Only trigger from listing-img div, not from step-cards or other elements
  if (!event.currentTarget.classList.contains('listing-img') && !event.currentTarget.classList.contains('wp-media')) return;
  // Don't trigger if user clicked a child button/link (contact, directions)
  if (event.target.closest('a') || event.target.closest('button')) return;
  event.stopPropagation();

  const props = getProps();
  const p = props.find(pr => pr.id === propId);
  if (!p) return;

  // Track a view when a tenant opens this property's photos
  trackListingViews([propId]);

  const images = p.images || [];
  if (images.length === 0) return;

  openLightbox(images, Math.min(images.length - 1, wpTrackIndex(event.currentTarget)), p.title);
}

// ── Cycle a listing card's photo via the in-card ‹ › arrows ───────────
// Swaps just the <img> src + counter text — no re-render, no lightbox.
function simpleCardNav(event, propId, dir) {
  event.stopPropagation();
  const p = getProps().find(pr => pr.id === propId);
  if (!p) return;
  const images = p.images || [];
  if (images.length <= 1) return;

  const imgEl = document.getElementById('scimg-' + propId);
  if (!imgEl) return;

  let idx = parseInt(imgEl.dataset.idx || '0', 10);
  idx = (idx + dir + images.length) % images.length;
  imgEl.src = images[idx];
  imgEl.dataset.idx = idx;

  const countEl = document.getElementById('sccount-' + propId);
  if (countEl) countEl.textContent = (idx + 1) + ' / ' + images.length;
}

// ── Cycle a SALES card's photo via the in-card ‹ › arrows ─────────────
// Mirrors simpleCardNav() above but reads from sales image storage
// (getSalesPropImages) instead of the rental p.images array.
function salesCardNav(event, propId, dir) {
  event.stopPropagation();
  const images = getSalesPropImages(propId);
  if (!images || images.length <= 1) return;

  const imgEl = document.getElementById('scsimg-' + propId);
  if (!imgEl) return;

  let idx = parseInt(imgEl.dataset.idx || '0', 10);
  idx = (idx + dir + images.length) % images.length;
  imgEl.src = images[idx];
  imgEl.dataset.idx = idx;

  const countEl = document.getElementById('scscount-' + propId);
  if (countEl) countEl.textContent = (idx + 1) + ' / ' + images.length;
}

// ── CONTACT MODAL ─────────────────────────────────────────────────────
function showContact(name, phone, email, title, address, area, lat, lng, propId) {
  // Track a view for this property when a tenant opens the contact modal
  if (propId) trackListingViews([propId]);
  document.getElementById('contact-title').textContent = escHtml(title);
  document.getElementById('contact-name').textContent  = 'Verified Property Owner';
  document.getElementById('contact-phone-display').textContent = phone;
  document.getElementById('contact-phone-link').href = 'tel:' + phone.replace(/\s/g,'');
  // Email (optional — only show the button if the landlord listed one)
  const emailLink    = document.getElementById('contact-email-link');
  const emailDisplay = document.getElementById('contact-email-display');
  const hintEl        = document.getElementById('contact-hint');
  if (email) {
    emailDisplay.textContent = email;
    emailLink.href = 'mailto:' + email + '?subject=' + encodeURIComponent('Enquiry: ' + title);
    emailLink.style.display = 'flex';
    if (hintEl) hintEl.textContent = 'Call, WhatsApp, or email to enquire. Tap Directions to open Google Maps.';
  } else {
    emailLink.style.display = 'none';
    if (hintEl) hintEl.textContent = 'Call or WhatsApp to enquire. Tap Directions to open Google Maps.';
  }
  // Directions
  const dirLink = document.getElementById('contact-directions-link');
  const addrDisplay = document.getElementById('contact-address-display');
  const mapsUrl = buildMapsUrl(address, area, lat, lng);
  dirLink.href = mapsUrl;
  if (address) {
    addrDisplay.textContent = '📍 ' + address;
    dirLink.style.display = 'flex';
  } else {
    addrDisplay.textContent = '📍 ' + (area || 'Papua New Guinea');
    dirLink.style.display = 'flex';
  }
  openModal('contact-modal');
}

// ── BUILD GOOGLE MAPS URL ─────────────────────────────────────────────
function buildMapsUrl(address, area, lat, lng) {
  // If the landlord dropped a precise pin, send renters straight to those
  // exact coordinates — far more accurate than a geocoded text address.
  if (lat != null && lng != null && !isNaN(lat) && !isNaN(lng)) {
    return 'https://www.google.com/maps/dir/?api=1&destination=' + lat + ',' + lng;
  }
  const query = (address && address.trim())
    ? address + ', Papua New Guinea'
    : (area || 'Papua New Guinea');
  return 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(query);
}

// ── AUTH ──────────────────────────────────────────────────────────────
// ── EMAIL / GOOGLE SIGN-IN ─────────────────────────────────────────────
// Google sign-in: create an OAuth "Web application" client ID in Google Cloud
// Console (APIs & Services → Credentials) and add your site's https:// origin
// under "Authorized JavaScript origins". Paste the client ID below.
// (Google sign-in does not work when this file is opened from file://.)
const GOOGLE_CLIENT_ID = '';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function normEmail(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

let _googlePending = null;   // Google profile for a brand-new account that still needs type + location
let _gsiLoading = null, _gsiReady = false;

function _authErrEl() {
  const reg = document.getElementById('tab-register');
  return (reg && reg.classList.contains('active')) ? document.getElementById('reg-error') : document.getElementById('login-error');
}

// Older accounts were created with a phone number — still recognise that number once
// so those landlords can sign in and attach an email (see openEmailMigration).
function _findLegacyPhoneUser(users, raw) {
  const digits = String(raw).replace(/\D/g, '').replace(/^0+/, '');
  if (digits.length < 6) return null;
  return users.find(u => {
    const d = String(u.phone || '').replace(/\D/g, '');
    return d && (d === digits || d.endsWith(digits));
  }) || null;
}

function doLogin() {
  const idRaw = (document.getElementById('login-email').value || '').trim();
  const pass  = document.getElementById('login-pass').value;
  const errEl = document.getElementById('login-error');
  errEl.style.display = 'none';

  if (!idRaw || !pass) { showErr(errEl, 'Please enter your email address and password.'); return; }

  const users = getUsers();
  let user = null;
  if (idRaw.indexOf('@') > -1) {
    const email = normEmail(idRaw);
    if (!EMAIL_RE.test(email)) { showErr(errEl, 'Please enter a valid email address.'); return; }
    user = users.find(u => normEmail(u.email) === email);
    if (!user) { showErr(errEl, 'No account found with this email. Please create an account or continue with Google.'); return; }
  } else {
    user = _findLegacyPhoneUser(users, idRaw);
    if (!user) { showErr(errEl, 'Please enter the email address you signed up with.'); return; }
  }
  if (!user.password) { showErr(errEl, 'This account uses Google sign-in. Please tap “Continue with Google” above.'); return; }
  if (user.password !== hashish(pass)) { showErr(errEl, 'Incorrect password. Please try again.'); return; }
  _finishLogin(user, errEl);
}

// Shared by password sign-in and Google sign-in.
function _finishLogin(user, errEl) {
  if (isUserSuspended(user.id)) { showErr(errEl, '⛔ Your account has been suspended. Please contact the site administrator.'); return false; }

  // Legacy migration: hospitality accounts no longer exist — fold into residential
  if (user.accountType === 'hospitality') {
    user.accountType = 'residential';
    const users = getUsers();
    const idx = users.findIndex(u => u.id === user.id);
    if (idx > -1) { users[idx].accountType = 'residential'; saveUsers(users); }
  }

  // If they tapped a specific account type in the menu and this account is
  // already locked to a different type, point them to the right option.
  if (pendingLoginType && user.accountType && user.accountType !== pendingLoginType) {
    const correct = ACCOUNT_TYPES[user.accountType];
    showErr(errEl, 'This account is registered as ' + (correct ? correct.icon + ' ' + correct.label : 'a different account type') + '. Please choose that option from the menu to sign in.');
    return false;
  }

  const usedType = pendingLoginType;
  pendingLoginType = null;
  const hint = document.getElementById('login-type-hint');
  if (hint) hint.style.display = 'none';

  currentUser = { id: user.id, name: user.name, email: user.email || '', phone: user.phone || '', area: user.area, province: user.province, country: user.country, countryCode: user.countryCode, accountType: user.accountType || null, ...(user.companyName ? { companyName: user.companyName } : {}) };
  try {
    _SS.setItem('pom_session', JSON.stringify(currentUser));
  } catch (e) {
    showErr(errEl, 'Could not start your session. Please try again. (' + e.message + ')');
    return false;
  }
  closeModal('auth-modal');
  setLoggedInNav();
  if (!currentUser.accountType) {
    openAccountTypeMigration(usedType);
  } else {
    showPage('dashboard');
    if (!user.email) setTimeout(openEmailMigration, 450);   // account made with a phone number — ask for an email once
  }
  showToast('Welcome back, ' + user.name + '! 👋', 'success');
  return true;
}

// ── Add-email prompt for accounts created with a phone number ──
function openEmailMigration() {
  if (!currentUser || currentUser.email) return;
  const err = document.getElementById('email-migrate-error'); if (err) err.style.display = 'none';
  const inp = document.getElementById('email-migrate-input'); if (inp) inp.value = '';
  openModal('email-migrate-modal');
}
function saveEmailMigration() {
  const errEl = document.getElementById('email-migrate-error');
  errEl.style.display = 'none';
  const email = normEmail(document.getElementById('email-migrate-input').value);
  if (!EMAIL_RE.test(email)) { showErr(errEl, 'Please enter a valid email address.'); return; }
  const users = getUsers();
  if (users.some(u => u.id !== currentUser.id && normEmail(u.email) === email)) { showErr(errEl, 'That email is already linked to another account.'); return; }
  const idx = users.findIndex(u => u.id === currentUser.id);
  if (idx === -1) { showErr(errEl, 'Something went wrong — please sign in again.'); return; }
  users[idx].email = email;
  saveUsers(users);
  currentUser.email = email;
  try { _SS.setItem('pom_session', JSON.stringify(currentUser)); } catch (e) {}
  closeModal('email-migrate-modal');
  showPage('dashboard');
  showToast('Email added — use it to sign in from now on ✅', 'success');
}

// ── Google Identity Services ──
function loadGoogleIdentity() {
  if (_gsiLoading) return _gsiLoading;
  _gsiLoading = new Promise((resolve, reject) => {
    if (window.google && google.accounts && google.accounts.id) { resolve(); return; }
    const s = document.createElement('script');
    s.src = 'https://accounts.google.com/gsi/client';
    s.async = true; s.defer = true;
    s.onload = () => resolve();
    s.onerror = () => { _gsiLoading = null; reject(new Error('Could not load Google sign-in')); };
    document.head.appendChild(s);
  });
  return _gsiLoading;
}

const _GOOGLE_G_SVG = '<svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>';

function _renderGoogleFallback(slot) {
  slot.innerHTML = '<button type="button" class="google-btn-fallback" onclick="googleNotAvailable()">' + _GOOGLE_G_SVG + '<span>Continue with Google</span></button>';
}
function googleNotAvailable() {
  if (!GOOGLE_CLIENT_ID) console.warn('[Wampac] Google sign-in is not configured. Set GOOGLE_CLIENT_ID in the auth section of the script.');
  showToast('Google sign-in is not available right now — please use your email instead.', 'error');
}

// Renders Google's official button into both slots (sign-in tab + sign-up form).
function initGoogleAuthButtons() {
  const slots = ['google-btn-login', 'google-btn-reg'].map(id => document.getElementById(id)).filter(Boolean);
  if (!slots.length) return;
  if (!GOOGLE_CLIENT_ID) { slots.forEach(_renderGoogleFallback); return; }
  loadGoogleIdentity().then(() => {
    if (!_gsiReady) {
      google.accounts.id.initialize({ client_id: GOOGLE_CLIENT_ID, callback: onGoogleCredential, ux_mode: 'popup', auto_select: false });
      _gsiReady = true;
    }
    const inner = document.getElementById('auth-modal-inner');
    const w = Math.max(220, Math.min(400, ((inner && inner.clientWidth) || 360) - 56));
    slots.forEach(slot => {
      slot.innerHTML = '';
      google.accounts.id.renderButton(slot, { type: 'standard', theme: 'outline', size: 'large', text: 'continue_with', shape: 'pill', logo_alignment: 'left', width: w });
    });
  }).catch(() => slots.forEach(_renderGoogleFallback));
}

function _decodeJwtPayload(token) {
  let b64 = String(token).split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
  b64 += '='.repeat((4 - b64.length % 4) % 4);
  const json = decodeURIComponent(atob(b64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
  return JSON.parse(json);
}

function onGoogleCredential(resp) {
  const errEl = _authErrEl();
  if (errEl) errEl.style.display = 'none';
  let p;
  try { p = _decodeJwtPayload(resp && resp.credential); } catch (e) { p = null; }
  const okIss = p && (p.iss === 'https://accounts.google.com' || p.iss === 'accounts.google.com');
  if (!p || !p.email || !okIss || p.aud !== GOOGLE_CLIENT_ID || (p.exp && p.exp * 1000 < Date.now())) {
    showErr(errEl, 'We could not verify your Google sign-in. Please try again.');
    return;
  }
  if (p.email_verified === false) { showErr(errEl, 'Your Google email address is not verified. Please verify it with Google first.'); return; }

  const profile = { email: normEmail(p.email), name: p.name || p.email.split('@')[0], googleId: p.sub };
  const users = getUsers();
  const existing = users.find(u => normEmail(u.email) === profile.email) || users.find(u => u.googleId && u.googleId === profile.googleId);

  if (existing) {
    // Existing account → sign in (and remember the Google link)
    if (!existing.googleId) {
      existing.googleId = profile.googleId;
      if (!existing.email) existing.email = profile.email;
      saveUsers(users);
    }
    _finishLogin(existing, errEl);
    return;
  }

  // Brand-new account → finish the sign-up wizard (account type + location) with the Google details pre-filled
  const regActive = document.getElementById('tab-register').classList.contains('active');
  if (!regActive) {
    _wizardStepTransitionGuardUntil = 0;
    switchTab('register');      // resets the wizard (and clears any pending Google profile)
    showToast('No account yet — let\u2019s set one up with Google', 'success');
  }
  _googlePending = profile;
  applyGoogleRegisterMode();
}

function clearGooglePending() {
  _googlePending = null;
  const emailEl = document.getElementById('reg-email'); if (emailEl) emailEl.value = '';
  const nameEl = document.getElementById('reg-name'); if (nameEl) nameEl.value = '';
  applyGoogleRegisterMode();
}

// Shows/hides the password + email fields on the sign-up form depending on whether a Google profile is attached.
function applyGoogleRegisterMode() {
  const g = _googlePending;
  const blk = document.getElementById('reg-google-block');
  const banner = document.getElementById('reg-google-banner');
  const passEl = document.getElementById('reg-pass');
  const passRow = passEl && passEl.closest ? passEl.closest('.form-row') : null;
  const emailEl = document.getElementById('reg-email');
  const nameEl = document.getElementById('reg-name');
  if (g) {
    if (blk) blk.style.display = 'none';
    if (banner) { banner.style.display = 'flex'; const be = document.getElementById('reg-google-email'); if (be) be.textContent = g.email; }
    if (passRow) passRow.style.display = 'none';
    if (emailEl) { emailEl.value = g.email; emailEl.readOnly = true; }
    if (nameEl && !nameEl.value) nameEl.value = g.name || '';
  } else {
    if (blk) blk.style.display = '';
    if (banner) banner.style.display = 'none';
    if (passRow) passRow.style.display = '';
    if (emailEl) emailEl.readOnly = false;
  }
}

// ── REGISTRATION WIZARD ──────────────────────────────────────────────
// Step state
let _wizardCategory = null; // 'landlord' | 'pmc'

// Guards against a mobile "ghost click": showWizardStep synchronously resets
// the modal's scroll position (see below) so the newly-revealed step is
// visible. On Android WebView/Chrome, if that scroll reset happens between
// touchstart and touchend of the same tap, the browser re-hit-tests at
// touchend and can dispatch the click to whatever now sits under the
// finger — usually the "Sign In"/"Create Account" tab bar, which always
// sits at the very top of the modal. That looked like pressing "Continue"
// on the registration form instantly bouncing the user back to the reset
// Landlord Portal screen. We give a brief window after any step change
// during which tab-switch clicks are ignored as likely ghost clicks.
let _wizardStepTransitionGuardUntil = 0;

function showWizardStep(stepId) {
  _wizardStepTransitionGuardUntil = Date.now() + 500;
  // Hide all steps inside tab-register
  document.querySelectorAll('#tab-register .wizard-step').forEach(s => {
    s.style.display = 'none';
  });
  const target = document.getElementById(stepId);
  if (target) target.style.display = 'block';
  // Clear any lingering errors
  const errEl = document.getElementById('reg-error');
  if (errEl) errEl.style.display = 'none';
  // Reset scroll to top — target every possible scrollable ancestor.
  // On mobile the user scrolls down to fill the form; without this reset the modal
  // stays scrolled past the newly-revealed step, showing an empty white modal card.
  try {
    var els = [
      document.getElementById('auth-modal-inner'),
      document.getElementById('auth-modal'),
      document.querySelector('#auth-modal .modal'),
      document.querySelector('#auth-modal .modal-body')
    ];
    els.forEach(function(el) { if (el) el.scrollTop = 0; });
  } catch(e) {}
  // Belt-and-suspenders: after the browser has rendered display:block,
  // use scrollIntoView to guarantee the step is on screen on any device.
  if (target) {
    setTimeout(function() {
      try {
        var inner = document.getElementById('auth-modal-inner');
        if (inner) inner.scrollTop = 0;
        target.scrollIntoView({ block: 'start', behavior: 'auto' });
      } catch(e) {}
    }, 50);
  }
}

// Every new account is created as the full-spectrum type (can list residential,
// commercial & industrial). No "who are you registering as?" question any more.
const DEFAULT_NEW_ACCOUNT_TYPE = 'property_management';

function wizardBackFromForm() {
  showWizardStep('wizard-step-location');
}

// "Change" link on the form step — jump back to location without losing account type
function wizardBackToLocation() {
  showWizardStep('wizard-step-location');
  wizLocInit();
}

function wizardFinalSelect(accountType) {
  // Account type is no longer chosen by the user: always use the default.
  accountType = DEFAULT_NEW_ACCOUNT_TYPE;
  document.getElementById('reg-acct-type').value = accountType;
  const companyGroup = document.getElementById('reg-company-group');
  if (companyGroup) companyGroup.style.display = 'none';
  showWizardStep('wizard-step-location');
  wizLocInit();
}

// Called when the register tab opens — always start at wizard step 0
function resetRegisterWizard() {
  _wizardCategory = null;
  _googlePending = null;
  document.getElementById('reg-acct-type').value = DEFAULT_NEW_ACCOUNT_TYPE;
  ['reg-name','reg-email','reg-pass','reg-pass2','reg-company-name'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const locCountry = document.getElementById('wiz-loc-country-code');
  const locProvince = document.getElementById('wiz-loc-province-val');
  if (locCountry) locCountry.value = '';
  if (locProvince) locProvince.value = '';
  const errEl = document.getElementById('reg-error');
  if (errEl) errEl.style.display = 'none';
  const companyGroup = document.getElementById('reg-company-group');
  if (companyGroup) companyGroup.style.display = 'none';
  showWizardStep('wizard-step-location');
  if (typeof wizLocInit === 'function') wizLocInit();
  applyGoogleRegisterMode();
}


// Legacy shim: direct account type selection (used by doRegister error re-entry etc.)
function selectRegAccountType(type) {
  wizardFinalSelect(type);
}

// ── REGISTRATION — validate form and create the account immediately (email/password or Google) ──
function doRegisterStep1() {
  const isGoogle    = !!_googlePending;
  const name        = document.getElementById('reg-name').value.trim();
  const email       = isGoogle ? _googlePending.email : normEmail(document.getElementById('reg-email').value);
  const pass        = document.getElementById('reg-pass').value;
  const pass2       = document.getElementById('reg-pass2').value;
  const countryCode = (_wizLocCountry && _wizLocCountry.code) || (_authDialCode['reg'] && _authDialCode['reg'].code) || 'PG';
  const province    = (document.getElementById('reg-province') || {}).value || '';
  const accountType = (document.getElementById('reg-acct-type') || {}).value || DEFAULT_NEW_ACCOUNT_TYPE;
  const companyName = '';
  const errEl       = document.getElementById('reg-error');
  errEl.style.display = 'none';

  if (!accountType)  { showErr(errEl,'Please choose your account type.'); return; }
  if (!_wizLocCountry){ showErr(errEl,'Please select your country.'); return; }
  if (!name)   { showErr(errEl,'Please enter your full name.'); return; }
  if (!email)  { showErr(errEl,'Please enter your email address.'); return; }
  if (!EMAIL_RE.test(email)) { showErr(errEl,'Please enter a valid email address.'); return; }
  if (!isGoogle) {
    if (!pass || pass.length < 6){ showErr(errEl,'Password must be at least 6 characters.'); return; }
    if (pass !== pass2){ showErr(errEl,'Passwords do not match.'); return; }
  }

  const users = getUsers();
  if (users.find(u => normEmail(u.email) === email)) {
    showErr(errEl,'An account with this email already exists. Please sign in.'); return;
  }

  const countryObj  = WORLD_COUNTRIES.find(c => c.code === countryCode);
  const countryName = countryObj ? countryObj.name : 'Papua New Guinea';
  const area = (document.getElementById('reg-area') || {}).value || '';

  const newUserData = {
    name, email, phone: '', area, province,
    country: countryName, countryCode, accountType,
    ...(companyName ? { companyName } : {}),
    ...(isGoogle
        ? { authProvider: 'google', googleId: _googlePending.googleId }
        : { authProvider: 'password', password: hashish(pass) })
  };

  const newUser = { id: 'u_' + Date.now(), ...newUserData };
  users.push(newUser);
  currentUser = { id: newUser.id, ...newUserData };
  delete currentUser.password;
  delete currentUser.googleId;
  delete currentUser.authProvider;

  try {
    saveUsers(users);
    _SS.setItem('pom_session', JSON.stringify(currentUser));
  } catch (e) {
    showErr(errEl, 'Could not save your account on this device. (' + e.message + ')');
    return;
  }

  _googlePending = null;
  closeModal('auth-modal');
  setLoggedInNav();
  showPage('dashboard');
  showToast('Account created! Welcome to Wampac 🎉', 'success');
}


// ── FORGOT PASSWORD FLOW ──────────────────────────────────────────────
let fpFoundUserId = null;
let _fpOtpCode     = null;

function fpGoStep(step) {
  ['phone','otp','reset','failed','done'].forEach(s => {
    const el = document.getElementById('fp-step-' + s);
    if (el) el.style.display = (s === step) ? 'block' : 'none';
  });
  const backLink = document.getElementById('fp-back-link');
  if (backLink) backLink.style.display = (step === 'done' || step === 'failed') ? 'none' : 'block';
  ['fp-error','fp-success'].forEach(id => {
    const el = document.getElementById(id); if (el) el.style.display = 'none';
  });
}

function fpResetState() {
  fpFoundUserId = null;
  _fpOtpCode = null;
  const ph = document.getElementById('fp-email'); if (ph) ph.value = '';
  fpGoStep('phone');
}

function openForgotPassword() {
  _authDialCode['fp'] = { code:'PG', flag:'\uD83C\uDDF5\uD83C\uDDEC', name:'Papua New Guinea', dial:'+675' };
  document.querySelectorAll('.modal-tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  const fpPanel = document.getElementById('tab-forgot');
  if (fpPanel) fpPanel.classList.add('active');
  const tabsBar = document.querySelector('.modal-tabs');
  if (tabsBar) tabsBar.style.display = 'none';
  fpResetState();
}

function fpBackToLogin() {
  const tabsBar = document.querySelector('.modal-tabs');
  if (tabsBar) tabsBar.style.display = 'flex';
  switchTab('login');
}

function fpFindAccount() {
  const email = normEmail(document.getElementById('fp-email').value);
  const errEl = document.getElementById('fp-error');
  errEl.style.display = 'none';
  if (!email) { showErr(errEl,'Please enter the email address on your account.'); return; }
  if (!EMAIL_RE.test(email)) { showErr(errEl,'Please enter a valid email address.'); return; }

  const user = getUsers().find(u => normEmail(u.email) === email);
  if (!user) { showErr(errEl,'No account found with this email. Check the address or create a new account.'); return; }

  fpFoundUserId = user.id;
  fpSendOtp(user);
}

// Sends (or re-sends) the 6-digit recovery code to the account's registered email.
function fpSendOtp(user) {
  _fpOtpCode = _genVerifyCode();
  const emailDisplay = document.getElementById('fp-otp-email-display');
  if (emailDisplay) emailDisplay.textContent = user.email;
  const codeInput = document.getElementById('fp-otp-code');
  if (codeInput) codeInput.value = '';

  // Same offline caveat as registration — no real mail server is wired up here.
  const demoHint = document.getElementById('fp-otp-demo-hint');
  if (demoHint) {
    demoHint.style.display = 'block';
    demoHint.innerHTML = '📨 Demo mode (no email server configured) — your code is <strong>' + _fpOtpCode + '</strong>';
  }

  fpGoStep('otp');
  showToast('Recovery code sent to ' + user.email, 'success');
}

function fpResendOtp() {
  const users = getUsers();
  const user = users.find(u => u.id === fpFoundUserId);
  if (!user) { fpGoStep('phone'); return; }
  fpSendOtp(user);
}

function fpVerifyOtp() {
  const errEl = document.getElementById('fp-error');
  errEl.style.display = 'none';
  const users = getUsers();
  const user  = users.find(u => u.id === fpFoundUserId);
  if (!user) { fpGoStep('phone'); return; }

  const entered = (document.getElementById('fp-otp-code').value || '').trim();
  if (!entered) { showErr(errEl,'Please enter the verification code.'); return; }

  if (entered === _fpOtpCode) {
    fpGoStep('reset');
    document.getElementById('fp-pass').value  = '';
    document.getElementById('fp-pass2').value = '';
  } else {
    fpGoStep('failed');
  }
}

function fpResetPassword() {
  const pass  = document.getElementById('fp-pass').value;
  const pass2 = document.getElementById('fp-pass2').value;
  const errEl = document.getElementById('fp-error');
  errEl.style.display = 'none';

  if (!pass || pass.length < 6){ showErr(errEl,'Password must be at least 6 characters.'); return; }
  if (pass !== pass2)           { showErr(errEl,'Passwords do not match.'); return; }

  const users = getUsers();
  const idx = users.findIndex(u => u.id === fpFoundUserId);
  if (idx === -1){ showErr(errEl,'Something went wrong — please start again.'); fpGoStep('phone'); return; }

  users[idx].password = hashish(pass);
  saveUsers(users);
  fpGoStep('done');
  showToast('Password reset successfully! \uD83D\uDD11', 'success');
}




function openAccountTypeMigration(preselect) {
  document.getElementById('acct-migrate-type').value = preselect || '';
  document.querySelectorAll('#acct-migrate-grid .acct-type-card').forEach(c => c.classList.toggle('selected', c.dataset.type === preselect));
  document.getElementById('acct-migrate-error').style.display = 'none';
  openModal('acct-migrate-modal');
}
function selectMigrateAccountType(type) {
  document.getElementById('acct-migrate-type').value = type;
  document.querySelectorAll('#acct-migrate-grid .acct-type-card').forEach(card => {
    card.classList.toggle('selected', card.dataset.type === type);
  });
  document.getElementById('acct-migrate-error').style.display = 'none';
}
function confirmAccountTypeMigration() {
  const type = document.getElementById('acct-migrate-type').value;
  const errEl = document.getElementById('acct-migrate-error');
  if (!type) { showErr(errEl, 'Please choose an account type to continue.'); return; }
  if (!currentUser) return;
  const users = getUsers();
  const idx = users.findIndex(u => u.id === currentUser.id);
  if (idx > -1) { users[idx].accountType = type; saveUsers(users); }
  currentUser.accountType = type;
  _SS.setItem('pom_session', JSON.stringify(currentUser));
  closeModal('acct-migrate-modal');
  showToast('Account type saved ✅', 'success');
  // Immediately open the listing form for the chosen account type
  openModal('post-modal');
}

function logout() {
  currentUser = null;
  _SS.removeItem('pom_session');
  setLoggedOutNav();
  showPage('home');
  showToast('You have been signed out.');
}

// ── Mode-aware "List" action: header + menu follow Sales/Rental mode ──
function isInSalesContext() {
  try {
    if (!isSalesModeEnabled()) return false;
    if (typeof _appMode !== 'undefined' && _appMode === 'sales') return true;
    const dp = document.getElementById('page-dashboard');
    if (dp && dp.classList.contains('active') && _LS.getItem('wampac_dash_mode') === 'sales') return true;
  } catch (e) {}
  return false;
}
function listPropertyForCurrentMode() {
  if (isInSalesContext() && typeof openSalePostModal === 'function') openSalePostModal();
  else openModal('post-modal');
}
function syncListButtonMode() {
  const b = document.getElementById('nav-btn-list'); if (!b) return;
  const sales = isInSalesContext();
  const t = sales ? 'List a property for sale' : 'List a property for rent';
  b.setAttribute('aria-label', t); b.setAttribute('title', t);
}

function setLoggedInNav() {
  document.getElementById('nav-actions').innerHTML = `
    <span class="nav-user-name">${escHtml(currentUser.name)}</span>
    <button id="nav-btn-dashboard" class="btn btn-gold nav-cta nav-cta-text" onclick="navDashHomeToggle()" aria-label="My Dashboard" title="My Dashboard">
      <span class="nav-cta-txt"><span class="dash-long">My Dashboard</span><span class="dash-short">Dashboard</span></span>
    </button>
    <button id="nav-btn-list" class="btn btn-gold nav-cta" onclick="listPropertyForCurrentMode()" aria-label="List a property for rent" title="List a property for rent">
      <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6z"/></svg>
      <span class="nav-cta-txt"><span class="lbl-long">List Property</span><span class="lbl-short">List</span></span>
    </button>
  `;
  if (document.getElementById('post-phone'))
    document.getElementById('post-phone').value = currentUser.phone || '';
  if (document.getElementById('post-email'))
    document.getElementById('post-email').value = currentUser.email || '';
  renderHamburgerMenu();
  syncNavDashHomeBtn();
}

// ── Dashboard ⇄ Home Screen toggle (logged-in landlords) ─────────────
// On the dashboard the nav button reads "Home Screen" and goes home;
// everywhere else it reads "My Dashboard" and returns to the dashboard.
// The landlord stays logged in the whole time.
function _activePageId() {
  const a = document.querySelector('.page.active');
  return a ? a.id.replace(/^page-/, '') : 'home';
}
function _goHomeScreen() {
  // In Sales mode the "home" is the sales browse page; otherwise the normal home page.
  try {
    if (_appMode === 'sales' && isSalesModeEnabled()) {
      renderSalesBrowsePage();
      showPageDirect('sales-browse');
      return;
    }
  } catch (e) {}
  showPage('home');
}
function navDashHomeToggle() {
  if (!currentUser) { showPage('home'); return; }
  if (_activePageId() === 'dashboard') _goHomeScreen();
  else showPage('dashboard');
}
function syncNavDashHomeBtn() {
  const onDash = _activePageId() === 'dashboard';
  const btn = document.getElementById('nav-btn-dashboard');
  if (btn) {
    const longTxt  = onDash ? 'Home Screen' : 'My Dashboard';
    const shortTxt = onDash ? 'Home'        : 'Dashboard';
    const l = btn.querySelector('.dash-long'), sh = btn.querySelector('.dash-short');
    if (l)  l.textContent  = longTxt;
    if (sh) sh.textContent = shortTxt;
    btn.setAttribute('aria-label', longTxt);
    btn.setAttribute('title', longTxt);
  }
  // Keep the hamburger entry in step too (it is rebuilt each time the menu opens)
  const hb = document.getElementById('hamburger-dash-home');
  if (hb) hb.innerHTML = _dashHomeMenuLabel(onDash);
}
function _dashHomeMenuLabel(onDash) {
  return onDash
    ? `${wi('home','🏠',16)} Home Screen`
    : `${wi('layout-dashboard','📊',16)} My Dashboard`;
}
// Page changes happen from many places (showPage, showPageDirect, back button),
// so watch the .page elements' "active" class instead of patching each caller.
(function _initDashHomeObserver() {
  function attach() {
    const mo = new MutationObserver(syncNavDashHomeBtn);
    document.querySelectorAll('.page').forEach(pg =>
      mo.observe(pg, { attributes: true, attributeFilter: ['class'] }));
    syncNavDashHomeBtn();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attach);
  else attach();
})();
function setLoggedOutNav() {
  document.getElementById('nav-actions').innerHTML = '';
  renderHamburgerMenu();
}

// ── POST PROPERTY ─────────────────────────────────────────────────────
function doPostProperty() {
  if (!currentUser) { closeModal('post-modal'); openModal('auth-modal'); return; }
  // FIX #7: Guard against submitting while images are still processing
  if (_pendingImageReads > 0) {
    const errEl = document.getElementById('post-error');
    showErr(errEl, '⏳ Please wait — photos are still uploading (' + _pendingImageReads + ' remaining).');
    return;
  }
  const title = document.getElementById('post-title').value.trim();
  const area  = document.getElementById('post-area').value;
  let   type  = document.getElementById('post-type').value;
  // If landlord chose "Other", use whatever they typed as the actual type
  const _isCustomCommercial = type === 'OtherCommercial';
  if (type === 'Other' || _isCustomCommercial) {
    let customVal = (document.getElementById('post-custom-type').value || '').trim().replace(/\s+/g,' ').slice(0,40);
    // Normalise capitalisation so "gym" and "Gym" show up as ONE type for the public
    customVal = customVal.replace(/\b([a-z])/g, (m) => m.toUpperCase());
    if (!customVal) {
      const errEl2 = document.getElementById('post-error');
      showErr(errEl2, 'Please describe your property type in the field below the dropdown.');
      document.getElementById('post-custom-type').focus();
      return;
    }
    type = customVal;
  }
  const isTransit  = type === 'Transit';
  const rent        = isTransit ? document.getElementById('post-rent-daily').value   : document.getElementById('post-rent').value;
  const rentWeekly  = isTransit ? document.getElementById('post-rent-weekly').value  : '';
  const rentMonthly = isTransit ? document.getElementById('post-rent-monthly').value : '';
  const beds  = document.getElementById('post-beds').value;
  const baths = document.getElementById('post-baths').value;
  const phone   = document.getElementById('post-phone').value.trim();
  const email   = (document.getElementById('post-email') || {}).value ? document.getElementById('post-email').value.trim() : '';
  const desc    = document.getElementById('post-desc').value.trim();
  const address = '';
  const errEl   = document.getElementById('post-error');
  errEl.style.display = 'none';
  clearFieldErrors();

  // Account-type integrity check: this landlord may only list types
  // that belong to their own account type (residential/commercial).
  // Custom "Other" types (already resolved above) bypass this list check
  // since the original selection was explicitly 'Other'.
  const _rawTypeVal = document.getElementById('post-type').value;
  const allowedTypes = getAccountType(currentUser).types;
  if (_rawTypeVal !== 'Other' && _rawTypeVal !== 'OtherCommercial' && !allowedTypes.includes(type)) {
    showFieldErr('ferr-title', 'This property type isn\'t available for your account type. Please pick from the list shown.', 'post-type');
    return;
  }

  const selectedCountry = document.getElementById('post-country').value;
  if (!selectedCountry) { showFieldErr('ferr-country','Please select the country.','post-country'); return; }
  // Check if this country is allowed by admin
  const _cCheck = WORLD_COUNTRIES.find(c => c.code === selectedCountry);
  const _cName  = _cCheck ? _cCheck.name : 'Papua New Guinea';
  const _access = checkPostingAllowed(_cName);
  if (!_access.allowed) { showErr(errEl, _access.reason); errEl.style.display='block'; return; }
  if (!title) { showFieldErr('ferr-title','Please enter a property title.','post-title'); return; }
  if (!area)  { showFieldErr('ferr-area','Please select the area/suburb.','post-area'); return; }
  if (!rent)  { showFieldErr('ferr-rent', isTransit ? 'Please enter the daily rate.' : 'Please enter the monthly rent.', isTransit ? 'post-rent-daily' : 'post-rent'); return; }
  if (isTransit && (!rentWeekly || !rentMonthly)) { showFieldErr('ferr-transit-rates','Transit / Short Stay listings need all three rates filled in — daily, weekly, and monthly.','post-rent-weekly'); return; }
  if (!phone) { showFieldErr('ferr-phone','Please enter a contact phone number for renters.','post-phone'); return; }
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showFieldErr('ferr-email','Please enter a valid email address, or leave it blank.','post-email'); return; }

  // Require units available for residential/commercial types that show the avail section
  if (AVAIL_TYPES.includes(type)) {
    const unitVal = document.getElementById('post-avail-note-val')
      ? document.getElementById('post-avail-note-val').value.trim()
      : document.getElementById('post-avail-note').value.trim();
    if (!unitVal || parseInt(unitVal) < 1) {
      showFieldErr('ferr-units','Please select how many units are available (tap 1, 2, 3 or enter a number).','post-avail-note-val');
      return;
    }
  }

  // Require exact location pin before publishing
  if (_prePublishLat == null || _prePublishLng == null) {
    const locSection = document.getElementById('post-location-section');
    if (locSection) {
      locSection.style.borderColor = '#e53e3e';
      locSection.style.background  = 'rgba(229,62,62,0.05)';
      setTimeout(() => {
        locSection.style.borderColor = 'rgba(13,92,99,0.15)';
        locSection.style.background  = 'rgba(13,92,99,0.05)';
      }, 2500);
      locSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    showToast('📍 Please set the exact location before publishing.', 'error');
    return;
  }

  // Resolve country + province names
  const _cObj = WORLD_COUNTRIES.find(c => c.code === selectedCountry);
  const _countryName   = _cObj ? _cObj.name : 'Papua New Guinea';
  const _provinceName  = (document.getElementById('post-province') && document.getElementById('post-province').value) || '';

  // Capture availability data (only for supported types)
  const availData = getAvailFromForm();

  // Commercial-specific fields
  const isCommercial = _isCustomCommercial || COMMERCIAL_TYPES.includes(type);
  const floorArea  = isCommercial ? (document.getElementById('post-floor-area')  || {}).value || '' : '';
  const carParks   = isCommercial ? (document.getElementById('post-carparks')    || {}).value || 'None' : '';
  const condition  = isCommercial ? (document.getElementById('post-condition')   || {}).value || '' : '';
  const leaseTerm  = isCommercial ? (document.getElementById('post-lease-term')  || {}).value || '' : '';
  const utilities  = isCommercial ? (document.getElementById('post-utilities')   || {}).value || '' : '';
  const security   = isCommercial ? (document.getElementById('post-security')    || {}).value || '' : '';
  // Derive the rent period from the site-wide appearance setting so that
  // landlords posting at "K5,000 / month" have rentPeriod:'month' saved —
  // not hardcoded 'week' — and price filters work correctly.
  const _apRentPeriod = getAppearance().rentPeriod || '/ week';
  const _apPeriodKey  = _apRentPeriod.includes('month') ? 'month'
                      : _apRentPeriod.includes('fortnight') ? 'fortnight'
                      : 'week';
  const rentPeriod = isCommercial ? 'month' : (isTransit ? 'day' : _apPeriodKey);
  // Transit / Short Stay listings carry all three rate tiers so renters
  // can pick whichever suits their stay; `rent`/`rentPeriod` above still
  // hold the daily rate as the headline figure for everywhere else in the
  // app (cards, filters, exports) that only knows about a single rent.
  const transitRates = isTransit
    ? { daily: Number(rent), weekly: Number(rentWeekly), monthly: Number(rentMonthly) }
    : null;

  // Build listing object but DON'T save yet — hold for payment
  const listingData = {
    id: 'p_' + Date.now(),
    landlordId: currentUser.id,
    landlordName: currentUser.name,
    landlordPhone: phone,
    landlordEmail: email,
    country: _countryName,
    province: _provinceName,
    title, area, type, rent: Number(rent), rentPeriod, transitRates,
    beds: isCommercial ? null : beds,
    baths: isCommercial ? null : baths,
    floorArea: floorArea ? Number(floorArea) : null,
    carParks, condition, leaseTerm, utilities, security,
    desc, address,
    availability: availData,
    isCommercial,
    images: [...uploadedImages],
    date: Date.now(),
    status: 'pending',
    paymentStatus: 'pending',
    // Pre-publish location pin (set inside the form before publishing)
    lat: (_prePublishLat  != null) ? _prePublishLat  : null,
    lng: (_prePublishLng  != null) ? _prePublishLng  : null,
  };

  // Reset form fields
  ['post-title','post-rent','post-rent-daily','post-rent-weekly','post-rent-monthly','post-desc','post-phone','post-email'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  // Collapse the transit rate block back to the standard single rent field
  const rentStdWrapReset = document.getElementById('post-rent-standard-wrap');
  const rentTransitWrapReset = document.getElementById('post-rent-transit-wrap');
  if (rentStdWrapReset) rentStdWrapReset.style.display = 'block';
  if (rentTransitWrapReset) rentTransitWrapReset.style.display = 'none';
  // Reset location cascade
  const pCountry = document.getElementById('post-country');
  const pProvince = document.getElementById('post-province');
  const pArea = document.getElementById('post-area');
  if (pCountry)  pCountry.innerHTML  = '<option value="">– Select country –</option>';
  if (pProvince) pProvince.innerHTML = '<option value="">– Select province –</option>';
  if (pArea)     pArea.innerHTML     = '<option value="">– Choose area –</option>';
  const pg = document.getElementById('post-province-group');
  const ag = document.getElementById('post-area-group');
  if (pg) pg.style.display = 'none';
  if (ag) ag.style.display = 'none';
  // Reset photos fully
  const preview = document.getElementById('upload-preview');
  if (preview) preview.innerHTML = '';
  const countEl2 = document.getElementById('upload-count');
  if (countEl2) countEl2.style.display = 'none';
  uploadedImages = [];
  _pendingImageReads = 0;
  // Re-enable publish button in case it was disabled
  const pubBtn = document.getElementById('publish-btn');
  if (pubBtn) { pubBtn.disabled = false; pubBtn.textContent = 'Publish Listing 🚀'; }
  // Clear the pre-publish location pin state so next listing starts fresh
  resetPrePublishLocation();

  closeModal('post-modal');
  // Open payment modal with the listing data
  openPaymentModal(listingData);
}

// ── DASHBOARD ─────────────────────────────────────────────────────────
function renderDashboard() {
  if (!currentUser) { showPage('home'); return; }

  // Storage health-check: if _LS is unavailable, warn landlord
  // immediately so they know why listings can't be saved or shown.
  try {
    const _testKey = '__pom_storage_test__';
    _LS.setItem(_testKey, '1');
    if (_LS.getItem(_testKey) !== '1') throw new Error('read-back failed');
    _LS.removeItem(_testKey);
  } catch(_se) {
    const list = document.getElementById('my-listings-list');
    if (list) list.innerHTML = `<div style="background:#fef2f2;border:1.5px solid #fca5a5;border-radius:10px;padding:20px;color:#991b1b;font-size:0.88rem;line-height:1.6;margin-top:16px;">
      <strong>⚠️ Storage not available</strong><br>
      Your browser is blocking local storage, so listings cannot be saved or displayed.<br><br>
      <strong>Fix:</strong> Open this file in <strong>Chrome</strong> or <strong>Firefox</strong> instead of your phone's file manager or Downloads viewer. Then your listings will save and appear here normally.
    </div>`;
    return;
  }

  document.getElementById('dash-name').textContent = currentUser.companyName || currentUser.name;
  const dc = currentUser.countryCode ? getDialCode(currentUser.countryCode) : null;
  const countryBadge = dc
    ? flagImg(dc.code, {width:18, emoji:dc.flag}) + ' ' + escHtml(currentUser.country || dc.name)
    : flagImg('pg', {width:18, emoji:'🇵🇬'}) + ' Papua New Guinea';
  document.getElementById('dash-phone').innerHTML = '✉️ ' + escHtml(currentUser.email || currentUser.phone || '') + '  ·  ' + countryBadge;
  // Show account type badge
  const acctBadgeEl = document.getElementById('dash-acct-badge');
  if (acctBadgeEl) {
    const acctInfo = ACCOUNT_TYPES[currentUser.accountType || 'residential'] || ACCOUNT_TYPES.residential;
    const badgeColors = {
      residential:        { bg:'#e0f2fe', color:'#0369a1' },
      commercial:         { bg:'#fef3c7', color:'#92400e' },
      property_management:{ bg:'#ede9fe', color:'#5b21b6' }
    };
    const bc = badgeColors[currentUser.accountType] || badgeColors.residential;
    acctBadgeEl.innerHTML = `<span style="display:inline-flex;align-items:center;gap:5px;background:${bc.bg};color:${bc.color};font-size:0.72rem;font-weight:700;padding:3px 10px;border-radius:20px;letter-spacing:0.3px;">${acctInfo.icon} ${acctInfo.label}</span>`;
    acctBadgeEl.style.display = 'block';
  }
  updateSupportBadgeForLandlord();
  if (document.getElementById('post-phone'))
    document.getElementById('post-phone').value = currentUser.phone || '';
  if (document.getElementById('post-email'))
    document.getElementById('post-email').value = currentUser.email || '';

  const myProps    = getProps().filter(p => p.landlordId === currentUser.id);
  const myApproved = myProps.filter(p => p.status === 'approved' || !p.status);
  const myPending  = myProps.filter(p => p.status === 'pending');
  const areas      = [...new Set(myProps.map(p => p.area))];
  // FIX #5: Show approved as "Live", pending separately
  document.getElementById('stat-active').textContent = myApproved.length;
  document.getElementById('stat-total').textContent  = myProps.length;
  document.getElementById('stat-areas').textContent  = areas.length;
  document.getElementById('stat-views').textContent  = myProps.reduce((s,p) => s + (p.views || 0), 0).toLocaleString();
  // Show pending badge on dashboard if any
  let pendingNote = document.getElementById('dash-pending-note');
  if (!pendingNote) {
    pendingNote = document.createElement('div');
    pendingNote.id = 'dash-pending-note';
    pendingNote.style.cssText = 'background:#fef3c7;border:1px solid #fde047;border-radius:8px;padding:10px 14px;font-size:0.82rem;color:#92400e;margin-bottom:16px;font-weight:600;';
    const statsRow = document.querySelector('.stats-row');
    if (statsRow) statsRow.parentNode.insertBefore(pendingNote, statsRow.nextSibling);
  }
  if (myPending.length > 0) {
    pendingNote.style.display = 'block';
    pendingNote.innerHTML = '<span class="wi-svg" data-lucide="clock" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">⏳</span> You have ' + myPending.length + ' listing' + (myPending.length>1?'s':'') + ' awaiting payment approval.';
  } else {
    pendingNote.style.display = 'none';
  }

  // ── Always restore Add Property button to standard state ──
  const addPropBtn = document.getElementById('dash-btn-add-property');
  if (addPropBtn) {
    addPropBtn.style.display = '';
    addPropBtn.innerHTML = '<span class="wi-svg" data-lucide="plus" style="width:14px;height:14px;vertical-align:middle;"></span><span class="wi-emoji">＋</span> List Property for Rent';
    addPropBtn.onclick = function() { openModal('post-modal'); };
    if (typeof lucide !== 'undefined') lucide.createIcons();
    const existingNote = document.getElementById('hosp-one-prop-note');
    if (existingNote) existingNote.style.display = 'none';
  }

  const list = document.getElementById('my-listings-list');
  if (myProps.length === 0) {
    list.innerHTML = `<div class="empty-state" style="padding:36px 0;">
      <div class="empty-icon">${wi('home','🏘️',40)}</div>
      <h3>No listings yet</h3>
      <p>Post your first rental listing and start getting inquiries from tenants.</p>
      <button id="dash-empty-add-btn" class="btn btn-gold btn-lg" style="margin-top:18px;border-radius:24px;">
        ＋ List Property for Rent
      </button>
    </div>`;
    // Attach click handler via JS — avoids broken nested-quote in template literal onclick
    const emptyBtn = document.getElementById('dash-empty-add-btn');
    if (emptyBtn) {
      emptyBtn.addEventListener('click', function() {
        openModal('post-modal');
      });
    }
    renderMyPayments();
    // No tour when there are no listings — tour needs listing cards in the DOM
    return;
  }
  list.innerHTML = myProps.sort((a,b)=>b.date-a.date).map((p, idx) => {
    const st = p.status || 'approved';
    const availLabel = p.availability && AVAIL_TYPES.includes(p.type) ? availDashLabel(p.availability, p.type) : '';

    let pill, label;
    if (st === 'rejected') {
      pill = 'status-rejected'; label = '❌ Rejected';
    } else if (st === 'pending') {
      pill = 'status-pending-pay'; label = '⏳ Pending Approval';
    } else {
      // Approved listing — reflect its actual per-property live state
      const liveState = getListingLiveState(p);
      if (liveState === 'pending') { pill = 'status-pending-pay'; label = '⏳ Approval Pending'; }
      else if (liveState === 'live' || liveState === 'live-free') { pill = 'status-approved'; label = '🟢 Live'; }
      else if (liveState === 'off' || liveState === 'off-free') { pill = 'status-pending-pay'; label = '⚫ Offline'; }
      else if (liveState === 'expired') { pill = 'status-rejected'; label = '🔴 Expired'; }
      else { pill = 'status-pending-pay'; label = '🟡 No Plan'; }
    }

    const _vc = p.views || 0;
    const _viewsAnimate = _vc > 0;
    const _viewsLabel = _vc === 0 ? 'No views yet' : _vc.toLocaleString() + ' view' + (_vc === 1 ? '' : 's');
    const _viewsId = 'views-badge-' + p.id;
    // Tour target IDs — only injected on the first (most recent) listing card
    const _isFirst = idx === 0;
    const _tourGoLiveId     = _isFirst ? ' id="wt-target-golive"'     : '';
    const _tourPreviewId    = _isFirst ? ' id="wt-target-preview"'    : '';
    const _tourLocationId   = _isFirst ? ' id="wt-target-location"'   : '';
    const _tourDeleteId     = _isFirst ? ' id="wt-target-delete"'     : '';
    const _tourStatusId     = _isFirst ? ' id="wt-target-status"'     : '';
    // ── Public-facing preview data (identical rules to buildTenantListingCard) ──
    const _imgs     = Array.isArray(p.images) ? p.images.filter(Boolean) : [];
    const _hasImgs  = _imgs.length > 0;
    const _cnt      = _imgs.length;
    const _typeIco  = TYPE_EMOJI[p.type] || '🏠';
    const _mediaClick = _hasImgs ? `lbOpenFromCard(event,'${escAttr(p.id)}')` : `openEditImagesModal('${escAttr(p.id)}')`;
    return `<div class="dash-card" data-prop-id="${escAttr(p.id)}">
      <div class="dash-card-label">${wi('eye','👁️',12)} Public preview — exactly what tenants see when browsing</div>
      <div class="dash-wp">${rentCardFromProp(p, 0, {mediaClick: `dashOpenPhotos('${escAttr(p.id)}')`, detailCall: `previewAsTenant('${escAttr(p.id)}')`, contactCall: '', hideSave: true,
        placeholderHTML: `<div class="wp-ph dash-ph">${_typeIco}<small>No photos yet — tenants can't see your property</small><button type="button" class="dash-ph-btn" onclick="event.stopPropagation();openEditImagesModal('${escAttr(p.id)}')">📷 Upload photos</button></div>`,
        mediaExtra: _hasImgs ? `<button type="button" class="dash-edit-photos" onclick="event.stopPropagation();openEditImagesModal('${escAttr(p.id)}')">✏️ Edit photos</button>` : ''})}</div>

      <div class="dash-card-manage">
        <div class="dash-manage-head">Manage listing</div>

        ${false ? `<div class="dash-photo-nudge">📷 <span>Add photos so tenants can see your property.</span><button type="button" onclick="openEditImagesModal('${escAttr(p.id)}')">Add Photos</button></div>` : ''}

        <div class="dash-manage-row">
          <span class="status-pill ${pill}">${label}</span>
          <!-- VIEWS BADGE — ids/classes preserved for live updates + confetti -->
          <div id="${_viewsId}" class="my-listing-views-badge${_vc === 0 ? ' views-zero' : ''}"
               title="${_vc > 0 ? _vc + ' people have viewed this listing' : 'No one has viewed this listing yet'}">
            <span class="views-eye">${wi('eye','👁️',13)}</span>
            <span class="views-count">${_vc > 0 ? _vc.toLocaleString() : '0'}</span>
            <span class="views-label">${_vc === 1 ? 'view' : 'views'}</span>
            ${_vc >= 50 ? `<span class="views-milestone">${wi('zap','⚡',13)}</span>` : _vc >= 10 ? `<span class="views-milestone">${wi('flame','🔥',13)}</span>` : ''}
          </div>
          ${st === 'approved' && p.availability && AVAIL_TYPES.includes(p.type)
            ? `<button class="btn btn-sm"${_tourStatusId} style="background:rgba(13,92,99,0.08);color:var(--teal);font-size:0.72rem;" onclick="openUpdateAvailModal('${p.id}')">${wi('pencil','✏️',12)} Update Status</button>`
            : ''}
        </div>

        <div${_tourGoLiveId}>${st === 'approved' ? renderListingGoLiveControl(p) : ''}</div>

        <div class="my-listing-actions">
          <button class="btn btn-sm dash-edit-btn" onclick="openOwnerEditListing('${p.id}')">${wi('pencil','✏️',14)} Edit Listing</button>
          <button class="btn btn-sm"${_tourPreviewId} style="background:rgba(13,92,99,0.08);color:var(--teal);" onclick="previewAsTenant('${p.id}')">${wi('eye','👁️',13)} Full Preview</button>
          <button class="btn btn-sm"${_tourLocationId} style="background:${p.lat!=null?'#dcfce7':'rgba(26,115,232,0.08)'};color:${p.lat!=null?'#166534':'#1a73e8'};" onclick="openLocationPicker('${p.id}')">${wi('map-pin','📍',13)} ${p.lat!=null?'Edit Location':'Set Location'}</button>
          <button class="btn btn-sm"${_tourDeleteId} style="background:var(--grey-light);color:var(--charcoal);" onclick="confirmDelete('${p.id}')">${wi('trash-2','🗑',13)} Delete</button>
        </div>
      </div>
    </div>`;
  }).join('');
  renderMyPayments();

  // Activate Lucide SVG icons inside freshly-injected listing cards
  wiRender(); // + confetti burst on badges that have views
  requestAnimationFrame(() => {
    document.querySelectorAll('.my-listing-views-badge:not(.views-zero)').forEach((badge, i) => {
      const delay = i * 180; // stagger if multiple listings
      setTimeout(() => {
        // Entrance animation
        badge.classList.remove('do-entrance');
        void badge.offsetWidth; // reflow
        badge.classList.add('do-entrance');

        // Confetti burst — 3 waves, each 600ms apart
        const colors = ['#ffd700','#ff6b6b','#4ecdc4','#45b7d1','#96ceb4','#ff9ff3','#ffeaa7','#fd79a8'];
        function spawnBurst(waveDelay) {
          setTimeout(() => {
            for (let c = 0; c < 8; c++) {
              const dot = document.createElement('span');
              dot.className = 'views-confetti-dot';
              dot.style.background = colors[c % colors.length];
              dot.style.left = (8 + c * 11) + '%';
              dot.style.animationDelay = (c * 55) + 'ms';
              dot.style.animationDuration = (650 + Math.random() * 350) + 'ms';
              badge.appendChild(dot);
              setTimeout(() => dot.remove(), 1300);
            }
          }, waveDelay);
        }
        spawnBurst(0);    // wave 1 — immediate
        spawnBurst(600);  // wave 2 — 600ms later
        spawnBurst(1200); // wave 3 — 1200ms later
      }, delay);
    });
  });

  // Restart the countdown ticker after DOM re-render
  setTimeout(startCdTicker, 50);

  // ── Auto-start onboarding tour for new landlords ──
  // Only fires when listing cards are in the DOM (myProps.length > 0).
  // wtMaybeAutoStart checks: first-time-ever (auto-play) vs already-seen (show replay btn).
  if (typeof wtMaybeAutoStart === 'function') setTimeout(wtMaybeAutoStart, 700);
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}


// ── TENANT PREVIEW (landlord sees exactly what tenants will see once live) ──
function buildTenantListingCard(p, isOwner) {
  const hasImgs  = p.images && p.images.length > 0;
  const imgCount = hasImgs ? p.images.length : 0;
  const firstImg = hasImgs ? p.images[0] : '';
  // Owner and non-owner both tap image to VIEW (lightbox); owner has Edit Photos button in the bar
  const imgOnClick = `lbOpenFromCard(event,'${escAttr(p.id)}')`;
  const imgTitle = 'Tap to view photos';
  return `
    <div class="listing-card" style="max-width:380px;margin:0 auto;">
      <div class="listing-img" style="position:relative;overflow:hidden;cursor:pointer;"
        onclick="${imgOnClick}"
        title="${imgTitle}">
        ${hasImgs
          ? `<img src="${firstImg}"
               style="width:100%;aspect-ratio:4/4;object-fit:cover;display:block;"
               loading="lazy" alt="${escHtml(p.title)}">`
          : `<div style="width:100%;aspect-ratio:4/4;display:flex;align-items:center;justify-content:center;font-size:5rem;background:linear-gradient(135deg,#dde8ea,#b2cdd1);">${TYPE_EMOJI[p.type]||'🏠'}</div>`
        }
        <div class="listing-type-badge" style="${p.isCommercial ? 'background:rgba(120,53,15,0.88);' : ''}">
          ${TYPE_EMOJI[p.type] || ''} ${p.type}
        </div>
        ${p.isCommercial
          ? `<div style="position:absolute;top:0;left:0;background:var(--gold);color:var(--charcoal);font-size:0.62rem;font-weight:900;padding:3px 10px 3px 8px;border-radius:0 0 10px 0;letter-spacing:0.5px;text-transform:uppercase;">COMMERCIAL</div>`
          : ''}
        ${imgCount > 1
          ? `<div style="position:absolute;bottom:14px;right:14px;z-index:3;background:rgba(0,0,0,0.65);backdrop-filter:blur(3px);color:#fff;font-size:0.72rem;font-weight:800;padding:5px 11px;border-radius:20px;display:flex;align-items:center;gap:5px;">
               📷 <span>1 / ${imgCount}</span>
             </div>`
          : imgCount === 1 ? `<div style="position:absolute;bottom:14px;right:14px;z-index:3;background:rgba(0,0,0,0.5);color:#fff;font-size:0.7rem;font-weight:700;padding:4px 10px;border-radius:20px;">📷 1 photo</div>` : ''
        }
        ${hasImgs ? `<div class="img-tap-hint">Tap to view${imgCount > 1 ? ' all ' + imgCount + ' photos' : ''}</div>` : ''}
      </div>
      <div class="listing-body">
        <div class="listing-title">${escHtml(p.title)}</div>
        <div class="listing-area">
          📍 ${escHtml(p.area)}${p.country && p.country !== 'Papua New Guinea' ? ' &nbsp;·&nbsp; ' + escHtml(p.country) : ''}${p.province ? ' &nbsp;·&nbsp; ' + escHtml(p.province) : ''}
        </div>
        <div class="listing-published">
          🗓️ Published: ${formatPublishedDate(p.publishedAt || p.date)}
          <span class="pub-time-ago">🕐 ${timeAgo(p.publishedAt || p.date)}</span>
        </div>
        <div class="listing-price">
          ${buildPriceBlockHTML(p)}
          ${p.isCommercial && p.utilities
            ? `<span style="font-size:0.7rem;color:var(--grey);margin-left:6px;">· utilities ${p.utilities === 'Included' ? '✓ incl.' : p.utilities === 'Excluded' ? 'excl.' : 'partial'}</span>`
            : ''}
        </div>
        <div class="listing-features">
          ${p.isCommercial
            ? `${p.floorArea ? `<span class="listing-feature">📐 ${p.floorArea} sqm</span>` : ''}
               ${p.carParks && p.carParks !== 'None' ? `<span class="listing-feature">🚗 ${p.carParks} park${p.carParks === '1' ? '' : 's'}</span>` : ''}
               ${p.condition ? `<span class="listing-feature">🏗️ ${escHtml(p.condition)}</span>` : ''}
               ${p.leaseTerm ? `<span class="listing-feature">📋 ${escHtml(p.leaseTerm)}</span>` : ''}`
            : `${p.beds ? `<span class="listing-feature">🛏️ ${p.beds === 'Studio' ? 'Studio' : p.beds + ' Bed' + (p.beds === '1' ? '' : 's')}</span>` : ''}
               ${p.baths ? `<span class="listing-feature">🚿 ${p.baths} Bath${p.baths === '1' ? '' : 's'}</span>` : ''}`
          }
        </div>
        ${availBadgeHTML(p.availability, p.type)}
        ${availBarHTML(p.availability, p.type)}
        ${p.availability && p.availability.note && !/^\d+$/.test(String(p.availability.note).trim())
          ? `<div style="font-size:0.8rem;color:var(--teal);font-weight:600;margin-bottom:12px;padding:8px 12px;background:rgba(13,92,99,0.06);border-radius:8px;border-left:3px solid var(--teal);line-height:1.5;">
               📌 ${escHtml(p.availability.note)}
             </div>`
          : ''}
        ${p.desc
          ? `<div style="font-size:0.85rem;color:var(--grey);line-height:1.6;margin-bottom:14px;">
               ${escHtml(p.desc)}
             </div>`
          : ''}
        <div class="listing-footer">
          <div class="listing-contact">
            <div class="listing-contact-avatar">🏠</div>
            <span>Verified Owner</span>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;width:100%;">
            ${(p.address || (p.lat != null && p.lng != null))
              ? `<a class="btn btn-sm" style="background:#1a73e8;color:#fff;text-decoration:none;border-radius:20px;padding:8px 14px;font-size:0.8rem;white-space:nowrap;"
                   href="${buildMapsUrl(p.address, p.area, p.lat, p.lng)}" target="_blank" rel="noopener">
                   ${getAppearance().dirBtn || '🗺️ Directions'}
                 </a>`
              : ''}
            <button class="btn btn-gold btn-sm" style="border-radius:20px;padding:8px 16px;font-size:0.82rem;white-space:nowrap;"
              onclick="showContact('${escAttr(p.landlordName)}','${escAttr(p.landlordPhone)}','${escAttr(p.landlordEmail||'')}','${escAttr(p.title)}','${escAttr(p.address||'')}','${escAttr(p.area)}',${p.lat!=null?p.lat:'null'},${p.lng!=null?p.lng:'null'})">
              ${getAppearance().contactBtn || '📞 Contact'}
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
}

// ── Track which property is being previewed (for edit-images shortcut) ──
let _previewPropId = null;
let _editImagesPropId = null;
let _editImagesNewQueue = []; // freshly uploaded base64 strings (not yet saved)
let _editImagesPendingReads = 0;

function previewAsTenant(id) {
  const props = getProps();
  const p = props.find(pr => pr.id === id);
  if (!p) { showToast('Listing not found.'); return; }
  _previewPropId = id;

  // Build preview card — inject tappable "Edit Photos" overlay on the image if owner
  const isOwner = currentUser && p.landlordId === currentUser.id;
  document.getElementById('tenant-preview-card').innerHTML = `<div style="max-width:380px;margin:0 auto;">${rentCardFromProp(p, 0, {mediaClick: `dashOpenPhotos('${escAttr(p.id)}')`, detailCall: 'void 0', contactCall: ''})}</div>`;

  // Show / update the Edit Photos bar
  const bar = document.getElementById('preview-edit-photos-bar');
  const lbl = document.getElementById('preview-photo-count-label');
  if (isOwner) {
    const cnt = (p.images || []).length;
    lbl.textContent = cnt === 0 ? 'No photos yet' : cnt + ' photo' + (cnt > 1 ? 's' : '');
    bar.style.display = 'flex';
  } else {
    bar.style.display = 'none';
  }

  openModal('tenant-preview-modal');
}

// Called from the "Edit Photos" button in the preview bar OR from tapping the image
function openEditImagesFromPreview() {
  if (!_previewPropId) return;
  openEditImagesModal(_previewPropId);
}

// ── Open the edit-images modal for a given listing ───────────────────
function openEditImagesModal(propId) {
  const props = getProps();
  const p = props.find(pr => pr.id === propId);
  if (!p) { showToast('Listing not found.'); return; }

  _editImagesPropId = propId;
  _editImagesNewQueue = [];

  // Subtitle
  document.getElementById('edit-images-modal-subtitle').textContent = p.title;

  // Render current images
  _editImagesRenderCurrent(p.images || []);

  // Clear new-images area
  document.getElementById('edit-images-new-grid').innerHTML = '';
  document.getElementById('edit-images-count').style.display = 'none';
  document.getElementById('edit-images-count').textContent = '';
  document.getElementById('edit-images-processing').style.display = 'none';
  const saveBtn = document.getElementById('edit-images-save-btn');
  saveBtn.disabled = false;
  saveBtn.textContent = '💾 Save Photos';
  // Reset file input
  const inp = document.getElementById('edit-images-input');
  if (inp) inp.value = '';

  openModal('edit-images-modal');
}

// Render current photos grid with delete buttons
function _editImagesRenderCurrent(images) {
  const grid = document.getElementById('edit-images-current-grid');
  const noPhotos = document.getElementById('edit-images-no-photos');

  if (!images || images.length === 0) {
    grid.innerHTML = '';
    noPhotos.style.display = 'block';
    return;
  }
  noPhotos.style.display = 'none';

  grid.innerHTML = images.map((src, i) => `
    <div id="ei-cur-${i}" style="position:relative;display:inline-block;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.12);">
      <img src="${src}" style="width:90px;height:70px;object-fit:cover;display:block;" alt="Photo ${i+1}">
      <button onclick="editImagesDeleteCurrent(${i})"
        style="position:absolute;top:3px;right:3px;background:rgba(220,38,38,0.9);color:#fff;border:none;border-radius:50%;width:20px;height:20px;font-size:0.65rem;font-weight:900;cursor:pointer;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;">✕</button>
      ${i === 0 ? '<div style="position:absolute;bottom:0;left:0;right:0;background:rgba(13,92,99,0.75);color:#fff;font-size:0.6rem;font-weight:700;text-align:center;padding:2px;">COVER</div>' : ''}
    </div>
  `).join('');
}

// Delete one current image (marks in-memory; committed on Save)
let _editImagesDeleted = new Set(); // indices to delete

function editImagesDeleteCurrent(idx) {
  const props = getProps();
  const p = props.find(pr => pr.id === _editImagesPropId);
  if (!p) return;

  // Remove immediately from the live list and re-render
  const imgs = [...(p.images || [])];
  imgs.splice(idx, 1);

  // Update in storage immediately so re-renders are consistent
  saveListingImages(_editImagesPropId, imgs);
  const all = getProps();
  const updated = all.find(pr => pr.id === _editImagesPropId);
  if (updated) updated.images = imgs;
  saveProps(all.map(pr => pr.id === _editImagesPropId ? { ...pr, images: imgs } : pr));

  _editImagesRenderCurrent(imgs);

  // Update count label in preview bar
  const lbl = document.getElementById('preview-photo-count-label');
  if (lbl) {
    const cnt = imgs.length;
    lbl.textContent = cnt === 0 ? 'No photos yet' : cnt + ' photo' + (cnt > 1 ? 's' : '');
  }
  showToast('🗑️ Photo removed.', 'success');
}

// Handle new file uploads inside the edit modal
function editImagesHandleUpload(e) {
  const files = Array.from(e.target.files);
  if (!files.length) return;

  const newGrid = document.getElementById('edit-images-new-grid');
  const saveBtn = document.getElementById('edit-images-save-btn');
  const procEl  = document.getElementById('edit-images-processing');

  saveBtn.disabled = true;
  procEl.style.display = 'block';

  const TARGET = 180 * 1024;

  files.forEach(file => {
    if (!file.type.startsWith('image/')) return;
    _editImagesPendingReads++;

    const reader = new FileReader();
    reader.onload = ev => {
      const img = new Image();
      img.onload = () => {
        // Same compression pipeline as the main form
        let MAX = 800, quality = 0.65, dataUrl = '';
        for (let pass = 0; pass < 6; pass++) {
          let w = img.width, h = img.height;
          if (w > MAX || h > MAX) {
            if (w > h) { h = Math.round(h * MAX / w); w = MAX; }
            else       { w = Math.round(w * MAX / h); h = MAX; }
          }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, w, h);
          ctx.drawImage(img, 0, 0, w, h);
          dataUrl = canvas.toDataURL('image/jpeg', quality);
          if (Math.round(dataUrl.length * 0.75) <= TARGET) break;
          MAX = Math.round(MAX * 0.80);
          quality = Math.max(0.40, quality - 0.08);
        }

        _editImagesNewQueue.push(dataUrl);
        _editImagesPendingReads = Math.max(0, _editImagesPendingReads - 1);

        // Render thumbnail with remove option
        const wrap = document.createElement('div');
        wrap.style.cssText = 'position:relative;display:inline-block;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.12);';
        const thumb = document.createElement('img');
        thumb.src = dataUrl;
        thumb.style.cssText = 'width:90px;height:70px;object-fit:cover;display:block;';
        const rmBtn = document.createElement('button');
        rmBtn.textContent = '✕';
        rmBtn.style.cssText = 'position:absolute;top:3px;right:3px;background:rgba(220,38,38,0.9);color:#fff;border:none;border-radius:50%;width:20px;height:20px;font-size:0.65rem;font-weight:900;cursor:pointer;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;';
        rmBtn.onclick = () => {
          const qi = _editImagesNewQueue.indexOf(dataUrl);
          if (qi > -1) _editImagesNewQueue.splice(qi, 1);
          wrap.remove();
          _editImagesUpdateCount();
        };
        wrap.appendChild(thumb);
        wrap.appendChild(rmBtn);
        newGrid.appendChild(wrap);
        _editImagesUpdateCount();

        if (_editImagesPendingReads <= 0) {
          saveBtn.disabled = false;
          procEl.style.display = 'none';
        }
      };
      img.onerror = () => {
        _editImagesPendingReads = Math.max(0, _editImagesPendingReads - 1);
        if (_editImagesPendingReads <= 0) {
          saveBtn.disabled = false;
          procEl.style.display = 'none';
        }
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });
  e.target.value = '';
}

function _editImagesUpdateCount() {
  const el = document.getElementById('edit-images-count');
  if (_editImagesNewQueue.length > 0) {
    el.textContent = _editImagesNewQueue.length + ' new photo' + (_editImagesNewQueue.length > 1 ? 's' : '') + ' ready to add ✅';
    el.style.display = 'block';
  } else {
    el.style.display = 'none';
  }
}

// Commit: merge current (already updated) images + new queue, then save
function editImagesSave() {
  if (_editImagesPendingReads > 0) {
    showToast('⏳ Still processing photos — please wait.', '');
    return;
  }
  const saveBtn = document.getElementById('edit-images-save-btn');
  saveBtn.disabled = true;
  saveBtn.textContent = '💾 Saving…';

  const allProps = getProps();
  const p = allProps.find(pr => pr.id === _editImagesPropId);
  if (!p) { showToast('Listing not found.', 'error'); return; }

  const merged = [...(p.images || []), ..._editImagesNewQueue];
  p.images = merged;

  saveProps(allProps.map(pr => pr.id === _editImagesPropId ? p : pr));

  // Refresh preview bar count
  const lbl = document.getElementById('preview-photo-count-label');
  if (lbl) {
    const cnt = merged.length;
    lbl.textContent = cnt === 0 ? 'No photos yet' : cnt + ' photo' + (cnt > 1 ? 's' : '');
  }

  // Refresh the preview card if still open
  if (_previewPropId === _editImagesPropId) {
    const refreshed = getProps().find(pr => pr.id === _editImagesPropId);
    if (refreshed) {
      const isOwner = currentUser && refreshed.landlordId === currentUser.id;
      document.getElementById('tenant-preview-card').innerHTML = buildTenantListingCard(refreshed, isOwner);
    }
  }

  // Refresh dashboard listing rows
  renderDashboard();

  showToast('✅ Photos updated successfully!', 'success');
  closeModal('edit-images-modal');
  saveBtn.disabled = false;
  saveBtn.textContent = '💾 Save Photos';
  _editImagesNewQueue = [];
}

// ── EXACT LOCATION PIN PICKER (Leaflet, no API key needed) ──────────────
let pinPickMap = null;
let pinPickMarker = null;
let pinPickPropId = null;
let pinPickLat = null;
let pinPickLng = null;

// ── PRE-PUBLISH location pin (set inside the Post modal BEFORE saving) ──
let _prePublishLat = null;
let _prePublishLng = null;
let _prePublishMode = false; // true while the picker is open for a not-yet-saved listing

let pinPickStreetLayer = null;
let pinPickSatelliteLayer = null;

// Default center: Port Moresby, PNG — used when a listing has no coords yet
const PNG_DEFAULT_CENTER = [-9.4438, 147.1803];

const LS_PIN_GUIDE_SEEN = 'wampac_pin_guide_seen';
let pinGuideStep = 0; // 0 = not showing, 1 = step 1, 2 = step 2

// ── PRE-PUBLISH: open the location picker for a listing not yet saved ──
function openPrePublishLocationPicker() {
  _prePublishMode = true;
  pinPickPropId   = '__pre_publish__';
  pinPickLat      = _prePublishLat;
  pinPickLng      = _prePublishLng;

  if (typeof hideGeoPermHelp === 'function') hideGeoPermHelp();
  openModal('location-pin-modal');
  updatePinUI();

  setTimeout(() => {
    initPinPickMap(pinPickLat, pinPickLng);
    if (pinPickLat == null || pinPickLng == null) {
      detectGpsLocation(/* forceOverride */ false);
    }
    if (typeof startLandlordLocationDemo === 'function') {
      startLandlordLocationDemo();
    } else {
      startPinGuide(false);
    }
  }, 80);
}

// ── PRE-PUBLISH: reflect the saved pin (or lack of one) in the post form ──
function _updatePrePublishBadge() {
  const btn    = document.getElementById('pre-publish-location-btn');
  const badge  = document.getElementById('pre-publish-location-badge');
  const coords = document.getElementById('pre-publish-location-coords');
  const hasPin = _prePublishLat != null && _prePublishLng != null;

  if (badge) badge.style.display = hasPin ? 'inline-flex' : 'none';
  if (btn) {
    btn.innerHTML = hasPin
      ? '<span style="font-size:1.1rem;">📍</span> Edit Location'
      : '<span style="font-size:1.1rem;">📍</span> Set Exact Location';
  }
  if (coords) {
    if (hasPin) {
      coords.textContent = '📌 ' + _prePublishLat.toFixed(6) + ', ' + _prePublishLng.toFixed(6);
      coords.style.display = 'block';
    } else {
      coords.style.display = 'none';
    }
  }
}

// ── SALES ADMIN location pin ──────────────────────────────────────
let _salesAdminLat = null;
let _salesAdminLng = null;

function openSalesAdminLocationPicker() {
  _prePublishMode = false;
  pinPickPropId   = '__sales_admin__';
  pinPickLat      = _salesAdminLat;
  pinPickLng      = _salesAdminLng;

  if (typeof hideGeoPermHelp === 'function') hideGeoPermHelp();
  openModal('location-pin-modal');
  updatePinUI();

  setTimeout(() => {
    initPinPickMap(pinPickLat, pinPickLng);
    if (pinPickLat == null || pinPickLng == null) {
      detectGpsLocation(false);
    }
    if (typeof startLandlordLocationDemo === 'function') {
      startLandlordLocationDemo();
    } else {
      startPinGuide(false);
    }
  }, 80);
}

function _updateSalesAdminLocationBadge() {
  const btn    = document.getElementById('sa-sales-location-btn');
  const badge  = document.getElementById('sa-sales-location-badge');
  const coords = document.getElementById('sa-sales-location-coords');
  const hasPin = _salesAdminLat != null && _salesAdminLng != null;

  if (badge) badge.style.display = hasPin ? 'inline-flex' : 'none';
  if (btn) {
    btn.innerHTML = (hasPin
      ? '<span style="font-size:1.1rem;">📍</span> Edit Location'
      : '<span style="font-size:1.1rem;">📍</span> Set Exact Location');
  }
  if (coords) {
    if (hasPin) {
      coords.textContent = '📌 ' + _salesAdminLat.toFixed(6) + ', ' + _salesAdminLng.toFixed(6);
      coords.style.display = 'block';
    } else {
      coords.style.display = 'none';
    }
  }
}

// ── PRE-PUBLISH: clear pin state so the next new listing starts fresh ──
function resetPrePublishLocation() {
  _prePublishLat  = null;
  _prePublishLng  = null;
  _prePublishMode = false;
  _updatePrePublishBadge();
}

function openLocationPicker(propId) {
  const props = getProps();
  const p = props.find(pr => pr.id === propId);
  if (!p) { showToast('Listing not found.'); return; }

  pinPickPropId = propId;
  pinPickLat = (p.lat != null) ? p.lat : null;
  pinPickLng = (p.lng != null) ? p.lng : null;

  if (typeof hideGeoPermHelp === 'function') hideGeoPermHelp();
  openModal('location-pin-modal');
  updatePinUI();

  // Defer map init until modal is visible — Leaflet needs a sized, visible container
  setTimeout(() => {
    initPinPickMap(pinPickLat, pinPickLng);
    // Only auto-detect GPS for a listing that has no saved pin yet —
    // never silently override a location the landlord already set.
    if (pinPickLat == null || pinPickLng == null) {
      detectGpsLocation(/* forceOverride */ false);
    }
    // Every time this opens: play the animated finger walk-through
    // (suburb → satellite → zoom controls → rooftop → pin → save).
    // A real tap/scroll from the landlord at any point cancels it
    // instantly and hands the map straight back to them. The
    // "Show me how" button is also available any time as a manual replay.
    if (typeof startLandlordLocationDemo === 'function') {
      startLandlordLocationDemo();
    } else {
      startPinGuide(false);
    }
  }, 80);
}

// ── COACH-MARK GUIDE: Map view (find suburb) → Satellite view (find roof) ──
function startPinGuide(isReplay) {
  pinGuideStep = 1;
  renderPinGuideStep();
  if (isReplay) showToast('Follow the 2 steps below 👇', 'success');
}

function renderPinGuideStep() {
  const box = document.getElementById('pin-guide-box');
  if (!box) return;

  if (pinGuideStep === 1) {
    // Switch the live map to street/Map view so it visually matches the instruction
    if (pinPickMap && pinPickStreetLayer && pinPickSatelliteLayer && !pinPickMap.hasLayer(pinPickStreetLayer)) {
      pinPickMap.removeLayer(pinPickSatelliteLayer);
      pinPickStreetLayer.addTo(pinPickMap);
    }
    box.innerHTML = `
      <div class="pin-guide">
        <div class="pin-guide-step">Step 1 of 2</div>
        <div class="pin-guide-text">🗺️ This is <strong>Map view</strong> — use it first to find your suburb, street and area, just like you would with regular directions.</div>
        <div class="pin-guide-footer">
          <div class="pin-guide-dots"><span class="pin-guide-dot active"></span><span class="pin-guide-dot"></span></div>
          <div class="pin-guide-btns">
            <button type="button" class="pin-guide-skip" onclick="dismissPinGuide()">Skip</button>
            <button type="button" class="pin-guide-next" onclick="advancePinGuide()">Next →</button>
          </div>
        </div>
      </div>`;
  } else if (pinGuideStep === 2) {
    // Switch the live map to satellite view to match step 2's instruction
    if (pinPickMap && pinPickStreetLayer && pinPickSatelliteLayer && !pinPickMap.hasLayer(pinPickSatelliteLayer)) {
      pinPickMap.removeLayer(pinPickStreetLayer);
      pinPickSatelliteLayer.addTo(pinPickMap);
    }
    box.innerHTML = `
      <div class="pin-guide">
        <div class="pin-guide-step">Step 2 of 2</div>
        <div class="pin-guide-text">🛰️ Now switch to <strong>Satellite view</strong> — zoom in until you can see actual rooftops, then tap directly on your property's roof to drop the pin.</div>
        <div class="pin-guide-footer">
          <div class="pin-guide-dots"><span class="pin-guide-dot"></span><span class="pin-guide-dot active"></span></div>
          <div class="pin-guide-btns">
            <button type="button" class="pin-guide-skip" onclick="dismissPinGuide()">Skip</button>
            <button type="button" class="pin-guide-next" onclick="advancePinGuide()">Got it ✓</button>
          </div>
        </div>
      </div>`;
  }
}

function advancePinGuide() {
  if (pinGuideStep === 1) {
    pinGuideStep = 2;
    renderPinGuideStep();
  } else {
    dismissPinGuide();
  }
}

function dismissPinGuide() {
  // If dismissed during step 1 (map was forced to Map view), restore the
  // normal Satellite default rather than leaving it on Map view.
  if (pinGuideStep === 1 && pinPickMap && pinPickStreetLayer && pinPickSatelliteLayer && pinPickMap.hasLayer(pinPickStreetLayer)) {
    pinPickMap.removeLayer(pinPickStreetLayer);
    pinPickSatelliteLayer.addTo(pinPickMap);
  }
  pinGuideStep = 0;
  const box = document.getElementById('pin-guide-box');
  if (box) box.innerHTML = '';
  _LS.setItem(LS_PIN_GUIDE_SEEN, '1');
}

// ── Browser-specific manual steps for re-enabling a blocked location
// permission. No website can re-open the browser's own permission prompt
// once it's been denied — that's a deliberate browser security boundary,
// not something missing from this app — so the best we can do is tell
// the landlord exactly where to look in their specific browser.
function getGeoPermHelpSteps() {
  const ua = navigator.userAgent || '';
  const isIOS     = /iPhone|iPad|iPod/.test(ua);
  const isAndroid = /Android/.test(ua);
  const isSamsung = /SamsungBrowser/.test(ua);
  const isFirefox = /Firefox/.test(ua);
  const isEdge    = /Edg\//.test(ua);
  const isChrome  = /Chrome/.test(ua) && !isEdge && !isSamsung;
  const isSafari  = /Safari/.test(ua) && !isChrome && !isEdge && !isSamsung && !isFirefox;

  if (isIOS) {
    // Same steps whether it's Safari or Chrome-on-iOS — iOS controls site
    // location access from one place regardless of which browser app it is.
    return [
      'Open the iPhone/iPad <strong>Settings</strong> app',
      'Scroll down and tap <strong>Safari</strong> (or your browser app, e.g. Chrome)',
      'Tap <strong>Location</strong> and choose <strong>Allow</strong> (or "Ask Next Time")',
      'Come back here and tap <strong>Try Again</strong> below'
    ];
  }
  if (isSamsung) {
    return [
      'Tap the <strong>⋮</strong> menu in Samsung Internet, then <strong>Settings</strong>',
      'Tap <strong>Sites and downloads → Site permissions → Location</strong>',
      'Find this site in the blocked list and switch it to <strong>Allow</strong>',
      'Come back here and tap <strong>Try Again</strong> below'
    ];
  }
  if (isAndroid && isChrome) {
    return [
      'Tap the <strong>🔒 lock icon</strong> (or ⓘ) in the address bar above',
      'Tap <strong>Permissions → Location</strong>',
      'Switch it to <strong>Allow</strong>',
      'Come back here and tap <strong>Try Again</strong> below'
    ];
  }
  if (isFirefox) {
    return [
      'Tap the <strong>🔒 lock icon</strong> (or ⓘ) in the address bar above',
      'Tap <strong>Permissions</strong>, find <strong>Location</strong>',
      'Clear the block, then choose <strong>Allow</strong> when asked again',
      'Come back here and tap <strong>Try Again</strong> below'
    ];
  }
  if (isEdge) {
    return [
      'Click the <strong>🔒 lock icon</strong> in the address bar above',
      'Click <strong>Permissions for this site → Location</strong>',
      'Set it to <strong>Allow</strong>',
      'Come back here and click <strong>Try Again</strong> below'
    ];
  }
  if (isChrome) {
    return [
      'Click the <strong>🔒 lock icon</strong> (or ⓘ) in the address bar above',
      'Click <strong>Site settings</strong>, find <strong>Location</strong>',
      'Change it from "Blocked" to <strong>Allow</strong>',
      'Come back here and click <strong>Try Again</strong> below'
    ];
  }
  if (isSafari) {
    return [
      'In the Safari menu bar, go to <strong>Safari → Settings for This Website</strong>',
      'Set <strong>Location</strong> to <strong>Allow</strong>',
      'Come back here and click <strong>Try Again</strong> below'
    ];
  }
  // Generic fallback for any browser we didn't specifically detect
  return [
    'Look for a <strong>🔒 lock</strong> or <strong>ⓘ</strong> icon in your address bar',
    'Open its site permissions and find <strong>Location</strong>',
    'Change it to <strong>Allow</strong>',
    'Come back here and tap <strong>Try Again</strong> below, or just tap your property\'s roof on the map'
  ];
}

function showGeoPermHelp() {
  const help = document.getElementById('geo-perm-help');
  const list = document.getElementById('geo-perm-steps');
  if (!help || !list) return;
  list.innerHTML = getGeoPermHelpSteps().map(s => `<li>${s}</li>`).join('');
  help.style.display = 'block';
  help.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function hideGeoPermHelp() {
  const help = document.getElementById('geo-perm-help');
  if (help) help.style.display = 'none';
}

// Manual button — landlord deliberately asked for this, so it always overrides
// whatever pin is currently on the map.
function tryAutoDetectLocation() {
  hideGeoPermHelp();
  detectGpsLocation(/* forceOverride */ true);
}

function detectGpsLocation(forceOverride) {
  const display = document.getElementById('pin-coords-display');
  if (!navigator.geolocation) {
    if (forceOverride) showToast('Location services aren\'t available on this device/browser.', 'error');
    return;
  }

  if (forceOverride) display.textContent = '📡 Finding your current location…';

  navigator.geolocation.getCurrentPosition(
    (pos) => {
      // For the automatic (on-open) call, skip if the landlord already tapped
      // a pin manually while we were waiting on GPS permission.
      if (!forceOverride && (pinPickLat != null || pinPickLng != null)) return;
      hideGeoPermHelp();
      const lat = pos.coords.latitude;
      const lng = pos.coords.longitude;
      pinPickMap.setView([lat, lng], 18);
      placePinMarker(lat, lng);
      showToast('📍 Pinned your current location — drag or tap elsewhere if this isn\'t the property.', 'success');
    },
    (err) => {
      if (forceOverride) {
        // err.code: 1 = PERMISSION_DENIED, 2 = POSITION_UNAVAILABLE, 3 = TIMEOUT
        // Only the permission case has a real fix the landlord can act on —
        // for the other two, "check your settings" wouldn't help, so keep
        // pointing them at the map instead.
        if (err && err.code === 1) {
          showGeoPermHelp();
        } else {
          showToast('Could not get your location right now. Just tap the map manually instead.', 'error');
        }
        if (display) updatePinUI();
      } else if (pinPickLat == null && pinPickLng == null) {
        updatePinUI();
      }
    },
    { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 }
  );
}

function initPinPickMap(lat, lng) {
  const center = (lat != null && lng != null) ? [lat, lng] : PNG_DEFAULT_CENTER;
  const zoom = (lat != null && lng != null) ? 18 : 12;

  if (pinPickMap) {
    // Reuse existing map instance, just recenter it
    pinPickMap.setView(center, zoom);
    if (pinPickMarker) { pinPickMap.removeLayer(pinPickMarker); pinPickMarker = null; }
    if (lat != null && lng != null) placePinMarker(lat, lng);
    pinPickMap.invalidateSize();
    return;
  }

  pinPickMap = L.map('location-pick-map').setView(center, zoom);

  pinPickStreetLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '© OpenStreetMap contributors'
  });

  pinPickSatelliteLayer = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 19,
    attribution: 'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics'
  });

  // Default to satellite — easiest way to actually spot the roofline/building
  // (the first-time guide will briefly switch to Map view for its Step 1)
  pinPickSatelliteLayer.addTo(pinPickMap);

  L.control.layers(
    { '🛰️ Satellite': pinPickSatelliteLayer, '🗺️ Map': pinPickStreetLayer },
    null,
    { position: 'topright', collapsed: false }
  ).addTo(pinPickMap);

  if (lat != null && lng != null) placePinMarker(lat, lng);

  pinPickMap.on('click', (e) => {
    placePinMarker(e.latlng.lat, e.latlng.lng);
  });

  setTimeout(() => pinPickMap.invalidateSize(), 100);
}

function placePinMarker(lat, lng) {
  pinPickLat = lat;
  pinPickLng = lng;
  if (pinPickMarker) {
    pinPickMarker.setLatLng([lat, lng]);
  } else {
    pinPickMarker = L.marker([lat, lng], { draggable: true }).addTo(pinPickMap);
    pinPickMarker.on('dragend', () => {
      const pos = pinPickMarker.getLatLng();
      pinPickLat = pos.lat;
      pinPickLng = pos.lng;
      updatePinUI();
    });
  }
  updatePinUI();
}

function updatePinUI() {
  const display = document.getElementById('pin-coords-display');
  const saveBtn = document.getElementById('save-pin-btn');

  if (pinPickLat != null && pinPickLng != null) {
    display.textContent = '📍 ' + pinPickLat.toFixed(6) + ', ' + pinPickLng.toFixed(6) + '  (drag pin to fine-tune)';
    saveBtn.disabled = false;
  } else {
    display.textContent = 'Tap anywhere on the map to drop a pin';
    saveBtn.disabled = true;
  }
}

function saveLocationPin() {
  if (pinPickLat == null || pinPickLng == null || !pinPickPropId) return;

  // ── Sale owner: pin for the listing form being filled in ────────────
  if (pinPickPropId === '__sales_owner__') {
    window._saleOwnerLat = pinPickLat;
    window._saleOwnerLng = pinPickLng;
    pinPickPropId = null;
    closeModal('location-pin-modal');
    if (typeof window.updateSaleOwnerLocationBadge === 'function') window.updateSaleOwnerLocationBadge();
    showToast('📍 Location pinned! Buyers will be able to get directions to it.', 'success');
    return;
  }

  // ── Sale owner: editing the pin of an existing sale listing ──────────
  if (typeof pinPickPropId === 'string' && pinPickPropId.indexOf('__sales_owner_edit__:') === 0) {
    const sid = pinPickPropId.split(':').slice(1).join(':');
    pinPickPropId = null;
    closeModal('location-pin-modal');
    if (typeof window.saleOwnerSavePin === 'function') window.saleOwnerSavePin(sid, pinPickLat, pinPickLng);
    return;
  }

  // ── Sales admin mode: save lat/lng to sales admin variables ─────────
  if (pinPickPropId === '__sales_admin__') {
    _salesAdminLat = pinPickLat;
    _salesAdminLng = pinPickLng;
    pinPickPropId  = null;
    closeModal('location-pin-modal');
    _updateSalesAdminLocationBadge();
    showToast('📍 Location pinned for sales property!', 'success');
    return;
  }

  // ── Pre-publish mode: the listing hasn't been saved yet ──────────────
  if (pinPickPropId === '__pre_publish__') {
    _prePublishLat  = pinPickLat;
    _prePublishLng  = pinPickLng;
    _prePublishMode = false;
    pinPickPropId   = null;
    closeModal('location-pin-modal');
    _updatePrePublishBadge();
    showToast('📍 Location pinned! It will be saved when you publish.', 'success');
    return;
  }

  // ── Normal mode: listing already exists in storage ────────────────────
  const props = getProps();
  const p = props.find(pr => pr.id === pinPickPropId);
  if (!p) { showToast('Listing not found.'); return; }

  p.lat = pinPickLat;
  p.lng = pinPickLng;
  saveProps(props);

  closeModal('location-pin-modal');
  renderDashboard();
  refreshAllGrids();
  // If the Super Admin listings table is on screen, refresh it too
  if (document.getElementById('sa-listings-tbody')) saRenderListings();
  showToast('✅ Exact location saved! Renters tapping Directions will go straight to this pin.', 'success');
}

// ══════════════════════════════════════════════════════════════════
//  LANDLORD LOCATION DEMO — animated finger walk-through
//  Suburb (Map view) → Satellite → zoom to rooftop → drop pin → Save
//  Plays automatically ONCE per browser the first time a landlord opens
//  the location picker on a listing with no pin yet. Any real tap,
//  scroll, or keypress cancels it immediately and hands the modal back.
// ══════════════════════════════════════════════════════════════════
(function () {

  // Demo target: Waigani, Port Moresby, NCD — a real, recognisable
  // suburb already in the AREAS list.
  const DEMO_SUBURB = { name: 'Waigani', lat: -9.417257, lng: 147.182903 };

  // The exact "rooftop" point the demo zooms in on and drops its pin at.
  // Fixed to a confirmed real building rooftop (previously this was looked
  // up dynamically via the OSM Overpass API, which could occasionally land
  // on open ground/bush when the lookup failed or picked the wrong nearby
  // footprint — using a known-good fixed coordinate avoids that entirely).
  const DEMO_ROOFTOP = { lat: -9.419806, lng: 147.182991 };

  let demoTimers = [];
  let demoCancelled = false;
  let demoRunning   = false;
  let tourInProgress = false; // true only while phase 2 (button tour) is active

  // Snapshot of the landlord's real pin state (if any) captured the instant
  // before the demo starts touching the map — used to restore things exactly
  // as they were once the demo ends, rather than leaving the demo's own
  // placeholder pin (at DEMO_ROOFTOP, a fixed demo-only coordinate) sitting
  // on the map looking like a confirmed location.
  let preDemoLat = null;
  let preDemoLng = null;

  let lpFinger = null;
  let lpRipple = null;
  const TIP_X = 16, TIP_Y = 4; // same fingertip offset logic as the tenant guide

  function ensureFingerEls() {
    if (lpFinger) return;
    lpFinger = document.createElement('div');
    lpFinger.id = 'lpd-finger-el';
    lpFinger.textContent = '👆';
    lpFinger.style.cssText = `
      position:fixed; z-index:100050; font-size:2rem; line-height:1; pointer-events:none;
      opacity:0; transition:none;
      filter:drop-shadow(0 4px 10px rgba(0,0,0,0.5));
      transform-origin:${TIP_X}px ${TIP_Y}px;
    `;
    document.body.appendChild(lpFinger);

    lpRipple = document.createElement('div');
    lpRipple.id = 'lpd-ripple-el';
    lpRipple.style.cssText = `
      position:fixed; z-index:100049; width:40px; height:40px;
      border-radius:50%; pointer-events:none; opacity:0;
      border:2.5px solid rgba(244,169,28,0.9);
      box-shadow:0 0 0 0 rgba(244,169,28,0.4);
      transform:scale(0); transition:none;
    `;
    document.body.appendChild(lpRipple);
  }

  function dwait(ms, fn) {
    const t = setTimeout(() => { if (!demoCancelled) fn(); }, ms);
    demoTimers.push(t);
  }
  function dclear() { demoTimers.forEach(clearTimeout); demoTimers = []; }

  function centreOf(el) {
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  }

  function moveFingerTo(x, y, cb) {
    lpFinger.style.transition =
      'left 0.55s cubic-bezier(0.34,1.4,0.64,1), top 0.55s cubic-bezier(0.34,1.4,0.64,1), opacity 0.3s';
    lpFinger.style.left = (x - TIP_X) + 'px';
    lpFinger.style.top  = (y - TIP_Y) + 'px';
    lpFinger.style.opacity = '1';
    dwait(580, cb);
  }

  function fingerTap(x, y, cb) {
    lpFinger.style.transition = 'transform 0.1s ease-in';
    lpFinger.style.transform  = 'scale(0.78)';

    lpRipple.style.transition = 'none';
    lpRipple.style.left = (x - 20) + 'px';
    lpRipple.style.top  = (y - 20) + 'px';
    lpRipple.style.opacity = '0';
    lpRipple.style.transform = 'scale(0)';
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (demoCancelled) return;
      lpRipple.style.transition = 'transform 0.5s ease-out, opacity 0.5s ease-out';
      lpRipple.style.transform  = 'scale(2.6)';
      lpRipple.style.opacity    = '1';
    }));

    dwait(150, () => {
      lpFinger.style.transition = 'transform 0.18s ease-out';
      lpFinger.style.transform  = 'scale(1)';
      lpRipple.style.opacity = '0';
      dwait(220, cb);
    });
  }

  function hideFingerD(cb) {
    lpFinger.style.transition = 'opacity 0.3s, top 0.3s';
    lpFinger.style.opacity = '0';
    lpFinger.style.top = (parseFloat(lpFinger.style.top || 0) - 30) + 'px';
    dwait(300, cb);
  }

  function setGuideText(html) {
    const box = document.getElementById('pin-guide-box');
    if (!box) return;
    box.innerHTML = `
      <div class="pin-guide">
        <div class="pin-guide-step" id="lpd-step-label">Watch &amp; learn</div>
        <div class="pin-guide-text">${html}</div>
      </div>`;
  }
  function setStepLabel(text) {
    const el = document.getElementById('lpd-step-label');
    if (el) el.textContent = text;
  }

  // ── Cancel the moment the landlord taps/scrolls for real ──────────
  // Always return to the app's actual default layer (Satellite — see
  // "Default to satellite" in initPinPickMap) whichever step the demo
  // was interrupted or finished on, so the landlord never gets left on
  // a layer the demo happened to be using mid-walkthrough.
  function resetToDefaultLayer() {
    if (pinPickStreetLayer && pinPickSatelliteLayer && pinPickMap &&
        !pinPickMap.hasLayer(pinPickSatelliteLayer)) {
      pinPickMap.removeLayer(pinPickStreetLayer);
      pinPickSatelliteLayer.addTo(pinPickMap);
    }
  }

  // Restore the landlord's real pin (or "no pin" empty state) exactly as it
  // was before the demo started — removes the demo's own placeholder marker
  // at DEMO_ROOFTOP and re-syncs pinPickLat/pinPickLng + the Save button/
  // coordinate display so nothing demo-related can accidentally get saved.
  // Restore the landlord's real pin (or "no pin" empty state) exactly as it
  // was before the demo started — removes the demo's own placeholder marker
  // at DEMO_ROOFTOP and re-syncs pinPickLat/pinPickLng + the Save button/
  // coordinate display so nothing demo-related can accidentally get saved.
  // `recenter`: pass true only when the demo finished on its own (so the
  // landlord isn't left staring at an unrelated neighbourhood); pass false
  // when a real tap interrupted it, since yanking the view away right as
  // they're about to tap their own roof would be counterproductive.
  function restorePreDemoPin(recenter) {
    if (pinPickMarker) {
      pinPickMap.removeLayer(pinPickMarker);
      pinPickMarker = null;
    }
    pinPickLat = preDemoLat;
    pinPickLng = preDemoLng;
    if (pinPickLat != null && pinPickLng != null) {
      // Landlord already had a real saved pin — put it back exactly.
      placePinMarker(pinPickLat, pinPickLng);
      if (recenter && pinPickMap) pinPickMap.flyTo([pinPickLat, pinPickLng], 18, { duration: 1 });
    } else {
      // No real pin yet — back to the genuine empty state
      // ("Tap anywhere on the map to drop a pin", Save disabled).
      if (typeof updatePinUI === 'function') updatePinUI();
      if (recenter && pinPickMap) pinPickMap.flyTo(PNG_DEFAULT_CENTER, 12, { duration: 1 });
    }
  }

  function cancelDemo() {
    if (demoCancelled || !demoRunning) return;
    demoCancelled = true;
    demoRunning   = false;
    dclear();
    if (lpFinger) { lpFinger.style.transition = 'opacity 0.2s'; lpFinger.style.opacity = '0'; }
    if (lpRipple) { lpRipple.style.transition = 'opacity 0.2s'; lpRipple.style.opacity = '0'; }
    // If phase 2 (the spotlight-card button tour) was running, tear it
    // down immediately — same overlay/card the dashboard tour uses.
    if (tourInProgress) {
      _wtActive = false;
      _wtOnEndOverride = null;
      if (typeof _wtHideOverlay === 'function') _wtHideOverlay();
      const wtCard = document.getElementById('wt-card');
      if (wtCard) wtCard.style.display = 'none';
      if (_wtResizeOb) { _wtResizeOb.disconnect(); _wtResizeOb = null; }
      window.removeEventListener('resize', _wtOnResize);
    }
    // Leave the map's pan/zoom exactly where it is — the landlord is taking
    // over, so don't yank the view out from under them — but do reset the
    // layer toggle back to the app's default, and remove the demo's own
    // placeholder pin so it can't be mistaken for a confirmed location.
    resetToDefaultLayer();
    restorePreDemoPin(false);
    const box = document.getElementById('pin-guide-box');
    if (box) box.innerHTML = tourInProgress
      ? `<div class="pin-guide"><div class="pin-guide-text">👍 No problem — go ahead and use any of the buttons below whenever you're ready.</div></div>`
      : `<div class="pin-guide"><div class="pin-guide-text">👍 Go ahead — tap your property's roof on the map to drop the pin.</div></div>`;

    if (tourInProgress) {
      // Phase 2 itself was what just got interrupted — the landlord has
      // now taken full control twice in a row, so respect that and don't
      // loop back into another tour.
      tourInProgress = false;
      return;
    }

    // The landlord interrupted the roof-pin walkthrough with a real touch —
    // rather than leaving them with nothing, roll straight into the
    // spotlight-card button tour so they still learn what the other
    // controls on this screen do. Give the reset message above a moment
    // to register.
    // (Uses a raw setTimeout, not dwait — dwait would see demoCancelled
    // still true at fire time and silently refuse to run.)
    setTimeout(startButtonTour, 1200);
  }

  ['pointerdown', 'touchstart', 'wheel', 'keydown'].forEach(evt => {
    document.addEventListener(evt, (e) => {
      if (!demoRunning) return;
      // Phase 2 (the spotlight-card button/layer tour) is compulsory — once
      // it starts, no real tap/scroll/keypress anywhere on screen should
      // stop it early. It only ever ends via its own "Skip tour" / "Got it →"
      // buttons (wtSkip()/wtNext()) or by running through all of its steps
      // naturally. The exemption below for the live Satellite/Map toggle is
      // therefore no longer load-bearing on its own, but is kept so taps
      // there are still routed to Leaflet's click handler rather than
      // swallowed silently.
      if (tourInProgress) return;
      // Ignore synthetic taps the demo fires at the map/controls itself —
      // those are dispatched programmatically (see simulateMapTap below)
      // and never reach a real input event, so any real event here is genuine.
      cancelDemo();
    }, { passive: true, capture: true });
  });

  // ── MAIN SEQUENCE ───────────────────────────────────────────────
  function runDemo() {
    if (demoCancelled) return;
    demoRunning = true;
    ensureFingerEls();

    const mapEl = document.getElementById('location-pick-map');
    if (!mapEl || !pinPickMap) { finishDemo(); return; }

    // Capture the real pin state exactly as it was before the demo touches
    // anything, so it can be restored once the demo ends.
    preDemoLat = pinPickLat;
    preDemoLng = pinPickLng;

    const TOTAL_STEPS = 5;

    setStepLabel('Step 1 of ' + TOTAL_STEPS);
    setGuideText('🗺️ First, use <strong>Map view</strong> to find your suburb — let\'s look for <strong>' + DEMO_SUBURB.name + '</strong>.');

    // Make sure we start on the street/Map layer to match the narration
    if (pinPickStreetLayer && pinPickSatelliteLayer && !pinPickMap.hasLayer(pinPickStreetLayer)) {
      pinPickMap.removeLayer(pinPickSatelliteLayer);
      pinPickStreetLayer.addTo(pinPickMap);
    }
    pinPickMap.setView(PNG_DEFAULT_CENTER, 12, { animate: false });

    dwait(900, () => {
      // Pan/zoom smoothly to the suburb — Leaflet's flyTo gives a nice "found it" feel
      pinPickMap.flyTo([DEMO_SUBURB.lat, DEMO_SUBURB.lng], 16, { duration: 1.4 });

      dwait(1700, () => {
        if (demoCancelled) return;
        const mc = centreOf(mapEl);
        moveFingerTo(mc.x, mc.y, () => {
          dwait(500, () => {

            // ── Step 2: switch to Satellite ──────────────────────────
            setStepLabel('Step 2 of ' + TOTAL_STEPS);
            setGuideText('🛰️ Now switch to <strong>Satellite view</strong> so you can actually see rooftops.');

            // Point at the real Satellite toggle in the layer control, then "tap" it
            const layerCtrl = mapEl.querySelector('.leaflet-control-layers');
            const satLabel  = layerCtrl ? Array.from(layerCtrl.querySelectorAll('label'))
                                .find(l => l.textContent.includes('Satellite')) : null;
            const satPos    = satLabel ? centreOf(satLabel) : centreOf(mapEl);

            moveFingerTo(satPos.x, satPos.y, () => {
              dwait(450, () => {
                fingerTap(satPos.x, satPos.y, () => {
                  if (pinPickStreetLayer && pinPickSatelliteLayer && !pinPickMap.hasLayer(pinPickSatelliteLayer)) {
                    pinPickMap.removeLayer(pinPickStreetLayer);
                    pinPickSatelliteLayer.addTo(pinPickMap);
                  }

                  dwait(500, () => {
                    if (demoCancelled) return;

                    // ── Step 3: show the zoom +/- buttons ────────────────
                    // Quick callout on the on-map zoom controls so landlords
                    // know they can fine-tune zoom by hand at any time, not
                    // just via pinch/scroll.
                    setStepLabel('Step 3 of ' + TOTAL_STEPS);
                    setGuideText('🔎 Use the <strong>+</strong> / <strong>−</strong> buttons here any time you want to zoom in or out manually.');

                    const zoomInBtn  = mapEl.querySelector('.leaflet-control-zoom-in');
                    const zoomOutBtn = mapEl.querySelector('.leaflet-control-zoom-out');

                    const afterZoomCallout = () => {
                      // ── Step 4: zoom in to rooftop level ───────────────
                      setStepLabel('Step 4 of ' + TOTAL_STEPS);
                      setGuideText('🔍 Zoom in close — right down to the actual <strong>rooftop</strong> of the property.');
                      pinPickMap.flyTo([DEMO_ROOFTOP.lat, DEMO_ROOFTOP.lng], 19, { duration: 1.3 });

                      dwait(1600, () => {
                        if (demoCancelled) return;

                        // ── Step 5: tap the roof to drop the pin ───────────
                        setStepLabel('Step 5 of ' + TOTAL_STEPS);
                        setGuideText('📍 Tap directly on the <strong>roof</strong> to drop your pin — drag it later to fine-tune.');

                        const roofPoint = pinPickMap.latLngToContainerPoint([DEMO_ROOFTOP.lat, DEMO_ROOFTOP.lng]);
                        const mapRect   = mapEl.getBoundingClientRect();
                        const roofX     = mapRect.left + roofPoint.x;
                        const roofY     = mapRect.top  + roofPoint.y;

                        moveFingerTo(roofX, roofY, () => {
                          dwait(550, () => {
                            fingerTap(roofX, roofY, () => {
                              // Demo-only pin: visual only, not yet saved as the real listing pin —
                              // the landlord still confirms with their own tap + Save below.
                              placePinMarker(DEMO_ROOFTOP.lat, DEMO_ROOFTOP.lng);

                              dwait(500, () => {
                                // Scroll the Save button into view first — it sits below
                                // the map and is often off-screen on mobile, so without
                                // this the finger would be positioned using coordinates
                                // for an element the landlord can't actually see yet.
                                const saveBtn = document.getElementById('save-pin-btn');
                                if (saveBtn) {
                                  saveBtn.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                  // Wait for the smooth scroll to finish, then re-measure
                                  // the button's position now that it's actually visible.
                                  dwait(650, () => {
                                    if (demoCancelled) return;
                                    const sp = centreOf(saveBtn);
                                    moveFingerTo(sp.x, sp.y, () => {
                                      dwait(500, () => {
                                        setGuideText('💾 Last step — tap <strong>Save This Location</strong> to lock it in!');
                                        hideFingerD(() => dwait(1600, finishDemo));
                                      });
                                    });
                                  });
                                } else {
                                  hideFingerD(() => dwait(1200, finishDemo));
                                }
                              });
                            });
                          });
                        });
                      });
                    };

                    if (zoomInBtn && zoomOutBtn) {
                      const inPos = centreOf(zoomInBtn);
                      // Point at "+" then actually tap it — pinPickMap.zoomIn()
                      // triggers the real Leaflet zoom animation, so the map
                      // visibly zooms in right as the finger lands.
                      moveFingerTo(inPos.x, inPos.y, () => {
                        dwait(420, () => {
                          fingerTap(inPos.x, inPos.y, () => {
                            pinPickMap.zoomIn(1);

                            dwait(550, () => {
                              if (demoCancelled) return;
                              const outPos = centreOf(zoomOutBtn);
                              // Then point at "−" right below it and actually tap it too —
                              // zoomOut() brings the view back out again.
                              moveFingerTo(outPos.x, outPos.y, () => {
                                dwait(420, () => {
                                  fingerTap(outPos.x, outPos.y, () => {
                                    pinPickMap.zoomOut(1);
                                    dwait(550, afterZoomCallout);
                                  });
                                });
                              });
                            });
                          });
                        });
                      });
                    } else {
                      // Zoom control not found for some reason — skip the callout gracefully
                      dwait(300, afterZoomCallout);
                    }
                  });
                });
              });
            });
          });
        });
      });
    });
  }

  // ── Finish after exactly one pass — leave the landlord in control ──
  function finishDemo() {
    if (demoCancelled) { demoRunning = false; return; }
    demoRunning = false;
    // Back to the app's default layer (Satellite — see "Default to
    // satellite" in initPinPickMap) and remove the demo's own placeholder
    // pin, so the landlord starts from a genuinely clean map rather than
    // one that looks like a location has already been picked for them.
    resetToDefaultLayer();
    restorePreDemoPin(true);
    const box = document.getElementById('pin-guide-box');
    if (box) box.innerHTML = `
      <div class="pin-guide">
        <div class="pin-guide-text">✅ That\'s it! Tap your real property\'s roof on the map below, then Save.</div>
      </div>`;

    // Roll straight into the second phase — a proper spotlight-card tour
    // (same visual style as the dashboard "Welcome to Wampac" tour) of the
    // other buttons on this screen that the roof-pin walkthrough above
    // never touches. Give the landlord a beat to read the message first.
    setTimeout(startButtonTour, 1500);
  }

  // ── PHASE 2: spotlight-card tour of the remaining buttons ──────────
  // Reuses the exact same tour engine as the dashboard onboarding tour
  // (gold spotlight ring + floating card with icon/title/description and
  // Skip / Got it buttons) — just pointed at the buttons the roof-pin
  // walkthrough above never touches. Never actually triggers a button's
  // real action (no GPS request, no opening Google Maps, etc; switching
  // layers is harmless to preview live, so the layer steps below DO let
  // the landlord actually tap them while the card is showing). Runs both
  // when phase 1 finishes naturally AND when a real touch interrupts
  // phase 1 partway through (see cancelDemo).

  // Finds the real Satellite/Map radio <label> inside the live Leaflet
  // layer control — same lookup Phase 1 already uses for its finger-tap.
  function findLayerLabel(matchText) {
    const mapEl = document.getElementById('location-pick-map');
    const layerCtrl = mapEl ? mapEl.querySelector('.leaflet-control-layers') : null;
    if (!layerCtrl) return null;
    return Array.from(layerCtrl.querySelectorAll('label'))
      .find(l => l.textContent.includes(matchText)) || null;
  }

  function wtGetLocationPinSteps() {
    return [
      {
        targetFn: () => findLayerLabel('Satellite'),
        icon: '🛰️',
        title: 'Satellite View',
        desc: 'Switch to Satellite to actually see rooftops up close — zoom in and tap directly on your property\'s roof to drop the pin in exactly the right spot.',
        position: 'below',
      },
      {
        targetFn: () => findLayerLabel('Map'),
        icon: '🗺️',
        title: 'Map View',
        desc: 'Switch to Map to see labeled streets and suburb names — handy for navigating to the right area before you zoom in on Satellite to find the exact rooftop.',
        position: 'below',
      },
      {
        targetFn: () => document.getElementById('pin-guide-replay-btn-el'),
        icon: '❓',
        title: 'Show Me How',
        desc: 'Replays this whole walkthrough any time you want a refresher on finding your property.',
        position: 'above',
      },
      {
        targetFn: () => document.getElementById('use-current-location-btn'),
        icon: '📡',
        title: 'Use My Current Location',
        desc: 'Standing at the property right now? Tap this to drop the pin using your phone\'s GPS instead of finding it on the map.',
        position: 'above',
      },
      {
        targetFn: () => document.getElementById('save-pin-btn'),
        icon: '💾',
        title: 'Save This Location',
        desc: 'This is the one that actually counts — once you\'ve dropped your pin, tap here to save it. It stays greyed out until a pin is set, so do this last after finding your property above.',
        position: 'above',
      }
    ];
  }

  // Bypasses the dwait()/demoCancelled guard on purpose — this is the
  // function responsible for clearing that flag, so it can't rely on a
  // helper that refuses to fire while the flag is still set.
  function startButtonTour() {
    demoCancelled = false;
    demoRunning   = true;
    tourInProgress = true;

    // Hand off to the shared tour engine (same one the dashboard uses).
    _wtSteps  = wtGetLocationPinSteps();
    _wtStep   = 0;
    _wtActive = true;
    // Tell the shared engine to call back into us when it ends, instead of
    // its normal dashboard-only wtEnd() behaviour (_LS flag,
    // replay button, etc — none of which apply inside this modal).
    _wtOnEndOverride = finishButtonTour;

    // Keep the spotlight/card aligned if the viewport changes mid-tour
    // (rotation, on-screen keyboard, etc) — same as wtStart() does.
    if (typeof _wtResizeOb !== 'undefined' && _wtResizeOb) _wtResizeOb.disconnect();
    if (typeof ResizeObserver !== 'undefined') {
      _wtResizeOb = new ResizeObserver(() => {
        if (!_wtActive) return;
        requestAnimationFrame(() => { if (typeof _wtRepositionCurrent === 'function') _wtRepositionCurrent(); });
      });
      _wtResizeOb.observe(document.body);
    }
    window.addEventListener('resize', _wtOnResize);

    _wtShowStep(0);
  }

  function finishButtonTour() {
    _wtOnEndOverride = null;
    if (demoCancelled) { demoRunning = false; return; }
    demoRunning = false;
    tourInProgress = false;
    const box = document.getElementById('pin-guide-box');
    if (box) box.innerHTML = `
      <div class="pin-guide">
        <div class="pin-guide-text">👍 That covers every button here — tap your real property\'s roof whenever you\'re ready.</div>
      </div>`;
  }

  // ── Public entry point, called from openLocationPicker() ──────────
  // Auto-plays EVERY time the location picker is opened (not just once) —
  // a real tap/scroll from the landlord cancels it instantly via cancelDemo()
  // above and hands the map straight back to them.
  window.startLandlordLocationDemo = function () {
    demoCancelled = false;
    demoRunning   = true; // armed now so an early tap during the warm-up delay still cancels cleanly
    tourInProgress = false;
    // In case a previous session left phase 2's spotlight/card showing
    // (e.g. modal was force-closed mid-tour), clear it before starting fresh.
    _wtActive = false;
    _wtOnEndOverride = null;
    if (typeof _wtHideOverlay === 'function') _wtHideOverlay();
    const wtCard0 = document.getElementById('wt-card');
    if (wtCard0) wtCard0.style.display = 'none';

    // Wait for the map to genuinely be ready (Leaflet + #location-pick-map
    // both present and sized) before kicking off, instead of a fixed delay —
    // on slower devices a flat timeout could fire before initPinPickMap()
    // has finished setting up the map.
    let attempts = 0;
    const tryStart = () => {
      if (demoCancelled) return;
      attempts++;
      const mapEl = document.getElementById('location-pick-map');
      if (mapEl && pinPickMap) {
        runDemo();
      } else if (attempts < 30) {
        // Keep polling every 150ms (up to ~4.5s) until the map is ready
        const t = setTimeout(tryStart, 150);
        demoTimers.push(t);
      }
      // If it never becomes ready within ~4.5s, give up quietly — the
      // landlord can still use "Show me how" manually any time.
    };
    dwait(500, tryStart);
  };

  // Manual replay — wired to the existing "❓ Show me how" button
  // (identical to startLandlordLocationDemo now that auto-play is unlimited,
  // kept as a separate name since other code calls it directly by that name)
  window.replayLandlordLocationDemo = function () {
    dclear();
    demoCancelled = false;
    demoRunning   = true;
    tourInProgress = false;
    if (lpFinger) lpFinger.style.opacity = '0';
    if (lpRipple) lpRipple.style.opacity = '0';
    // Also clear any phase-2 spotlight/card left over from a prior run.
    _wtActive = false;
    _wtOnEndOverride = null;
    if (typeof _wtHideOverlay === 'function') _wtHideOverlay();
    const wtCard1 = document.getElementById('wt-card');
    if (wtCard1) wtCard1.style.display = 'none';
    dwait(300, runDemo);
  };

})();

function confirmDelete(id) {
  const props = getProps();
  const target = props.find(p => p.id === id);
  if (!confirm('Remove this listing? This cannot be undone.')) return;
  deleteListingImages(id); // clean up _SS images

  let remainingProps = props.filter(p => p.id !== id);
  saveProps(remainingProps);
  renderDashboard();
  refreshAllGrids();
  showToast('Listing removed.');
}

// ── OWNER: EDIT AN EXISTING RENTAL LISTING ────────────────────────────
let _oeEditId = null;
function _oeSel(id, opts, cur) {
  const c = (cur == null) ? '' : String(cur);
  const list = opts.slice();
  if (c !== '' && !list.some(o => o[0] === c)) list.unshift([c, c]);
  return '<select id="' + id + '">' + list.map(o =>
    '<option value="' + escHtml(o[0]) + '"' + (o[0] === c ? ' selected' : '') + '>' + escHtml(o[1]) + '</option>').join('') + '</select>';
}
function openOwnerEditListing(id) {
  const p = getProps().find(x => x.id === id);
  if (!p) { showToast('Listing not found.', 'error'); return; }
  if (currentUser && p.landlordId && p.landlordId !== currentUser.id) { showToast('You can only edit your own listings.', 'error'); return; }
  _oeEditId = id;
  const isTransit = p.type === 'Transit';
  const isComm = !!p.isCommercial || COMMERCIAL_TYPES.includes(p.type);
  const per = p.rentPeriod || 'month';
  const tr = p.transitRates || {};
  const val = v => escHtml(v == null ? '' : v);
  const sid = escAttr(id);
  let h = '';
  h += '<div class="oe-chip">' + escHtml(p.type || 'Property') + (p.area ? ' · ' + escHtml(p.area) : '') + '</div>';
  h += '<div class="oe-shortcuts">' +
         '<button type="button" onclick="closeModal(\'owner-edit-modal\');openEditImagesModal(\'' + sid + '\')">📷 Edit photos</button>' +
         '<button type="button" onclick="closeModal(\'owner-edit-modal\');openLocationPicker(\'' + sid + '\')">📍 ' + (p.lat != null ? 'Edit location' : 'Set location') + '</button>' +
       '</div>';
  h += '<div class="form-group"><label>🏷️ Property Title</label><input type="text" id="oe-title" maxlength="80" value="' + val(p.title) + '"></div>';
  if (isTransit) {
    h += '<div style="background:rgba(13,92,99,0.05);border:1.5px solid rgba(13,92,99,0.12);border-radius:10px;padding:14px;margin-bottom:16px;">' +
           '<div style="font-size:0.78rem;font-weight:700;color:var(--teal);margin-bottom:10px;">🚇 Transit / Short Stay rates</div>' +
           '<div class="form-row"><div class="form-group"><label>☀️ Daily</label><input type="number" id="oe-rent-daily" min="1" value="' + val(tr.daily != null ? tr.daily : p.rent) + '"></div>' +
           '<div class="form-group"><label>📅 Weekly</label><input type="number" id="oe-rent-weekly" min="1" value="' + val(tr.weekly) + '"></div></div>' +
           '<div class="form-group" style="margin-bottom:0;"><label>🗓️ Monthly</label><input type="number" id="oe-rent-monthly" min="1" value="' + val(tr.monthly) + '"></div></div>';
  } else {
    h += '<div class="form-group"><label>💰 Rent (per ' + escHtml(per) + ')</label><input type="number" id="oe-rent" min="1" inputmode="numeric" value="' + val(p.rent) + '"></div>';
  }
  if (!isComm) {
    h += '<div class="form-row">' +
      '<div class="form-group"><label>🛏️ Bedrooms</label>' + _oeSel('oe-beds', [['Studio','Studio'],['1','1 Bed'],['2','2 Beds'],['3','3 Beds'],['4+','4+ Beds']], p.beds || 'Studio') + '</div>' +
      '<div class="form-group"><label>🚿 Bathrooms</label>' + _oeSel('oe-baths', [['1','1 Bath'],['2','2 Baths'],['3+','3+']], p.baths || '1') + '</div></div>';
  } else {
    h += '<div class="form-row">' +
      '<div class="form-group"><label>📐 Floor Area (sqm)</label><input type="number" id="oe-floor" min="1" value="' + val(p.floorArea) + '"></div>' +
      '<div class="form-group"><label>🚗 Car Parks</label>' + _oeSel('oe-carparks', [['None','None'],['1','1'],['2','2'],['3','3'],['4+','4+']], p.carParks || 'None') + '</div></div>' +
      '<div class="form-row">' +
      '<div class="form-group"><label>🏗️ Condition</label>' + _oeSel('oe-condition', [['Ready to Use','Ready to Use'],['Fitted Out','Fitted Out'],['Shell & Core','Shell & Core'],['Needs Renovation','Needs Renovation'],['Under Construction','Under Construction']], p.condition || 'Ready to Use') + '</div>' +
      '<div class="form-group"><label>📋 Lease Term</label>' + _oeSel('oe-lease', [['Monthly','Month-to-Month'],['6 Months','6 Months'],['1 Year','1 Year'],['2 Years','2 Years'],['3+ Years','3+ Years'],['Negotiable','Negotiable']], p.leaseTerm || 'Monthly') + '</div></div>' +
      '<div class="form-row">' +
      '<div class="form-group"><label>⚡ Utilities</label>' + _oeSel('oe-utilities', [['Included','Included in rent'],['Excluded','Excluded (tenant pays)'],['Partial','Partial (electricity only)']], p.utilities || 'Included') + '</div>' +
      '<div class="form-group"><label>🔐 Security</label>' + _oeSel('oe-security', [['None','None'],['CCTV','CCTV'],['Guard','Security Guard'],['Full','Full Security']], p.security || 'None') + '</div></div>';
  }
  h += '<div class="form-group"><label>📍 Street address <span style="font-weight:400;color:var(--grey);">(optional)</span></label><input type="text" id="oe-address" maxlength="120" value="' + val(p.address) + '"></div>';
  h += '<div class="form-group"><label>📝 Description</label><textarea id="oe-desc" rows="4">' + val(p.desc) + '</textarea></div>';
  h += '<div class="form-row">' +
       '<div class="form-group"><label>📱 Contact Number</label><input type="tel" id="oe-phone" value="' + val(p.landlordPhone) + '"></div>' +
       '<div class="form-group"><label>✉️ Contact Email</label><input type="email" id="oe-email" value="' + val(p.landlordEmail) + '"></div></div>';
  document.getElementById('oe-body').innerHTML = h;
  document.getElementById('oe-error').style.display = 'none';
  openModal('owner-edit-modal');
}
function ownerEditListingSave() {
  const err = document.getElementById('oe-error'); err.style.display = 'none';
  const props = getProps();
  const p = props.find(x => x.id === _oeEditId);
  if (!p) { showErr(err, 'This listing no longer exists.'); return; }
  const g = id => { const e = document.getElementById(id); return e ? String(e.value || '').trim() : ''; };
  const isTransit = p.type === 'Transit';
  const isComm = !!p.isCommercial || COMMERCIAL_TYPES.includes(p.type);
  const title = g('oe-title'), phone = g('oe-phone'), email = g('oe-email');
  if (!title) return showErr(err, 'Please enter a property title.');
  if (!phone) return showErr(err, 'Please enter a contact number so tenants can reach you.');
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return showErr(err, 'Please enter a valid email address.');
  if (isTransit) {
    const d = Number(g('oe-rent-daily')), w = Number(g('oe-rent-weekly')), m = Number(g('oe-rent-monthly'));
    if (!(d > 0 && w > 0 && m > 0)) return showErr(err, 'Please enter all three rates (daily, weekly and monthly).');
    p.transitRates = { daily: d, weekly: w, monthly: m };
    p.rent = d;
  } else {
    const r = Number(g('oe-rent'));
    if (!(r > 0)) return showErr(err, 'Please enter the rent amount.');
    p.rent = r;
  }
  if (isComm) {
    const fa = g('oe-floor');
    p.floorArea = fa ? Number(fa) : null;
    p.carParks = g('oe-carparks') || 'None';
    p.condition = g('oe-condition'); p.leaseTerm = g('oe-lease');
    p.utilities = g('oe-utilities'); p.security = g('oe-security');
  } else {
    p.beds = g('oe-beds'); p.baths = g('oe-baths');
  }
  p.title = title; p.address = g('oe-address'); p.desc = g('oe-desc');
  p.landlordPhone = phone; p.landlordEmail = email;
  p.editedAt = Date.now();
  if (!saveProps(props)) { showErr(err, '⚠️ Could not save — storage may be full.'); return; }
  closeModal('owner-edit-modal');
  _oeEditId = null;
  try { renderDashboard(); } catch (e) { console.warn(e); }
  try { refreshAllGrids(); } catch (e) {}
  showToast('✅ Listing updated.', 'success');
}

// ── IMAGE PREVIEW ─────────────────────────────────────────────────────
let _pendingImageReads = 0; // FIX #7: track async reads in progress

function addMoreImages(e) {
  const files = Array.from(e.target.files);
  if (!files.length) return;
  const preview = document.getElementById('upload-preview');
  const countEl = document.getElementById('upload-count');
  const publishBtn = document.getElementById('publish-btn');

  files.forEach(file => {
    if (!file.type.startsWith('image/')) return;
    _pendingImageReads++;
    if (publishBtn) { publishBtn.disabled = true; publishBtn.textContent = '⏳ Processing photos…'; }
    const reader = new FileReader();
    reader.onload = ev => {
      // Compress each image
      const img = new Image();
      img.onload = () => {
        // Aggressive multi-pass compression — target under 180KB base64
        const TARGET = 180 * 1024;
        let MAX = 800; let quality = 0.65; let dataUrl = '';
        for (let pass = 0; pass < 6; pass++) {
          let w = img.width, h = img.height;
          if (w > MAX || h > MAX) {
            if (w > h) { h = Math.round(h*MAX/w); w = MAX; }
            else       { w = Math.round(w*MAX/h); h = MAX; }
          }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.fillStyle = '#fff'; ctx.fillRect(0,0,w,h);
          ctx.drawImage(img,0,0,w,h);
          dataUrl = canvas.toDataURL('image/jpeg', quality);
          if (Math.round(dataUrl.length * 0.75) <= TARGET) break;
          MAX = Math.round(MAX * 0.80); quality = Math.max(0.40, quality - 0.08);
        }
        uploadedImages.push(dataUrl);

        // Render thumbnail with remove button
        const wrap = document.createElement('div');
        wrap.style.cssText = 'position:relative;display:inline-block;';
        const thumb = document.createElement('img');
        thumb.className = 'upload-thumb';
        thumb.src = dataUrl;
        thumb.title = 'Click to remove';
        const idx = uploadedImages.length - 1;
        const removeBtn = document.createElement('button');
        removeBtn.textContent = '✕';
        removeBtn.style.cssText = 'position:absolute;top:-6px;right:-6px;background:var(--coral);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:0.65rem;font-weight:800;cursor:pointer;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;';
        removeBtn.onclick = () => { uploadedImages.splice(uploadedImages.indexOf(dataUrl), 1); wrap.remove(); updateUploadCount(); };
        wrap.appendChild(thumb);
        wrap.appendChild(removeBtn);
        preview.appendChild(wrap);
        updateUploadCount();
        _pendingImageReads--;
        // FIX #7b: re-enable publish button when all reads complete
        if (_pendingImageReads <= 0) {
          _pendingImageReads = 0;
          const btn = document.getElementById('publish-btn');
          if (btn) { btn.disabled = false; btn.textContent = 'Publish Listing 🚀'; }
        }
      };
      img.onerror = () => {
        _pendingImageReads = Math.max(0, _pendingImageReads - 1);
        const btn = document.getElementById('publish-btn');
        if (btn && _pendingImageReads === 0) { btn.disabled = false; btn.textContent = 'Publish Listing 🚀'; }
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });
  // Reset input so same files can be re-added
  e.target.value = '';
}

function updateUploadCount() {
  const countEl = document.getElementById('upload-count');
  if (!countEl) return;
  if (uploadedImages.length > 0) {
    countEl.textContent = uploadedImages.length + ' photo' + (uploadedImages.length>1?'s':'') + ' added ✅';
    countEl.style.display = 'block';
  } else {
    countEl.style.display = 'none';
  }
}

// ── MODAL HELPERS ─────────────────────────────────────────────────────
function openModal(id) {
  // ── Early redirects: BEFORE opening anything ──────────────────────
  // Must run before classList.add('open') — prevents the wrong modal
  // from flashing open before being swapped out.
  if (id === 'post-modal') {
    if (!currentUser) {
      openModal('auth-modal');
      return;
    }
    if (!currentUser.accountType) {
      openAccountTypeMigration();
      return;
    }
  }
  if (id === 'auth-modal' && currentUser) {
    showPage('dashboard');
    return;
  }
  // Don't blow away an in-progress email-verification step if something
  // re-triggers an auth-modal open while the user is already sitting on
  // it (see _authModalMidVerification for why this happens in practice).
  if (id === 'auth-modal' && typeof _authModalMidVerification === 'function' && _authModalMidVerification()) {
    return;
  }
  // ── Safe to open the modal now ─────────────────────────────────────
  document.getElementById(id).classList.add('open');
  document.body.style.overflow = 'hidden';
  // Always hide the Tour Guide floating button while any modal is open
  const rb = document.getElementById('wt-replay-btn');
  if (rb) rb.style.display = 'none';
  if (id === 'auth-modal') {
    // Reset errors
    ['login-error','login-success','reg-error','reg-success'].forEach(eid => {
      const el = document.getElementById(eid);
      if (el) el.style.display = 'none';
    });
    // Reset email inputs
    ['login-email','reg-email'].forEach(eid => {
      const el = document.getElementById(eid);
      if (el) el.value = '';
    });
    // Populate country lists and auto-select if only one allowed. This also
    // sets the phone-prefix flag/dial-code chips — must run AFTER the resets
    // above (not before), otherwise the chips get wiped back to a bare
    // globe/+ placeholder right after being set correctly.
    populateAuthCountries();
    _googlePending = null;
    if (typeof applyGoogleRegisterMode === 'function') applyGoogleRegisterMode();
    setTimeout(initGoogleAuthButtons, 60);
    // Make sure we're not left mid-way through the forgot-password flow
    // from a previous time the modal was opened
    const tabsBar = document.querySelector('.modal-tabs');
    if (tabsBar) tabsBar.style.display = 'flex';
    document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
    document.getElementById('tab-login').classList.add('active');
    document.querySelectorAll('.modal-tab').forEach((t,i) => t.classList.toggle('active', i === 0));
    if (typeof fpResetState === 'function') fpResetState();
  }
  if (id === 'post-modal' && currentUser) {
    document.getElementById('post-phone').value = currentUser.phone || '';
    if (document.getElementById('post-email'))
      document.getElementById('post-email').value = currentUser.email || '';
    // Show today's date as the publish date
    const pubDateEl = document.getElementById('post-publish-date');
    if (pubDateEl) pubDateEl.textContent = formatPublishedDate(Date.now());
    // Reset photo uploads
    uploadedImages = [];
    const preview = document.getElementById('upload-preview');
    if (preview) preview.innerHTML = '';
    const countEl = document.getElementById('upload-count');
    if (countEl) countEl.style.display = 'none';
    // Reset the exact-location pin from any previous listing
    resetPrePublishLocation();
    // Populate countries (only allowed ones)
    populatePostCountries();
    // Auto-select landlord's own country if available
    const postSel = document.getElementById('post-country');
    if (postSel) {
      const landlordCode = currentUser.countryCode || 'PG';
      const allowed = getAllowedCountries();
      const match = allowed.find(c => c.code === landlordCode);
      if (match) {
        postSel.value = landlordCode;
      } else if (allowed.length === 1) {
        postSel.value = allowed[0].code;
      }
      onPostCountryChange();
    }
    // Reset error
    document.getElementById('post-error').style.display = 'none';
    clearFieldErrors();
    // Reset availability form
    resetAvailForm();
    // Reset commercial fields
    ['post-floor-area','post-carparks','post-condition','post-lease-term','post-utilities','post-security'].forEach(id => {
      const el = document.getElementById(id);
      if (el) { if (el.tagName === 'SELECT') el.selectedIndex = 0; else el.value = ''; }
    });

    // ── Category picker: show for property_management, hide for others ──
    const isPropMgmt = currentUser.accountType === 'property_management';
    const catPicker  = document.getElementById('post-cat-picker');
    const fieldsBody = document.getElementById('post-fields-body');
    if (catPicker) catPicker.style.display = isPropMgmt ? 'block' : 'none';
    if (fieldsBody) fieldsBody.style.display = isPropMgmt ? 'none' : 'block';
    // Reset picker selection
    ['residential','commercial'].forEach(c => {
      const card = document.getElementById('pcc-' + c);
      if (card) card.classList.remove('selected');
    });

    // Filter the Property Type dropdown to this landlord's account type
    populatePostTypeOptions();
    // Reset custom type field
    const ctWrap = document.getElementById('post-custom-type-wrap');
    const ctInput = document.getElementById('post-custom-type');
    if (ctWrap) ctWrap.style.display = 'none';
    if (ctInput) ctInput.value = '';
    // Trigger type change to show correct fields
    onTypeChange();
    // Reset description tour flag so it fires once on first focus in this modal session
    _wtDescTourShown = false;
    // Show landlord's own sale-request status (and hide the button if one's pending)
    closeSaleRequestForm();
    if (typeof renderMySaleRequestStatus === 'function') renderMySaleRequestStatus();
  }
  wiRender();
}
function closeModal(id) {
  document.getElementById(id).classList.remove('open');
  document.body.style.overflow = '';
  if (id === 'location-pin-modal' && typeof hideGeoPermHelp === 'function') hideGeoPermHelp();
  // End tour if it's tied to this modal
  if (_wtActive && (id === 'post-modal' || id === 'location-pin-modal')) {
    _wtHideOverlay();
    const card = document.getElementById('wt-card');
    if (card) card.style.display = 'none';
    _wtActive = false;
    _wtOnEndOverride = null;
    if (_wtResizeOb) { _wtResizeOb.disconnect(); _wtResizeOb = null; }
    window.removeEventListener('resize', _wtOnResize);
  }
  // Restore Tour Guide replay button if no other modals remain open and we're on dashboard
  requestAnimationFrame(() => {
    const anyOpen = document.querySelector('.modal-overlay.open');
    if (!anyOpen) {
      const dash = document.getElementById('page-dashboard');
      const rb   = document.getElementById('wt-replay-btn');
      if (rb && dash && dash.classList.contains('active')) {
        try {
          const key = _wtUserKey ? _wtUserKey() : WT_KEY;
          if (_LS.getItem(key)) rb.style.display = 'flex';
        } catch(e) {}
      }
    }
  });
}

// Close on overlay click — but NOT payment modal (accidental close loses listing data)
document.querySelectorAll('.modal-overlay').forEach(ov => {
  ov.addEventListener('click', e => {
    if (e.target === ov && ov.id !== 'payment-modal' && ov.id !== 'acct-migrate-modal') closeModal(ov.id);
  });
});

// ── TAB SWITCH ────────────────────────────────────────────────────────
function switchTab(tab) {
  // Swallow ghost clicks that land on the tab bar immediately after a
  // registration wizard step change (see _wizardStepTransitionGuardUntil).
  // A genuine, intentional tap on "Sign In"/"Create Account" from the user
  // will always be well outside this ~500ms window.
  if (Date.now() < _wizardStepTransitionGuardUntil) return;
  document.querySelectorAll('.modal-tab').forEach((t,i) => {
    t.classList.toggle('active', (tab==='login'&&i===0)||(tab==='register'&&i===1));
  });
  document.querySelectorAll('.tab-panel').forEach((p,i) => {
    p.classList.toggle('active', (tab==='login'&&i===0)||(tab==='register'&&i===1));
  });
  if (tab === 'register') {
    pendingLoginType = null;
    const hint = document.getElementById('login-type-hint');
    if (hint) hint.style.display = 'none';
    // Always start the wizard at step 0 when the register tab opens —
    // unless the user is already mid email-verification, in which case
    // this would silently discard their pending code (see
    // _authModalMidVerification).
    const alreadyMidVerify = typeof _authModalMidVerification === 'function' && _authModalMidVerification();
    if (!alreadyMidVerify && typeof resetRegisterWizard === 'function') resetRegisterWizard();
  }
}

// ── HAMBURGER MENU ───────────────────────────────────────────────────
function toggleHamburgerMenu() {
  const dd  = document.getElementById('hamburger-dropdown');
  const btn = document.getElementById('hamburger-btn');
  const isOpen = dd.classList.toggle('open');
  btn.classList.toggle('open', isOpen);
  btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  if (isOpen) renderHamburgerMenu();
}
function closeHamburgerMenu() {
  document.getElementById('hamburger-dropdown').classList.remove('open');
  document.getElementById('hamburger-btn').classList.remove('open');
  document.getElementById('hamburger-btn').setAttribute('aria-expanded', 'false');
}
function toggleHamburgerSub(which) {
  const sub     = document.getElementById('hb-' + which + '-sub');
  const chevron = document.getElementById('hb-' + which + '-chevron');
  const toggle  = document.getElementById('hb-' + which + '-toggle');
  if (!sub || !chevron || !toggle) return;
  const isOpen  = sub.classList.toggle('open');
  chevron.classList.toggle('open', isOpen);
  toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

  // Collapse the other sub-menu so only one is open at a time
  const other = which === 'login' ? 'register' : 'login';
  const otherSub = document.getElementById('hb-' + other + '-sub');
  const otherChevron = document.getElementById('hb-' + other + '-chevron');
  const otherToggle = document.getElementById('hb-' + other + '-toggle');
  if (otherSub) otherSub.classList.remove('open');
  if (otherChevron) otherChevron.classList.remove('open');
  if (otherToggle) otherToggle.setAttribute('aria-expanded', 'false');
}
// Rebuilds the hamburger dropdown contents based on who's logged in:
// nobody → Login/Register; a landlord → their dashboard + account links;
// admin → admin panel link. Called whenever the menu opens and whenever
// login state changes, so it never goes stale.
function renderHamburgerMenu() {
  const wrap = document.getElementById('hamburger-content');
  if (!wrap) return;
  syncModeBar();

  // Rental/Sales mode switching lives on the home page only — not in this menu.
  const salesOn = isSalesModeEnabled();
  const modeSection = '';

  if (adminSession) {
    wrap.innerHTML = modeSection + `
      <div class="hamburger-dropdown-label">Admin</div>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); showPage('admin');">${wi('settings','⚙️',16)} Admin Panel</button>
      <div class="hamburger-divider"></div>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); showPage('about');">${wi('info','ℹ️',16)} About Us</button>
      <div class="hamburger-divider"></div>
      <button class="hamburger-item" style="color:var(--coral);" onclick="closeHamburgerMenu(); adminLogout();">${wi('log-out','🚪',16,'var(--coral)')} Sign Out</button>
    `;
    wiRender();
    setTimeout(_attachSalesPillAnim, 60);
    return;
  }

  if (_appMode === 'sales' && salesOn) {
    wrap.innerHTML = modeSection + `
      <div class="hamburger-dropdown-label">Sales Mode</div>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); enterSalesMode();">🏡 Browse Properties For Sale</button>
      <div class="hamburger-divider"></div>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); showPage('about');">${wi('info','ℹ️',16)} About Us</button>
    `;
    wiRender(); return;
  }

  if (currentUser) {
    wrap.innerHTML = modeSection + `
      <div class="hamburger-dropdown-label">${escHtml(currentUser.name)}</div>
      <button id="hamburger-dash-home" class="hamburger-item" onclick="closeHamburgerMenu(); navDashHomeToggle();">${_dashHomeMenuLabel(_activePageId() === 'dashboard')}</button>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); listPropertyForCurrentMode();">${wi('plus-circle','➕',16)} List Property</button>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); openSupportModal();">${wi('message-circle','💬',16)} Message Wampac</button>
      <div class="hamburger-divider"></div>
      <button class="hamburger-item" onclick="closeHamburgerMenu(); showPage('about');">${wi('info','ℹ️',16)} About Us</button>
      <div class="hamburger-divider"></div>
      <button class="hamburger-item" style="color:var(--coral);" onclick="closeHamburgerMenu(); logout();">${wi('log-out','🚪',16,'var(--coral)')} Log Out</button>
    `;
    wiRender();
    setTimeout(_attachSalesPillAnim, 60);
    return;
  }

  wrap.innerHTML = modeSection + `
    <div class="hamburger-dropdown-label">Landlords</div>
    <button class="hamburger-item" onclick="openLandlordLogin()">${wi('key-round','🔑',16)} Landlord Login</button>
    <button class="hamburger-item" onclick="openRegisterWizard()">${wi('user-plus','📝',16)} Register as a Landlord</button>
    <div class="hamburger-divider"></div>
    <div class="hamburger-dropdown-label">General</div>
    <button class="hamburger-item" onclick="closeHamburgerMenu(); showPage('about');">${wi('info','ℹ️',16)} About Us</button>
  `;
  wiRender();
  setTimeout(_attachSalesPillAnim, 60);
}

// ── Sales pill tap animation ──────────────────────────────────────
function _attachSalesPillAnim() {
  // Highlight removed: the Sales pill stays normal. Just clean up any leftovers.
  const old = document.getElementById('_sales-pill-finger');
  if (old) old.remove();
  const btn = document.getElementById('mode-pill-sales-btn');
  if (btn) btn.classList.remove('sales-pill-animate');
}
// NOTE: registration no longer has an email-verification step (accounts are
// created immediately), so there's nothing left to guard against wiping.
// Kept as a no-op so existing call sites below don't need to change.
function _authModalMidVerification() {
  return false;
}

function openLandlordLogin() {
  closeHamburgerMenu();
  if (currentUser) { showPage('dashboard'); return; }
  if (_authModalMidVerification()) return;
  pendingLoginType = null;
  openModal('auth-modal');
  switchTab('login');
  const hint = document.getElementById('login-type-hint');
  if (hint) hint.style.display = 'none';
}
function openRegisterWizard() {
  closeHamburgerMenu();
  if (currentUser) { showPage('dashboard'); return; }
  if (_authModalMidVerification()) return;
  openModal('auth-modal');
  switchTab('register'); // switchTab calls resetRegisterWizard which shows step-0
}
// Legacy shims (called from About page CTA and other places)
function startLandlordLogin(type) {
  closeHamburgerMenu();
  if (currentUser) { showPage('dashboard'); return; }
  if (_authModalMidVerification()) return;
  pendingLoginType = type || null;
  openModal('auth-modal');
  switchTab('login');
  const hint = document.getElementById('login-type-hint');
  if (hint) {
    const acct = type ? ACCOUNT_TYPES[type] : null;
    hint.textContent = acct ? ('Signing in as: ' + acct.icon + ' ' + acct.label) : '';
    hint.style.display = acct ? 'block' : 'none';
  }
}
function startLandlordRegister(type) {
  closeHamburgerMenu();
  if (currentUser) { showPage('dashboard'); return; }
  if (_authModalMidVerification()) return;
  openModal('auth-modal');
  switchTab('register'); // this calls resetRegisterWizard which sets step-0
  // Account type is no longer chosen at sign-up; the wizard already starts at the location step.
}
// Close hamburger dropdown when clicking outside it
document.addEventListener('click', e => {
  if (!e.target.closest('.hamburger-dropdown') && !e.target.closest('.hamburger-btn')) {
    closeHamburgerMenu();
  }
});

// ══════════════════════════════════════════════════════════════════
//  SALES MODE — Full property-for-sale feature set
//  • Rental Mode  = original Wampac experience (no change)
//  • Sales Mode   = admin-managed listings; browse by Country → Province/State → Listings
// ══════════════════════════════════════════════════════════════════

// ── State ────────────────────────────────────────────────────────
const LS_SALES_PROPS   = 'wampac_sales_props';
const LS_SALES_IMAGES  = 'wampac_sales_imgs_';
let   _appMode         = _LS.getItem('wampac_app_mode') || 'rental'; // 'rental' | 'sales'
let   _salesFilter     = 'All';
let   _salesBrowseCountry  = null;
let   _salesBrowseProvince = null;
let   _salesAdminPhotos    = [];

// ── Storage helpers ──────────────────────────────────────────────
function getSalesProps() {
  try { return JSON.parse(_LS.getItem(LS_SALES_PROPS) || '[]'); } catch(e) { return []; }
}
function saveSalesProps(props) {
  try {
    // Strip _imgs from each property before writing to _LS — avoids localStorage quota overflow.
    // Images are stored separately in _SS via saveSalesPropImages (same pattern as rental listings).
    const lean = props.map(p => {
      const { _imgs, ...rest } = p;
      if (_imgs && _imgs.length > 0) saveSalesPropImages(p.id, _imgs);
      return rest;
    });
    _LS.setItem(LS_SALES_PROPS, JSON.stringify(lean));
    const verify = _LS.getItem(LS_SALES_PROPS);
    if (!verify) throw new Error('Write verification failed');
    return true;
  } catch(e) {
    console.error('saveSalesProps failed:', e);
    // Last resort: strip all image data and retry
    try {
      const minimal = props.map(p => { const { _imgs, ...rest } = p; return rest; });
      _LS.setItem(LS_SALES_PROPS, JSON.stringify(minimal));
      return true;
    } catch(e2) {
      console.error('saveSalesProps minimal also failed:', e2);
      return false;
    }
  }
}
function getSalesPropImages(id) {
  // Primary: _SS (sessionStorage) — same pattern as rental images, avoids _LS quota issues
  try {
    const r = _SS.getItem(LS_SALES_IMAGES + id);
    if (r) return JSON.parse(r);
  } catch(e) {}
  // Fallback: legacy _imgs embedded in property object (old saves before this fix)
  try {
    const props = getSalesProps();
    const p = props.find(x => x.id === id);
    if (p && p._imgs && p._imgs.length > 0) {
      // Migrate to _SS on first read so future reads are fast
      try { _SS.setItem(LS_SALES_IMAGES + id, JSON.stringify(p._imgs)); } catch(e2) {}
      return p._imgs;
    }
  } catch(e) {}
  // Last resort: dedicated _LS key (very old saves)
  try {
    const r = _LS.getItem(LS_SALES_IMAGES + id);
    if (r) return JSON.parse(r);
  } catch(e) {}
  return [];
}
function saveSalesPropImages(id, imgs) {
  if (!imgs || imgs.length === 0) return;
  // Store in _SS (sessionStorage) — avoids localStorage quota; same as rental image storage
  try {
    _SS.setItem(LS_SALES_IMAGES + id, JSON.stringify(imgs));
  } catch(e) {
    // _SS full — compress and retry once
    try {
      const smaller = imgs.map(img => {
        const c = document.createElement('canvas');
        const image = new Image(); image.src = img;
        c.width = Math.min(image.naturalWidth || 400, 400);
        c.height = Math.min(image.naturalHeight || 300, 300);
        c.getContext('2d').drawImage(image, 0, 0, c.width, c.height);
        return c.toDataURL('image/jpeg', 0.55);
      });
      _SS.setItem(LS_SALES_IMAGES + id, JSON.stringify(smaller));
    } catch(e2) { console.warn('Could not store sales images for', id); }
  }
}

// ── Sales hero search: matching countries appear right under the search bar ──
function salesSearchSuggest(q) {
  const box = document.getElementById('sales-search-suggest');
  if (!box) return;
  const query = String(q || '').trim().toLowerCase();
  if (!query) { box.classList.remove('show'); box.innerHTML = ''; return; }
  const salesProps = getSalesProps().filter(p => !p.hidden);
  const list = getAllowedCountries().filter(c => c.name.toLowerCase().includes(query));
  if (!list.length) {
    box.innerHTML = '<div class="hss-empty">No country matches "' + escHtml(q) + '". Try a different search.</div>';
  } else {
    box.innerHTML = list.map(c => {
      const n = salesProps.filter(p => (p.country || 'Papua New Guinea') === c.name).length;
      return '<div class="hss-item" onclick="salesSearchPick(\'' + escAttr(c.code) + '\')">' +
        '<span class="hss-icon">' + flagImg(c.code, { width: 24, emoji: c.icon }) + '</span>' +
        '<span class="hss-name">' + escHtml(c.name) + '</span>' +
        '<span class="hss-sub">' + (n > 0 ? n + ' listing' + (n !== 1 ? 's' : '') : 'No listings yet') + '</span></div>';
    }).join('');
  }
  box.classList.add('show');
}
function salesSearchPick(code) {
  const box = document.getElementById('sales-search-suggest');
  if (box) { box.classList.remove('show'); box.innerHTML = ''; }
  const inp = document.getElementById('sales-country-search'); if (inp) inp.blur();
  selectSalesCountry(code);
}
function salesSearchGo() {
  const inp = document.getElementById('sales-country-search');
  const q = inp ? inp.value : '';
  renderSalesCountryStep(q);
  salesSearchSuggest(q);
  const first = document.querySelector('#sales-search-suggest .hss-item');
  if (first) first.click(); else if (inp) inp.blur();
}
// Bring the search bar to the top of the screen so the results stay above the keyboard
function salesSearchFocus() {
  const wrap = document.getElementById('sales-browse-search-wrap');
  if (!wrap) return;
  setTimeout(function () {
    const y = wrap.getBoundingClientRect().top + window.pageYOffset - 90;
    window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
  }, 250);
}

// ── Mode switching ───────────────────────────────────────────────
function setAppMode(mode) {
  if (mode === 'sales' && !isSalesModeEnabled()) {
    showToast('Sales Mode is currently unavailable.', 'error');
    return;
  }
  _appMode = mode;
  _LS.setItem('wampac_app_mode', mode);
  closeHamburgerMenu();

  if (mode === 'sales') {
    document.body.classList.add('sales-mode');
    enterSalesMode();
  } else {
    document.body.classList.remove('sales-mode');
    // Restore hero to rental look
    const heroTag = document.querySelector('.hero-tag');
    if (heroTag) heroTag.textContent = '🌍 Global Real Estate Platform';
    const heroH1 = document.querySelector('.hero h1');
    if (heroH1) heroH1.innerHTML = '<span class="wel">Wel</span>come to<br><em>Wam</em>pac';
    const heroP = document.querySelector('.hero p');
    if (heroP) heroP.textContent = DEFAULT_APPEARANCE.subtext;
    document.querySelector('nav').style.cssText = '';
    document.querySelector('.nav-logo').innerHTML = wampacLogoImgHTML(32);
    showPage('home');
    showToast('🏠 Switched to Rental Mode', 'success');
  }
  // Re-render hamburger to update pill state
  const dd = document.getElementById('hamburger-dropdown');
  if (dd && dd.classList.contains('open')) renderHamburgerMenu();
  syncModeBar();
}

// Keeps the always-visible Rental/Sales bar (under the logo) in sync with the current mode
function syncModeBar() {
  const enabled = isSalesModeEnabled();
  document.querySelectorAll('.hero-mode-switch').forEach(el => el.classList.toggle('hidden-by-admin', !enabled));
  document.querySelectorAll('.mode-switch-rental').forEach(el => el.classList.toggle('active-rental', _appMode === 'rental'));
  document.querySelectorAll('.mode-switch-sales').forEach(el => el.classList.toggle('active-sales', _appMode === 'sales'));
  try { syncListButtonMode(); } catch (e) {}
  // Sales pill no longer pulses — it looks normal until selected
  document.querySelectorAll('.mode-switch-sales').forEach(el => el.classList.remove('sales-pill-animate'));
}
document.addEventListener('DOMContentLoaded', () => setTimeout(function(){ syncModeBar(); try { syncSalesHeroBg(); } catch (e) {} }, 150));
window.addEventListener('load', () => setTimeout(syncModeBar, 300));

function enterSalesMode() {
  // Apply gold-tinted nav
  const nav = document.querySelector('nav');
  if (nav) nav.style.cssText = 'background:linear-gradient(90deg,#1a0f00,#5a2e00);';
  const logo = document.querySelector('.nav-logo');
  if (logo) logo.innerHTML = wampacLogoImgHTML(32);

  // Apply sales page wallpaper (if one has been set by admin)
  applySalesWallpaper();

  // Render browse page
  _salesBrowseCountry  = null;
  _salesBrowseProvince = null;
  renderSalesBrowsePage();
  showPageDirect('sales-browse');
  try { syncSalesHeroBg(); } catch (e) {}
  showToast('🏡 Switched to Sales Mode', 'success');
}

function leaveSalesMode() {
  setAppMode('rental');
}

// ── Direct page show (bypasses showPage mode checks) ────────────
function showPageDirect(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const el = document.getElementById('page-' + id);
  if (el) el.classList.add('active');
  window.scrollTo(0, 0);
}

// ── Sales Browse: Country → Province/State → Listings ───────────
// Same flow as Rental Mode: pick a country first, then its province/state.
function renderSalesBrowsePage() {
  if (_salesBrowseCountry) renderSalesProvinceStep();
  else renderSalesCountryStep();
}

function _salesBrowseHeader(sub, backLabel) {
  const subEl = document.getElementById('sales-browse-sub');
  if (subEl) subEl.innerHTML = sub;
  const bl = document.getElementById('sales-browse-back-label');
  if (bl) bl.textContent = backLabel;
  // No Back button on the Sales home (country) step — the Rental/Sales switch is the way out.
  // It stays on the province step as "Change Country".
  const bb = document.getElementById('sales-browse-back-btn');
  if (bb) {
    if (backLabel === 'Back to Home') bb.style.setProperty('display', 'none', 'important');
    else bb.style.removeProperty('display');
  }
}

// STEP 1 — countries
function renderSalesCountryStep(query) {
  const grid = document.getElementById('sales-province-grid');
  if (!grid) return;
  _salesBrowseCountry = null;
  _salesBrowseProvince = null;
  _salesBrowseHeader('Select a country to get started', 'Back to Home');
  const searchWrap = document.getElementById('sales-browse-search-wrap');
  if (searchWrap) searchWrap.style.display = 'block';

  const salesProps = getSalesProps().filter(p => !p.hidden);
  const q = (query || '').trim().toLowerCase();
  let list = getAllowedCountries();
  if (q) list = list.filter(c => c.name.toLowerCase().includes(q));

  if (list.length === 0) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--grey);padding:36px;">No countries found.</div>';
    return;
  }
  const withCounts = list.map(c => ({
    c,
    count: salesProps.filter(p => (p.country || 'Papua New Guinea') === c.name).length
  }));
  // Countries with listings first, then the admin's original order
  withCounts.sort((x, y) => (y.count > 0) - (x.count > 0));

  grid.innerHTML = withCounts.map(({ c, count }) => `
    <div class="sales-province-card" onclick="selectSalesCountry('${c.code}')">
      <div class="spc-icon">${flagImg(c.code, { width: 34, emoji: c.icon })}</div>
      <div class="spc-name">${escHtml(c.name)}</div>
      <div class="spc-count ${count === 0 ? 'zero' : ''}">${count > 0 ? count + ' listing' + (count !== 1 ? 's' : '') : 'No listings yet'}</div>
    </div>
  `).join('');
}

function selectSalesCountry(code) {
  const c = WORLD_COUNTRIES.find(x => x.code === code);
  if (!c) return;
  const allowed = (getSettings().allowedCountries || ['PG']);
  if (!allowed.includes(code)) {
    showToast('This country is not available on Wampac yet.', 'error');
    return;
  }
  _salesBrowseCountry = c;
  _salesBrowseProvince = null;
  const sw = document.getElementById('sales-country-search'); if (sw) sw.value = '';
  try { const _sb = document.getElementById('sales-search-suggest'); if (_sb) { _sb.classList.remove('show'); _sb.innerHTML = ''; } } catch (e) {}
  renderSalesProvinceStep();
  window.scrollTo(0, 0);
}

// STEP 2 — provinces / states of the chosen country
function renderSalesProvinceStep() {
  const grid = document.getElementById('sales-province-grid');
  if (!grid || !_salesBrowseCountry) return;
  const country = _salesBrowseCountry;
  const searchWrap = document.getElementById('sales-browse-search-wrap');
  if (searchWrap) searchWrap.style.display = 'none';
  _salesBrowseHeader(flagImg(country.code,{width:22,emoji:country.icon}) + ' ' + escHtml(country.name) + ' — select province / state', 'Change Country');

  const salesProps = getSalesProps().filter(p => !p.hidden);
  const inCountry  = salesProps.filter(p => (p.country || 'Papua New Guinea') === country.name);

  const defaultProvinces = [
    { name:'NCD',                 icon:'🌆' },  // capital — largest economy
    { name:'Western',             icon:'⛏️' },  // Ok Tedi mine
    { name:'Southern Highlands',  icon:'⛰️' },  // oil & gas (Kutubu)
    { name:'Hela',                icon:'🛢️' },  // PNG LNG project
    { name:'Morobe',              icon:'⚓' },  // Lae — main commercial port
    { name:'New Ireland',         icon:'🐠' },  // Lihir gold mine
    { name:'Enga',                icon:'⛏️' },  // Porgera gold mine
    { name:'East New Britain',    icon:'🌋' },  // Kokopo — cocoa/copra trade hub
    { name:'West New Britain',    icon:'🌴' },  // Hoskins — oil palm industry
    { name:'Western Highlands',   icon:'☕' },  // Mt Hagen — coffee
    { name:'Madang',              icon:'🌊' },  // port & fisheries
    { name:'Bougainville',        icon:'🌴' },  // Panguna mine legacy
    { name:'Milne Bay',           icon:'🏖️' },
    { name:'Central',             icon:'🏛️' },
    { name:'Gulf',                icon:'🌊' },
    { name:'Simbu',               icon:'⛰️' },
    { name:'Eastern Highlands',   icon:'🏔️' },
    { name:'Jiwaka',              icon:'🌾' },
    { name:'East Sepik',          icon:'🌿' },
    { name:'Manus',               icon:'🏝️' },
    { name:'West Sepik',          icon:'🌿' },
    { name:'Oro',                 icon:'🌺' },
  ];
  const provinceRank = new Map(defaultProvinces.map((p, i) => [p.name, i]));

  // Province names: PNG uses the economic-order list above; other countries use their own list
  let baseNames = country.code === 'PG'
    ? defaultProvinces.map(p => p.name)
    : (WORLD_PROVINCES[country.code] || []).slice();
  // Also include any province an admin used on a listing in this country
  inCountry.forEach(p => { if (p.province && !baseNames.includes(p.province)) baseNames.push(p.province); });

  // Country with no province list at all → skip straight to its listings
  if (baseNames.length === 0) {
    browseSalesByProvince(null);
    return;
  }

  const provinceList = baseNames.map(name => {
    const def = defaultProvinces.find(p => p.name === name);
    const icon = (country.code === 'PG' && def) ? def.icon : ((typeof PROV_ICONS !== 'undefined' && PROV_ICONS[name]) || '📍');
    const count = inCountry.filter(p => p.province === name).length;
    return { name, icon, count };
  });
  if (country.code === 'PG') {
    provinceList.sort((a, b) => {
      const ra = provinceRank.has(a.name) ? provinceRank.get(a.name) : Infinity;
      const rb = provinceRank.has(b.name) ? provinceRank.get(b.name) : Infinity;
      return ra !== rb ? ra - rb : a.name.localeCompare(b.name);
    });
  } else {
    provinceList.sort((a, b) => (b.count - a.count) || a.name.localeCompare(b.name));
  }

  grid.innerHTML = provinceList.map(prov => `
    <div class="sales-province-card" onclick="browseSalesByProvince('${escAttr(prov.name)}')">
      <div class="spc-icon">${prov.icon}</div>
      <div class="spc-name">${escHtml(prov.name)}</div>
      <div class="spc-count ${prov.count === 0 ? 'zero' : ''}">${prov.count} listing${prov.count !== 1 ? 's' : ''}</div>
    </div>
  `).join('');
}

// Back button on the browse page: province step → country step → home
function salesBrowseBack() {
  if (_salesBrowseCountry) {
    _salesBrowseCountry = null;
    _salesBrowseProvince = null;
    renderSalesCountryStep();
    window.scrollTo(0, 0);
  } else {
    leaveSalesMode();
  }
}

// Back button on the listings page: return to the province step of the chosen country
function salesListingsBack() {
  _salesBrowseProvince = null;
  renderSalesBrowsePage();
  showPageDirect('sales-browse');
}

function browseSalesByProvince(province) {
  _salesBrowseProvince = province;
  _salesFilter = 'All';
  applySalesWallpaper();
  renderSalesListingsPage();
  showPageDirect('sales');

  // Update header
  const meta = document.getElementById('sales-listing-meta');
  if (meta) meta.textContent = (province ? province + (_salesBrowseCountry ? ' · ' + _salesBrowseCountry.name : '') : (_salesBrowseCountry ? _salesBrowseCountry.name : ''));
}

// ── Sales Listings Page ───────────────────────────────────────────
function renderSalesListingsPage() {
  const grid = document.getElementById('sales-grid');
  if (!grid) return;

  let props = getSalesProps().filter(p => !p.hidden);

  // Country filter
  if (_salesBrowseCountry) {
    props = props.filter(p => (p.country || 'Papua New Guinea') === _salesBrowseCountry.name);
  }
  // Province filter
  if (_salesBrowseProvince) {
    props = props.filter(p => p.province === _salesBrowseProvince);
  }
  // Type filter
  if (_salesFilter !== 'All') {
    props = props.filter(p => p.type === _salesFilter);
  }

  props = browseSortList(props, p => Number(p.price) || 0);

  const meta = document.getElementById('sales-listing-meta');
  if (meta) meta.textContent = props.length + ' propert' + (props.length === 1 ? 'y' : 'ies') + ' for sale';

  // City/province photo stays put with zero listings; once there's at
  // least one property for sale, switch to the repeating water-bubbles wallpaper.
  setBubblesBackgroundActive(props.length > 0);

  if (props.length === 0) {
    grid.innerHTML = `<div class="sales-empty-state">
      <div class="sei">🏚️</div>
      <h3>${_salesFilter !== 'All' ? 'No ' + escHtml(_salesFilter) + ' listings here' : 'No listings yet'}</h3>
      <p>${_salesFilter !== 'All' ? 'Try another property type — there may be other properties for sale in this area.' : 'No properties for sale in this area at this time. Check back soon or contact us to list a property.'}</p>
      ${_salesFilter !== 'All' ? `<button class="btn btn-gold" style="border-radius:24px;margin-top:12px;" onclick="salesFilterType('All', document.querySelector('#page-sales .filter-chip'))">Show all types</button>` : ''}
    </div>`;
    return;
  }

  grid.innerHTML = props.map((p, i) => {
    const imgs = getSalesPropImages(p.id) || [];
    const TYPE_SALES_EMOJI = { House:'🏠', Apartment:'🏢', Land:'🌾', Commercial:'🏢', Other:'📦' };
    const currency = p.currency || 'PGK';
    const feats = [];
    if (p.beds) feats.push(wpIco('bed') + p.beds + ' Bed' + (Number(p.beds) > 1 ? 's' : ''));
    // Owner-listed properties store the suburb in p.area and the size in p.size;
    // admin-listed ones store the size (sqm) in p.area.
    if (p.ownerSubmitted) { if (p.size) feats.push(wpIco('area') + escHtml(p.size)); }
    else if (p.area) feats.push(wpIco('area') + escHtml(p.area) + ' sqm');
    const loc = [p.ownerSubmitted ? p.area : null, p.province, (p.country && p.country !== 'Papua New Guinea') ? p.country : null].filter(Boolean).map(escHtml).join(' · ');
    const hasPin = p.address || (p.lat != null && p.lng != null);
    const idq = escAttr(p.id);
    return wpCardHTML({
      mode: 'sale', idx: i, id: p.id, title: p.title, images: imgs,
      imgPrefix: 'scsimg-', countPrefix: 'scscount-', navFn: 'salesCardNav',
      mediaClick: `trackSalesViews(['${idq}']);openSalesPropDetail('${idq}')`,
      detailCall: `trackSalesViews(['${idq}']);openSalesPropDetail('${idq}')`,
      type: p.type, emoji: TYPE_SALES_EMOJI[p.type] || '🏡',
      priceHTML: `<div class="wp-sale-price"><small>${escHtml(currency)}</small>${Number(p.price).toLocaleString()}</div>`,
      ago: timeAgo(p.publishedAt || p.date), ts: p.publishedAt || p.date,
      location: loc || 'Location on request', feats,
      dirUrl: hasPin ? buildMapsUrl(p.address, p.province, p.lat, p.lng) : '',
      contactLabel: 'Contact',
      contactCall: p.phone ? `trackSalesViews(['${idq}']);showContact('Seller','${escAttr(p.phone)}','${escAttr(p.email||'')}','${escAttr(p.title)}','${escAttr(p.address||'')}','${escAttr(p.province||'')}',${p.lat != null ? p.lat : 'null'},${p.lng != null ? p.lng : 'null'},null)` : ''
    });
  }).join('');
}

function salesFilterType(type, el) {
  _salesFilter = type;
  document.querySelectorAll('#page-sales .filter-chip').forEach(c => c.classList.remove('active'));
  if (el) el.classList.add('active');
  renderSalesListingsPage();
}

function salesContact(phone, email) {
  if (phone) {
    const msg = email ? `Contact this seller:\n📞 ${phone}\n✉️ ${email}` : `Contact this seller:\n📞 ${phone}`;
    if (confirm(msg + '\n\nTap OK to call now.')) {
      window.location.href = 'tel:' + phone.replace(/\s+/g, '');
    }
  }
}

// ── ADMIN: Sales photo handler ────────────────────────────────────
function saSalesHandlePhotos(input) {
  const preview = document.getElementById('sa-sales-photo-preview');
  if (!preview) return;
  const files = Array.from(input.files).slice(0, 10);
  _salesAdminPhotos = [];
  preview.innerHTML = '';

  // Show loading indicator
  const countLabel = document.createElement('div');
  countLabel.id = 'sa-sales-photo-count';
  countLabel.style.cssText = 'font-size:0.78rem;color:var(--teal);font-weight:600;margin-top:4px;';
  countLabel.textContent = 'Loading photos…';
  preview.after(countLabel);

  let loaded = 0;
  files.forEach((file, idx) => {
    const reader = new FileReader();
    reader.onload = e => {
      _salesAdminPhotos[idx] = e.target.result;
      loaded++;

      const img = document.createElement('img');
      img.src = e.target.result;
      img.style.cssText = 'width:80px;height:60px;object-fit:cover;border-radius:8px;border:2px solid #e5e7eb;';
      preview.appendChild(img);

      if (loaded === files.length) {
        // All done — compact array (remove any gaps) and update label
        _salesAdminPhotos = _salesAdminPhotos.filter(Boolean);
        countLabel.textContent = `✅ ${_salesAdminPhotos.length} photo${_salesAdminPhotos.length !== 1 ? 's' : ''} ready`;
      }
    };
    reader.onerror = () => { loaded++; };
    reader.readAsDataURL(file);
  });
}

// ── ADMIN: Add sales property ─────────────────────────────────────
function saAddSalesProperty() {
  const errEl = document.getElementById('sa-sales-error');
  errEl.style.display = 'none';

  const title    = (document.getElementById('sa-sales-title')?.value || '').trim();
  const type     = document.getElementById('sa-sales-type')?.value || '';
  const country  = document.getElementById('sa-sales-country')?.value || '';
  const province = document.getElementById('sa-sales-province')?.value || '';
  const price    = document.getElementById('sa-sales-price')?.value || '';
  const currency = document.getElementById('sa-sales-currency')?.value || 'PGK';
  const beds     = document.getElementById('sa-sales-beds')?.value || '';
  const area     = document.getElementById('sa-sales-area')?.value || '';
  const address  = (document.getElementById('sa-sales-address')?.value || '').trim();
  const desc     = (document.getElementById('sa-sales-desc')?.value || '').trim();
  const phone    = (document.getElementById('sa-sales-phone')?.value || '').trim();
  const email    = (document.getElementById('sa-sales-email')?.value || '').trim();

  if (!title)    { showErr(errEl, 'Please enter a property title.'); return; }
  if (!type)     { showErr(errEl, 'Please select a property type.'); return; }
  if (!country)  { showErr(errEl, 'Please select a country.'); return; }
  if (!province) { showErr(errEl, 'Please select a province.'); return; }
  if (!price)    { showErr(errEl, 'Please enter an asking price.'); return; }
  if (!phone)    { showErr(errEl, 'Please enter a contact phone number.'); return; }

  const countryData = WORLD_COUNTRIES.find(c => c.code === country);
  // Guard: if FileReader is still processing, wait up to 3s then proceed
  const photoCountEl = document.getElementById('sa-sales-photo-count');
  const filesInput = document.getElementById('sa-sales-photos');
  const expectedCount = filesInput && filesInput.files ? Math.min(filesInput.files.length, 10) : 0;

  function _doSave() {
    const id = 'sp_' + Date.now();
    const photosToSave = _salesAdminPhotos.filter(Boolean);

    const newProp = {
      id, title, type,
      country: countryData ? countryData.name : country,
      countryCode: country,
      province,
      price: Number(price),
      currency,
      beds: beds || null,
      area: area || null,
      address: address || null,
      lat: _salesAdminLat,
      lng: _salesAdminLng,
      desc,
      phone,
      email,
      date: Date.now(),
      hidden: false,
    };

    const props = getSalesProps();
    props.push(newProp);

    // Save property metadata (without images) to _LS
    const saved = saveSalesProps(props);
    if (!saved) {
      showErr(errEl, '⚠️ Save failed — storage may be full. Try clearing browser data or using fewer/smaller photos.');
      return;
    }

    // Save images separately to _SS (sessionStorage) — avoids localStorage quota
    if (photosToSave.length > 0) {
      saveSalesPropImages(id, photosToSave);
    }

    // Reset form
    ['sa-sales-title','sa-sales-price','sa-sales-area','sa-sales-address','sa-sales-desc','sa-sales-phone','sa-sales-email'].forEach(k => {
      const el = document.getElementById(k); if (el) el.value = '';
    });
    ['sa-sales-type','sa-sales-country','sa-sales-province','sa-sales-currency'].forEach(k => {
      const el = document.getElementById(k); if (el) el.value = el.tagName === 'SELECT' ? (el.options[0]?.value || '') : '';
    });
    const prev = document.getElementById('sa-sales-photo-preview');
    if (prev) prev.innerHTML = '';
    const fi = document.getElementById('sa-sales-photos');
    if (fi) fi.value = '';
    _salesAdminPhotos = [];
    const lbl = document.getElementById('sa-sales-photo-count');
    if (lbl) lbl.remove();

    _salesAdminLat = null;
    _salesAdminLng = null;
    _updateSalesAdminLocationBadge();

    saLog('create', 'Sales property added', title, 'superadmin');
    renderSalesAdminList();
    showToast('🏡 Sales property added! (' + (photosToSave.length > 0 ? photosToSave.length + ' photo' + (photosToSave.length > 1 ? 's' : '') : 'no photos') + ')', 'success');
  }

  // If photos were selected but not all loaded yet, poll briefly
  if (expectedCount > 0 && _salesAdminPhotos.filter(Boolean).length < expectedCount) {
    let attempts = 0;
    const poll = setInterval(() => {
      attempts++;
      if (_salesAdminPhotos.filter(Boolean).length >= expectedCount || attempts > 30) {
        clearInterval(poll);
        _doSave();
      }
    }, 100);
    if (photoCountEl) photoCountEl.textContent = 'Saving photos…';
  } else {
    _doSave();
  }
}

// ── ADMIN: Render sales list ──────────────────────────────────────
function renderSalesAdminList() {
  const list = document.getElementById('sa-sales-list');
  const countEl = document.getElementById('sa-sales-count');
  if (!list) return;

  const props = getSalesProps();
  if (countEl) countEl.textContent = props.length;

  if (props.length === 0) {
    list.innerHTML = '<div style="text-align:center;padding:32px;color:var(--grey);font-size:0.88rem;">No sales properties yet.</div>';
    return;
  }

  list.innerHTML = props.sort((a, b) => b.date - a.date).map(p => {
    const imgs = getSalesPropImages(p.id);
    const fmtPrice = Number(p.price).toLocaleString();
    const vc = p.views || 0;
    const viewsBadgeId = 'sales-views-badge-' + p.id;
    const viewsCountId = 'sales-views-count-' + p.id;
    return `
    <div class="sales-admin-card">
      <div class="sales-admin-card-header">
        <div class="sales-admin-card-title">
          ${p.hidden ? '🙈' : '🏡'} ${escHtml(p.title)}
        </div>
        <div class="sales-admin-card-meta">
          <span class="sales-price-pill">${p.currency} ${fmtPrice}</span>
          <span style="color:#6b7280;">📍 ${escHtml(p.province || '–')}, ${escHtml(p.country || 'PNG')}</span>
          <span style="color:#6b7280;">🏠 ${escHtml(p.type)}</span>
        </div>
        <div id="${viewsBadgeId}" class="my-listing-views-badge${vc === 0 ? ' views-zero' : ''}" style="margin-top:8px;"
             title="${vc > 0 ? vc + ' people have viewed this property' : 'No one has viewed this property yet'}">
          <span class="views-eye">👁️</span>
          <span class="views-count" id="${viewsCountId}">${vc > 0 ? vc.toLocaleString() : '0'}</span>
          <span class="views-label">${vc === 1 ? 'view' : 'views'}</span>
          ${vc >= 50 ? `<span class="views-milestone">⚡</span>` : vc >= 10 ? `<span class="views-milestone">🔥</span>` : ''}
        </div>
      </div>
      <div style="padding:10px 18px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
        <label class="live-switch live-switch-sm" title="${p.hidden ? 'Turn on to make this visible to the public' : 'Turn off to take this down from the public'}" style="margin-right:2px;">
          <input type="checkbox" ${p.hidden ? '' : 'checked'} onchange="saToggleSalesHide('${escAttr(p.id)}')">
          <div class="live-switch-track"></div>
          <div class="live-switch-thumb"></div>
        </label>
        <span style="font-size:0.78rem;font-weight:800;color:${p.hidden ? '#9ca3af' : '#22c55e'};">${p.hidden ? '⚫ OFF' : '🟢 ON'}</span>
        <button class="btn btn-sm" style="background:#fef3c7;color:#92400e;" onclick="saEditSalesProperty('${escAttr(p.id)}')">✏️ Edit</button>
        ${imgs.length > 0 ? `<button class="btn btn-sm" style="background:#ede9fe;color:#6d28d9;" onclick="openLightbox(${JSON.stringify(imgs).replace(/"/g,'&quot;')},0,'${escAttr(p.title)}')">🖼️ ${imgs.length} Photo${imgs.length > 1 ? 's' : ''}</button>` : ''}
        <button class="btn btn-sm" style="background:#fee2e2;color:#dc2626;" onclick="saDeleteSalesProperty('${escAttr(p.id)}')">🗑 Delete</button>
        <span style="font-size:0.72rem;color:var(--grey);margin-left:auto;">Listed ${timeAgo(p.date)}</span>
      </div>
    </div>`;
  }).join('');
  wiRender();
}

function saEditSalesProperty(id) {
  const props = getSalesProps();
  const p = props.find(x => x.id === id);
  if (!p) return;

  // Seed the sales admin pin with existing coords for editing
  _salesAdminLat = (p.lat != null) ? p.lat : null;
  _salesAdminLng = (p.lng != null) ? p.lng : null;

  // Load existing images into the edit buffer so they are preserved unless replaced
  const existingImgs = getSalesPropImages(id);
  _salesAdminPhotos = existingImgs.slice(); // copy so edits don't mutate the stored array

  const hasPinNow = _salesAdminLat != null && _salesAdminLng != null;
  const existingPhotoCount = existingImgs.length;

  saOpenModal('✏️ Edit Sales Property', `
    <div class="form-group"><label>Title</label><input type="text" id="saed-title" value="${escAttr(p.title)}"></div>
    <div class="form-group"><label>Price (${p.currency})</label><input type="number" id="saed-price" value="${p.price}"></div>
    <div class="form-group"><label>Province</label><input type="text" id="saed-province" value="${escAttr(p.province||'')}"></div>
    <div class="form-group"><label>📍 Address / Directions</label><input type="text" id="saed-address" value="${escAttr(p.address||'')}" placeholder="e.g. Lot 12, Section 45, Waigani Drive"></div>
    <div class="form-group"><label>Description</label><textarea id="saed-desc" style="min-height:80px;">${escHtml(p.desc||'')}</textarea></div>
    <div class="form-group"><label>Phone</label><input type="text" id="saed-phone" value="${escAttr(p.phone||'')}"></div>
    <div class="form-group"><label>Email</label><input type="email" id="saed-email" value="${escAttr(p.email||'')}"></div>

    <!-- ── Photo Editor ── -->
    <div style="background:#f8fafc;border:1.5px solid #e5e7eb;border-radius:10px;padding:12px;margin-bottom:12px;">
      <div style="font-size:0.75rem;font-weight:800;color:var(--teal);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:8px;">📸 Photos</div>
      ${existingPhotoCount > 0
        ? `<div style="font-size:0.8rem;color:#374151;margin-bottom:8px;">Currently <strong>${existingPhotoCount}</strong> photo${existingPhotoCount !== 1 ? 's' : ''}. Upload new photos below to <strong>replace</strong> them, or leave blank to keep existing.</div>
           <div id="saed-photo-current" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">
             ${existingImgs.map((img,i) => `<div style="position:relative;display:inline-block;">
               <img src="${escAttr(img)}" style="width:72px;height:54px;object-fit:cover;border-radius:6px;border:2px solid #d1d5db;" alt="Photo ${i+1}">
               <button onclick="saedRemoveSalesPhoto(${i})" title="Remove" style="position:absolute;top:-6px;right:-6px;background:#dc2626;color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;">✕</button>
             </div>`).join('')}
           </div>`
        : `<div style="font-size:0.8rem;color:#6b7280;margin-bottom:8px;">No photos yet. Upload photos below.</div>`
      }
      <label style="display:inline-flex;align-items:center;gap:8px;background:#f0fdf4;border:1.5px dashed #86efac;border-radius:8px;padding:9px 16px;cursor:pointer;font-size:0.82rem;color:#166534;font-weight:600;">
        📸 ${existingPhotoCount > 0 ? 'Replace All Photos' : 'Add Photos'} (up to 10)
        <input type="file" id="saed-photos" accept="image/*" multiple style="display:none;" onchange="saedHandleSalesEditPhotos(this)">
      </label>
      <div id="saed-photo-preview" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;"></div>
      <div id="saed-photo-status" style="font-size:0.78rem;color:var(--teal);font-weight:600;margin-top:6px;"></div>
    </div>

    <div style="background:rgba(13,92,99,0.05);border:1.5px solid rgba(13,92,99,0.18);border-radius:10px;padding:12px;margin-top:4px;">
      <div style="font-size:0.75rem;font-weight:800;color:var(--teal);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:8px;">📍 Exact Map Location</div>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
        <button type="button" id="sa-sales-location-btn"
          onclick="openSalesAdminLocationPicker()"
          style="flex:1;min-width:160px;display:flex;align-items:center;justify-content:center;gap:8px;padding:10px 14px;border-radius:10px;border:1.5px dashed rgba(13,92,99,0.4);background:rgba(13,92,99,0.06);color:var(--teal);font-size:0.85rem;font-weight:700;cursor:pointer;">
          <span>📍</span> ${hasPinNow ? 'Edit Location' : 'Set Exact Location'}
        </button>
        <div id="sa-sales-location-badge" style="display:${hasPinNow ? 'inline-flex' : 'none'};align-items:center;gap:6px;background:#dcfce7;border:1.5px solid #86efac;border-radius:20px;padding:5px 10px;font-size:0.78rem;font-weight:700;color:#166534;white-space:nowrap;">
          ✅ Pinned
        </div>
      </div>
      <div id="sa-sales-location-coords" style="display:${hasPinNow ? 'block' : 'none'};font-size:0.72rem;color:var(--grey);margin-top:6px;">${hasPinNow ? '📌 ' + _salesAdminLat.toFixed(6) + ', ' + _salesAdminLng.toFixed(6) : ''}</div>
    </div>
  `, () => {
    p.title    = document.getElementById('saed-title').value.trim() || p.title;
    p.price    = Number(document.getElementById('saed-price').value) || p.price;
    p.province = document.getElementById('saed-province').value.trim() || p.province;
    p.address  = document.getElementById('saed-address').value.trim() || null;
    p.desc     = document.getElementById('saed-desc').value.trim();
    p.phone    = document.getElementById('saed-phone').value.trim();
    p.email    = document.getElementById('saed-email').value.trim();
    // Save the pin if it was updated
    if (_salesAdminLat != null) { p.lat = _salesAdminLat; p.lng = _salesAdminLng; }
    _salesAdminLat = null; _salesAdminLng = null;
    // Save updated images (may be unchanged, partially removed, or fully replaced)
    const finalImgs = _salesAdminPhotos.filter(Boolean);
    if (finalImgs.length > 0) saveSalesPropImages(id, finalImgs);
    _salesAdminPhotos = [];
    saveSalesProps(props);
    renderSalesAdminList();
    saLog('update','Sales property edited', p.title, 'superadmin');
    showToast('Sales property updated ✅' + (finalImgs.length > 0 ? ' (' + finalImgs.length + ' photo' + (finalImgs.length !== 1 ? 's' : '') + ')' : ''), 'success');
  });
}

// Remove a single photo from the edit buffer and refresh the current-photo strip
function saedRemoveSalesPhoto(idx) {
  _salesAdminPhotos.splice(idx, 1);
  // Rebuild the current-photos strip in the edit modal
  const strip = document.getElementById('saed-photo-current');
  if (strip) {
    if (_salesAdminPhotos.length === 0) {
      strip.innerHTML = '';
    } else {
      strip.innerHTML = _salesAdminPhotos.map((img, i) => `<div style="position:relative;display:inline-block;">
        <img src="${escAttr(img)}" style="width:72px;height:54px;object-fit:cover;border-radius:6px;border:2px solid #d1d5db;" alt="Photo ${i+1}">
        <button onclick="saedRemoveSalesPhoto(${i})" title="Remove" style="position:absolute;top:-6px;right:-6px;background:#dc2626;color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;">✕</button>
      </div>`).join('');
    }
  }
  const status = document.getElementById('saed-photo-status');
  if (status) status.textContent = _salesAdminPhotos.length > 0 ? `${_salesAdminPhotos.length} photo${_salesAdminPhotos.length !== 1 ? 's' : ''} remaining` : 'No photos — add new ones below.';
}

// Handle new photo uploads in the edit modal
function saedHandleSalesEditPhotos(input) {
  const preview = document.getElementById('saed-photo-preview');
  const status  = document.getElementById('saed-photo-status');
  if (!preview) return;
  const files = Array.from(input.files).slice(0, 10);
  if (!files.length) return;
  // Replace buffer with newly selected files
  _salesAdminPhotos = [];
  preview.innerHTML = '';
  if (status) status.textContent = 'Loading photos…';
  // Also clear the current-strip since new photos will replace them on save
  const strip = document.getElementById('saed-photo-current');
  if (strip) strip.innerHTML = '<div style="font-size:0.78rem;color:#6b7280;font-style:italic;">Current photos will be replaced on save.</div>';

  let loaded = 0;
  files.forEach((file, idx) => {
    const reader = new FileReader();
    reader.onload = e => {
      _salesAdminPhotos[idx] = e.target.result;
      loaded++;
      const img = document.createElement('img');
      img.src = e.target.result;
      img.style.cssText = 'width:72px;height:54px;object-fit:cover;border-radius:6px;border:2px solid #86efac;';
      preview.appendChild(img);
      if (loaded === files.length) {
        _salesAdminPhotos = _salesAdminPhotos.filter(Boolean);
        if (status) status.textContent = `✅ ${_salesAdminPhotos.length} new photo${_salesAdminPhotos.length !== 1 ? 's' : ''} ready`;
      }
    };
    reader.onerror = () => { loaded++; };
    reader.readAsDataURL(file);
  });
}

function saToggleSalesHide(id) {
  const props = getSalesProps();
  const p = props.find(x => x.id === id);
  if (!p) return;
  p.hidden = !p.hidden;
  saveSalesProps(props);
  renderSalesAdminList();
  showToast(p.hidden ? '🙈 Property hidden.' : '👁 Property visible.', 'success');
}

function saDeleteSalesProperty(id) {
  if (!confirm('Permanently delete this sales property?')) return;
  const props = getSalesProps().filter(x => x.id !== id);
  saveSalesProps(props);
  // Clean up images from both _SS and _LS
  try { _SS.removeItem(LS_SALES_IMAGES + id); } catch(e) {}
  try { _LS.removeItem(LS_SALES_IMAGES + id); } catch(e) {}
  renderSalesAdminList();
  saLog('delete','Sales property deleted', id, 'superadmin');
  showToast('🗑 Sales property deleted.', 'success');
}

// ── Admin: populate province dropdown for country ─────────────────
function saPopulateSalesProvinces() {
  const countryCode = document.getElementById('sa-sales-country')?.value || '';
  const sel = document.getElementById('sa-sales-province');
  if (!sel) return;

  const PNG_PROVINCES = [
    'NCD','Morobe','Western Highlands','Madang','Eastern Highlands',
    'Bougainville','East Sepik','Hela','Milne Bay','Southern Highlands',
    'Jiwaka','Simbu','Gulf','Western','Oro','Manus',
    'East New Britain','West New Britain','New Ireland','Central','West Sepik','Enga'
  ];

  sel.innerHTML = '<option value="">— Select province/state —</option>';
  if (countryCode === 'PG') {
    PNG_PROVINCES.forEach(p => {
      const o = document.createElement('option'); o.value = p; o.textContent = p;
      sel.appendChild(o);
    });
  } else {
    // Real province/state list for the country (falls back to generic names)
    const genericProvinces = (typeof WORLD_PROVINCES !== 'undefined' && WORLD_PROVINCES[countryCode] && WORLD_PROVINCES[countryCode].length)
      ? WORLD_PROVINCES[countryCode]
      : ['Capital Region','Province 1','Province 2','Province 3','Province 4','Province 5','Northern Region','Southern Region','Eastern Region','Western Region'];
    genericProvinces.forEach(p => {
      const o = document.createElement('option'); o.value = p; o.textContent = p;
      sel.appendChild(o);
    });
  }
}

// ── Admin: populate country dropdown in sales form ────────────────
function saPopulateSalesCountries() {
  const sel = document.getElementById('sa-sales-country');
  if (!sel || sel.options.length > 1) return;
  sel.innerHTML = '<option value="">— Select country —</option>';
  getAllowedCountries().forEach(c => {
    const o = document.createElement('option');
    o.value = c.code; o.textContent = c.icon + ' ' + c.name;
    sel.appendChild(o);
  });
}

// ── Admin: render the Sales tab UI ───────────────────────────────
