// ── SALES MODE FEATURE TOGGLE ─────────────────────────────
// Controls whether the "Sales" pill/mode is offered to anyone at all.
// When off: the Sales pill disappears from the hamburger menu for every
// visitor, and anyone already in Sales Mode gets bounced back to Rental.
function isSalesModeEnabled() {
  return getSettings().salesModeEnabled !== false;
}

function toggleSalesModeFeature(enabled) {
  const s = getSettings();
  s.salesModeEnabled = enabled;
  saveSettings(s);

  if (!enabled && _appMode === 'sales') {
    setAppMode('rental');
  }

  syncModeBar();
  const dd = document.getElementById('hamburger-dropdown');
  if (dd && dd.classList.contains('open')) renderHamburgerMenu();

  showToast(enabled ? '🏡 Sales Mode is now available to visitors.' : '🚫 Sales Mode has been switched off.', enabled ? 'success' : 'error');
}

// Defensive guard — if something tries to force Sales Mode on while the
// admin has switched the feature off, fall back to Rental instead.
function enforceSalesModeAvailability() {
  if (_appMode === 'sales' && !isSalesModeEnabled()) {
    setAppMode('rental');
  }
}

// ── COUNTRY ACCESS CONTROL ───────────────────────────────
// Reusable helper: render a list of HTML row-strings into a container,
// showing only the first `limit` by default with a "See All" button to
// reveal the rest (and a "Show Less" button to re-collapse). Searching
// always shows full, unrestricted results.
function renderCollapsibleList(container, rows, opts) {
  const limit    = (opts && opts.limit) || 4;
  const itemWord = (opts && opts.itemWord) || 'items';
  const isFiltered = !!(opts && opts.isFiltered);

  if (rows.length <= limit || isFiltered) {
    container.innerHTML = rows.join('');
    return;
  }

  const visible = rows.slice(0, limit).join('');
  const hidden  = rows.slice(limit).join('');
  const remaining = rows.length - limit;
  const expandId = 'collapsible-' + Math.random().toString(36).slice(2, 9);

  container.innerHTML = `
    ${visible}
    <div class="admin-collapsible-hidden" id="${expandId}-hidden">${hidden}</div>
    <button type="button" class="admin-see-all-btn" id="${expandId}-btn" data-item-word="${escAttr(itemWord)}" onclick="toggleCollapsibleList('${expandId}', ${rows.length})">
      ⌄ See All ${rows.length} ${itemWord}
    </button>
  `;
}

function toggleCollapsibleList(expandId, total) {
  const hiddenBlock = document.getElementById(expandId + '-hidden');
  const btn = document.getElementById(expandId + '-btn');
  if (!hiddenBlock || !btn) return;
  const isOpen = !hiddenBlock.classList.contains('admin-collapsible-hidden');
  if (isOpen) {
    hiddenBlock.classList.add('admin-collapsible-hidden');
    btn.textContent = `⌄ See All ${total} ${btn.dataset.itemWord || 'items'}`;
    btn.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } else {
    hiddenBlock.classList.remove('admin-collapsible-hidden');
    btn.textContent = '⌃ Show Less';
  }
}

function renderCountryAccessList(query) {
  const container = document.getElementById('adm-country-list');
  if (!container) return;
  const s = getSettings();
  const allowed = s.allowedCountries || ['PG'];
  const q = (query || '').trim().toLowerCase();

  const list = q
    ? WORLD_COUNTRIES.filter(c => c.name.toLowerCase().includes(q))
    : WORLD_COUNTRIES;

  if (!list.length) {
    container.innerHTML = `<div style="text-align:center;color:var(--grey);font-size:0.85rem;padding:20px;">No countries match "${escHtml(query)}".</div>`;
    return;
  }

  const rows = list.map(c => {
    const isOn = allowed.includes(c.code);
    return `<div class="country-access-row ${isOn?'':'disabled'}" id="crow-${c.code}">
      <div class="cr-info">
        <span class="cr-flag">${flagImg(c.code,{width:24,emoji:c.icon})}</span>
        <div>
          <div class="cr-name">${escHtml(c.name)}</div>
          <div class="cr-sub">${c.currency} · ${c.payMethod === 'bank' ? '🏦 Bank Transfer' : '💳 Visa/Card'}</div>
        </div>
      </div>
      <div style="display:flex;align-items:center;gap:10px;">
        <span style="font-size:0.72rem;font-weight:700;color:${isOn?'#15803d':'#6b7280'};">${isOn?'ENABLED':'DISABLED'}</span>
        <label class="toggle-switch" style="width:48px;height:26px;">
          <input type="checkbox" ${isOn?'checked':''} onchange="toggleCountryAccess('${c.code}',this.checked)">
          <span class="toggle-slider"></span>
        </label>
      </div>
    </div>`;
  });

  renderCollapsibleList(container, rows, { limit: 4, itemWord: 'countries', isFiltered: !!q });
}

function setAllCountryAccess(enabled) {
  if (!confirm(enabled ? 'Enable ALL countries for registration & posting?' : 'Disable ALL countries? No landlords will be able to register or post until you re-enable some.')) return;
  const s = getSettings();
  s.allowedCountries = enabled ? WORLD_COUNTRIES.map(c => c.code) : [];
  saveSettings(s);
  const searchEl = document.getElementById('adm-country-search');
  renderCountryAccessList(searchEl ? searchEl.value : '');
  renderAdminStats();
  renderCountryGrid(getAllowedCountries());
  populatePostCountries();
  showToast(enabled ? '✅ All countries enabled' : '⛔ All countries disabled', enabled ? 'success' : 'error');
}

function toggleCountryAccess(code, enabled) {
  const s = getSettings();
  let allowed = s.allowedCountries || ['PG'];
  if (enabled) { if (!allowed.includes(code)) allowed.push(code); }
  else         { allowed = allowed.filter(c => c !== code); }
  s.allowedCountries = allowed;
  saveSettings(s);
  // Update row style
  const row = document.getElementById('crow-' + code);
  if (row) {
    row.classList.toggle('disabled', !enabled);
    const label = row.querySelector('span[style*="font-size:0.72rem"]');
    if (label) { label.textContent = enabled ? 'ENABLED' : 'DISABLED'; label.style.color = enabled ? '#15803d' : '#6b7280'; }
  }
  renderAdminStats();
  // Immediately refresh public country grid so change is live
  renderCountryGrid(getAllowedCountries());
  // Also refresh post-country dropdown for any open landlord sessions
  populatePostCountries();
  showToast((enabled ? '✅ ' : '⛔ ') + WORLD_COUNTRIES.find(c=>c.code===code)?.name + (enabled?' enabled':' disabled'), enabled?'success':'error');
}

function isCountryAllowed(countryName) {
  const s = getSettings();
  const allowed = s.allowedCountries || ['PG'];
  const country = WORLD_COUNTRIES.find(c => c.name === countryName);
  if (!country) return true; // unknown country — allow
  return allowed.includes(country.code);
}

// ── PRICING EDITOR ───────────────────────────────────────
function savePricing() {
  const basic    = Number(document.getElementById('adm-price-basic').value);
  const standard = Number(document.getElementById('adm-price-standard').value);
  const premium  = Number(document.getElementById('adm-price-premium').value);
  const iBasic   = Number(document.getElementById('adm-price-intl-basic').value);
  const iStd     = Number(document.getElementById('adm-price-intl-standard').value);
  const iPrem    = Number(document.getElementById('adm-price-intl-premium').value);

  const dBasic   = Number(document.getElementById('adm-days-basic').value);
  const dStd     = Number(document.getElementById('adm-days-standard').value);
  const dPrem    = Number(document.getElementById('adm-days-premium').value);
  const diBasic  = Number(document.getElementById('adm-days-intl-basic').value);
  const diStd    = Number(document.getElementById('adm-days-intl-standard').value);
  const diPrem   = Number(document.getElementById('adm-days-intl-premium').value);

  const err = document.getElementById('adm-price-error');
  const ok  = document.getElementById('adm-price-success');
  err.style.display = 'none'; ok.style.display = 'none';

  if (!basic || !standard || !premium || !iBasic || !iStd || !iPrem) {
    showErr(err, 'All prices must be filled in.'); return;
  }
  if (!dBasic || !dStd || !dPrem || !diBasic || !diStd || !diPrem) {
    showErr(err, 'All plan days must be filled in (minimum 1 day).'); return;
  }

  const s = getSettings();
  s.pricingPNG   = { basic, standard, premium };
  s.pricingIntl  = { basic: iBasic, standard: iStd, premium: iPrem };
  s.planDaysPNG  = { basic: dBasic, standard: dStd, premium: dPrem };
  s.planDaysIntl = { basic: diBasic, standard: diStd, premium: diPrem };
  saveSettings(s);

  // Refresh the payment modal plan cards so new days show immediately
  refreshPlanCards();

  ok.textContent = '✅ Pricing & days saved! Changes are now live for all landlords.';
  ok.style.display = 'block';
  showToast('Pricing & days updated! ✅', 'success');
}

function getPricingPNG()   { return getSettings().pricingPNG   || DEFAULT_SETTINGS.pricingPNG; }
function getPricingIntl()  { return getSettings().pricingIntl  || DEFAULT_SETTINGS.pricingIntl; }
function getPlanDaysPNG()  { return getSettings().planDaysPNG  || DEFAULT_SETTINGS.planDaysPNG; }
function getPlanDaysIntl() { return getSettings().planDaysIntl || DEFAULT_SETTINGS.planDaysIntl; }

// Re-renders the payment modal plan cards with current prices + days
function refreshPlanCards() {
  const p = getPricingPNG();
  const d = getPlanDaysPNG();
  const pi = getPricingIntl();
  const di = getPlanDaysIntl();

  // PNG cards
  const bp = document.getElementById('plan-price-basic');
  const sp = document.getElementById('plan-price-standard');
  const pp = document.getElementById('plan-price-premium');
  if (bp) bp.innerHTML = `K${p.basic} <span>/${d.basic} days</span>`;
  if (sp) sp.innerHTML = `K${p.standard} <span>/${d.standard} days</span>`;
  if (pp) pp.innerHTML = `K${p.premium} <span>/${d.premium} days</span>`;

  // Update onclick for PNG cards
  const bc = document.getElementById('plan-card-basic');
  const sc = document.getElementById('plan-card-standard');
  const pc = document.getElementById('plan-card-premium');
  if (bc) bc.setAttribute('onclick', `selectPlan(this,'basic',${p.basic},${d.basic})`);
  if (sc) sc.setAttribute('onclick', `selectPlan(this,'standard',${p.standard},${d.standard})`);
  if (pc) pc.setAttribute('onclick', `selectPlan(this,'premium',${p.premium},${d.premium})`);

  // Intl cards — update price text and onclick
  document.querySelectorAll('.pricing-card[data-plan="basic-intl"]').forEach(el => {
    const priceEl = el.querySelector('.plan-price');
    if (priceEl) priceEl.innerHTML = `$${pi.basic} <span>/${di.basic} days</span>`;
    el.setAttribute('onclick', `selectPlanIntl(this,'basic',${pi.basic},${di.basic})`);
  });
  document.querySelectorAll('.pricing-card[data-plan="standard-intl"]').forEach(el => {
    const priceEl = el.querySelector('.plan-price');
    if (priceEl) priceEl.innerHTML = `$${pi.standard} <span>/${di.standard} days</span>`;
    el.setAttribute('onclick', `selectPlanIntl(this,'standard',${pi.standard},${di.standard})`);
  });
  document.querySelectorAll('.pricing-card[data-plan="premium-intl"]').forEach(el => {
    const priceEl = el.querySelector('.plan-price');
    if (priceEl) priceEl.innerHTML = `$${pi.premium} <span>/${di.premium} days</span>`;
    el.setAttribute('onclick', `selectPlanIntl(this,'premium',${pi.premium},${di.premium})`);
  });
}

