function resetSiteAppearance() {
  if (!confirm('Reset all appearance settings to defaults?')) return;
  _LS.removeItem('wampac_appearance');
  applySiteAppearance(DEFAULT_APPEARANCE);
  loadAppearanceForm();
  showToast('Appearance reset to defaults.', 'success');
}

function applySiteAppearance(a) {
  if (!a) a = getAppearance();

  // ── CSS Variables (colors) ──────────────────────────────
  if (a.colorPrimary) {
    document.documentElement.style.setProperty('--teal', a.colorPrimary);
    // Derive dark/light variants
    document.documentElement.style.setProperty('--teal-dark', a.colorPrimary);
  }
  if (a.colorAccent) {
    document.documentElement.style.setProperty('--gold', a.colorAccent);
  }

  // ── Navbar logo ─────────────────────────────────────────
  const logo = document.querySelector('.nav-logo');
  if (logo && a.siteName) {
    if (a.siteName === 'Wampac') {
      logo.innerHTML = wampacLogoImgHTML(32);
    } else {
      const split = Math.max(1, Math.min(a.logoSplit || 3, a.siteName.length - 1));
      logo.innerHTML = escHtml(a.siteName.slice(0, split)) + '<span>' + escHtml(a.siteName.slice(split)) + '</span>';
    }
    // Note: click/tap behavior (single tap = home, double tap = hidden admin
    // access) is handled by the dedicated gesture listener on #nav-logo —
    // do not attach a separate onclick here, it would double-fire.
  }

  // ── Hero section ────────────────────────────────────────
  // Skip while a country is selected (the country hero text is showing).
  // Old saved defaults (PNG/“World” wording) are treated as unset.
  if (!browseCountry) {
    const _legacy = (v) => !v || /^Find your next place anywhere in the$/i.test(v) || /^World$/i.test(v) ||
                           /^Browse apartments, houses, offices and more — across every country\.$/i.test(v);
    const _l1 = _legacy(a.heroLine1) ? DEFAULT_APPEARANCE.heroLine1 : a.heroLine1;
    const _l2 = _legacy(a.heroLine2) ? DEFAULT_APPEARANCE.heroLine2 : a.heroLine2;
    const _sub = _legacy(a.subtext) ? DEFAULT_APPEARANCE.subtext : a.subtext;
    const heroTag = document.getElementById('hero-tag-el') || document.querySelector('.hero-tag');
    if (heroTag) heroTag.textContent = (!a.badge || /Rental Platform\s*$/i.test(a.badge)) ? DEFAULT_APPEARANCE.badge : a.badge;
    const heroH1 = document.getElementById('hero-h1-el') || document.querySelector('.hero h1');
    if (heroH1) heroH1.innerHTML = (/^welcome to$/i.test(_l1) ? '<span class="wel">Wel</span>come to' : escHtml(_l1)) + '<br>' + (/^wampac$/i.test(_l2) ? '<em>Wam</em>pac' : '<em>' + escHtml(_l2) + '</em>');
    const heroP = document.getElementById('hero-p-el') || document.querySelector('.hero p');
    if (heroP) heroP.textContent = _sub;
  }

  // ── Page title ──────────────────────────────────────────
  document.title = (a.siteName || 'Wampac') + ' – Real Estate Platform';

  // ── Step breadcrumbs ────────────────────────────────────
  const step1bc = document.querySelector('#step-country .step-breadcrumb');
  if (step1bc) step1bc.textContent = a.step1Label || DEFAULT_APPEARANCE.step1Label;

  // ── Footer ──────────────────────────────────────────────
  // Use targeted ID-based updates — avoids innerHTML corruption
  const footerName = document.getElementById('footer-site-name');
  if (footerName) footerName.textContent = a.siteName || 'Wampac';
  const footerSub = document.getElementById('footer-platform-sub');
  if (footerSub && !footerSub.dataset.countryOverride) footerSub.textContent = a.footerLine2 || DEFAULT_APPEARANCE.footerLine2;

  // ── Footer social links ──────────────────────────────────
  renderFooterSocialLinks(a);

  // Also re-apply hero background (colors may have changed)
  applyHeroBg();
}

// Normalizes a bare handle/URL entered by admin into a usable https:// link.
function normalizeSocialUrl(value, platform) {
  if (!value) return '';
  let v = value.trim();
  if (!v) return '';
  if (/^https?:\/\//i.test(v)) return v;
  // Admin typed a handle like "@wampac" or "wampac" instead of a full URL
  const handle = v.replace(/^@/, '');
  const bases = {
    facebook:  'https://facebook.com/',
    instagram: 'https://instagram.com/',
    youtube:   'https://youtube.com/@',
    linkedin:  'https://linkedin.com/company/',
  };
  return (bases[platform] || '') + handle;
}

// Formats a phone number the admin typed into a tel: link.
function normalizePhoneUrl(value) {
  if (!value) return '';
  const v = value.trim();
  if (!v) return '';
  const digits = v.replace(/[^\d+]/g, '');
  return 'tel:' + digits;
}

// Official Facebook glyph (embedded so it renders offline, no external fetch)
const FACEBOOK_ICON_URI = "data:image/png;base64,";

// Official brand glyphs (embedded so they render offline, no external fetch)
const YOUTUBE_ICON_URI = "data:image/png;base64,";
const INSTAGRAM_ICON_URI = "data:image/png;base64,";
const LINKEDIN_ICON_URI = "data:image/png;base64,";

function renderFooterSocialLinks(a) {
  const wrap = document.getElementById('footer-social-links');
  if (!wrap) return;
  const BRAND_ICONS = {
    facebook:  FACEBOOK_ICON_URI,
    youtube:   YOUTUBE_ICON_URI,
    linkedin:  LINKEDIN_ICON_URI,
    instagram: INSTAGRAM_ICON_URI,
  };
  const links = [
    { key: 'socialFacebook',  platform: 'facebook',  emoji: '📘', label: 'Facebook' },
    { key: 'socialYoutube',   platform: 'youtube',   emoji: '▶️', label: 'YouTube' },
    { key: 'socialLinkedin',  platform: 'linkedin',  emoji: '💼', label: 'LinkedIn' },
    { key: 'socialInstagram', platform: 'instagram', emoji: '📷', label: 'Instagram' },
    { key: 'socialPhone',     platform: 'phone',      emoji: '📞', label: 'Call Us' },
  ];
  const html = links
    .map(l => {
      const raw = (a[l.key] || '').trim();
      const brandUri = BRAND_ICONS[l.platform];
      // Disabled state keeps full color but dims slightly + desaturates a touch —
      // stays clearly recognizable instead of washing out to near-invisible.
      const dimStyle = raw ? '' : 'opacity:0.55;filter:grayscale(0.35);';
      const icon = brandUri
        ? `<img src="${brandUri}" alt="${l.label}" style="width:26px;height:26px;border-radius:6px;display:block;${dimStyle}">`
        : wi(l.platform, l.emoji, 24, raw ? 'currentColor' : 'rgba(255,255,255,0.55)');

      if (!raw) {
        // Not configured by admin yet — icon shows but does nothing on tap
        return `<span class="footer-social-disabled" aria-disabled="true" aria-label="${l.label} — not set up yet" title="${l.label} — not set up yet">${icon}</span>`;
      }
      const url = (l.platform === 'phone') ? normalizePhoneUrl(raw) : normalizeSocialUrl(raw, l.platform);
      const targetAttrs = (l.platform === 'phone') ? '' : ' target="_blank" rel="noopener noreferrer"';
      return `<a href="${escHtml(url)}"${targetAttrs} aria-label="${l.label}" title="${l.label}">${icon}</a>`;
    })
    .join('');
  wrap.innerHTML = html;
  wiRender();
}

// ── DEFAULT AREAS TABLE ──────────────────────────────────
function renderDefaultAreasTable() {
  const tbody = document.getElementById('adm-default-areas-tbody');
  const countEl = document.getElementById('default-area-count');
  if (!tbody) return;
  const props = getProps();
  const areas = DEFAULT_AREAS;
  if (countEl) countEl.textContent = areas.length + ' built-in areas';
  tbody.innerHTML = areas.map(a => {
    const count = props.filter(p => p.area === a.name && (p.status==='approved'||!p.status)).length;
    return `<tr>
      <td style="font-size:1.2rem;">${a.icon}</td>
      <td class="name-cell">${escHtml(a.name)}</td>
      <td>${escHtml(a.province||'—')}</td>
      <td>PNG ${FlagIcon('pg',{width:18})}</td>
      <td><span class="pill ${count>0?'pill-blue':'pill-yellow'}">${count}</span></td>
    </tr>`;
  }).join('');
}

// ══════════════════════════════════════════════════════════════════
//  PROVINCE ACCORDION — Areas Admin
//  • All areas grouped by province
//  • Each province is a collapsible row
//  • Inline ＋ form per province to add area without leaving the view
//  • Custom (admin-added) areas show a purple badge + delete button
//  • Adding an area to a province = it appears under that province only
// ══════════════════════════════════════════════════════════════════

const PNG_PROVINCES = [
  'NCD','Morobe','Western Highlands','Eastern Highlands','East New Britain',
  'West New Britain','Madang','Sandaun','East Sepik','Manus','New Ireland',
  'Milne Bay','Central','Gulf','Oro','Southern Highlands','Hela','Jiwaka',
  'Simbu','Western','Bougainville','Enga'
];

// Which province accordions are currently open (persisted in memory)
const _openProvinces = new Set(['NCD']); // NCD open by default
const _expandedAreaLists = new Set(); // provinces whose "see more" area list is expanded

// ── ADMIN: review landlord-submitted area requests ─────────────────
function updateAreaRequestBadge() {
  const count = getAreaRequests().filter(r => r.status === 'pending').length;
  const badge = document.getElementById('pending-area-req-badge');
  if (badge) { badge.textContent = count; badge.style.display = count > 0 ? 'inline-flex' : 'none'; }
}

function renderAreaRequests() {
  const listEl = document.getElementById('adm-area-requests-list');
  if (!listEl) return;
  const requests = getAreaRequests().filter(r => r.status === 'pending').sort((a,b) => a.submittedAt - b.submittedAt);
  const countEl = document.getElementById('area-request-count');
  if (countEl) countEl.textContent = requests.length ? `${requests.length} awaiting review` : '';
  updateAreaRequestBadge();

  if (requests.length === 0) {
    listEl.innerHTML = `<div style="padding:14px;font-size:0.82rem;color:var(--grey);background:#fff;border-radius:10px;border:1.5px solid #e5e7eb;">No pending area requests right now.</div>`;
    return;
  }

  listEl.innerHTML = requests.map(r => {
    const safeId = r.id;
    const submittedDate = new Date(r.submittedAt).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });
    const provOptions = PNG_PROVINCES.map(p => `<option value="${escAttr(p)}" ${p===r.province?'selected':''}>${escHtml(p)}</option>`).join('');
    return `<div class="area-req-card" id="area-req-${safeId}" style="background:#fff;border:1.5px solid #fde68a;border-radius:12px;padding:14px;margin-bottom:12px;">
      <div style="font-size:0.72rem;color:var(--grey);margin-bottom:10px;">
        Submitted by <strong>${escHtml(r.landlordName||'Unknown')}</strong> · ${submittedDate}
      </div>
      <div class="form-group" style="margin-bottom:8px;">
        <label style="font-size:0.72rem;">Area / suburb name</label>
        <input type="text" id="area-req-name-${safeId}" value="${escAttr(r.name)}" style="width:100%;box-sizing:border-box;padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:0.85rem;">
      </div>
      <div class="form-group" style="margin-bottom:10px;">
        <label style="font-size:0.72rem;">Province</label>
        <select id="area-req-prov-${safeId}" style="width:100%;padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:0.85rem;">
          <option value="">– Select province –</option>
          ${provOptions}
        </select>
      </div>
      <div class="prov-inline-err" id="area-req-err-${safeId}"></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        <button class="prov-inline-save" onclick="approveAreaRequest('${safeId}')"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Approve</button>
        <button class="prov-inline-cancel" style="background:#fee2e2;color:var(--coral);" onclick="rejectAreaRequest('${safeId}')"><span class="wi-svg" data-lucide="x-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">❌</span> Reject</button>
      </div>
    </div>`;
  }).join('');
}

function approveAreaRequest(id) {
  const requests = getAreaRequests();
  const req = requests.find(r => r.id === id);
  if (!req) return;
  const nameEl = document.getElementById(`area-req-name-${id}`);
  const provEl = document.getElementById(`area-req-prov-${id}`);
  const errEl  = document.getElementById(`area-req-err-${id}`);
  const finalName = nameEl ? nameEl.value.trim() : req.name;
  const finalProv = provEl ? provEl.value : req.province;

  if (errEl) errEl.style.display = 'none';
  if (!finalName) { if (errEl) { errEl.textContent = 'Name cannot be empty.'; errEl.style.display = 'block'; } return; }
  if (!finalProv) { if (errEl) { errEl.textContent = 'Please select a province.'; errEl.style.display = 'block'; } return; }

  const existingNames = getAREAS().map(a => a.name.toLowerCase());
  if (existingNames.includes(finalName.toLowerCase())) {
    if (errEl) { errEl.textContent = `"${finalName}" already exists in the area list.`; errEl.style.display = 'block'; }
    return;
  }

  // Add to the custom area list (same storage the manual "add area" admin form uses)
  const extras = JSON.parse(_LS.getItem('wampac_extra_areas') || '[]');
  extras.push({ name: finalName, province: finalProv, icon: req.icon || '🏘️', countryCode: req.countryCode || 'PG' });
  _LS.setItem('wampac_extra_areas', JSON.stringify(extras));

  // If the admin corrected the spelling, carry that fix over to any listing already using the original name
  if (finalName !== req.name) {
    const props = getProps();
    let changed = false;
    props.forEach(p => { if (p.area === req.name) { p.area = finalName; changed = true; } });
    if (changed) saveProps(props);
  }

  req.status = 'approved';
  req.reviewedAt = Date.now();
  req.approvedAs = finalName;
  req.approvedProvince = finalProv;
  saveAreaRequests(requests);

  AREAS = getAREAS();
  populateAreaSelects();
  refreshAllGrids();
  _openProvinces.add(finalProv);
  renderProvinceAccordion();
  renderAreaRequests();
  showToast(`✅ "${finalName}" approved and added to ${finalProv}!`, 'success');
}

function rejectAreaRequest(id) {
  if (!confirm('Reject this area request? The landlord will need to pick an existing area or submit a new request.')) return;
  const requests = getAreaRequests();
  const req = requests.find(r => r.id === id);
  if (!req) return;
  req.status = 'rejected';
  req.reviewedAt = Date.now();
  saveAreaRequests(requests);
  renderAreaRequests();
  showToast(`"${req.name}" request rejected.`, 'error');
}

function renderProvinceAccordion() {
  const container = document.getElementById('adm-province-accordion');
  if (!container) return;

  const props   = getProps();
  const extras  = JSON.parse(_LS.getItem('wampac_extra_areas') || '[]');
  const extraNames = new Set(extras.map(a => a.name.toLowerCase()));

  // Count label
  const allAreas = getAREAS();
  const countEl  = document.getElementById('default-area-count');
  if (countEl) countEl.textContent = `${DEFAULT_AREAS.length} built-in · ${extras.length} custom · ${allAreas.length} total`;

  container.innerHTML = PNG_PROVINCES.map(prov => {
    const provAreas = allAreas.filter(a => a.province === prov);
    const listingCount = props.filter(p => provAreas.some(a => a.name === p.area) && (p.status==='approved'||!p.status)).length;
    const isOpen = _openProvinces.has(prov);
    const provIcon = PROV_ICONS[prov] || '📍';
    const safeId   = prov.replace(/\s+/g,'_');

    const areaRowsArr = provAreas.map(a => {
      const isCustom = extraNames.has(a.name.toLowerCase());
      const aListings = props.filter(p => p.area === a.name && (p.status==='approved'||!p.status)).length;
      const badge = isCustom ? `<span class="prov-area-custom-badge">custom</span>` : `<span class="prov-area-custom-badge" style="background:#e0f2fe;color:#0369a1;">built-in</span>`;
      const areaKey = encodeURIComponent(a.name); // safe key for DOM ids
      const safeAreaId = a.name.replace(/[^a-zA-Z0-9]/g,'_');

      return `<div class="prov-area-wrap" id="area-wrap-${safeAreaId}">
        <div class="prov-area-row">
          <span class="prov-area-emoji" id="area-icon-display-${safeAreaId}">${a.icon||'🏘️'}</span>
          <span class="prov-area-name" id="area-name-display-${safeAreaId}">${escHtml(a.name)}</span>
          ${badge}
          <span class="prov-area-listings">${aListings > 0 ? aListings + ' listing' + (aListings!==1?'s':'') : ''}</span>
          <div class="prov-area-actions">
            <button class="prov-area-action-btn edit-btn" onclick="event.stopPropagation();openAreaEdit('${escAttr(a.name)}','${escAttr(prov)}')" title="Edit">✏️</button>
            <button class="prov-area-action-btn del-btn" onclick="event.stopPropagation();adminDeleteAreaInline('${escAttr(a.name)}','${escAttr(prov)}')" title="Remove"><span class="wi-svg" data-lucide="trash-2" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">🗑</span></button>
          </div>
        </div>
        <div class="area-inline-edit" id="area-edit-${safeAreaId}">
          <div style="font-size:0.75rem;font-weight:700;color:#7c3aed;margin-bottom:8px;">✏️ Edit: ${escHtml(a.name)}</div>
          <input type="text" class="area-edit-name-input" id="area-edit-name-${safeAreaId}" value="${escAttr(a.name)}" placeholder="Area name…">
          <div class="emoji-picker-wrap" style="margin-top:8px;">
            <div class="emoji-picker-label">Choose icon:</div>
            <div class="emoji-picker-grid" id="area-edit-emoji-grid-${safeAreaId}"></div>
            <div class="emoji-selected-preview" id="area-edit-preview-${safeAreaId}" style="display:none;">
              <span class="prev-em" id="area-edit-emoji-show-${safeAreaId}">${a.icon||'🏘️'}</span>
              <span>Selected</span>
            </div>
          </div>
          <input type="hidden" id="area-edit-icon-${safeAreaId}" value="${escAttr(a.icon||'🏘️')}">
          <div class="prov-inline-err" id="area-edit-err-${safeAreaId}"></div>
          <div class="prov-inline-add-actions" style="margin-top:10px;">
            <button class="prov-inline-save" style="background:#7c3aed;" onclick="saveAreaEdit('${escAttr(a.name)}','${escAttr(prov)}')">Save Changes</button>
            <button class="prov-inline-cancel" onclick="closeAreaEdit('${escAttr(a.name)}')">Cancel</button>
          </div>
        </div>
      </div>`;
    });

    const AREA_ROWS_VISIBLE = 4;
    const visibleAreaRows = areaRowsArr.slice(0, AREA_ROWS_VISIBLE).join('');
    const extraAreaRows   = areaRowsArr.slice(AREA_ROWS_VISIBLE).join('');
    const extraCount      = areaRowsArr.length - AREA_ROWS_VISIBLE;
    const isAreasExpanded = _expandedAreaLists.has(prov);
    const seeMoreBtn = extraCount > 0
      ? `<button type="button" class="prov-area-seemore" id="prov-seemore-${safeId}" onclick="event.stopPropagation();toggleProvAreaSeeMore('${escAttr(prov)}')">${isAreasExpanded ? '▲ Show less' : `▾ See ${extraCount} more`}</button>`
      : '';
    const areaRows = visibleAreaRows
      + (extraCount > 0 ? `<div class="prov-area-extra" id="prov-area-extra-${safeId}" style="${isAreasExpanded?'':'display:none;'}">${extraAreaRows}</div>` : '')
      + seeMoreBtn;

    return `<div class="prov-accordion-item" id="prov-item-${safeId}">
      <div class="prov-accordion-header ${isOpen?'open':''}" id="prov-header-${safeId}" onclick="toggleProvAccordion('${escAttr(prov)}')">
        <span class="prov-accordion-icon">${provIcon}</span>
        <span class="prov-accordion-name">${escHtml(prov)}</span>
        <span class="prov-accordion-meta">${provAreas.length} areas${listingCount>0?' · '+listingCount+' listing'+(listingCount!==1?'s':''):''}</span>
        <button class="prov-add-btn" onclick="event.stopPropagation();openProvInlineAdd('${escAttr(prov)}')" title="Add area to ${escAttr(prov)}">＋</button>
        <span class="prov-accordion-chevron">▼</span>
      </div>
      <div class="prov-accordion-body ${isOpen?'open':''}" id="prov-body-${safeId}">
        ${areaRows || '<div style="padding:8px;font-size:0.8rem;color:var(--grey);">No areas yet — add one below.</div>'}
        <div class="prov-inline-add" id="prov-add-form-${safeId}">
          <div style="font-size:0.78rem;font-weight:700;color:var(--teal);margin-bottom:8px;">➕ Add area to ${escHtml(prov)}</div>
          <div class="prov-inline-add-row">
            <input type="text" id="prov-add-name-${safeId}" placeholder="Area / suburb name…" onkeydown="if(event.key==='Enter')saveProvArea('${escAttr(prov)}')">
          </div>
          <div class="emoji-picker-wrap">
            <div class="emoji-picker-label">Choose an icon emoji:</div>
            <div class="emoji-picker-grid" id="prov-emoji-grid-${safeId}"></div>
            <div class="emoji-selected-preview" id="prov-emoji-preview-${safeId}" style="display:none;">
              <span class="prev-em" id="prov-emoji-show-${safeId}">🏘️</span>
              <span>Selected</span>
            </div>
          </div>
          <input type="hidden" id="prov-add-icon-${safeId}" value="🏘️">
          <div class="prov-inline-err" id="prov-add-err-${safeId}"></div>
          <div class="prov-inline-add-actions">
            <button class="prov-inline-save" onclick="saveProvArea('${escAttr(prov)}')">Save Area</button>
            <button class="prov-inline-cancel" onclick="closeProvInlineAdd('${escAttr(prov)}')">Cancel</button>
          </div>
        </div>
      </div>
    </div>`;
  }).join('');
}

