function adminClearAllListings() {
  if (!confirm('⚠️ DELETE ALL LISTINGS permanently? This cannot be undone.')) return;
  // Wipe all listing images from _SS
  const allProps = getProps();
  allProps.forEach(p => deleteListingImages(p.id));
  // Also scan _SS for any orphaned image keys
  try {
    Object.keys(_SS).filter(k => k.startsWith(IMG_PREFIX)).forEach(k => _SS.removeItem(k));
  } catch(e) {}
  saveProps([]);
  renderAdminStats();
  showToast('All listings cleared.', 'error');
}
function adminClearAllPayments() {
  if (!confirm('⚠️ DELETE ALL PAYMENT RECORDS permanently?')) return;
  _LS.removeItem(LS_PAYMENTS); renderAdminStats();
  showToast('All payment records cleared.', 'error');
}
function adminClearAllUsers() {
  if (!confirm('⚠️ DELETE ALL LANDLORD ACCOUNTS permanently?')) return;
  saveUsers([]); saveProps([]); _LS.removeItem(LS_PAYMENTS); renderAdminStats();
  showToast('All landlord data cleared.', 'error');
}

