function checkPostingAllowed(countryName) {
  // Check if country is allowed
  if (!isCountryAllowed(countryName)) {
    return { allowed: false, reason: `⛔ "${countryName}" is not yet enabled on Wampac. Contact the site administrator.` };
  }
  return { allowed: true };
}

