// ── Admin: render waitlist entries ───────────────────────
function renderAdminWaitlist() {
  const el = document.getElementById('adm-waitlist-list');
  if (!el) return;
  const LS_WL = 'wampac_waitlist';
  const wl = JSON.parse(_LS.getItem(LS_WL) || '[]');
  if (wl.length === 0) {
    el.innerHTML = '<div style="text-align:center;color:var(--grey);padding:20px;">No waitlist entries yet.</div>';
    return;
  }
  const props = getProps();
  const limit = 4;
  const buildRow = (w, idx) => {
    const p = props.find(x => x.id === w.propId);
    const d = new Date(w.date).toLocaleDateString('en-PG');
    return `<tr>
      <td class="name-cell">${p ? escHtml(p.title) : 'Unknown listing'}<div class="sub-cell">${p ? escHtml(p.area) : ''}</div></td>
      <td>${escHtml(w.name)}</td>
      <td><a href="tel:${escHtml(w.phone)}" style="color:var(--teal);font-weight:600;">${escHtml(w.phone)}</a></td>
      <td style="font-size:0.78rem;color:var(--grey);">${d}</td>
      <td><button class="admin-action-btn danger" onclick="adminDeleteWaitlist(${idx})">🗑 Remove</button></td>
    </tr>`;
  };

  if (wl.length <= limit) {
    el.innerHTML = `<div class="admin-table-wrap"><table class="admin-table">
      <thead><tr><th>Property</th><th>Tenant Name</th><th>Phone</th><th>Date</th><th>Actions</th></tr></thead>
      <tbody>${wl.map(buildRow).join('')}</tbody>
    </table></div>`;
    return;
  }

  const expandId = 'wl-collapsible-' + Math.random().toString(36).slice(2, 9);
  const visibleRows = wl.slice(0, limit).map(buildRow).join('');
  const hiddenRows  = wl.slice(limit).map((w, i) => buildRow(w, i + limit)).join('');

  el.innerHTML = `<div class="admin-table-wrap"><table class="admin-table">
    <thead><tr><th>Property</th><th>Tenant Name</th><th>Phone</th><th>Date</th><th>Actions</th></tr></thead>
    <tbody>${visibleRows}<tbody class="admin-collapsible-hidden" id="${expandId}-hidden" style="display:table-row-group;">${hiddenRows}</tbody>
  </table></div>
  <button type="button" class="admin-see-all-btn" id="${expandId}-btn" data-item-word="waitlist entries" onclick="toggleCollapsibleList('${expandId}', ${wl.length})">⌄ See All ${wl.length} waitlist entries</button>`;
}

function adminDeleteWaitlist(idx) {
  const LS_WL = 'wampac_waitlist';
  const wl = JSON.parse(_LS.getItem(LS_WL) || '[]');
  wl.splice(idx, 1);
  _LS.setItem(LS_WL, JSON.stringify(wl));
  renderAdminWaitlist();
  showToast('Waitlist entry removed.', 'error');
}

