const LS_ADMIN       = 'pom_admin_creds';

// ── Reset stored admin creds so the hardcoded super-admin always works ──
// This runs once per page load. If the admin has a custom username/pass
// saved in _LS from a prior session, it won't block login on a
// fresh device. Custom creds can still be set from inside the Admin Panel.
(function _resetAdminCreds() {
  try {
    const stored = JSON.parse(_LS.getItem(LS_ADMIN) || 'null');
    // If stored creds don't match our current defaults, clear them so the
    // hardcoded ADMIN_DEFAULT_USER / ADMIN_DEFAULT_PASS are always valid.
    if (stored) {
      _LS.removeItem(LS_ADMIN);
    }
  } catch(e) {}
})();
const LS_ANNOUNCE    = 'pom_announcement';
const LS_SUSPENDED   = 'pom_suspended';
const ADMIN_DEFAULT_USER = 'wampac@2026';
const ADMIN_DEFAULT_PASS = 'r5redino';

function getAdminCreds() {
  try { return JSON.parse(_LS.getItem(LS_ADMIN) || 'null'); } catch(e){ return null; }
}
function getSuspended() {
  try { return JSON.parse(_LS.getItem(LS_SUSPENDED) || '[]'); } catch(e){ return []; }
}
function saveSuspended(s) { _LS.setItem(LS_SUSPENDED, JSON.stringify(s)); }

let adminSession = false;
let currentAdminAccount = null; // { id, username, role } for sub-admins; null = Super Admin

function openAdminLogin() {
  closeModal('auth-modal');
  document.getElementById('adm-login-error').style.display = 'none';
  document.getElementById('adm-username').value = '';
  document.getElementById('adm-password').value = '';
  openModal('admin-login-modal');
}

// ── Hidden admin access: double-tap the logo ──
// A single tap on the logo navigates home as usual. Only when tapped/clicked
// twice in quick succession (within 400ms) does it open the admin login —
// there is no visible hint this exists; only an admin who knows to
// double-tap the logo will find it.
(function initAdminAccessDoubleTap() {
  const DOUBLE_TAP_MS = 400;
  let lastTapTime = 0;
  let singleTapTimer = null;

  function attach() {
    const logo = document.getElementById('nav-logo');
    if (!logo) return;

    const handleTap = (e) => {
      e.preventDefault();
      const now = Date.now();
      if (now - lastTapTime < DOUBLE_TAP_MS) {
        // Double tap detected — cancel the pending single-tap navigation
        // and open the hidden admin login instead.
        lastTapTime = 0;
        if (singleTapTimer) { clearTimeout(singleTapTimer); singleTapTimer = null; }
        openAdminLogin();
      } else {
        lastTapTime = now;
        // Wait to see if a second tap follows; if not, treat as a normal
        // single tap and navigate home.
        if (singleTapTimer) clearTimeout(singleTapTimer);
        singleTapTimer = setTimeout(() => {
          singleTapTimer = null;
          showPage('home');
        }, DOUBLE_TAP_MS);
      }
    };

    logo.addEventListener('click', handleTap);
    // Mobile browsers fire 'click' for taps too, so this single listener
    // handles both touch double-tap and desktop double-click correctly.
    logo.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attach);
  } else {
    attach();
  }
})();

function doAdminLogin() {
  const u = document.getElementById('adm-username').value.trim();
  const p = document.getElementById('adm-password').value;
  const err = document.getElementById('adm-login-error');
  err.style.display = 'none';

  if (!u || !p) { showErr(err, 'Please enter username and password.'); return; }

  // 1) Super Admin — always checked against hardcoded credentials first (no _LS override)
  if (u === ADMIN_DEFAULT_USER && p === ADMIN_DEFAULT_PASS) {
    adminSession = true;
    currentAdminAccount = null;
    _SS.setItem('pom_admin_session', '1');
    _SS.removeItem('pom_subadmin_session');
    closeModal('admin-login-modal');
    showPage('admin');
    renderAdminDashboard();
    renderHamburgerMenu();
    showToast('Welcome, Admin! 👑', 'success');
    return;
  }

  // 2) Sub-admin accounts
  const accounts = saGetAdminAccounts();
  const acct = accounts.find(a => a.username === u);
  if (acct && hashish(p) === acct.hash) {
    adminSession = true;
    currentAdminAccount = { id: acct.id, username: acct.username, role: acct.role || 'moderator' };
    _SS.setItem('pom_admin_session', '1');
    _SS.setItem('pom_subadmin_session', JSON.stringify(currentAdminAccount));
    closeModal('admin-login-modal');
    showPage('admin');
    renderAdminDashboard();
    renderHamburgerMenu();
    const rm = SA_ROLE_META[currentAdminAccount.role] || { label: currentAdminAccount.role, icon: '🛡️' };
    showToast(`Welcome, ${acct.username}! ${rm.icon} ${rm.label}`, 'success');
    return;
  }

  showErr(err, 'Incorrect credentials. Access denied.');
}

function adminLogout() {
  adminSession = false;
  currentAdminAccount = null;
  _SS.removeItem('pom_admin_session');
  _SS.removeItem('pom_subadmin_session');
  showPage('home');
  renderHamburgerMenu();
  showToast('Admin signed out.');
}


// ── ADMIN AREA MANAGEMENT ────────────────────────────────────────────
function adminDeleteArea(name) {
  if (!confirm(`Remove "${name}" from the area list? Existing listings in this area will remain but won't be browseable.`)) return;
  let extras = JSON.parse(_LS.getItem('wampac_extra_areas') || '[]');
  extras = extras.filter(a => a.name !== name);
  _LS.setItem('wampac_extra_areas', JSON.stringify(extras));
  AREAS = getAREAS();
  populateAreaSelects();
  renderExtraAreas();
  refreshAllGrids();
  showToast(`"${name}" removed.`, 'error');
}

function renderAdminDashboard() {
  renderAdminStats();
  loadAnnouncement();
  renderOverviewFinKPI();
  updatePaymentBadge(isPaymentEnabled());
  updateSupportNavBadge();
  applySiteAppearance();
  checkMaintenanceMode();
  updateAdminTopbarIdentity();

  // ── RBAC: hide tabs the current role is not permitted to see ──
  document.querySelectorAll('.adm-tab').forEach(btn => {
    // Extract tab key from onclick="switchAdminTab('KEY',this)"
    const match = (btn.getAttribute('onclick') || '').match(/switchAdminTab\('([^']+)'/);
    if (!match) return;
    const tabKey = match[1];
    const requiredPerm = TAB_PERMISSIONS[tabKey];
    // undefined means not in map → show to all (defensive default)
    const allowed = (requiredPerm === undefined) ? true : adminHasPerm(requiredPerm);
    btn.style.display = allowed ? '' : 'none';
  });

  // ── Determine the first visible tab and land on it ──
  document.querySelectorAll('.adm-tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.adm-tab-panel').forEach(p => p.style.display = 'none');

  const firstVisible = Array.from(document.querySelectorAll('.adm-tab'))
    .find(t => t.style.display !== 'none');
  if (firstVisible) {
    firstVisible.classList.add('active');
    const match = (firstVisible.getAttribute('onclick') || '').match(/switchAdminTab\('([^']+)'/);
    if (match) {
      const panel = document.getElementById('adm-tab-' + match[1]);
      if (panel) panel.style.display = 'block';
      // Lazy-load the landing tab
      if (match[1] === 'overview')   { renderAdminStats(); loadAnnouncement(); }
      if (match[1] === 'landlords')  renderAdminUsers('');
      if (match[1] === 'listings')   renderAdminListings('');
      if (match[1] === 'payments')   { renderAdminPayments(); loadBankDetailsForm(); renderAdminWaitlist(); }
      if (match[1] === 'areas')      { renderExtraAreas(''); renderDefaultAreasTable(); renderAreaRequests(); }
      if (match[1] === 'support')    renderAdminSupportTickets();
      if (match[1] === 'audit')      { if (typeof saRenderAuditLog === 'function') saRenderAuditLog(); }
    }
  }

  // ── Settings tab: hide Credentials & Danger Zone sub-tabs for non-super-admins ──
  _enforceSettingsSubTabAccess();
  wiRender();
}

// Reflects the actual logged-in admin (Super Admin or a sub-admin like
// Moderator / Finance Verifier) in the dashboard topbar — role badge +
// username — instead of always showing "Super Admin".
function updateAdminTopbarIdentity() {
  const badge = document.getElementById('adm-topbar-role-badge');
  const userEl = document.getElementById('sa-session-user');
  if (currentAdminAccount) {
    const rm = (typeof SA_ROLE_META !== 'undefined' && SA_ROLE_META[currentAdminAccount.role])
      || { label: currentAdminAccount.role || 'Admin', icon: '🛡️' };
    if (badge) { badge.textContent = rm.icon + ' ' + rm.label; badge.classList.add('role-mod'); }
    if (userEl) userEl.textContent = '● ' + currentAdminAccount.username;
  } else {
    const creds = getAdminCreds ? getAdminCreds() : null;
    if (badge) { badge.textContent = '👑 Super Admin'; badge.classList.remove('role-mod'); }
    if (userEl) userEl.textContent = '● ' + (creds ? creds.username : ADMIN_DEFAULT_USER);
  }
}

// ── RBAC: hide super-admin-only sub-tabs inside Settings for sub-admins ──
// The Settings tab itself is already super-admin-only via TAB_PERMISSIONS,
// but if that mapping is ever relaxed this function ensures Credentials and
// Danger Zone are always protected regardless.
function _enforceSettingsSubTabAccess() {
  if (currentAdminAccount) {
    // Hide Credentials sub-tab button
    const settSubtabs = document.querySelectorAll('#adm-tab-settings .sa-subtab');
    settSubtabs.forEach(btn => {
      const txt = btn.textContent || '';
      if (txt.includes('Credentials') || txt.includes('Danger Zone')) {
        btn.style.display = 'none';
      }
    });
    // Also blank-out the credentials sub-panel HTML so its fields are never accessible
    if (credPanel) {
      credPanel.innerHTML = `
        <div style="display:flex;flex-direction:column;align-items:center;padding:48px 24px;text-align:center;">
          <div style="font-size:2.5rem;margin-bottom:12px;">🔒</div>
          <h4 style="color:#1e293b;margin-bottom:6px;">Credentials — Super Admin Only</h4>
          <p style="color:#64748b;font-size:0.85rem;max-width:340px;line-height:1.6;">
            Username and password changes are restricted to the Super Admin account.
          </p>
        </div>`;
    }
    // Hide Danger Zone sub-panel
    const dangerPanel = document.getElementById('sa-sett-subpanel-dangerzone');
    if (dangerPanel) dangerPanel.style.display = 'none';
  } else {
    // Super Admin: restore sub-tab visibility
    const settSubtabs = document.querySelectorAll('#adm-tab-settings .sa-subtab');
    settSubtabs.forEach(btn => { btn.style.display = ''; });
    const dangerPanel = document.getElementById('sa-sett-subpanel-dangerzone');
    if (dangerPanel) dangerPanel.style.display = '';

    // If a sub-admin visited Settings earlier in this same session, the
    // branch above replaced the credentials sub-panel's innerHTML with a
    // "Super Admin Only" placeholder — and never put the real form back.
    // Rebuild it here so the Super Admin doesn't end up permanently locked
    // out of changing their own credentials until a full page reload.
    const credPanel = document.getElementById('sa-sett-subpanel-credentials');
    if (credPanel && !document.getElementById('adm-new-username')) {
      credPanel.innerHTML = `
        <div class="sa-settings-grid">
          <div class="sa-settings-card">
            <h4>👤 Change Admin Username</h4>
            <div class="form-group" style="margin-bottom:10px;">
              <label>Current Username</label>
              <input type="text" id="adm-current-user-display" placeholder="Current username" readonly
                style="background:#f1f5f9;color:var(--grey);cursor:not-allowed;">
            </div>
            <div class="form-group" style="margin-bottom:10px;">
              <label>New Username</label>
              <input type="text" id="adm-new-username" placeholder="Min 4 chars" autocomplete="off">
            </div>
            <div class="form-group" style="margin-bottom:14px;">
              <label>Confirm with Password</label>
              <input type="password" id="adm-user-confirm-pass" placeholder="Current password">
            </div>
            <div class="error-msg" id="adm-user-error"></div>
            <div class="success-msg" id="adm-user-success"></div>
            <button class="btn btn-teal" onclick="changeAdminUsername()"><span class="wi-svg" data-lucide="pencil" style="width:14px;height:14px;vertical-align:middle;"></span><span class="wi-emoji">✏️</span> Update Username</button>
          </div>
          <div class="sa-settings-card">
            <h4>🔒 Change Admin Password</h4>
            <div class="form-group" style="margin-bottom:10px;"><label>Current Password</label><input type="password" id="adm-old-pass" placeholder="Current password"></div>
            <div class="form-group" style="margin-bottom:10px;"><label>New Password</label><input type="password" id="adm-new-pass" placeholder="Min 8 chars"></div>
            <div class="form-group" style="margin-bottom:14px;"><label>Confirm New Password</label><input type="password" id="adm-new-pass2" placeholder="Repeat password"></div>
            <div class="error-msg" id="adm-pass-error"></div>
            <div class="success-msg" id="adm-pass-success"></div>
            <button class="btn btn-teal" onclick="changeAdminPassword()">Update Password</button>
          </div>
        </div>
        <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:12px 16px;font-size:0.82rem;color:#92400e;margin-top:4px;">
          🔐 <strong>Two-Factor Authentication:</strong> For production deployments, connect a backend to enforce 2FA on admin login. All credential changes are recorded in the Audit Log.
        </div>`;
    }
    // Always reflect the real current username in the readonly field —
    // this previously never happened at all, so the field permanently
    // showed its placeholder text instead of the actual username.
    const userDisplay = document.getElementById('adm-current-user-display');
    if (userDisplay) {
      const creds = getAdminCreds();
      userDisplay.value = creds ? creds.username : ADMIN_DEFAULT_USER;
    }
  }
}

function renderAdminStats() {
  const users    = getUsers();
  const props    = getProps();
  const susp     = getSuspended();
  const approved = props.filter(p => p.status === 'approved' || !p.status);
  const areas    = [...new Set(approved.map(p => p.area))];
  const pending  = getPayments().filter(p => p.status === 'pending').length;
  const s = getSettings();
  const enabledCountries = getAllowedCountries().length;
  const totalRevenue = getPayments().filter(p => p.status === 'approved').length;
  document.getElementById('adm-stat-users').textContent     = users.length;
  const sv = document.getElementById('adm-stat-visitors');
  if (sv) sv.textContent = getSiteVisits().toLocaleString();
  document.getElementById('adm-stat-listings').textContent  = approved.length;
  document.getElementById('adm-stat-suspended').textContent = susp.length;
  document.getElementById('adm-stat-areas').textContent     = areas.length;
  const sc = document.getElementById('adm-stat-countries');
  if (sc) sc.textContent = enabledCountries;
  const sr = document.getElementById('adm-stat-revenue');
  if (sr) sr.textContent = totalRevenue;
  // Update pending badge
  const badge = document.getElementById('pending-pay-badge');
  if (badge) { badge.textContent = pending; badge.style.display = pending > 0 ? 'inline-flex' : 'none'; }
  if (typeof updateAreaRequestBadge === 'function') updateAreaRequestBadge();
  if (typeof updateSaleRequestBadge === 'function') updateSaleRequestBadge();
}

function renderAdminUsers(query) {
  const tbody = document.getElementById('adm-users-tbody');
  // Guard: old table removed in favour of sa-landlords-tbody; delegate and return safely
  if (!tbody) { if (typeof saRenderLandlords === 'function') saRenderLandlords(); return; }
  const susp  = getSuspended();
  let users = getUsers();
  if (query) {
    const q = query.toLowerCase();
    users = users.filter(u => (u.name||'').toLowerCase().includes(q) || (u.phone||'').includes(q) || (u.email||'').toLowerCase().includes(q));
  }
  if (users.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;color:var(--grey);padding:24px;">No landlords registered yet.</td></tr>`;
    return;
  }
  const props = getProps();
  tbody.innerHTML = users.map(u => {
    const listCount = props.filter(p => p.landlordId === u.id).length;
    const isSusp = susp.includes(u.id);
    const countryDC = u.countryCode ? getDialCode(u.countryCode) : null;
    const countryDisplay = countryDC
      ? flagImg(countryDC.code, {width:18, emoji:countryDC.flag}) + ' ' + escHtml(u.country||u.countryCode)
      : (u.country ? escHtml(u.country) : flagImg('pg', {width:18, emoji:'🇵🇬'}) + ' PNG');
    return `<tr>
      <td><div class="name-cell">${escHtml(u.name)}</div><div class="sub-cell">${escHtml(u.area||'')}</div></td>
      <td>${escHtml(u.email || u.phone || '—')}</td>
      <td>${countryDisplay}</td>
      <td><span class="pill pill-blue">${listCount}</span></td>
      <td><span class="pill ${isSusp ? 'pill-red' : 'pill-green'}">${isSusp ? 'Suspended' : 'Active'}</span></td>
      <td>
        ${isSusp
          ? `<button class="admin-action-btn restore" onclick="toggleSuspend('${u.id}', false)"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Restore</button>`
          : `<button class="admin-action-btn" onclick="toggleSuspend('${u.id}', true)">🚫 Suspend</button>`}
        <button class="admin-action-btn danger" onclick="adminDeleteUser('${u.id}')">🗑 Delete</button>
      </td>
    </tr>`;
  }).join('');
  wiRender();
}

function renderAdminListings(query) {
  const tbody = document.getElementById('adm-listings-tbody');
  // Guard: old table removed in favour of sa-listings-tbody; delegate and return safely
  if (!tbody) { if (typeof saRenderListings === 'function') saRenderListings(); return; }
  let props = getProps();
  if (query) {
    const q = query.toLowerCase();
    props = props.filter(p =>
      p.title.toLowerCase().includes(q) ||
      p.area.toLowerCase().includes(q) ||
      p.type.toLowerCase().includes(q) ||
      (p.landlordName||'').toLowerCase().includes(q)
    );
  }
  props.sort((a,b) => b.date - a.date);
  if (props.length === 0) {
    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;color:var(--grey);padding:24px;">No listings found.</td></tr>`;
    return;
  }
  tbody.innerHTML = props.map(p => {
    const d = new Date(p.date);
    const dateStr = d.getDate() + '/' + (d.getMonth()+1) + '/' + d.getFullYear();
    return `<tr>
      <td>
        <div class="name-cell">${TYPE_EMOJI[p.type]||'🏠'} ${escHtml(p.title)}</div>
        <div class="sub-cell">📍 ${escHtml(p.address || p.area)}</div>
      </td>
      <td>
        <div>${escHtml(p.landlordName||'—')}</div>
        <div class="sub-cell">${escHtml(p.landlordPhone||'')}</div>
      </td>
      <td><span class="pill pill-blue">${p.type}</span></td>
      <td style="font-weight:700;color:var(--teal);">K${Number(p.rent).toLocaleString()}</td>
      <td>${escHtml(p.area)}<br><span style="font-size:0.72rem;color:var(--grey);">${p.country||'PNG'}</span></td>
      <td style="font-size:0.78rem;color:var(--grey);">${dateStr}
        <div><span class="pill ${p.status==='approved'||!p.status?'pill-green':p.status==='rejected'?'pill-red':'pill-yellow'}">${p.status==='approved'||!p.status?'Live':p.status==='rejected'?'Rejected':'Pending'}</span></div>
      </td>
      <td><button class="admin-action-btn danger" onclick="adminDeleteListing('${p.id}')">🗑 Remove</button></td>
    </tr>`;
  }).join('');
  wiRender();
}

function toggleSuspend(userId, suspend) {
  let susp = getSuspended();
  if (suspend) { if (!susp.includes(userId)) susp.push(userId); }
  else         { susp = susp.filter(id => id !== userId); }
  saveSuspended(susp);
  renderAdminStats();
  renderAdminUsers('');
  showToast(suspend ? 'User suspended.' : 'User restored.', suspend ? 'error' : 'success');
}

function adminDeleteUser(userId) {
  if (!confirm('Delete this landlord account AND all their listings? This cannot be undone.')) return;
  let users = getUsers().filter(u => u.id !== userId);
  let props = getProps().filter(p => p.landlordId !== userId);
  let susp  = getSuspended().filter(id => id !== userId);
  saveUsers(users); saveProps(props); saveSuspended(susp);
  renderAdminDashboard();
  refreshAllGrids();
  showToast('User and their listings deleted.', 'error');
}

function adminDeleteListing(propId) {
  if (!confirm('Remove this listing permanently?')) return;
  let props = getProps().filter(p => p.id !== propId);
  saveProps(props);
  renderAdminStats();
  renderAdminListings('');
  refreshAllGrids();
  showToast('Listing removed.', 'error');
}

function loadAnnouncement() {
  const text = _LS.getItem(LS_ANNOUNCE);
  if (text) {
    showAnnouncementBanner(text);
  }
}

function showAnnouncementBanner(text) {
  document.getElementById('announce-text').textContent = text;
  document.getElementById('announce-banner').classList.add('visible');
}

// NOTE: this function was previously missing entirely — the "✏️ Update
// Username" button called it via onclick, but with no matching function
// defined anywhere, that click silently threw a ReferenceError in the
// console and did nothing. Any username typed into "New Username" was
// never actually saved, while changeAdminPassword() right below it DID
// work and would always re-save the *unchanged* existing username
// alongside the new password hash — so a landlord changing both fields
// at once would end up with their new password but still the old
// username, with no error message anywhere to explain why.
function changeAdminUsername() {
  // ── RBAC: Credential changes are Super Admin only ──
  if (!adminHasPerm(null)) {
    showToast('⛔ Only the Super Admin can change credentials.', 'error');
    return;
  }
  const newU = document.getElementById('adm-new-username').value.trim();
  const confirmP = document.getElementById('adm-user-confirm-pass').value;
  const err = document.getElementById('adm-user-error');
  const ok  = document.getElementById('adm-user-success');
  err.style.display = 'none'; ok.style.display = 'none';

  const creds     = getAdminCreds();
  const validUser = creds ? creds.username : ADMIN_DEFAULT_USER;

  if (confirmP !== ADMIN_DEFAULT_PASS) { showErr(err, 'Current password is incorrect.'); return; }
  if (!newU || newU.length < 4)        { showErr(err, 'New username must be at least 4 characters.'); return; }
  if (newU === validUser)               { showErr(err, 'That is already the current username.'); return; }
  // Don't let the Super Admin username collide with an existing sub-admin's
  // username — doAdminLogin() checks Super Admin first, so a collision
  // would make that sub-admin account unreachable by its own username.
  const subAdminTaken = saGetAdminAccounts().some(a => a.username === newU);
  if (subAdminTaken) { showErr(err, 'That username is already used by a sub-admin account.'); return; }

  _LS.setItem(LS_ADMIN, JSON.stringify({ username: newU, hash: validHash }));
  const displayEl = document.getElementById('adm-current-user-display');
  if (displayEl) displayEl.value = newU;
  ok.textContent = 'Username updated successfully! ✅';
  ok.style.display = 'block';
  document.getElementById('adm-new-username').value = '';
  document.getElementById('adm-user-confirm-pass').value = '';
}

function changeAdminPassword() {
  // ── RBAC: Credential changes are Super Admin only ──
  if (!adminHasPerm(null)) {
    showToast('⛔ Only the Super Admin can change credentials.', 'error');
    return;
  }
  const oldP  = document.getElementById('adm-old-pass').value;
  const newP  = document.getElementById('adm-new-pass').value;
  const newP2 = document.getElementById('adm-new-pass2').value;
  const err   = document.getElementById('adm-pass-error');
  const ok    = document.getElementById('adm-pass-success');
  err.style.display = 'none'; ok.style.display = 'none';

  const creds    = getAdminCreds();
  const validUser = creds ? creds.username : ADMIN_DEFAULT_USER;
  const validHash = creds ? creds.hash     : hashish(ADMIN_DEFAULT_PASS);

  if (hashish(oldP) !== validHash) { showErr(err, 'Current password is incorrect.'); return; }
  if (!newP || newP.length < 8)   { showErr(err, 'New password must be at least 8 characters.'); return; }
  if (newP !== newP2)              { showErr(err, 'New passwords do not match.'); return; }

  _LS.setItem(LS_ADMIN, JSON.stringify({ username: validUser, hash: hashish(newP) }));
  ok.textContent = 'Password updated successfully! ✅';
  ok.style.display = 'block';
  ['adm-old-pass','adm-new-pass','adm-new-pass2'].forEach(id => document.getElementById(id).value = '');
}

// Restore admin session on page reload
function restoreAdminSession() {
  if (_SS.getItem('pom_admin_session') === '1') {
    adminSession = true;
    try {
      const saved = _SS.getItem('pom_subadmin_session');
      currentAdminAccount = saved ? JSON.parse(saved) : null;
    } catch(e) { currentAdminAccount = null; }
  }
}

// Check if a user is suspended (used in login gating)
function isUserSuspended(userId) {
  return getSuspended().includes(userId);
}


