// ── Reusable FlagIcon component ──────────────────────────
// Renders a flag as an <img>, 20-22px by default, rounded corners baked
// into the asset, vertical-align:middle so it sits inline with text.
// Looks up CUSTOM_FLAG_ICONS first (used for PNG's custom artwork); any
// other country code falls through to the flagcdn.com image set via
// flagImg() below, with an emoji as the last-resort fallback.
function FlagIcon(countryCode, opts) {
  const cc = (countryCode || 'pg').toLowerCase();
  const custom = CUSTOM_FLAG_ICONS[cc];
  const w = (opts && opts.width) || 20;
  const h = (opts && opts.height) || Math.round(w * (cc === 'pg' ? 88/132 : 94/126));
  const cls = (opts && opts.className) || 'flag-icon';
  if (custom) {
    return `<img src="${custom}" width="${w}" height="${h}" alt="${cc.toUpperCase()} flag"
      class="${cls}" loading="lazy" decoding="async"
      style="border-radius:4px;vertical-align:middle;display:inline-block;object-fit:cover;">`;
  }
  return flagImg(cc, opts);
}

// ── Real flag image helper ──────────────────────────────
// Regional-indicator flag emoji (🇵🇬 etc) render perfectly on iOS/Android,
// but most desktop browsers — Windows Chrome/Edge/Firefox in particular —
// have no flag glyphs in their system emoji font, so they silently fall
// back to showing the plain two-letter country code text ("PG") instead
// of a flag. That's exactly what shows up when the app is opened on a
// computer. Rendering an actual flag <img> (via flagcdn.com's small SVG/PNG
// flag set, the same free CDN used across most production apps for this
// exact problem) sidesteps font support entirely, so it looks identical
// on phones, tablets, and desktops alike. The emoji is kept only as a
// last-resort fallback if the image itself ever fails to load (e.g. no
// internet) via onerror, so nothing breaks even in the worst case.
// PG specifically uses the custom embedded flag art via FlagIcon/CUSTOM_FLAG_ICONS
// above instead of the CDN, so it never depends on flagcdn.com being reachable.
// flagcdn.com only serves fixed sizes (w20, w40, w80, w160, w320, w640...) -
// arbitrary sizes like 34x25 return 404, which is why flags fell back to the
// two-letter code. Request a valid width, then try the SVG, then show a clean
// country-code badge (never the raw flag emoji, which Windows can't draw).
function flagImgFallback(img) {
  const cc = (img.getAttribute('data-cc') || '').toLowerCase();
  if (!img.getAttribute('data-tried-svg') && cc) {
    img.setAttribute('data-tried-svg', '1');
    img.removeAttribute('srcset');
    img.src = 'https://flagcdn.com/' + cc + '.svg';
    return;
  }
  const w = parseInt(img.getAttribute('width') || '28', 10);
  const badge = document.createElement('span');
  badge.className = 'flag-code-badge';
  badge.textContent = cc.toUpperCase();
  badge.style.cssText = 'display:inline-flex;align-items:center;justify-content:center;min-width:' + w + 'px;height:' + Math.round(w*0.75) + 'px;padding:0 4px;box-sizing:border-box;border-radius:4px;background:#0f5c63;color:#fff;font:700 ' + Math.max(9, Math.round(w*0.36)) + 'px/1 Inter,sans-serif;letter-spacing:.4px;vertical-align:middle;';
  if (img.parentNode) img.parentNode.replaceChild(badge, img);
}

function flagImg(countryCode, opts) {
  const cc = (countryCode || 'pg').toLowerCase();
  if (CUSTOM_FLAG_ICONS[cc]) return FlagIcon(cc, opts);
  const w  = (opts && opts.width)  || 28;
  const h  = (opts && opts.height) || Math.round(w * 0.75);
  const cls = (opts && opts.className) || 'flag-img';
  const sizes = [20, 40, 80, 160, 320, 640];
  const pick = n => sizes.find(x => x >= n) || 640;
  const src1 = pick(w * 2), src2 = pick(w * 3);
  return `<img src="https://flagcdn.com/w${src1}/${cc}.png"
    srcset="https://flagcdn.com/w${src2}/${cc}.png 2x"
    width="${w}" height="${h}" alt="${cc.toUpperCase()} flag" data-cc="${cc}"
    class="${cls}" loading="lazy" decoding="async"
    style="border-radius:3px;object-fit:cover;vertical-align:middle;"
    onerror="flagImgFallback(this)">`;
}

// ── Flag mount hydration ─────────────────────────────────
// Static HTML markup can't call JS functions inline, so spots that need
// FlagIcon inside plain page markup (not a template string) use a
// <span class="flag-mount" data-flag="pg" data-w="20"></span> placeholder;
// this fills every one of them in on load (and can be re-run for any
// content injected later via innerHTML, e.g. modals rebuilt at runtime).
function hydrateFlagMounts(root) {
  (root || document).querySelectorAll('.flag-mount:not([data-flag-done])').forEach(el => {
    const w = parseInt(el.getAttribute('data-w') || '20', 10);
    el.innerHTML = FlagIcon(el.getAttribute('data-flag') || 'pg', { width: w });
    el.setAttribute('data-flag-done', '1');
  });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => hydrateFlagMounts());
} else {
  hydrateFlagMounts();
}

