// Track selected dial code per context ('login' or 'reg')
const _authDialCode = { login: null, reg: null };

function getDialCode(countryCode) {
  return DIAL_CODES.find(d => d.code === countryCode) || null;
}

// ── Build the prefix dropdown list ───────────────────────
function buildPrefixList(context, filter) {
  const listEl = document.getElementById(context + '-prefix-list');
  if (!listEl) return;
  const q = (filter || '').toLowerCase();
  const items = q
    ? DIAL_CODES.filter(d => d.name.toLowerCase().includes(q) || d.dial.includes(q))
    : DIAL_CODES;

  const selected = _authDialCode[context];
  listEl.innerHTML = items.map(d => `
    <div class="phone-country-option ${selected && selected.code === d.code ? 'selected' : ''}"
      onclick="selectDialCode('${context}','${d.code}')">
      <span class="pco-flag">${flagImg(d.code,{width:20,emoji:d.flag})}</span>
      <span class="pco-name">${escHtml(d.name)}</span>
      <span class="pco-dial">${d.dial}</span>
    </div>
  `).join('');
}

function selectDialCode(context, countryCode) {
  const dc = getDialCode(countryCode);
  if (!dc) return;
  _authDialCode[context] = dc;

  // Update prefix button display
  document.getElementById(context + '-prefix-flag').innerHTML = flagImg(dc.code,{width:20,emoji:dc.flag});
  document.getElementById(context + '-prefix-code').textContent = dc.dial;

  // Close dropdown
  const dd = document.getElementById(context + '-prefix-dropdown');
  if (dd) dd.classList.remove('open');

  // Sync full phone number
  syncPhoneWithPrefix(context);

  // Also update the country select if it matches
  const countrySel = document.getElementById(context + '-country');
  if (countrySel && countrySel.value !== countryCode) {
    countrySel.value = countryCode;
    onAuthCountryChange(context);
  }
}

function togglePrefixDropdown(context) {
  const dd = document.getElementById(context + '-prefix-dropdown');
  if (!dd) return;
  const isOpen = dd.classList.contains('open');
  // Close all dropdowns first
  document.querySelectorAll('.phone-country-dropdown').forEach(d => d.classList.remove('open'));
  if (!isOpen) {
    dd.classList.add('open');
    buildPrefixList(context, '');
    const searchEl = dd.querySelector('.phone-country-search');
    if (searchEl) { searchEl.value = ''; searchEl.focus(); }
  }
}

function filterPrefixList(context, q) {
  buildPrefixList(context, q);
}

// Close dropdown when clicking outside
document.addEventListener('click', e => {
  if (!e.target.closest('.phone-input-relative')) {
    document.querySelectorAll('.phone-country-dropdown').forEach(d => d.classList.remove('open'));
  }
  // Close auth country pickers when clicking outside
  if (!e.target.closest('[id$="-country-picker"]') && !e.target.closest('[id$="-country-display"]')) {
    ['login','reg'].forEach(ctx => {
      const p = document.getElementById(ctx + '-country-picker');
      if (p) p.style.display = 'none';
    });
  }
});

// Sync: build the full E.164-style number for storage
function syncPhoneWithPrefix(context) {
  const dc = _authDialCode[context];
  const numEl = document.getElementById(context + '-phone');
  if (!dc || !numEl) return;
  // Just update placeholder — actual value is the raw digits user typed
  numEl.placeholder = dc.code === 'PG' ? '7XXX XXXX' :
                      dc.code === 'AU' ? '4XX XXX XXX' :
                      dc.code === 'US' || dc.code === 'CA' ? 'XXX XXX XXXX' : 'Your number';
}

// Build full phone with dial code for storage
function buildFullPhone(context) {
  const dc  = _authDialCode[context];
  const num = (document.getElementById(context + '-phone') || {}).value || '';
  const clean = num.replace(/\D/g,'').replace(/^0+/, ''); // strip leading zeros
  if (!dc || !clean) return num; // fallback to raw input
  return dc.dial + ' ' + clean;
}

// ── Auth country change ──────────────────────────────────
function onAuthCountryChange(context) {
  const sel  = document.getElementById(context + '-country');
  const code = sel ? sel.value : '';
  if (!code) return;

  // Sync prefix picker with country select
  const dc = getDialCode(code);
  if (dc) {
    _authDialCode[context] = dc;
    const flagEl = document.getElementById(context + '-prefix-flag');
    const codeEl = document.getElementById(context + '-prefix-code');
    if (flagEl) flagEl.innerHTML = flagImg(dc.code,{width:20,emoji:dc.flag});
    if (codeEl) codeEl.textContent = dc.dial;
    syncPhoneWithPrefix(context);
  }

  // For register tab: update province + area cascades
  if (context === 'reg') {
    updateRegAreaCascade(code);
  }
}

// ── Register: keep the hidden reg-province field's default in sync with
// whatever country is currently active, before the user reaches the
// dedicated "Where are you based?" wizard step. The real selection UI now
// lives in wizard-step-location (see wizLoc* functions below).
function updateRegAreaCascade(countryCode) {
  const provInput = document.getElementById('reg-province');
  const provDisplay = document.getElementById('reg-province-display');
  if (provInput) provInput.value = '';
  if (provDisplay) provDisplay.textContent = '';
  if (!countryCode) return;

  const provinces = WORLD_PROVINCES[countryCode] || [];
  // Auto-fill when there's exactly one province (nothing to choose)
  if (provinces.length === 1) {
    if (provInput) provInput.value = provinces[0];
    if (provDisplay) provDisplay.textContent = provinces[0];
  }
}

function onRegProvinceChange() {
  const code     = (_authDialCode['reg'] && _authDialCode['reg'].code) || 'PG';
  const province = document.getElementById('reg-province') ? document.getElementById('reg-province').value : '';
  const areaGroup= document.getElementById('reg-area-group');
  const areaSel  = document.getElementById('reg-area');
  if (areaSel) areaSel.innerHTML = '<option value="">– Select your area –</option>';
  if (!province) { if (areaGroup) areaGroup.style.display = 'none'; return; }
  populateRegAreas(code, province);
  if (areaGroup) areaGroup.style.display = 'block';
}

function populateRegAreas(countryCode, province) {
  const areaSel = document.getElementById('reg-area');
  if (!areaSel) return;
  areaSel.innerHTML = '<option value="">– Select your area –</option>';

  let areas = [];
  if (countryCode === 'PG') {
    // Filter PNG areas by province — NCD areas don't appear for Morobe etc.
    areas = AREAS.filter(a =>
      !province || (a.province || '') === province
    );
  } else {
    // International: show admin-added areas for this country
    const extras = JSON.parse(_LS.getItem('wampac_extra_areas') || '[]');
    areas = extras
      .filter(a => (a.countryCode || 'PG') === countryCode)
      .map(a => ({ name: a.name, province: a.province, icon: a.icon }));
    // Add generic option
    const other = document.createElement('option');
    other.value = 'Other / Custom Area'; other.textContent = 'Other / Custom Area';
    areaSel.appendChild(other);
  }

  areas.forEach(a => {
    const o = document.createElement('option');
    o.value = a.name; o.textContent = a.name;
    areaSel.appendChild(o);
  });
}

// ══════════════════════════════════════════════════════════
// REGISTRATION WIZARD — "Where are you based?" location step
// Dedicated country + province/state picker shown as its own wizard step,
// mirroring the splash screen's UX. Feeds into reg-country-name/-flag and
// the hidden reg-province field used by doRegister().
// ══════════════════════════════════════════════════════════
let _wizLocCountry = null; // { name, code, icon, ... } from WORLD_COUNTRIES

function wizLocInit() {
  // Default to whatever country is already active (browse country / a
  // previous pick), but always show the picker so it can be changed.
  const defaultCode = (document.getElementById('wiz-loc-country-code') || {}).value
    || (browseCountry && browseCountry.code)
    || 'PG';
  const country = getAllowedCountries().find(c => c.code === defaultCode) || getAllowedCountries()[0];
  _wizLocCountry = country || null;

  document.getElementById('wiz-loc-country-search').value = '';
  wizLocRenderCountryGrid('');

  // If we already have a valid default country, jump straight to its
  // province step (or unlock Continue if it has none) instead of forcing
  // the user to re-tap the country they already chose at the splash.
  if (_wizLocCountry) {
    wizLocSelectCountry(_wizLocCountry.code, /*fromInit*/ true);
  } else {
    document.getElementById('wiz-loc-province-block').style.display = 'none';
    document.getElementById('wiz-loc-country-block').style.display = 'block';
    wizLocUpdateContinueState();
  }
}

function wizLocFilterCountries(q) {
  wizLocRenderCountryGrid(q);
}

function wizLocRenderCountryGrid(q) {
  const grid = document.getElementById('wiz-loc-country-grid');
  if (!grid) return;
  let list = getAllowedCountries();
  if (q) list = list.filter(c => c.name.toLowerCase().includes(q.toLowerCase()));
  list = [...list].sort((a,b) => {
    if (a.code === 'PG') return -1;
    if (b.code === 'PG') return 1;
    return a.name.localeCompare(b.name);
  });
  if (!list.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--grey);padding:16px;font-size:0.85rem;">No countries found.</div>';
    return;
  }
  grid.innerHTML = list.map(c => {
    const isSel = _wizLocCountry && _wizLocCountry.code === c.code;
    return `<div onclick="wizLocSelectCountry('${c.code}')"
      style="display:flex;align-items:center;gap:8px;padding:10px 12px;border:1.5px solid ${isSel ? 'var(--teal)' : 'var(--grey-light)'};background:${isSel ? '#f0fafa' : 'var(--white)'};border-radius:10px;cursor:pointer;font-family:'Inter',sans-serif;transition:border-color 0.15s,background 0.15s;">
      ${flagImg(c.code, { width:22, height:16, emoji: c.icon })}
      <span style="font-size:0.85rem;font-weight:600;color:var(--charcoal);">${escHtml(c.name)}</span>
    </div>`;
  }).join('');
}

function wizLocSelectCountry(code, fromInit) {
  const country = getAllowedCountries().find(c => c.code === code);
  if (!country) return;
  _wizLocCountry = country;
  document.getElementById('wiz-loc-country-code').value = country.code;

  // Reflect into the read-only summary shown later on the form step
  const flagEl = document.getElementById('reg-country-flag');
  const nameEl = document.getElementById('reg-country-name');
  if (flagEl) flagEl.innerHTML = flagImg(country.code, { width:22, height:16, emoji: country.icon || '🌍' });
  if (nameEl) nameEl.textContent = country.name;
  const dc = getDialCode(country.code);
  if (dc) {
    _authDialCode['reg'] = dc;
    const pfFlag = document.getElementById('reg-prefix-flag');
    const pfCode = document.getElementById('reg-prefix-code');
    if (pfFlag) pfFlag.innerHTML = flagImg(country.code, { width:20, height:15, emoji: dc.flag });
    if (pfCode) pfCode.textContent = dc.dial;
    syncPhoneWithPrefix('reg');
  }

  if (!fromInit) wizLocRenderCountryGrid(document.getElementById('wiz-loc-country-search').value);

  // Country only: no province / state step. Clear any stale value.
  const provVal = document.getElementById('wiz-loc-province-val'); if (provVal) provVal.value = '';
  const provDisplay = document.getElementById('reg-province-display'); if (provDisplay) provDisplay.textContent = '';
  const regProv = document.getElementById('reg-province'); if (regProv) regProv.value = '';
  const provBlock = document.getElementById('wiz-loc-province-block'); if (provBlock) provBlock.style.display = 'none';
  const countryBlock = document.getElementById('wiz-loc-country-block'); if (countryBlock) countryBlock.style.display = 'block';
  wizLocUpdateContinueState();
}

function wizLocChangeCountry() {
  document.getElementById('wiz-loc-province-block').style.display = 'none';
  document.getElementById('wiz-loc-country-block').style.display = 'block';
  wizLocRenderCountryGrid(document.getElementById('wiz-loc-country-search').value);
  wizLocUpdateContinueState();
}

function wizLocFilterProvinces(q) {
  wizLocRenderProvinceGrid(q);
}

function wizLocRenderProvinceGrid(q) {
  const grid = document.getElementById('wiz-loc-province-grid');
  if (!grid || !_wizLocCountry) return;
  let list = WORLD_PROVINCES[_wizLocCountry.code] || [];
  if (q) list = list.filter(p => p.toLowerCase().includes(q.toLowerCase()));
  if (!list.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--grey);padding:16px;font-size:0.85rem;">No matches.</div>';
    return;
  }
  const current = document.getElementById('wiz-loc-province-val').value;
  grid.innerHTML = list.map(p => {
    const isSel = p === current;
    return `<div onclick="wizLocSelectProvince('${p.replace(/'/g, "\\'")}')"
      style="padding:10px 12px;border:1.5px solid ${isSel ? 'var(--teal)' : 'var(--grey-light)'};background:${isSel ? '#f0fafa' : 'var(--white)'};border-radius:10px;cursor:pointer;font-family:'Inter',sans-serif;font-size:0.85rem;font-weight:600;color:var(--charcoal);transition:border-color 0.15s,background 0.15s;">${escHtml(p)}</div>`;
  }).join('');
}

function wizLocSelectProvince(province) {
  document.getElementById('wiz-loc-province-val').value = province;
  document.getElementById('reg-province').value = province;
  const provDisplay = document.getElementById('reg-province-display');
  if (provDisplay) provDisplay.textContent = province;
  wizLocRenderProvinceGrid(document.getElementById('wiz-loc-province-search').value);
  wizLocUpdateContinueState();
}

function wizLocUpdateContinueState() {
  const btn = document.getElementById('wiz-loc-continue-btn');
  if (!btn) return;
  if (!_wizLocCountry) { btn.disabled = true; return; }
  btn.disabled = false;
}

function wizLocContinue() {
  if (!_wizLocCountry) return;
  showWizardStep('wizard-step-form');
  applyGoogleRegisterMode();
}

// ── Populate auth modal — defaults to browse country, full picker available ─
function populateAuthCountries() {
  // Determine default country: use browseCountry if set, else PNG
  const defaultCode = (browseCountry && browseCountry.code) ? browseCountry.code : 'PG';
  const defaultCountry = WORLD_COUNTRIES.find(c => c.code === defaultCode) ||
                         WORLD_COUNTRIES.find(c => c.code === 'PG');

  // Set auth context for both login and reg
  ['login', 'reg'].forEach(ctx => {
    _setAuthCountry(ctx, defaultCountry || { code:'PG', name:'Papua New Guinea', icon:'🇵🇬' });
  });

  // Forgot-password prefix: mirror login
  _authDialCode['fp'] = _authDialCode['login'];
  const fpFlag = document.getElementById('fp-prefix-flag');
  const fpCode = document.getElementById('fp-prefix-code');
  const fpDc = _authDialCode['fp'];
  if (fpFlag && fpDc) fpFlag.innerHTML = flagImg(fpDc.code, { width:20, height:15, emoji: fpDc.flag });
  if (fpCode && fpDc) fpCode.textContent = fpDc.dial;
}

// Set a context (login|reg) to a given WORLD_COUNTRIES entry
function _setAuthCountry(ctx, country) {
  // Update country display pill
  const flagEl = document.getElementById(ctx + '-country-flag');
  const nameEl = document.getElementById(ctx + '-country-name');
  if (flagEl) flagEl.innerHTML = flagImg(country.code, { width:22, height:16, emoji: country.icon || '🌍' });
  if (nameEl) nameEl.textContent = country.name;

  // Look up dial code from full DIAL_CODES table
  const dc = getDialCode(country.code);
  if (dc) {
    _authDialCode[ctx] = dc;
    const pfFlag = document.getElementById(ctx + '-prefix-flag');
    const pfCode = document.getElementById(ctx + '-prefix-code');
    if (pfFlag) pfFlag.innerHTML = flagImg(country.code, { width:20, height:15, emoji: dc.flag });
    if (pfCode) pfCode.textContent = dc.dial;
    syncPhoneWithPrefix(ctx);
  }

  // Province cascade
  if (ctx === 'reg') {
    updateRegAreaCascade(country.code);
  }
}

// Toggle the auth modal country picker open/close
function toggleAuthCountryPicker(ctx) {
  const picker = document.getElementById(ctx + '-country-picker');
  if (!picker) return;
  const isOpen = picker.style.display !== 'none';
  // Close both pickers first
  ['login','reg'].forEach(c => {
    const p = document.getElementById(c + '-country-picker');
    if (p) p.style.display = 'none';
  });
  if (!isOpen) {
    picker.style.display = 'block';
    _buildAuthCountryList(ctx, '');
    const search = document.getElementById(ctx + '-country-search');
    if (search) { search.value = ''; search.focus(); }
  }
}

// Filter auth country list
function filterAuthCountryList(ctx, q) {
  _buildAuthCountryList(ctx, q);
}

// Build auth country list items
function _buildAuthCountryList(ctx, q) {
  const listEl = document.getElementById(ctx + '-country-list');
  if (!listEl) return;
  let list = getAllowedCountries();
  if (q) list = list.filter(c => c.name.toLowerCase().includes(q.toLowerCase()));
  list = [...list].sort((a,b) => {
    if (a.code === 'PG') return -1;
    if (b.code === 'PG') return 1;
    return a.name.localeCompare(b.name);
  });
  listEl.innerHTML = list.map(c => `
    <div onclick="selectAuthCountry('${ctx}','${c.code}')"
      style="display:flex;align-items:center;gap:10px;padding:9px 12px;cursor:pointer;font-size:0.88rem;font-family:'Inter',sans-serif;border-bottom:1px solid #f3f4f6;transition:background 0.13s;"
      onmouseover="this.style.background='#f0fdf4'" onmouseout="this.style.background=''">
      ${flagImg(c.code, { width:22, height:16, emoji: c.icon })}
      <span style="font-weight:600;color:#1a1a2e;">${escHtml(c.name)}</span>
      <span style="margin-left:auto;font-size:0.78rem;color:#6b7280;">${(getDialCode(c.code)||{}).dial||''}</span>
    </div>
  `).join('') || '<div style="padding:12px;color:#9ca3af;font-size:0.85rem;text-align:center;">No countries found</div>';
}

// User selects a country in the auth modal
function selectAuthCountry(ctx, code) {
  const country = WORLD_COUNTRIES.find(c => c.code === code);
  if (!country) return;
  _setAuthCountry(ctx, country);
  // Keep login and register in sync
  if (ctx === 'login') _setAuthCountry('reg', country);
  // Close picker
  const picker = document.getElementById(ctx + '-country-picker');
  if (picker) picker.style.display = 'none';
  // Sync forgot-password prefix
  _authDialCode['fp'] = _authDialCode['login'];
  const fpFlag = document.getElementById('fp-prefix-flag');
  const fpCode = document.getElementById('fp-prefix-code');
  const fpDc = _authDialCode['fp'];
  if (fpFlag && fpDc) fpFlag.innerHTML = flagImg(fpDc.code, { width:20, height:15, emoji: fpDc.flag });
  if (fpCode && fpDc) fpCode.textContent = fpDc.dial;
}


// ══════════════════════════════════════════════════════════
// HERO BACKGROUND IMAGE SYSTEM
// ══════════════════════════════════════════════════════════
const LS_HERO_BG     = 'wampac_hero_bg';
const LS_HERO_PRESET = 'wampac_hero_preset';
const LS_HERO_OPACITY = 'wampac_hero_opacity';

const HERO_PRESETS = {
  'gradient-teal':   { type:'gradient', value:'linear-gradient(135deg, #0D5C63 0%, #137A82 60%, #1a8f98 100%)' },
  'gradient-sunset': { type:'gradient', value:'linear-gradient(135deg, #c0392b 0%, #e67e22 50%, #f39c12 100%)' },
  'gradient-night':  { type:'gradient', value:'linear-gradient(135deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%)' },
  'gradient-forest': { type:'gradient', value:'linear-gradient(135deg, #1b5e20 0%, #2e7d32 60%, #388e3c 100%)' },
  'gradient-ocean':  { type:'gradient', value:'linear-gradient(135deg, #0277bd 0%, #0288d1 60%, #039be5 100%)' },
};

function getHeroConfig() {
  const safeGet = (key, fallback) => {
    try { return _LS.getItem(key) || fallback; }
    catch (e) { return fallback; }
  };
  return {
    bgImage:  safeGet(LS_HERO_BG, null),
    preset:   safeGet(LS_HERO_PRESET, null),
    opacity:  parseInt(safeGet(LS_HERO_OPACITY, '40')),
  };
}

function applyHeroBg() {
  const cfg     = getHeroConfig();
  const heroEl  = document.getElementById('hero-section');
  const bgEl    = document.getElementById('hero-bg');
  const ovEl    = document.getElementById('hero-overlay');
  if (!heroEl) return;

  if (cfg.bgImage) {
    // Custom uploaded photo
    if (bgEl) {
      bgEl.style.backgroundImage = 'url(' + cfg.bgImage + ')';
      bgEl.style.opacity = '1';
    }
    if (ovEl) ovEl.style.background = buildOverlayGradient(cfg.opacity);
    heroEl.classList.add('has-bg-image');
    heroEl.style.background = 'none';
  } else if (cfg.preset && HERO_PRESETS[cfg.preset]) {
    // Preset gradient
    if (bgEl) { bgEl.style.backgroundImage = 'none'; bgEl.style.opacity = '0'; }
    heroEl.classList.remove('has-bg-image');
    heroEl.style.background = HERO_PRESETS[cfg.preset].value;
    if (ovEl) ovEl.style.background = 'linear-gradient(to bottom,rgba(0,0,0,0.15),rgba(0,0,0,0.25))';
  } else {
    // Default teal
    if (bgEl) { bgEl.style.backgroundImage = 'none'; bgEl.style.opacity = '0'; }
    heroEl.classList.remove('has-bg-image');
    heroEl.style.background = 'linear-gradient(135deg, var(--teal-dark) 0%, var(--teal) 60%, var(--teal-light) 100%)';
    if (ovEl) ovEl.style.background = 'none';
  }
  try { syncSalesHeroBg(); } catch (e) {}
}

// Mirror the rental hero wallpaper (and its overlay) into the Sales home hero,
// so Sales mode shows the same picture — only the mode changes.
function syncSalesHeroBg() {
  const src = document.getElementById('hero-bg');
  const srcOv = document.getElementById('hero-overlay');
  const hero = document.getElementById('hero-section');
  const dst = document.getElementById('sales-hero-bg');
  const dstOv = document.getElementById('sales-hero-overlay');
  const box = document.getElementById('sales-home-hero');
  if (!src || !dst || !box) return;
  const img = src.style.backgroundImage;
  const has = !!(img && img !== 'none' && hero && hero.classList.contains('has-bg-image'));
  if (has) {
    dst.style.backgroundImage = img;
    dst.style.opacity = '1';
    if (dstOv && srcOv) dstOv.style.background = srcOv.style.background;
    box.classList.add('has-bg-image');
  } else {
    dst.style.backgroundImage = 'none';
    dst.style.opacity = '0';
    if (dstOv) dstOv.style.background = 'none';
    box.classList.remove('has-bg-image');
  }
}

function buildOverlayGradient(opacity) {
  const o = Math.max(0.1, Math.min(0.85, opacity / 100));
  return `linear-gradient(to bottom, rgba(0,0,0,${(o*0.8).toFixed(2)}) 0%, rgba(0,0,0,${(o*0.55).toFixed(2)}) 50%, rgba(0,0,0,${o.toFixed(2)}) 100%)`;
}

function uploadHeroBg(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (!file.type.startsWith('image/')) {
    showToast('Please select an image file (JPG, PNG, WebP, GIF, etc.).', 'error');
    e.target.value = '';
    return;
  }

  const upArea = document.getElementById('hero-bg-upload-area');
  if (upArea) upArea.style.opacity = '0.6';
  showToast('Uploading background image…', 'success');

  const reader = new FileReader();

  reader.onerror = () => {
    if (upArea) upArea.style.opacity = '1';
    showToast('Could not read that file — please try a different image.', 'error');
    e.target.value = '';
  };

  reader.onload = ev => {
    const img = new Image();

    img.onerror = () => {
      if (upArea) upArea.style.opacity = '1';
      showToast('That file doesn\'t look like a valid image — please try another.', 'error');
      e.target.value = '';
    };

    img.onload = () => {
      try {
        // Downscale to a sensible max dimension for a full-width hero banner
        const MAX = 1200;
        let w = img.width, h = img.height;
        if (!w || !h) throw new Error('Image has no dimensions');
        if (w > MAX || h > MAX) {
          if (w > h) { h = Math.round(h * MAX / w); w = MAX; }
          else       { w = Math.round(w * MAX / h); h = MAX; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Canvas not supported');
        ctx.drawImage(img, 0, 0, w, h);

        // Multi-pass compression: keep shrinking quality (and, as a last
        // resort, physical size) until it actually fits in _LS.
        // This loop ALWAYS ends with either a successful save or a clear
        // error message — it never fails silently.
        const qualitySteps = [0.80, 0.65, 0.50, 0.38, 0.28, 0.20];
        let saved = false;
        let lastErr = null;

        for (let pass = 0; pass < qualitySteps.length && !saved; pass++) {
          let dataUrl;
          try {
            dataUrl = canvas.toDataURL('image/jpeg', qualitySteps[pass]);
          } catch (encErr) {
            lastErr = encErr;
            continue; // try next quality step
          }
          try {
            _LS.setItem(LS_HERO_BG, dataUrl);
            _LS.removeItem(LS_HERO_PRESET);
            saved = true;

            // Update preview in admin
            const previewWrap = document.getElementById('hero-bg-preview-wrap');
            const previewImg  = document.getElementById('hero-bg-preview-img');
            if (previewWrap) previewWrap.style.display = 'block';
            if (previewImg)  previewImg.src = dataUrl;

            applyHeroBg();
            const ok = document.getElementById('hero-bg-success');
            if (ok) { ok.textContent = '✅ Background image applied!'; ok.style.display = 'block'; }
            showToast('Hero background updated! ✅', 'success');
          } catch (storErr) {
            lastErr = storErr;
            // Quota exceeded at this quality — loop will try a smaller/lower-quality pass
          }
        }

        // Last resort: if every JPEG quality pass still didn't fit, try a
        // much smaller physical size (half the dimensions) at low quality.
        if (!saved) {
          try {
            const small = document.createElement('canvas');
            small.width = Math.max(1, Math.round(w * 0.5));
            small.height = Math.max(1, Math.round(h * 0.5));
            small.getContext('2d').drawImage(img, 0, 0, small.width, small.height);
            const tinyUrl = small.toDataURL('image/jpeg', 0.5);
            _LS.setItem(LS_HERO_BG, tinyUrl);
            _LS.removeItem(LS_HERO_PRESET);
            saved = true;

            const previewWrap = document.getElementById('hero-bg-preview-wrap');
            const previewImg  = document.getElementById('hero-bg-preview-img');
            if (previewWrap) previewWrap.style.display = 'block';
            if (previewImg)  previewImg.src = tinyUrl;

            applyHeroBg();
            const ok = document.getElementById('hero-bg-success');
            if (ok) { ok.textContent = '✅ Background image applied (reduced size to fit storage)!'; ok.style.display = 'block'; }
            showToast('Hero background updated (size reduced to fit) ✅', 'success');
          } catch (finalErr) {
            lastErr = finalErr;
          }
        }

        if (!saved) {
          console.warn('Hero background upload failed after all compression passes:', lastErr);
          showToast('This image is too large to store on this device. Try a smaller image, or clear some space (Reset Appearance won\'t help — try a different photo).', 'error');
        }
      } catch (procErr) {
        console.warn('Hero background processing error:', procErr);
        showToast('Something went wrong processing that image — please try a different file.', 'error');
      } finally {
        if (upArea) upArea.style.opacity = '1';
        e.target.value = ''; // allow re-selecting the same file again if needed
      }
    };

    img.src = ev.target.result;
  };

  reader.readAsDataURL(file);
}

function removeHeroBg() {
  _LS.removeItem(LS_HERO_BG);
  _LS.removeItem(LS_HERO_PRESET);
  const previewWrap = document.getElementById('hero-bg-preview-wrap');
  const previewImg  = document.getElementById('hero-bg-preview-img');
  if (previewWrap) previewWrap.style.display = 'none';
  if (previewImg)  previewImg.src = '';
  applyHeroBg();
  showToast('Background removed — using default teal.', 'success');
}

function applyHeroPreset(key) {
  try {
    _LS.removeItem(LS_HERO_BG);
    _LS.setItem(LS_HERO_PRESET, key);
  } catch (e) {
    console.warn('Could not save preset wallpaper choice:', e);
    showToast('Could not save your choice — storage may be disabled in this browser.', 'error');
    return;
  }
  applyHeroBg();
  // Update preview area
  const previewWrap = document.getElementById('hero-bg-preview-wrap');
  if (previewWrap) previewWrap.style.display = 'none';
  const ok = document.getElementById('hero-bg-success');
  if (ok) { ok.textContent = '✅ Preset applied!'; ok.style.display = 'block'; }
  showToast('Preset wallpaper applied! ✅', 'success');
}

function previewOverlay(val) {
  const pctEl = document.getElementById('overlay-pct');
  if (pctEl) pctEl.textContent = val;
  const ovEl = document.getElementById('hero-overlay');
  if (ovEl) ovEl.style.background = buildOverlayGradient(parseInt(val));
  _LS.setItem(LS_HERO_OPACITY, val);
}

function loadHeroBgAdminPreview() {
  const cfg = getHeroConfig();
  // Show current image in admin if set
  const previewWrap = document.getElementById('hero-bg-preview-wrap');
  const previewImg  = document.getElementById('hero-bg-preview-img');
  if (cfg.bgImage && previewWrap && previewImg) {
    previewWrap.style.display = 'block';
    previewImg.src = cfg.bgImage;
  }
  // Set opacity slider
  const slider = document.getElementById('hero-overlay-opacity');
  const pctEl  = document.getElementById('overlay-pct');
  if (slider) slider.value = cfg.opacity;
  if (pctEl)  pctEl.textContent = cfg.opacity;
}

