// ── KEYWORD sheet ─────────────────────────────────────────
function buildKeywordSheet() { return '<div>' + buildKeywordSheetContent() + '</div>'; }
function buildKeywordSheetContent() {
  const suggestions = ['furnished','security fence','generator','water tank','garden','aircon','wifi','parking','tiled','concrete'];
  return `
    <div class="fs-keyword-hint">
      Type any word to search across property titles, descriptions, and features.
    </div>
    <input class="fs-keyword-input" type="text" id="fs-kw-input"
      placeholder="e.g. furnished, security, generator…"
      value="${escHtml(_sheetTemp.keyword || '')}"
      oninput="setSheetKeyword(this.value)"
      onkeydown="if(event.key==='Enter') applyCurrentFilter()">
    <div class="fs-section-title">Popular searches</div>
    <div class="fs-keyword-tags">
      ${suggestions.map(s =>
        `<button class="fs-kw-tag" onclick="setKeyword('${s}')">${s}</button>`
      ).join('')}
    </div>`;
}

function setKeyword(word) {
  _sheetTemp.keyword = word;
  const inp = document.getElementById('fs-kw-input');
  if (inp) inp.value = word;
}

// ── Update the single Filters button state ───────────────
function updateFilterPills() {
  const f = _searchFilters;
  const mainBtn   = document.getElementById('fpill-main');
  const mainLabel = document.getElementById('fpill-main-label');
  const badge     = document.getElementById('fpill-badge');
  const clearBtn  = document.getElementById('fpill-clear');

  // Count active filters
  let count = 0;
  if (f.minPrice !== null || f.maxPrice !== null) count++;
  if (f.beds)    count++;
  if (f.keyword) count++;

  // Update main button appearance
  if (mainBtn) mainBtn.classList.toggle('has-filters', count > 0);

  // Update badge
  if (badge) {
    badge.textContent = count;
    badge.style.display = count > 0 ? 'inline-flex' : 'none';
  }

  // Label: always 'Filters' — the removable tag chips (renderActiveTagsRow)
  // already show the detail, so we don't repeat it here and squeeze the row.
  if (mainLabel) {
    mainLabel.textContent = 'Filters';
  }

  // Show/hide clear button
  const hasAny = count > 0;
  if (clearBtn) clearBtn.style.display = hasAny ? 'inline-flex' : 'none';

  renderActiveTagsRow();
}

function renderActiveTagsRow() {
  const f = _searchFilters;
  const tagsEl = document.getElementById('filter-active-tags');
  const countEl = document.getElementById('filter-result-count');
  if (!tagsEl) return;

  const tags = [];
  if (f.minPrice !== null || f.maxPrice !== null) {
    const pStr = f.minPrice && f.maxPrice
      ? `K${f.minPrice.toLocaleString()}–K${f.maxPrice.toLocaleString()} /${f.period}`
      : f.minPrice ? `From K${f.minPrice.toLocaleString()}` : `Up to K${f.maxPrice.toLocaleString()}`;
    tags.push({ label: pStr, key: 'price' });
  }
  if (f.beds)    tags.push({ label: f.beds === 'Studio' ? 'Studio' : f.beds + '+ Beds', key: 'beds' });
  if (f.type)    tags.push({ label: (TYPE_EMOJI[f.type]||'') + ' ' + f.type, key: 'type' });
  if (f.keyword) tags.push({ label: '"' + f.keyword + '"', key: 'keyword' });

  const summaryRow = document.getElementById('filter-summary-row') || tagsEl.parentElement;
  if (tags.length === 0) {
    tagsEl.innerHTML = '';
    if (countEl) countEl.style.display = 'none';
    return;
  }

  tagsEl.innerHTML = tags.map(t =>
    `<span class="fat-tag">${escHtml(t.label)}<button onclick="clearSingleFilter('${t.key}')">✕</button></span>`
  ).join('');
}

function clearSearchFilters() {
  const _rsAppPer = (getAppearance().rentPeriod || '/ week').includes('month') ? 'month'
                 : (getAppearance().rentPeriod || '/ week').includes('fortnight') ? 'fortnight'
                 : 'week';
  _searchFilters = { minPrice:null, maxPrice:null, period:_rsAppPer, beds:'', type:'', keyword:'' };
  _sheetTemp     = { ..._searchFilters };
  ['sf-min-price','sf-max-price','sf-keyword','sf-beds','sf-period'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = id==='sf-period'?'month':'';
  });
  const cEl = document.getElementById('filter-result-count');
  if (cEl) cEl.style.display = 'none';
  renderListings();
  updateFilterPills();
}

function clearSingleFilter(key) {
  if (key === 'price')   { _searchFilters.minPrice = null; _searchFilters.maxPrice = null; }
  if (key === 'beds')    _searchFilters.beds    = '';
  if (key === 'type')    _searchFilters.type    = '';
  if (key === 'keyword') _searchFilters.keyword = '';
  renderListings();
  updateFilterPills();
}

function applySearchFilterToProps(props) {
  const f = _searchFilters;
  const hasFilter = f.minPrice!==null || f.maxPrice!==null || f.beds || f.type || f.keyword;
  if (!hasFilter) return { filtered: props, hasFilter: false };

  let result = props;

  // ── Price ────────────────────────────────────────────────
  if (f.minPrice !== null || f.maxPrice !== null) {
    result = result.filter(p => {
      let rent = Number(p.rent);
      // Fall back to the site appearance period if not stored on the listing
      const _appPer = (getAppearance().rentPeriod || '/ week').includes('month') ? 'month'
                    : (getAppearance().rentPeriod || '/ week').includes('fortnight') ? 'fortnight'
                    : 'week';
      const lp = p.rentPeriod || _appPer;
      // Normalise to search period
      if (lp === 'week'      && f.period === 'month')     rent = rent * 4.33;
      if (lp === 'week'      && f.period === 'fortnight') rent = rent * 2;
      if (lp === 'month'     && f.period === 'week')      rent = rent / 4.33;
      if (lp === 'month'     && f.period === 'fortnight') rent = rent / 2.165;
      if (lp === 'fortnight' && f.period === 'week')      rent = rent / 2;
      if (lp === 'fortnight' && f.period === 'month')     rent = rent * 2.165;
      // Transit / Short Stay listings store their headline `rent` as a
      // daily rate — normalise that against whichever period the search
      // is using too, same as week/month/fortnight above.
      if (lp === 'day'       && f.period === 'week')      rent = rent * 7;
      if (lp === 'day'       && f.period === 'fortnight') rent = rent * 14;
      if (lp === 'day'       && f.period === 'month')     rent = rent * 30;
      if (lp === 'week'      && f.period === 'day')       rent = rent / 7;
      if (lp === 'fortnight' && f.period === 'day')       rent = rent / 14;
      if (lp === 'month'     && f.period === 'day')       rent = rent / 30;
      if (f.minPrice !== null && rent < f.minPrice) return false;
      if (f.maxPrice !== null && rent > f.maxPrice) return false;
      return true;
    });
  }

  // ── Beds ─────────────────────────────────────────────────
  if (f.beds) {
    result = result.filter(p => {
      if (p.isCommercial || !p.beds) return !f.beds; // commercial: skip if beds filter set
      if (f.beds === 'Studio') return p.beds === 'Studio';
      const bedsNum = p.beds === 'Studio' ? 0 : parseInt(p.beds) || 0;
      return bedsNum >= (parseInt(f.beds) || 0);
    });
  }

  // ── Type (from sheet — separate from chip filter) ────────
  if (f.type) {
    result = result.filter(p => p.type === f.type);
  }

  // ── Keyword ──────────────────────────────────────────────
  if (f.keyword) {
    result = result.filter(p => {
      const hay = [p.title,p.desc,p.area,p.type,p.address,p.condition,p.leaseTerm]
        .filter(Boolean).join(' ').toLowerCase();
      return hay.includes(f.keyword);
    });
  }

  return { filtered: result, hasFilter: true };
}

// Update result count in filter bar
function updateFilterResultCount(count, total) {
  const cEl = document.getElementById('filter-result-count');
  if (!cEl) return;
  const f = _searchFilters;
  const hasFilter = f.minPrice!==null || f.maxPrice!==null || f.beds || f.type || f.keyword;
  if (hasFilter && count < total) {
    cEl.style.display = 'block';
    cEl.textContent = count + ' of ' + total + ' match';
  } else {
    cEl.style.display = 'none';
  }
}


// ── Payment method tab switcher ───────────────────────────
function switchPayTab(tab) {
  const bankTab = document.getElementById('pay-tab-bank');
  const cardTab = document.getElementById('pay-tab-card');
  const bankSection = document.getElementById('pay-section-png');
  const cardSection = document.getElementById('pay-section-intl');

  if (tab === 'bank') {
    if (bankTab) bankTab.classList.add('active');
    if (cardTab) cardTab.classList.remove('active');
    if (bankSection) bankSection.style.display = 'block';
    if (cardSection) cardSection.style.display = 'none';
  } else {
    if (bankTab) bankTab.classList.remove('active');
    if (cardTab) cardTab.classList.add('active');
    if (bankSection) bankSection.style.display = 'none';
    if (cardSection) cardSection.style.display = 'block';
    // Populate visa pricing when switching to card
    const pi = getPricingIntl();
    ['basic','standard','premium'].forEach(plan => {
      const btn = document.querySelector('[data-plan="' + plan + '-intl"]');
      if (btn) {
        const priceEl = btn.querySelector('.plan-price');
        if (priceEl) {
          const amounts = { basic: pi.basic, standard: pi.standard, premium: pi.premium };
          priceEl.innerHTML = '$' + amounts[plan];
        }
      }
    });
  }
}


