function seGet(id) {
  const el = document.getElementById(id);
  return el ? el.value : null;
}
function seSet(id, val) {
  const el = document.getElementById(id);
  if (el) el.value = val;
}

// Sync color picker -> hex text input
function seColorSync(colorEl, hexId) {
  const hex = document.getElementById(hexId);
  if (hex) hex.value = colorEl.value;
}
// Sync hex text input -> color picker
function seHexSync(hexEl, colorId) {
  const v = hexEl.value.trim();
  if (/^#[0-9a-fA-F]{6}$/.test(v)) {
    const cp = document.getElementById(colorId);
    if (cp) cp.value = v;
  }
}

// Accordion toggle
function seToggleAcc(btn) {
  btn.classList.toggle('open');
  const body = btn.nextElementSibling;
  if (body) body.classList.toggle('open');
}

// ── Quick theme presets ──────────────────────────────────
const SE_THEMES = {
  default: { colorPrimary:'#0D5C63', colorPrimaryDark:'#093E44', colorPrimaryLight:'#137A82', colorAccent:'#F4A91C', colorAccentLight:'#FFC94A', colorNavBg:'#093E44' },
  ocean:   { colorPrimary:'#0277bd', colorPrimaryDark:'#01579b', colorPrimaryLight:'#0288d1', colorAccent:'#00bcd4', colorAccentLight:'#4dd0e1', colorNavBg:'#01579b' },
  forest:  { colorPrimary:'#2e7d32', colorPrimaryDark:'#1b5e20', colorPrimaryLight:'#388e3c', colorAccent:'#ffb300', colorAccentLight:'#ffd54f', colorNavBg:'#1b5e20' },
  sunset:  { colorPrimary:'#e64a19', colorPrimaryDark:'#bf360c', colorPrimaryLight:'#f4511e', colorAccent:'#FF9800', colorAccentLight:'#FFB74D', colorNavBg:'#bf360c' },
  night:   { colorPrimary:'#5e35b1', colorPrimaryDark:'#311b92', colorPrimaryLight:'#7c4dff', colorAccent:'#00e5ff', colorAccentLight:'#80deea', colorNavBg:'#1a1a2e' },
  royal:   { colorPrimary:'#1565c0', colorPrimaryDark:'#0d47a1', colorPrimaryLight:'#1976d2', colorAccent:'#ffd700', colorAccentLight:'#ffe566', colorNavBg:'#0d47a1' },
  rose:    { colorPrimary:'#c2185b', colorPrimaryDark:'#880e4f', colorPrimaryLight:'#e91e63', colorAccent:'#ff6090', colorAccentLight:'#ff8fab', colorNavBg:'#880e4f' },
};

function seApplyTheme(name, btn) {
  document.querySelectorAll('.se-chip').forEach(c => c.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const t = SE_THEMES[name];
  if (!t) return;
  const map = {
    colorPrimary:      ['se-color-primary','se-hex-primary'],
    colorPrimaryDark:  ['se-color-primary-dark','se-hex-primary-dark'],
    colorPrimaryLight: ['se-color-primary-light','se-hex-primary-light'],
    colorAccent:       ['se-color-accent','se-hex-accent'],
    colorAccentLight:  ['se-color-accent-light','se-hex-accent-light'],
    colorNavBg:        ['se-color-nav-bg','se-hex-nav-bg'],
  };
  Object.entries(map).forEach(([key,[cpId,hexId]]) => {
    if (t[key]) {
      seSet(cpId, t[key]);
      seSet(hexId, t[key]);
    }
  });
  seLivePreview();
}

// ── Read all controls into a config object ───────────────
function seReadConfig() {
  return {
    colorPrimary:      seGet('se-color-primary')      || SE_DEFAULTS.colorPrimary,
    colorPrimaryDark:  seGet('se-color-primary-dark') || SE_DEFAULTS.colorPrimaryDark,
    colorPrimaryLight: seGet('se-color-primary-light')|| SE_DEFAULTS.colorPrimaryLight,
    colorAccent:       seGet('se-color-accent')       || SE_DEFAULTS.colorAccent,
    colorAccentLight:  seGet('se-color-accent-light') || SE_DEFAULTS.colorAccentLight,
    colorCoral:        seGet('se-color-coral')        || SE_DEFAULTS.colorCoral,
    colorBg:           seGet('se-color-bg')           || SE_DEFAULTS.colorBg,
    colorCharcoal:     seGet('se-color-charcoal')     || SE_DEFAULTS.colorCharcoal,
    colorCardBg:       seGet('se-color-card-bg')      || SE_DEFAULTS.colorCardBg,
    colorPrice:        seGet('se-color-price')        || SE_DEFAULTS.colorPrice,
    colorInputBg:      seGet('se-color-input-bg')     || SE_DEFAULTS.colorInputBg,
    colorInputBorder:  seGet('se-color-input-border') || SE_DEFAULTS.colorInputBorder,
    colorInputText:    seGet('se-color-input-text')   || SE_DEFAULTS.colorInputText,
    colorNavBg:        seGet('se-color-nav-bg')       || SE_DEFAULTS.colorNavBg,
    btnRadius:         parseInt(seGet('se-btn-radius'))       || SE_DEFAULTS.btnRadius,
    btnFontSize:       parseInt(seGet('se-btn-fontsize'))     || SE_DEFAULTS.btnFontSize,
    btnPy:             parseInt(seGet('se-btn-py'))           || SE_DEFAULTS.btnPy,
    btnPx:             parseInt(seGet('se-btn-px'))           || SE_DEFAULTS.btnPx,
    btnFontWeight:     seGet('se-btn-fontweight')             || SE_DEFAULTS.btnFontWeight,
    btnTransform:      seGet('se-btn-transform')              || SE_DEFAULTS.btnTransform,
    btnLetterSpacing:  parseFloat(seGet('se-btn-ls'))         || SE_DEFAULTS.btnLetterSpacing,
    btnShadow:         seGet('se-btn-shadow')                 || SE_DEFAULTS.btnShadow,
    cardRadius:        parseInt(seGet('se-card-radius'))      || SE_DEFAULTS.cardRadius,
    cardImgH:          parseInt(seGet('se-card-img-h'))       || SE_DEFAULTS.cardImgH,
    cardShadow:        seGet('se-card-shadow')                || SE_DEFAULTS.cardShadow,
    inputRadius:       parseInt(seGet('se-input-radius'))     || SE_DEFAULTS.inputRadius,
    inputPadding:      parseInt(seGet('se-input-p'))          || SE_DEFAULTS.inputPadding,
    inputBorderStyle:  seGet('se-input-border-style')         || SE_DEFAULTS.inputBorderStyle,
    inputBorderWidth:  seGet('se-input-border-width')         || SE_DEFAULTS.inputBorderWidth,
    fontHeading:       seGet('se-font-heading')               || SE_DEFAULTS.fontHeading,
    fontBody:          seGet('se-font-body')                  || SE_DEFAULTS.fontBody,
    fontBase:          parseInt(seGet('se-font-base'))        || SE_DEFAULTS.fontBase,
    lineHeight:        parseInt(seGet('se-line-height'))      || SE_DEFAULTS.lineHeight,
    navH:              parseInt(seGet('se-nav-h'))            || SE_DEFAULTS.navH,
    navLogoText:       seGet('se-nav-logo-text')              || SE_DEFAULTS.navLogoText,
    logoSplit:         parseInt(seGet('se-logo-split'))       || SE_DEFAULTS.logoSplit,
  };
}

// ── Populate editor controls from a config object ────────
function sePopulateControls(cfg) {
  const c = Object.assign({}, SE_DEFAULTS, cfg);
  // Color pickers + hex inputs
  const pairs = [
    ['se-color-primary','se-hex-primary', c.colorPrimary],
    ['se-color-primary-dark','se-hex-primary-dark', c.colorPrimaryDark],
    ['se-color-primary-light','se-hex-primary-light', c.colorPrimaryLight],
    ['se-color-accent','se-hex-accent', c.colorAccent],
    ['se-color-accent-light','se-hex-accent-light', c.colorAccentLight],
    ['se-color-coral','se-hex-coral', c.colorCoral],
    ['se-color-bg','se-hex-bg', c.colorBg],
    ['se-color-charcoal','se-hex-charcoal', c.colorCharcoal],
    ['se-color-card-bg','se-hex-card-bg', c.colorCardBg],
    ['se-color-price','se-hex-price', c.colorPrice],
    ['se-color-input-bg','se-hex-input-bg', c.colorInputBg],
    ['se-color-input-border','se-hex-input-border', c.colorInputBorder],
    ['se-color-input-text','se-hex-input-text', c.colorInputText],
    ['se-color-nav-bg','se-hex-nav-bg', c.colorNavBg],
  ];
  pairs.forEach(([cpId, hexId, val]) => { seSet(cpId, val); seSet(hexId, val); });
  // Sliders
  seSet('se-btn-radius',    c.btnRadius);
  seSet('se-btn-fontsize',  c.btnFontSize);
  seSet('se-btn-py',        c.btnPy);
  seSet('se-btn-px',        c.btnPx);
  seSet('se-btn-ls',        c.btnLetterSpacing);
  seSet('se-card-radius',   c.cardRadius);
  seSet('se-card-img-h',    c.cardImgH);
  seSet('se-input-radius',  c.inputRadius);
  seSet('se-input-p',       c.inputPadding);
  seSet('se-font-base',     c.fontBase);
  seSet('se-line-height',   c.lineHeight);
  seSet('se-nav-h',         c.navH);
  seSet('se-logo-split',    c.logoSplit);
  // Select & text
  seSet('se-btn-fontweight',     c.btnFontWeight);
  seSet('se-btn-transform',      c.btnTransform);
  seSet('se-btn-shadow',         c.btnShadow);
  seSet('se-card-shadow',        c.cardShadow);
  seSet('se-input-border-style', c.inputBorderStyle);
  seSet('se-input-border-width', c.inputBorderWidth);
  seSet('se-font-heading',       c.fontHeading);
  seSet('se-font-body',          c.fontBody);
  seSet('se-nav-logo-text',      c.navLogoText);
  // Update slider labels
  document.getElementById('se-lbl-btn-radius') && (document.getElementById('se-lbl-btn-radius').textContent = c.btnRadius + 'px');
  document.getElementById('se-lbl-btn-size')   && (document.getElementById('se-lbl-btn-size').textContent = (c.btnFontSize/16).toFixed(3) + 'rem');
  document.getElementById('se-lbl-btn-py')     && (document.getElementById('se-lbl-btn-py').textContent = c.btnPy + 'px');
  document.getElementById('se-lbl-btn-px')     && (document.getElementById('se-lbl-btn-px').textContent = c.btnPx + 'px');
  document.getElementById('se-lbl-btn-ls')     && (document.getElementById('se-lbl-btn-ls').textContent = c.btnLetterSpacing + 'px');
  document.getElementById('se-lbl-card-radius')  && (document.getElementById('se-lbl-card-radius').textContent = c.cardRadius + 'px');
  document.getElementById('se-lbl-card-img-h')   && (document.getElementById('se-lbl-card-img-h').textContent = c.cardImgH + 'px');
  document.getElementById('se-lbl-input-radius') && (document.getElementById('se-lbl-input-radius').textContent = c.inputRadius + 'px');
  document.getElementById('se-lbl-input-p')      && (document.getElementById('se-lbl-input-p').textContent = c.inputPadding + 'px');
  document.getElementById('se-lbl-font-base')    && (document.getElementById('se-lbl-font-base').textContent = c.fontBase + 'px');
  document.getElementById('se-lbl-line-height')  && (document.getElementById('se-lbl-line-height').textContent = (c.lineHeight/10).toFixed(1));
  document.getElementById('se-lbl-nav-h')        && (document.getElementById('se-lbl-nav-h').textContent = c.navH + 'px');
  document.getElementById('se-lbl-logo-split')   && (document.getElementById('se-lbl-logo-split').textContent = c.logoSplit);
}

// ── Load from _LS ───────────────────────────────
function seLoadFromStorage() {
  try {
    const saved = JSON.parse(_LS.getItem(SE_LS_KEY) || 'null');
    const cfg = saved ? Object.assign({}, SE_DEFAULTS, saved) : { ...SE_DEFAULTS };
    sePopulateControls(cfg);
    seLivePreview();
  } catch(e) {
    sePopulateControls(SE_DEFAULTS);
  }
}

// ── Resolve button shadow CSS ────────────────────────────
function seBtnShadow(level, color) {
  if (level === 'none') return 'none';
  if (level === 'sm')   return '0 1px 4px rgba(0,0,0,0.15)';
  if (level === 'md')   return '0 4px 12px rgba(0,0,0,0.20)';
  if (level === 'lg')   return '0 8px 24px rgba(0,0,0,0.28)';
  if (level === 'glow') return '0 0 16px ' + (color || '#0D5C63') + '88';
  return 'none';
}
function seCardShadow(level) {
  if (level === 'none') return 'none';
  if (level === 'sm')   return '0 1px 6px rgba(13,92,99,0.06)';
  if (level === 'md')   return '0 2px 12px rgba(13,92,99,0.10)';
  if (level === 'lg')   return '0 8px 32px rgba(13,92,99,0.18)';
  return 'none';
}

// ── Live preview update ──────────────────────────────────
function seLivePreview() {
  const c = seReadConfig();

  // ── NAVBAR ──
  const nav = document.getElementById('prev-navbar');
  if (nav) {
    nav.style.background = c.colorNavBg;
    nav.style.height = c.navH + 'px';
  }
  // Logo split
  const logoEl   = document.getElementById('prev-logo');
  const logoGold = document.getElementById('prev-logo-gold');
  const logoText = c.navLogoText || 'Wampac';
  const split    = Math.max(1, Math.min(c.logoSplit, logoText.length - 1));
  if (logoEl) {
    logoEl.innerHTML = escHtml(logoText.slice(0, split)) +
      '<span id="prev-logo-gold" style="color:' + c.colorAccent + ';">' +
      escHtml(logoText.slice(split)) + '</span>';
  }

  // ── HERO ──
  const hero = document.getElementById('prev-hero');
  if (hero) {
    hero.style.background = 'linear-gradient(135deg,' + c.colorPrimaryDark + ',' + c.colorPrimary + ',' + c.colorPrimaryLight + ')';
    hero.style.fontFamily = c.fontHeading + ', sans-serif';
  }

  // ── BUTTONS ──
  const btnStyle = {
    borderRadius:    c.btnRadius + 'px',
    fontSize:        (c.btnFontSize / 16).toFixed(3) + 'rem',
    padding:         c.btnPy + 'px ' + c.btnPx + 'px',
    fontWeight:      c.btnFontWeight,
    textTransform:   c.btnTransform,
    letterSpacing:   c.btnLetterSpacing + 'px',
  };
  const applyBtn = (id, extra) => {
    const el = document.getElementById(id);
    if (!el) return;
    Object.assign(el.style, btnStyle, extra);
    el.style.boxShadow = seBtnShadow(c.btnShadow, extra.background);
  };
  applyBtn('prev-btn-primary',  { background: c.colorPrimary,  color: '#fff' });
  applyBtn('prev-btn-accent',   { background: c.colorAccent,   color: c.colorCharcoal });
  applyBtn('prev-btn-danger',   { background: c.colorCoral,    color: '#fff' });
  applyBtn('prev-btn-outline',  { background: 'transparent', color: '#fff', border: '1.5px solid rgba(255,255,255,0.4)' });
  applyBtn('prev-btn-gold',     { background: c.colorAccent, color: c.colorCharcoal });
  applyBtn('prev-contact-btn',  { background: c.colorAccent,  color: c.colorCharcoal });
  applyBtn('prev-dir-btn',      { background: '#1a73e8',       color: '#fff' });

  // ── CARD ──
  const card = document.getElementById('prev-card');
  if (card) {
    card.style.borderRadius = c.cardRadius + 'px';
    card.style.boxShadow    = seCardShadow(c.cardShadow);
    card.style.background   = c.colorCardBg;
  }
  const cardImg = document.getElementById('prev-card-img');
  if (cardImg) {
    cardImg.style.height     = Math.min(c.cardImgH, 140) + 'px';
    cardImg.style.background = 'linear-gradient(135deg,' + c.colorPrimary + ',' + c.colorPrimaryLight + ')';
  }
  const priceEl = document.getElementById('prev-price');
  if (priceEl) priceEl.style.color = c.colorPrice;

  // ── FORM FIELDS ──
  ['prev-input-1','prev-input-2'].forEach(id => {
    const inp = document.getElementById(id);
    if (!inp) return;
    inp.style.background   = c.colorInputBg;
    inp.style.borderRadius = c.inputRadius + 'px';
    inp.style.padding      = c.inputPadding + 'px ' + (c.inputPadding + 3) + 'px';
    inp.style.color        = c.colorInputText;
    inp.style.fontSize     = (c.fontBase / 16 * 0.9).toFixed(3) + 'rem';
    if (c.inputBorderStyle === 'none') {
      inp.style.border = 'none';
      inp.style.boxShadow = 'inset 0 0 0 2px ' + c.colorInputBorder;
    } else {
      inp.style.border = c.inputBorderWidth + ' ' + c.inputBorderStyle + ' ' + c.colorInputBorder;
      inp.style.boxShadow = 'none';
    }
  });

  // ── TYPOGRAPHY ──
  const headingEl = document.getElementById('prev-heading');
  if (headingEl) {
    headingEl.style.fontFamily = c.fontHeading + ', sans-serif';
    headingEl.style.color = c.colorCharcoal;
    headingEl.style.fontSize = (c.fontBase * 1.15 / 16).toFixed(3) + 'rem';
  }
  const bodyTextEl = document.getElementById('prev-body-text');
  if (bodyTextEl) {
    bodyTextEl.style.fontFamily = c.fontBody + ', sans-serif';
    bodyTextEl.style.fontSize   = (c.fontBase * 0.85 / 16).toFixed(3) + 'rem';
    bodyTextEl.style.lineHeight = (c.lineHeight / 10).toFixed(1);
  }
}

// ── Apply all styles to the live site ───────────────────
function seApplyToSite() {
  const c = seReadConfig();

  // Save to _LS
  _LS.setItem(SE_LS_KEY, JSON.stringify(c));

  // ── CSS Variables ──
  const r = document.documentElement;
  r.style.setProperty('--teal',       c.colorPrimary);
  r.style.setProperty('--teal-dark',  c.colorPrimaryDark);
  r.style.setProperty('--teal-light', c.colorPrimaryLight);
  r.style.setProperty('--gold',       c.colorAccent);
  r.style.setProperty('--gold-light', c.colorAccentLight);
  r.style.setProperty('--coral',      c.colorCoral);
  r.style.setProperty('--bg',         c.colorBg);
  r.style.setProperty('--charcoal',   c.colorCharcoal);

  // ── Inject a <style> block for dynamic overrides ──
  let dynStyle = document.getElementById('se-dynamic-style');
  if (!dynStyle) {
    dynStyle = document.createElement('style');
    dynStyle.id = 'se-dynamic-style';
    document.head.appendChild(dynStyle);
  }
  const lh = (c.lineHeight / 10).toFixed(1);
  dynStyle.textContent = `
    /* === Wampac Style Editor Applied === */
    body { font-family: '${c.fontBody}', sans-serif; font-size: ${c.fontBase}px; line-height: ${lh}; }
    h1,h2,h3,h4,h5,.nav-logo,.section-title,.listing-title,.dashboard-section-title,
    .admin-section-title,.modal-header h3,.prev-heading {
      font-family: '${c.fontHeading}', sans-serif;
    }
    nav { background: ${c.colorNavBg}; height: ${c.navH}px; }
    .btn {
      border-radius: ${c.btnRadius}px !important;
      font-size: ${(c.btnFontSize/16).toFixed(3)}rem !important;
      padding: ${c.btnPy}px ${c.btnPx}px !important;
      font-weight: ${c.btnFontWeight} !important;
      text-transform: ${c.btnTransform} !important;
      letter-spacing: ${c.btnLetterSpacing}px !important;
      box-shadow: ${seBtnShadow(c.btnShadow, c.colorPrimary)} !important;
    }
    .btn-teal   { background: ${c.colorPrimary} !important; color: #fff !important; }
    .btn-gold   { background: ${c.colorAccent}  !important; color: ${c.colorCharcoal} !important; }
    .btn-coral  { background: ${c.colorCoral}   !important; color: #fff !important; }
    .listing-card { border-radius: ${c.cardRadius}px !important; background: ${c.colorCardBg} !important; box-shadow: ${seCardShadow(c.cardShadow)} !important; }
    .listing-price { color: ${c.colorPrice} !important; }
    .form-group input, .form-group select, .form-group textarea {
      background: ${c.colorInputBg} !important;
      border-radius: ${c.inputRadius}px !important;
      padding: ${c.inputPadding}px ${c.inputPadding+3}px !important;
      color: ${c.colorInputText} !important;
      border: ${c.inputBorderStyle === 'none' ? 'none' : c.inputBorderWidth + ' ' + c.inputBorderStyle + ' ' + c.colorInputBorder} !important;
    }
    .modal-tab.active { color: ${c.colorPrimary} !important; }
    .filter-chip.active { background: ${c.colorPrimary} !important; border-color: ${c.colorPrimary} !important; }
    .listing-type-badge { background: rgba(0,0,0,0.6) !important; }
    .area-card::after { background: ${c.colorAccent} !important; }
    .stat-card .stat-num { color: ${c.colorPrimary} !important; }
  `;

  // ── Navbar logo ──
  const logo = document.querySelector('.nav-logo');
  if (logo) {
    const logoText = c.navLogoText || 'Wampac';
    if (logoText === 'Wampac') {
      logo.innerHTML = wampacLogoImgHTML(32);
    } else {
      const split = Math.max(1, Math.min(c.logoSplit, logoText.length - 1));
      logo.innerHTML = escHtml(logoText.slice(0, split)) + '<span>' + escHtml(logoText.slice(split)) + '</span>';
    }
    // Note: click/tap behavior is handled by the dedicated gesture listener
    // on #nav-logo — do not attach a separate onclick here.
  }

  // Also sync with existing appearance system
  const a = getAppearance();
  a.colorPrimary = c.colorPrimary;
  a.colorAccent  = c.colorAccent;
  a.siteName     = c.navLogoText;
  a.logoSplit    = c.logoSplit;
  saveAppearanceData(a);

  // Show success
  const ok = document.getElementById('se-save-success');
  if (ok) { ok.style.display = 'block'; setTimeout(() => ok.style.display = 'none', 3500); }
  showToast('🎨 Styles applied site-wide!', 'success');
}

// ── Reset to defaults ────────────────────────────────────
function seReset() {
  if (!confirm('Reset all Style Editor settings to defaults?')) return;
  _LS.removeItem(SE_LS_KEY);
  sePopulateControls(SE_DEFAULTS);
  seLivePreview();
  // Remove dynamic style override
  const dynStyle = document.getElementById('se-dynamic-style');
  if (dynStyle) dynStyle.remove();
  // Reset CSS vars
  const r = document.documentElement;
  r.style.setProperty('--teal',       SE_DEFAULTS.colorPrimary);
  r.style.setProperty('--teal-dark',  SE_DEFAULTS.colorPrimaryDark);
  r.style.setProperty('--teal-light', SE_DEFAULTS.colorPrimaryLight);
  r.style.setProperty('--gold',       SE_DEFAULTS.colorAccent);
  r.style.setProperty('--gold-light', SE_DEFAULTS.colorAccentLight);
  r.style.setProperty('--coral',      SE_DEFAULTS.colorCoral);
  r.style.setProperty('--bg',         SE_DEFAULTS.colorBg);
  r.style.setProperty('--charcoal',   SE_DEFAULTS.colorCharcoal);
  showToast('Style Editor reset to defaults.', 'success');
}

// ── Export CSS ───────────────────────────────────────────
function seExportCSS() {
  const c = seReadConfig();
  const lh = (c.lineHeight / 10).toFixed(1);
  const css = `:root {
  --teal:       ${c.colorPrimary};
  --teal-dark:  ${c.colorPrimaryDark};
  --teal-light: ${c.colorPrimaryLight};
  --gold:       ${c.colorAccent};
  --gold-light: ${c.colorAccentLight};
  --coral:      ${c.colorCoral};
  --bg:         ${c.colorBg};
  --charcoal:   ${c.colorCharcoal};
}
body {
  font-family: '${c.fontBody}', sans-serif;
  font-size: ${c.fontBase}px;
  line-height: ${lh};
  background: ${c.colorBg};
  color: ${c.colorCharcoal};
}
h1,h2,h3,h4,h5 { font-family: '${c.fontHeading}', sans-serif; }
nav { background: ${c.colorNavBg}; height: ${c.navH}px; }
.btn {
  border-radius: ${c.btnRadius}px;
  font-size: ${(c.btnFontSize/16).toFixed(3)}rem;
  padding: ${c.btnPy}px ${c.btnPx}px;
  font-weight: ${c.btnFontWeight};
  text-transform: ${c.btnTransform};
  letter-spacing: ${c.btnLetterSpacing}px;
  box-shadow: ${seBtnShadow(c.btnShadow, c.colorPrimary)};
}
.btn-teal  { background: ${c.colorPrimary}; color: #fff; }
.btn-gold  { background: ${c.colorAccent};  color: ${c.colorCharcoal}; }
.btn-coral { background: ${c.colorCoral};   color: #fff; }
.listing-card {
  border-radius: ${c.cardRadius}px;
  background: ${c.colorCardBg};
  box-shadow: ${seCardShadow(c.cardShadow)};
}
.listing-price { color: ${c.colorPrice}; }
.form-group input,
.form-group select,
.form-group textarea {
  background: ${c.colorInputBg};
  border-radius: ${c.inputRadius}px;
  padding: ${c.inputPadding}px ${c.inputPadding+3}px;
  color: ${c.colorInputText};
  border: ${c.inputBorderStyle === 'none' ? 'none' : c.inputBorderWidth + ' ' + c.inputBorderStyle + ' ' + c.colorInputBorder};
}
`;
  const blob = new Blob([css], { type: 'text/css' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'wampac-custom-styles.css';
  a.click();
  URL.revokeObjectURL(a.href);
  showToast('CSS exported!', 'success');
}

// ── On page load: restore any saved Style Editor settings ─
(function seRestoreOnLoad() {
  try {
    const saved = JSON.parse(_LS.getItem(SE_LS_KEY) || 'null');
    if (!saved) return;
    const r = document.documentElement;
    if (saved.colorPrimary)      r.style.setProperty('--teal',       saved.colorPrimary);
    if (saved.colorPrimaryDark)  r.style.setProperty('--teal-dark',  saved.colorPrimaryDark);
    if (saved.colorPrimaryLight) r.style.setProperty('--teal-light', saved.colorPrimaryLight);
    if (saved.colorAccent)       r.style.setProperty('--gold',       saved.colorAccent);
    if (saved.colorAccentLight)  r.style.setProperty('--gold-light', saved.colorAccentLight);
    if (saved.colorCoral)        r.style.setProperty('--coral',      saved.colorCoral);
    if (saved.colorBg)           r.style.setProperty('--bg',         saved.colorBg);
    if (saved.colorCharcoal)     r.style.setProperty('--charcoal',   saved.colorCharcoal);
    // Re-inject dynamic style sheet
    sePopulateControls(Object.assign({}, SE_DEFAULTS, saved));
    // Rebuild the dynamic <style> block
    let dynStyle = document.getElementById('se-dynamic-style');
    if (!dynStyle) {
      dynStyle = document.createElement('style');
      dynStyle.id = 'se-dynamic-style';
      document.head.appendChild(dynStyle);
    }
    const c = Object.assign({}, SE_DEFAULTS, saved);
    const lh = (c.lineHeight / 10).toFixed(1);
    dynStyle.textContent = `
      body { font-family: '${c.fontBody}', sans-serif; font-size: ${c.fontBase}px; line-height: ${lh}; }
      h1,h2,h3,h4,h5,.nav-logo,.section-title,.listing-title { font-family: '${c.fontHeading}', sans-serif; }
      nav { background: ${c.colorNavBg}; height: ${c.navH}px; }
      .btn { border-radius: ${c.btnRadius}px !important; font-size: ${(c.btnFontSize/16).toFixed(3)}rem !important; padding: ${c.btnPy}px ${c.btnPx}px !important; font-weight: ${c.btnFontWeight} !important; text-transform: ${c.btnTransform} !important; letter-spacing: ${c.btnLetterSpacing}px !important; }
      .btn-teal  { background: ${c.colorPrimary} !important; }
      .btn-gold  { background: ${c.colorAccent}  !important; }
      .listing-card { border-radius: ${c.cardRadius}px !important; box-shadow: ${seCardShadow(c.cardShadow)} !important; }
      .listing-price { color: ${c.colorPrice} !important; }
      .form-group input,.form-group select,.form-group textarea { background: ${c.colorInputBg} !important; border-radius: ${c.inputRadius}px !important; padding: ${c.inputPadding}px ${c.inputPadding+3}px !important; color: ${c.colorInputText} !important; }
    `;
  } catch(e) {}
})();


// ══════════════════════════════════════════════════════════════════════
//  SUPER ADMIN ENGINE  —  v32
//  Covers: Audit Log · Landlords · Listings · Moderation · Comms ·
//          RBAC · Impersonation · Bulk Actions · System Settings
// ══════════════════════════════════════════════════════════════════════

const LS_AUDIT       = 'wampac_audit_log';
const LS_ADMINS      = 'wampac_admin_accounts';
const LS_RBAC        = 'wampac_rbac';
const LS_NOTIFS      = 'wampac_notifications';
const LS_ANNOUNCE_HISTORY = 'wampac_announce_history';
const LS_IMPERSONATE = 'wampac_impersonate';

let _saAuditPage     = 1;
const SA_AUDIT_PER_PAGE = 30;
let _saAnnounceBannerColor = '#137A82';
let _saNotifTarget   = 'all';
let _saCurrentRole   = 'moderator';
let _saImpersonating = null;

// ──────────────────────────────────────────────
// AUDIT LOG ENGINE
// ──────────────────────────────────────────────
function saLog(type, action, detail, userId) {
  const log = saGetAuditLog();
  const entry = {
    id:     'al_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    type,          // create | update | delete | suspend | login | system
    action,        // Human-readable action label
    detail,        // Extra context
    userId: userId || 'superadmin',
    ts:     Date.now()
  };
  log.unshift(entry);
  // Keep max 2000 entries
  if (log.length > 2000) log.length = 2000;
  _LS.setItem(LS_AUDIT, JSON.stringify(log));
  // Update counter chip in topbar
  const el = document.getElementById('sa-audit-count');
  if (el) el.textContent = 'Audit log: ' + log.length + ' entries';
}

function saGetAuditLog() {
  try { return JSON.parse(_LS.getItem(LS_AUDIT) || '[]'); } catch(e) { return []; }
}

function saRenderAuditLog() {
  const container = document.getElementById('sa-audit-log-list');
  if (!container) return;

  const query  = (document.getElementById('sa-audit-search')?.value || '').toLowerCase();
  const filter = document.getElementById('sa-audit-type-filter')?.value || 'all';

  let log = saGetAuditLog();
  if (filter !== 'all') log = log.filter(e => e.type === filter);
  if (query) log = log.filter(e =>
    e.action.toLowerCase().includes(query) ||
    (e.detail||'').toLowerCase().includes(query) ||
    (e.userId||'').toLowerCase().includes(query)
  );

  // Update stat chips
  const all = saGetAuditLog();
  const today = Date.now() - 86400000;
  saSetEl('sa-audit-total',   all.length);
  saSetEl('sa-audit-today',   all.filter(e => e.ts > today).length);
  saSetEl('sa-audit-deletes', all.filter(e => e.type === 'delete').length);
  saSetEl('sa-audit-logins',  all.filter(e => e.type === 'login').length);

  // Pagination
  const totalPages = Math.max(1, Math.ceil(log.length / SA_AUDIT_PER_PAGE));
  _saAuditPage = Math.min(_saAuditPage, totalPages);
  const start = (_saAuditPage - 1) * SA_AUDIT_PER_PAGE;
  const page  = log.slice(start, start + SA_AUDIT_PER_PAGE);

  if (page.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:32px;color:var(--grey);">No audit events match your filter.</div>';
    document.getElementById('sa-audit-pagination').innerHTML = '';
    return;
  }

  const TYPE_ICONS = { create:'➕', update:'✏️', delete:'🗑', suspend:'🚫', login:'🔑', system:'⚙️' };
  const TYPE_CLASSES = { create:'audit-create', update:'audit-update', delete:'audit-delete', suspend:'audit-suspend', login:'audit-login', system:'audit-system' };

  container.innerHTML = page.map(e => {
    const d  = new Date(e.ts);
    const ts = d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
    return `<div class="sa-audit-row">
      <div class="sa-audit-icon ${TYPE_CLASSES[e.type]||''}">${TYPE_ICONS[e.type]||'📝'}</div>
      <div class="sa-audit-meta">
        <div class="sa-audit-action">${escHtml(e.action)}</div>
        <div class="sa-audit-detail">${escHtml(e.detail||'')} <span style="color:#bbb;">· by ${escHtml(e.userId||'system')}</span></div>
      </div>
      <div class="sa-audit-time">${ts}</div>
    </div>`;
  }).join('');

  // Pagination buttons
  const pag = document.getElementById('sa-audit-pagination');
  if (pag) {
    let btns = '';
    for (let i = 1; i <= totalPages; i++) {
      btns += `<button onclick="saAuditGotoPage(${i})" style="padding:6px 12px;border-radius:8px;border:1.5px solid ${i===_saAuditPage?'var(--teal)':'#e5e7eb'};background:${i===_saAuditPage?'var(--teal)':'#fff'};color:${i===_saAuditPage?'#fff':'#374151'};font-weight:600;font-size:0.78rem;cursor:pointer;">${i}</button>`;
    }
    pag.innerHTML = btns;
  }
}

function saAuditGotoPage(n) { _saAuditPage = n; saRenderAuditLog(); }

function saClearAuditLog() {
  if (!confirm('Clear entire audit log? This cannot be undone.')) return;
  _LS.removeItem(LS_AUDIT);
  saRenderAuditLog();
  showToast('Audit log cleared.', 'error');
}

function saExportAuditLog() {
  const log = saGetAuditLog();
  const rows = ['Type,Action,Detail,User,Timestamp', ...log.map(e =>
    [e.type, '"'+e.action.replace(/"/g,'""')+'"', '"'+(e.detail||'').replace(/"/g,'""')+'"',
     e.userId, new Date(e.ts).toISOString()].join(',')
  )];
  const blob = new Blob([rows.join('\n')], {type:'text/csv'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = 'wampac-audit-log.csv'; a.click(); URL.revokeObjectURL(a.href);
  showToast('Audit log exported!', 'success');
}

// ──────────────────────────────────────────────
// LANDLORD MANAGEMENT  (Super Admin)
// ──────────────────────────────────────────────
function saRenderLandlords() {
  const tbody = document.getElementById('sa-landlords-tbody');
  if (!tbody) return;

  const query   = (document.getElementById('sa-ll-search')?.value || '').toLowerCase();
  const statusF = document.getElementById('sa-ll-status-filter')?.value || 'all';
  const countryF= document.getElementById('sa-ll-country-filter')?.value || 'all';
  const susp    = getSuspended();
  let users = getUsers();

  if (query) users = users.filter(u =>
    (u.name||'').toLowerCase().includes(query) ||
    (u.email||'').toLowerCase().includes(query) ||
    (u.phone||'').toLowerCase().includes(query) ||
    (u.country||'').toLowerCase().includes(query)
  );
  if (statusF === 'active')    users = users.filter(u => !susp.includes(u.id));
  if (statusF === 'suspended') users = users.filter(u =>  susp.includes(u.id));
  if (countryF !== 'all')      users = users.filter(u => u.countryCode === countryF);

  const props = getProps();
  const total = getUsers().length;
  saSetEl('sa-ll-total',     total);
  saSetEl('sa-ll-active',    getUsers().filter(u => !susp.includes(u.id)).length);
  saSetEl('sa-ll-suspended', susp.length);
  saSetEl('sa-ll-listings',  props.length);

  if (users.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--grey);padding:28px;">No landlords match your filter.</td></tr>';
    return;
  }

  tbody.innerHTML = users.map(u => {
    const listCount = props.filter(p => p.landlordId === u.id).length;
    const isSusp    = susp.includes(u.id);
    const joined    = u.id ? new Date(parseInt(u.id.split('_')[1]||Date.now())).toLocaleDateString() : '—';
    const acctInfo  = ACCOUNT_TYPES[u.accountType || 'residential'] || ACCOUNT_TYPES.residential;
    const acctColors = { residential:'#dbeafe|#1d4ed8', commercial:'#fef3c7|#92400e', property_management:'#ede9fe|#5b21b6' };
    const [acBg, acFg] = (acctColors[u.accountType] || acctColors.residential).split('|');
    return `<tr>
      <td>
        <div style="font-weight:700;color:#1a1a2e;">${escHtml(u.companyName || u.name)}</div>
        ${u.companyName ? `<div style="font-size:0.72rem;color:#6b7280;">Owner: ${escHtml(u.name)}</div>` : ''}
        <div style="font-size:0.72rem;color:#6b7280;">${escHtml(u.email||'—')}</div>
        <span style="display:inline-flex;align-items:center;gap:3px;background:${acBg};color:${acFg};font-size:0.65rem;font-weight:700;padding:2px 7px;border-radius:20px;margin-top:3px;">${acctInfo.icon} ${acctInfo.label}</span>
      </td>
      <td>
        <div style="font-size:0.82rem;">${escHtml(u.phone || '—')}</div>
      </td>
      <td>
        <div style="font-size:0.82rem;">${escHtml(u.country||'PNG')}</div>
        <div style="font-size:0.72rem;color:#6b7280;">${escHtml(u.province||u.area||'')}</div>
      </td>
      <td><span class="pill pill-blue">${listCount}</span></td>
      <td style="font-size:0.78rem;color:#6b7280;">${joined}</td>
      <td><span class="pill ${isSusp?'pill-red':'pill-green'}">${isSusp?'Suspended':'Active'}</span></td>
      <td>
        <div class="sa-actions-cell">
          <button class="sa-btn edit"     onclick="saEditLandlord('${u.id}')"><span class="wi-svg" data-lucide="pencil" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✏️</span> Edit</button>
          <button class="sa-btn login-as" onclick="saImpersonate('${u.id}')">🎭 Login As</button>
          <button class="sa-btn reset-pw" onclick="saResetPassword('${u.id}')">🔑 Reset PW</button>
          ${isSusp
            ? `<button class="sa-btn restore" onclick="saToggleSuspend('${u.id}',false)"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Restore</button>`
            : `<button class="sa-btn"    style="background:#fff7ed;color:#b45309;" onclick="saToggleSuspend('${u.id}',true)">🚫 Suspend</button>`}
          <button class="sa-btn danger"   onclick="saDeleteLandlord('${u.id}')"><span class="wi-svg" data-lucide="trash-2" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">🗑</span></button>
        </div>
      </td>
    </tr>`;
  }).join('');
  wiRender();
}

function saToggleSuspend(userId, suspend) {
  let susp = getSuspended();
  const users = getUsers();
  const u = users.find(x => x.id === userId);
  if (suspend) { if (!susp.includes(userId)) susp.push(userId); }
  else         { susp = susp.filter(id => id !== userId); }
  saveSuspended(susp);
  saLog('suspend', suspend ? 'Landlord suspended' : 'Landlord restored',
    `${u?.name||userId}`, 'superadmin');
  saRenderLandlords();
  renderAdminStats();
  showToast(suspend ? 'Landlord suspended.' : 'Landlord restored.', suspend?'error':'success');
}

function saDeleteLandlord(userId) {
  const users = getUsers();
  const u = users.find(x => x.id === userId);
  if (!confirm(`Delete ${u?.name||'this landlord'} and ALL their listings? Cannot be undone.`)) return;
  saveUsers(users.filter(x => x.id !== userId));
  saveProps(getProps().filter(p => p.landlordId !== userId));
  saveSuspended(getSuspended().filter(id => id !== userId));
  saLog('delete', 'Landlord account deleted', `${u?.name||userId} (${u?.phone||''})`, 'superadmin');
  saRenderLandlords();
  renderAdminStats();
  refreshAllGrids();
  showToast('Landlord deleted.', 'error');
}

function saEditLandlord(userId) {
  const u = getUsers().find(x => x.id === userId);
  if (!u) return;
  saOpenModal('✏️ Edit Landlord Account', `
    <div class="form-group"><label>Full Name</label><input type="text" id="sa-edit-name" value="${escAttr(u.name)}"></div>
    <div class="form-group"><label>Email</label><input type="email" id="sa-edit-email" value="${escAttr(u.email||'')}"></div>
    <div class="form-group"><label>Phone</label><input type="tel" id="sa-edit-phone" value="${escAttr(u.phone || '')}"></div>
    <div class="form-group"><label>Country</label><input type="text" id="sa-edit-country" value="${escAttr(u.country||'')}"></div>
    <div class="form-group"><label>Province / Area</label><input type="text" id="sa-edit-area" value="${escAttr(u.area||u.province||'')}"></div>
  `, () => {
    const users = getUsers();
    const idx   = users.findIndex(x => x.id === userId);
    if (idx === -1) return;
    const newEmail = document.getElementById('sa-edit-email').value.trim();
    if (newEmail && users.some((x, i) => i !== idx && normEmail(x.email) === normEmail(newEmail))) { showToast('That email is already used by another account.','error'); return; }
    const oldName = users[idx].name;
    users[idx].name    = document.getElementById('sa-edit-name').value.trim()   || users[idx].name;
    users[idx].email   = document.getElementById('sa-edit-email').value.trim();
    users[idx].phone   = document.getElementById('sa-edit-phone').value.trim();
    users[idx].country = document.getElementById('sa-edit-country').value.trim();
    users[idx].area    = document.getElementById('sa-edit-area').value.trim();
    saveUsers(users);
    saLog('update', 'Landlord profile edited', `${oldName} → ${users[idx].name}`, 'superadmin');
    saRenderLandlords();
    showToast('Landlord updated.', 'success');
  });
}

function saResetPassword(userId) {
  const users = getUsers();
  const u     = users.find(x => x.id === userId);
  if (!u) return;
  saOpenModal('🔑 Reset Password', `
    <div style="margin-bottom:14px;font-size:0.85rem;color:#374151;">Reset password for <strong>${escHtml(u.name)}</strong>.</div>
    <div class="form-group"><label>New Password</label><input type="password" id="sa-new-pw" placeholder="Min 6 characters"></div>
    <div class="form-group"><label>Confirm Password</label><input type="password" id="sa-new-pw2" placeholder="Repeat password"></div>
  `, () => {
    const pw  = document.getElementById('sa-new-pw').value;
    const pw2 = document.getElementById('sa-new-pw2').value;
    if (!pw || pw.length < 6) { showToast('Password too short.','error'); return; }
    if (pw !== pw2)            { showToast('Passwords do not match.','error'); return; }
    const idx = users.findIndex(x => x.id === userId);
    users[idx].password = hashish(pw);
    saveUsers(users);
    saLog('update', 'Password reset by admin', `Account: ${u.name}`, 'superadmin');
    showToast(`Password reset for ${u.name}.`, 'success');
  });
}

function saOpenCreateLandlord() {
  saOpenModal('➕ Create Landlord Account', `
    <div class="form-group"><label>Full Name</label><input type="text" id="sa-cl-name" placeholder="e.g. James Kila"></div>
    <div class="form-group"><label>Email *</label><input type="email" id="sa-cl-email" placeholder="you@example.com"></div>
    <div class="form-group"><label>Country</label><input type="text" id="sa-cl-country" placeholder="Papua New Guinea" value="Papua New Guinea"></div>
    <div class="form-group"><label>Province / Area</label><input type="text" id="sa-cl-area" placeholder="NCD"></div>
    <div class="form-group"><label>Password</label><input type="password" id="sa-cl-pw" placeholder="Min 6 characters"></div>
  `, () => {
    const name  = document.getElementById('sa-cl-name').value.trim();
    const email = document.getElementById('sa-cl-email').value.trim();
    const country = document.getElementById('sa-cl-country').value.trim() || 'Papua New Guinea';
    const area  = document.getElementById('sa-cl-area').value.trim();
    const pw    = document.getElementById('sa-cl-pw').value;
    if (!name || !email) { showToast('Name and email are required.','error'); return; }
    if (!EMAIL_RE.test(normEmail(email))) { showToast('Please enter a valid email address.','error'); return; }
    if (!pw || pw.length < 6) { showToast('Password too short.','error'); return; }
    const users = getUsers();
    if (users.find(u => normEmail(u.email) === normEmail(email))) {
      showToast('Email already registered.','error'); return;
    }
    const newUser = { id:'u_'+Date.now(), name, email: normEmail(email), country, area, authProvider:'password', password: hashish(pw) };
    users.push(newUser);
    saveUsers(users);
    saLog('create', 'Landlord account created by admin', `${name} (${normEmail(email)})`, 'superadmin');
    saRenderLandlords();
    renderAdminStats();
    showToast('Landlord account created!', 'success');
  });
}

// ──────────────────────────────────────────────
// LISTINGS MANAGEMENT  (Super Admin)
// ──────────────────────────────────────────────
function saRenderListings() {
  const tbody = document.getElementById('sa-listings-tbody');
  if (!tbody) return;

  const query   = (document.getElementById('sa-lst-search')?.value || '').toLowerCase();
  const statusF = document.getElementById('sa-lst-status-filter')?.value || 'all';
  const typeF   = document.getElementById('sa-lst-type-filter')?.value   || 'all';

  let props = getProps();
  if (query) props = props.filter(p =>
    (p.title||'').toLowerCase().includes(query) ||
    (p.area||'').toLowerCase().includes(query) ||
    (p.landlordName||'').toLowerCase().includes(query)
  );
  if (statusF !== 'all') {
    if (statusF === 'hidden')   props = props.filter(p => p.hidden);
    else if (statusF === 'approved') props = props.filter(p => !p.hidden && (p.status==='approved'||!p.status));
    else props = props.filter(p => !p.hidden && p.status === statusF);
  }
  if (typeF !== 'all') props = props.filter(p => p.type === typeF);
  props.sort((a,b) => b.date - a.date);

  const all = getProps();
  saSetEl('sa-lst-total',    all.length);
  saSetEl('sa-lst-live',     all.filter(p => !p.hidden && (p.status==='approved'||!p.status)).length);
  saSetEl('sa-lst-pending',  all.filter(p => p.status==='pending').length);
  saSetEl('sa-lst-hidden',   all.filter(p => p.hidden).length);
  saSetEl('sa-lst-featured', all.filter(p => p.featured).length);

  if (props.length === 0) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--grey);padding:28px;">No listings match your filter.</td></tr>';
    return;
  }

  tbody.innerHTML = props.map(p => {
    const status = p.hidden ? 'hidden' : (p.status||'approved');
    const statusPill = {
      approved: '<span class="pill pill-green">Live</span>',
      pending:  '<span class="pill pill-yellow">Pending</span>',
      rejected: '<span class="pill pill-red">Rejected</span>',
      hidden:   '<span class="pill-hidden">Hidden</span>',
    }[status] || '<span class="pill pill-green">Live</span>';

    return `<tr>
      <td>
        <div style="font-weight:700;font-size:0.82rem;">${TYPE_EMOJI[p.type]||'🏠'} ${escHtml(p.title)}</div>
        <div style="font-size:0.72rem;color:#6b7280;">📍 ${escHtml(p.area||'')}</div>
      </td>
      <td style="font-size:0.82rem;">${escHtml(p.landlordName||'—')}</td>
      <td><span class="pill pill-blue" style="font-size:0.7rem;">${p.type}</span></td>
      <td style="font-weight:700;color:var(--teal);">K${Number(p.rent).toLocaleString()}</td>
      <td style="font-size:0.78rem;">${escHtml(p.area)}</td>
      <td>${statusPill}</td>
      <td>${p.featured ? '<span class="pill-orange">⭐ Featured</span>' : '<span style="color:#9ca3af;font-size:0.75rem;">—</span>'}</td>
      <td>
        <div class="sa-actions-cell">
          ${status==='pending'?`<button class="sa-btn approve" onclick="saApproveListing('${p.id}')">✅</button><button class="sa-btn reject" onclick="saRejectListing('${p.id}')">❌</button>`:''}
          <button class="sa-btn feature" onclick="saToggleFeature('${p.id}')">${p.featured?'★ Unfeature':'⭐ Feature'}</button>
          <button class="sa-btn hide-btn" onclick="saToggleHide('${p.id}')">${p.hidden?'👁 Show':'🙈 Hide'}</button>
          <button class="sa-btn pin"    onclick="openLocationPicker('${p.id}')">${p.lat!=null?'📍 Update Pin':'📍 Set Pin'}</button>
          <button class="sa-btn edit"   onclick="saEditListing('${p.id}')">✏️</button>
          <button class="sa-btn danger" onclick="saDeleteListing('${p.id}')"><span class="wi-svg" data-lucide="trash-2" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">🗑</span></button>
        </div>
      </td>
    </tr>`;
  }).join('');
  wiRender();
}

function saApproveListing(id) {
  const props = getProps();
  const p = props.find(x => x.id === id);
  if (p) { p.status = 'approved'; p.hidden = false; saveProps(props); }
  saLog('update','Listing approved',`"${p?.title||id}"`, 'superadmin');
  saRenderListings(); refreshAllGrids();
  showToast('Listing approved!','success');
}

function saRejectListing(id) {
  const props = getProps();
  const p = props.find(x => x.id === id);
  if (p) { p.status = 'rejected'; saveProps(props); }
  saLog('update','Listing rejected',`"${p?.title||id}"`, 'superadmin');
  saRenderListings(); refreshAllGrids();
  showToast('Listing rejected.','error');
}

function saToggleFeature(id) {
  const props = getProps();
  const p = props.find(x => x.id === id);
  if (p) { p.featured = !p.featured; saveProps(props); }
  saLog('update', p?.featured?'Listing featured':'Listing unfeatured', `"${p?.title||id}"`, 'superadmin');
  saRenderListings(); refreshAllGrids();
  showToast(p?.featured ? '⭐ Featured!':'Feature removed.','success');
}

function saToggleHide(id) {
  const props = getProps();
  const p = props.find(x => x.id === id);
  if (p) { p.hidden = !p.hidden; saveProps(props); }
  saLog('update', p?.hidden?'Listing hidden':'Listing restored', `"${p?.title||id}"`, 'superadmin');
  saRenderListings(); refreshAllGrids();
  showToast(p?.hidden?'Listing hidden.':'Listing restored.','success');
}

function saEditListing(id) {
  const p = getProps().find(x => x.id === id);
  if (!p) return;
  saOpenModal('✏️ Edit Listing', `
    <div class="form-group"><label>Title</label><input type="text" id="sa-el-title" value="${escAttr(p.title)}"></div>
    <div class="form-group"><label>Rent (K)</label><input type="number" id="sa-el-rent" value="${p.rent}"></div>
    <div class="form-group"><label>Area</label><input type="text" id="sa-el-area" value="${escAttr(p.area)}"></div>
    <div class="form-group"><label>Address</label><input type="text" id="sa-el-address" value="${escAttr(p.address||'')}"></div>
    <div class="form-group"><label>Description</label><textarea id="sa-el-desc" style="min-height:80px;">${escHtml(p.description||p.desc||'')}</textarea></div>
    <div class="form-group"><label>Status</label>
      <select id="sa-el-status">
        <option value="approved" ${p.status==='approved'||!p.status?'selected':''}>Live</option>
        <option value="pending"  ${p.status==='pending'?'selected':''}>Pending</option>
        <option value="rejected" ${p.status==='rejected'?'selected':''}>Rejected</option>
      </select>
    </div>
  `, () => {
    const props = getProps();
    const idx   = props.findIndex(x => x.id === id);
    if (idx === -1) return;
    const old = props[idx].title;
    props[idx].title       = document.getElementById('sa-el-title').value.trim() || props[idx].title;
    props[idx].rent        = Number(document.getElementById('sa-el-rent').value) || props[idx].rent;
    props[idx].area        = document.getElementById('sa-el-area').value.trim()    || props[idx].area;
    props[idx].address     = document.getElementById('sa-el-address').value.trim();
    props[idx].description = document.getElementById('sa-el-desc').value.trim();
    props[idx].desc        = props[idx].description;
    props[idx].status      = document.getElementById('sa-el-status').value;
    saveProps(props);
    saLog('update','Listing edited by admin',`"${old}" → "${props[idx].title}"`, 'superadmin');
    saRenderListings(); refreshAllGrids();
    showToast('Listing updated!','success');
  });
}

function saDeleteListing(id) {
  const p = getProps().find(x => x.id === id);
  if (!confirm(`Delete "${p?.title||'this listing'}" permanently?`)) return;
  saveProps(getProps().filter(x => x.id !== id));
  saLog('delete','Listing deleted',`"${p?.title||id}"`, 'superadmin');
  saRenderListings(); renderAdminStats(); refreshAllGrids();
  showToast('Listing deleted.','error');
}

function saOpenCreateListing() {
  const users = getUsers();
  const userOpts = users.map(u => `<option value="${escAttr(u.id)}">${escHtml(u.name)} (${escHtml(u.email || u.phone || '')})</option>`).join('');
  saOpenModal('➕ Post Listing (on behalf of landlord)', `
    <div class="form-group"><label>Landlord</label>
      <select id="sa-nl-landlord">${userOpts.length ? userOpts : '<option value="">No landlords yet</option>'}</select>
    </div>
    <div class="form-group"><label>Title</label><input type="text" id="sa-nl-title" placeholder="e.g. 3 Bedroom House in Gerehu"></div>
    <div class="form-group"><label>Type</label>
      <select id="sa-nl-type">
        <option value="apartment">Apartment</option><option value="house">House</option>
        <option value="land">Land</option><option value="office">Office</option>
      </select>
    </div>
    <div class="form-group"><label>Rent (K/week)</label><input type="number" id="sa-nl-rent" placeholder="800"></div>
    <div class="form-group"><label>Area</label><input type="text" id="sa-nl-area" placeholder="Gerehu, NCD"></div>
    <div class="form-group"><label>Address <span style="color:var(--grey);font-weight:400;">(optional)</span></label><input type="text" id="sa-nl-address" placeholder="Lot 12, Stage 3"></div>
    <div class="form-group"><label>Description</label><textarea id="sa-nl-desc" style="min-height:70px;"></textarea></div>
  `, () => {
    const landlordId = document.getElementById('sa-nl-landlord').value;
    const title  = document.getElementById('sa-nl-title').value.trim();
    const rent   = Number(document.getElementById('sa-nl-rent').value);
    const area   = document.getElementById('sa-nl-area').value.trim();
    if (!title || !rent || !area) { showToast('Title, rent and area are required.','error'); return; }
    const u = users.find(x => x.id === landlordId) || {};
    const props = getProps();
    const newProp = {
      id: 'p_'+Date.now(), landlordId, landlordName: u.name||'Admin',
      landlordPhone: u.phone||'', title, rent, area,
      address: document.getElementById('sa-nl-address').value.trim(),
      description: document.getElementById('sa-nl-desc').value.trim(),
      desc: document.getElementById('sa-nl-desc').value.trim(),
      type: document.getElementById('sa-nl-type').value,
      country: u.country||'Papua New Guinea', countryCode: u.countryCode||'PG',
      status: 'approved', date: Date.now(), publishedAt: Date.now(), liveState: 'live', images: [], postedByAdmin: true
    };
    props.push(newProp);
    saveProps(props);
    saLog('create','Listing posted by admin',`"${title}" for ${u.name||landlordId}`,'superadmin');
    saRenderListings(); renderAdminStats(); refreshAllGrids();
    showToast('Listing posted!','success');
  });
}

function saBulkApproveAll() {
  const props = getProps();
  let count = 0;
  props.forEach(p => { if (p.status === 'pending') { p.status = 'approved'; if (!p.publishedAt) p.publishedAt = Date.now(); count++; } });
  saveProps(props);
  saLog('update',`Bulk approved ${count} listings`,'','superadmin');
  saRenderListings(); refreshAllGrids();
  showToast(`${count} listings approved!`,'success');
}

// ──────────────────────────────────────────────
// IMPERSONATION
// ──────────────────────────────────────────────
function saImpersonate(userId) {
  const u = getUsers().find(x => x.id === userId);
  if (!u) return;
  if (!confirm(`Log in as "${u.name}" for support? You can exit via the purple bar at the bottom.`)) return;
  _saImpersonating = u;
  currentUser = { id:u.id, name:u.name, email:u.email||'', phone:u.phone||'', area:u.area||'', province:u.province||'', country:u.country||'', countryCode:u.countryCode||'PG', accountType:u.accountType||null, ...(u.companyName ? { companyName:u.companyName } : {}) };
  _SS.setItem('pom_session', JSON.stringify(currentUser));
  document.getElementById('sa-impersonate-bar').classList.add('active');
  document.getElementById('sa-impersonate-name').textContent = u.name;
  saLog('login', 'Admin impersonated landlord', `${u.name} (${u.phone})`, 'superadmin');
  closeModal('auth-modal');
  setLoggedInNav();
  showPage('dashboard');
  showToast(`🎭 Viewing as ${u.name}. Exit via the purple bar.`, 'success');
}

function saExitImpersonation() {
  _saImpersonating = null;
  currentUser = null;
  _SS.removeItem('pom_session');
  document.getElementById('sa-impersonate-bar').classList.remove('active');
  saLog('login','Admin exited impersonation','', 'superadmin');
  setLoggedOutNav();
  showPage('home');
  // Re-open admin
  setTimeout(() => showAdminPage(), 400);
  showToast('Returned to Super Admin.', 'success');
}

// ──────────────────────────────────────────────
// BULK ACTIONS
// ──────────────────────────────────────────────
function saBulkExport(type) {
  let rows, headers;
  if (type === 'landlords') {
    const susp = getSuspended();
    headers = 'Name,Email,Phone,Country,Province,Area,Status,Listings';
    const props = getProps();
    rows = getUsers().map(u => {
      const lc = props.filter(p => p.landlordId===u.id).length;
      return [u.name, u.email||'', u.phone||'', u.country||'PNG', u.province||'', u.area||'',
              susp.includes(u.id)?'Suspended':'Active', lc].map(v => '"'+String(v).replace(/"/g,'""')+'"').join(',');
    });
  } else {
    headers = 'Title,Type,Rent,Area,Country,Landlord,Status,Featured,Date';
    rows = getProps().map(p => {
      const d = new Date(p.date).toLocaleDateString();
      return [p.title, p.type, p.rent, p.area, p.country||'PNG', p.landlordName||'',
              p.hidden?'Hidden':(p.status||'approved'), p.featured?'Yes':'No', d]
              .map(v => '"'+String(v).replace(/"/g,'""')+'"').join(',');
    });
  }
  const blob = new Blob([[headers, ...rows].join('\n')], {type:'text/csv'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = `wampac-${type}-export.csv`; a.click(); URL.revokeObjectURL(a.href);
  showToast('CSV exported!','success');
}

function saBulkAction(entity, action) {
  if (!confirm(`Apply "${action}" to all selected ${entity}?`)) return;
  showToast(`Bulk ${action} applied.`, action==='restore'?'success':'error');
}

// ──────────────────────────────────────────────
// COMMUNICATIONS
// ──────────────────────────────────────────────
let _saAnnounceTarget = 'all';

function saSelectTarget(t, btn) {
  _saAnnounceTarget = t;
  document.querySelectorAll('.sa-notif-target-row .sa-target-chip').forEach(c => c.classList.remove('active'));
  btn.classList.add('active');
}

function saAnnounceBannerColor(color, btn) {
  _saAnnounceBannerColor = color;
  document.querySelectorAll('.sa-notif-composer button[onclick^="saAnnounceBannerColor"]').forEach(b => b.style.outline = 'none');
  btn.style.outline = '3px solid #1a1a2e';
}

function saPublishAnnouncement() {
  const title = (document.getElementById('sa-announce-title')?.value || '').trim();
  const body  = (document.getElementById('sa-announce-body')?.value  || '').trim();
  if (!body) { showToast('Please write a message.','error'); return; }
  const text = title ? `${title}: ${body}` : body;
  _LS.setItem(LS_ANNOUNCE, text);
  // Change banner color
  const banner = document.getElementById('announce-banner');
  if (banner) banner.style.background = _saAnnounceBannerColor;
  showAnnouncementBanner(text);
  // Save to history
  const hist = JSON.parse(_LS.getItem(LS_ANNOUNCE_HISTORY)||'[]');
  hist.unshift({ text, target: _saAnnounceTarget, color: _saAnnounceBannerColor, ts: Date.now() });
  if (hist.length > 50) hist.length = 50;
  _LS.setItem(LS_ANNOUNCE_HISTORY, JSON.stringify(hist));
  saLog('system','Announcement published',`Target: ${_saAnnounceTarget} — "${text.slice(0,60)}"`, 'superadmin');
  saRenderAnnounceHistory();
  showToast('Announcement published! ✅','success');
}

function saClearAnnouncement() {
  _LS.removeItem(LS_ANNOUNCE);
  document.getElementById('announce-banner')?.classList.remove('visible');
  if (document.getElementById('sa-announce-title')) document.getElementById('sa-announce-title').value = '';
  if (document.getElementById('sa-announce-body'))  document.getElementById('sa-announce-body').value  = '';
  saLog('system','Announcement cleared','','superadmin');
  showToast('Banner cleared.','success');
}

function saScheduleAnnouncement() {
  showToast('Schedule feature: integrate with a backend cron/API for full scheduling support.','success');
}

function saRenderAnnounceHistory() {
  const el = document.getElementById('sa-announce-history');
  if (!el) return;
  const hist = JSON.parse(_LS.getItem(LS_ANNOUNCE_HISTORY)||'[]');
  if (!hist.length) { el.innerHTML = '<div style="text-align:center;padding:18px;color:var(--grey);">No announcements sent yet.</div>'; return; }
  el.innerHTML = hist.slice(0,20).map(h => {
    const d = new Date(h.ts);
    return `<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #f1f5f9;flex-wrap:wrap;">
      <div style="width:12px;height:12px;border-radius:3px;background:${h.color||'#137A82'};flex-shrink:0;"></div>
      <div style="flex:1;min-width:0;"><div style="font-size:0.82rem;font-weight:600;color:#1a1a2e;">${escHtml(h.text.slice(0,80))}${h.text.length>80?'…':''}</div>
      <div style="font-size:0.72rem;color:#6b7280;">Audience: ${h.target} · ${d.toLocaleDateString()} ${d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</div></div>
    </div>`;
  }).join('');
}

function saSelectNotifTarget(t, btn) {
  _saNotifTarget = t;
  const row = btn.closest('.sa-notif-target-row');
  row.querySelectorAll('.sa-target-chip').forEach(c => c.classList.remove('active'));
  btn.classList.add('active');
  const f = document.getElementById('sa-notif-user-field');
  if (f) f.style.display = t === 'single' ? 'block' : 'none';
}

function saSendNotification() {
  const msg  = (document.getElementById('sa-notif-msg')?.value||'').trim();
  const type = document.getElementById('sa-notif-type')?.value || 'info';
  if (!msg) { showToast('Please enter a message.','error'); return; }
  // Store in _LS for real-time retrieval
  const notifs = JSON.parse(_LS.getItem(LS_NOTIFS)||'[]');
  notifs.unshift({ id:'n_'+Date.now(), msg, type, target:_saNotifTarget, ts:Date.now(), read:false });
  if (notifs.length > 200) notifs.length = 200;
  _LS.setItem(LS_NOTIFS, JSON.stringify(notifs));
  saLog('system',`In-app notification sent`,`Target: ${_saNotifTarget} — "${msg.slice(0,60)}"`, 'superadmin');
  showToast(`Notification sent (${type}): "${msg.slice(0,40)}"`, type==='error'?'error':'success');
  if (document.getElementById('sa-notif-msg')) document.getElementById('sa-notif-msg').value = '';
}

