const SA_ALL_PERMISSIONS = [
  { id:'view_landlords',   label:'View Landlord Accounts',    desc:'See the landlords list' },
  { id:'edit_landlords',   label:'Edit Landlord Accounts',    desc:'Modify landlord profiles' },
  { id:'suspend_users',    label:'Suspend / Restore Users',   desc:'Disable or enable accounts' },
  { id:'delete_users',     label:'Delete User Accounts',      desc:'Permanently remove accounts' },
  { id:'reset_passwords',  label:'Reset Passwords',           desc:'Force password changes' },
  { id:'impersonate',      label:'Impersonate Accounts',      desc:'Log in as any landlord' },
  { id:'view_listings',    label:'View All Listings',         desc:'Browse all listings' },
  { id:'edit_listings',    label:'Edit Listings',             desc:'Modify any listing' },
  { id:'approve_listings', label:'Approve / Reject Listings', desc:'Control listing visibility' },
  { id:'delete_listings',  label:'Delete Listings',           desc:'Permanently remove listings' },
  { id:'feature_listings', label:'Feature / Hide Listings',   desc:'Promote or hide listings' },
  { id:'view_payments',    label:'View Payments',             desc:'See all transactions' },
  { id:'manage_payments',  label:'Manage Payments',           desc:'Approve, reject, refund' },
  { id:'manage_pricing',   label:'Manage Pricing',            desc:'Change plan prices' },
  { id:'moderation',       label:'Content Moderation',        desc:'Remove images & flag content' },
  { id:'send_announcements',label:'Send Announcements',       desc:'Publish banners & notifications' },
  { id:'site_controls',    label:'Site Controls',             desc:'Toggle payment, maintenance etc.' },
  { id:'style_editor',     label:'Style Editor',              desc:'Change site appearance' },
  { id:'view_audit',       label:'View Audit Log',            desc:'See system event history' },
  { id:'manage_areas',     label:'Manage Areas',              desc:'Add/remove location areas' },
];

const SA_DEFAULT_ROLES = {
  moderator: ['view_landlords','view_listings','moderation','send_announcements','view_audit'],
  manager:   ['view_landlords','edit_landlords','suspend_users','view_listings','edit_listings','approve_listings','feature_listings','view_payments','manage_payments','send_announcements','view_audit'],
  support:   ['view_landlords','reset_passwords','view_listings','view_payments'],
  finance:   ['view_payments','manage_payments','manage_pricing','view_listings','view_audit'],
  listing_approver: ['view_listings','approve_listings','feature_listings','view_landlords'],
  compliance: ['view_listings','moderation','view_landlords','view_audit'],
  auditor:   ['view_landlords','view_listings','view_payments','view_audit'],
};

const SA_ROLE_META = {
  moderator:        { label:'Moderator',                  icon:'🛡️' },
  manager:          { label:'Manager',                    icon:'📊' },
  support:          { label:'Support',                    icon:'🎧' },
  finance:          { label:'Finance Verifier',            icon:'💳' },
  listing_approver: { label:'Listing Approver',            icon:'✅' },
  compliance:       { label:'Content/Compliance Officer',  icon:'📋' },
  auditor:          { label:'Read-Only Auditor',           icon:'🔎' },
};

function saGetRoles() {
  try { return JSON.parse(_LS.getItem(LS_RBAC)||'null') || { ...SA_DEFAULT_ROLES }; } catch(e) { return { ...SA_DEFAULT_ROLES }; }
}
function saSaveRoles(roles) { _LS.setItem(LS_RBAC, JSON.stringify(roles)); }

// ── RBAC: check if the currently-logged-in admin has a given permission ──
// Super Admin (currentAdminAccount === null) always returns true.
// Pass null as permId to mean "super admin only" — always false for sub-admins.
function adminHasPerm(permId) {
  if (!currentAdminAccount) return true;          // Super Admin — full access
  if (permId === null)       return false;         // Explicitly super-admin-only
  const roles = saGetRoles();
  const myPerms = roles[currentAdminAccount.role] || [];
  return myPerms.includes(permId);
}

// Maps each admin tab key → the permission required to see/use it.
// null means super-admin only (no sub-admin ever gets it regardless of RBAC).
const TAB_PERMISSIONS = {
  overview:    'view_listings',     // basic stats — anyone with view_listings can see
  landlords:   'view_landlords',
  listings:    'view_listings',
  payments:    'view_payments',
  moderation:  'moderation',
  support:     'view_landlords',    // support agents need landlord context
  comms:       'send_announcements',
  controls:    null,                // super admin only
  areas:       'manage_areas',
  styleeditor: null,                // super admin only
  access:      null,                // super admin only — account/credential management
  audit:       'view_audit',
  settings:    null,                // super admin only (contains credentials/danger zone)
  wizard:      null,                // super admin only
};

function saSelectRoleEditor(role, btn) {
  _saCurrentRole = role;
  document.querySelectorAll('#sa-role-selector .sa-target-chip').forEach(c => c.classList.remove('active'));
  btn.classList.add('active');
  saRenderPermGrid();
}

function saRenderPermGrid() {
  const grid = document.getElementById('sa-perm-grid');
  if (!grid) return;
  const roles = saGetRoles();
  const perms = roles[_saCurrentRole] || [];
  grid.innerHTML = SA_ALL_PERMISSIONS.map(p => `
    <div class="sa-perm-row">
      <div>
        <label><input type="checkbox" id="perm-${p.id}" ${perms.includes(p.id)?'checked':''} onchange="saTogglePermCheck('${p.id}')"> ${p.label}</label>
        <div class="sa-perm-desc">${p.desc}</div>
      </div>
    </div>
  `).join('');
}

function saTogglePermCheck(permId) {}  // Just read on save

function saSaveRolePermissions() {
  if (!adminHasPerm(null)) { showToast('⛔ Only the Super Admin can modify role permissions.', 'error'); return; }
  const roles = saGetRoles();
  roles[_saCurrentRole] = SA_ALL_PERMISSIONS
    .filter(p => document.getElementById('perm-'+p.id)?.checked)
    .map(p => p.id);
  saSaveRoles(roles);
  saLog('system',`Role permissions updated`,`Role: ${_saCurrentRole}`, 'superadmin');
  showToast(`${_saCurrentRole} permissions saved!`, 'success');
}

// ──────────────────────────────────────────────
// ADMIN ACCOUNTS
// ──────────────────────────────────────────────
function saGetAdminAccounts() {
  try { return JSON.parse(_LS.getItem(LS_ADMINS)||'[]'); } catch(e) { return []; }
}

function saRenderAdminAccounts() {
  const el = document.getElementById('sa-admin-accounts-list');
  if (!el) return;
  // ── RBAC: Access & RBAC panel is Super Admin only ──
  if (!adminHasPerm(null)) {
    el.innerHTML = `<div style="padding:32px;text-align:center;color:#64748b;font-size:0.9rem;">
      🔒 Admin account management is restricted to the Super Admin.
    </div>`;
    return;
  }
  const accounts = saGetAdminAccounts();
  const creds    = getAdminCreds();
  const superName = creds ? creds.username : ADMIN_DEFAULT_USER;

  let html = `<div class="sa-admin-card">
    <div class="sa-admin-avatar">👑</div>
    <div class="sa-admin-info">
      <div class="sa-admin-name">${escHtml(superName)}</div>
      <div class="sa-admin-role">Super Admin · Full Control · Cannot be restricted</div>
    </div>
    <div class="sa-admin-actions"><span class="sa-role-badge">👑 Super Admin</span></div>
  </div>`;

  accounts.forEach(a => {
    const rm = SA_ROLE_META[a.role] || { label: a.role || 'moderator', icon: '🛡️' };
    html += `<div class="sa-admin-card">
      <div class="sa-admin-avatar" style="background:linear-gradient(135deg,#1a73e8,#0d47a1);">${rm.icon}</div>
      <div class="sa-admin-info">
        <div class="sa-admin-name">${escHtml(a.username)}</div>
        <div class="sa-admin-role">Role: <strong>${escHtml(rm.label)}</strong> · Created ${new Date(a.created||Date.now()).toLocaleDateString()}</div>
      </div>
      <div class="sa-admin-actions">
        <span class="sa-role-badge role-admin">${escHtml(rm.label)}</span>
        <button class="sa-btn edit" onclick="saEditAdminAccount('${a.id}')"><span class="wi-svg" data-lucide="pencil" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✏️</span> Edit</button>
        <button class="sa-btn danger" onclick="saDeleteAdminAccount('${a.id}')">🗑 Remove</button>
      </div>
    </div>`;
  });

  el.innerHTML = html;
  wiRender();
}

function saOpenCreateAdmin() {
  // ── RBAC: Only Super Admin can create admin accounts / set credentials ──
  if (!adminHasPerm(null)) { showToast('⛔ Only the Super Admin can create admin accounts.', 'error'); return; }
  saOpenModal('➕ Create Admin Account', `
    <div class="form-group"><label>Username</label><input type="text" id="sa-ca-user" placeholder="e.g. moderator1" autocomplete="off"></div>
    <div class="form-group"><label>Password</label><input type="password" id="sa-ca-pw" placeholder="Min 8 characters"></div>
    <div class="form-group"><label>Role</label>
      <select id="sa-ca-role">
        ${Object.keys(SA_ROLE_META).map(r => `<option value="${r}">${SA_ROLE_META[r].icon} ${SA_ROLE_META[r].label}</option>`).join('')}
      </select>
    </div>
    <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:10px 14px;font-size:0.78rem;color:#92400e;margin-top:4px;">
      ⚠️ Admin accounts can only log in through direct _LS access in this demo. Full multi-admin login requires a backend.
    </div>
  `, () => {
    const username = document.getElementById('sa-ca-user').value.trim();
    const pw       = document.getElementById('sa-ca-pw').value;
    const role     = document.getElementById('sa-ca-role').value;
    if (!username) { showToast('Username required.','error'); return; }
    if (!pw || pw.length < 8) { showToast('Password must be at least 8 characters.','error'); return; }
    const accounts = saGetAdminAccounts();
    if (accounts.find(a => a.username === username)) { showToast('Username already exists.','error'); return; }
    accounts.push({ id:'adm_'+Date.now(), username, hash: hashish(pw), role, created: Date.now() });
    _LS.setItem(LS_ADMINS, JSON.stringify(accounts));
    saLog('create','Admin account created',`${username} (${role})`, 'superadmin');
    saRenderAdminAccounts();
    showToast('Admin account created!','success');
  });
}

function saEditAdminAccount(id) {
  if (!adminHasPerm(null)) { showToast('⛔ Only the Super Admin can edit admin accounts.', 'error'); return; }
  const accounts = saGetAdminAccounts();
  const a = accounts.find(x => x.id === id);
  if (!a) return;
  saOpenModal('✏️ Edit Admin Account', `
    <div class="form-group"><label>Username</label><input type="text" id="sa-ea-user" value="${escAttr(a.username)}"></div>
    <div class="form-group"><label>New Password (leave blank to keep current)</label><input type="password" id="sa-ea-pw" placeholder="Leave blank to keep"></div>
    <div class="form-group"><label>Role</label>
      <select id="sa-ea-role">
        ${Object.keys(SA_ROLE_META).map(r => `<option value="${r}" ${a.role===r?'selected':''}>${SA_ROLE_META[r].icon} ${SA_ROLE_META[r].label}</option>`).join('')}
      </select>
    </div>
  `, () => {
    const idx = accounts.findIndex(x => x.id === id);
    accounts[idx].username = document.getElementById('sa-ea-user').value.trim() || accounts[idx].username;
    accounts[idx].role     = document.getElementById('sa-ea-role').value;
    const pw = document.getElementById('sa-ea-pw').value;
    if (pw && pw.length >= 8) accounts[idx].hash = hashish(pw);
    _LS.setItem(LS_ADMINS, JSON.stringify(accounts));
    saLog('update','Admin account updated',`${accounts[idx].username}`, 'superadmin');
    saRenderAdminAccounts();
    showToast('Admin account updated!','success');
  });
}

function saDeleteAdminAccount(id) {
  if (!adminHasPerm(null)) { showToast('⛔ Only the Super Admin can remove admin accounts.', 'error'); return; }
  if (!confirm('Remove this admin account?')) return;
  const accounts = saGetAdminAccounts().filter(a => a.id !== id);
  _LS.setItem(LS_ADMINS, JSON.stringify(accounts));
  saLog('delete','Admin account removed','', 'superadmin');
  saRenderAdminAccounts();
  showToast('Admin account removed.','error');
}

// ──────────────────────────────────────────────
// CONTENT MODERATION
// ──────────────────────────────────────────────
function saLoadModerationImages() {
  const container = document.getElementById('sa-mod-images-list');
  if (!container) return;
  const props = getProps().filter(p => p.images && p.images.length > 0);
  if (!props.length) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--grey);">No listing images found.</div>';
    return;
  }
  let html = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px;">`;
  props.forEach(p => {
    p.images.slice(0,3).forEach((img, i) => {
      html += `<div class="sa-mod-card" style="flex-direction:column;padding:0;overflow:hidden;">
        <img src="${img}" style="width:100%;height:140px;object-fit:cover;" onerror="this.style.display='none'">
        <div style="padding:10px 12px;">
          <div class="sa-mod-title">${escHtml(p.title)}</div>
          <div class="sa-mod-sub">Image ${i+1} · ${escHtml(p.landlordName||'—')}</div>
          <div style="display:flex;gap:6px;margin-top:8px;">
            <button class="sa-btn restore" onclick="showToast('Image approved.','success')"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Approve</button>
            <button class="sa-btn danger"  onclick="saRemoveListingImage('${p.id}',${i})">🗑 Remove</button>
          </div>
        </div>
      </div>`;
    });
  });
  html += '</div>';
  container.innerHTML = html;
}

function saRemoveListingImage(propId, idx) {
  if (!confirm('Remove this image from the listing?')) return;
  const props = getProps();
  const p     = props.find(x => x.id === propId);
  if (!p || !p.images) return;
  const removed = p.images.splice(idx, 1);
  saveProps(props);
  saLog('delete','Listing image removed by admin',`Listing: "${p.title}" image ${idx}`, 'superadmin');
  saLoadModerationImages();
  refreshAllGrids();
  showToast('Image removed.','error');
}

// ──────────────────────────────────────────────
// MODAL HELPER
// ──────────────────────────────────────────────
let _saModalCallback = null;

function saOpenModal(title, bodyHTML, onConfirm) {
  _saModalCallback = onConfirm;
  let overlay = document.getElementById('sa-global-modal');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'sa-global-modal';
    overlay.className = 'sa-modal-overlay';
    overlay.innerHTML = `<div class="sa-modal">
      <div class="sa-modal-head">
        <h3 id="sa-modal-title"></h3>
        <button class="sa-modal-close" onclick="saCloseModal()">✕</button>
      </div>
      <div class="sa-modal-body" id="sa-modal-body"></div>
      <div class="sa-modal-foot">
        <button class="btn" style="background:#f1f5f9;color:#374151;" onclick="saCloseModal()">Cancel</button>
        <button class="btn btn-teal" onclick="saModalConfirm()"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Confirm</button>
      </div>
    </div>`;
    overlay.addEventListener('click', e => { if (e.target === overlay) saCloseModal(); });
    document.body.appendChild(overlay);
  }
  document.getElementById('sa-modal-title').textContent = title;
  document.getElementById('sa-modal-body').innerHTML = bodyHTML;
  overlay.classList.add('open');
}

function saCloseModal() {
  const overlay = document.getElementById('sa-global-modal');
  if (overlay) overlay.classList.remove('open');
  _saModalCallback = null;
}

function saModalConfirm() {
  if (_saModalCallback) _saModalCallback();
  // Don't auto-close — let callback decide
  const overlay = document.getElementById('sa-global-modal');
  if (overlay) overlay.classList.remove('open');
}

