function saSubTab(group, panel, btn) {
  const parentTab = btn.closest('.adm-tab-panel');
  parentTab.querySelectorAll('.sa-subtab').forEach(t => t.classList.remove('active'));
  parentTab.querySelectorAll('.sa-subpanel').forEach(p => p.classList.remove('active'));
  btn.classList.add('active');
  const el = document.getElementById(`sa-${group}-subpanel-${panel}`);
  if (el) el.classList.add('active');
}

