// ──────────────────────────────────────────────
// PAYMENT MANAGEMENT (Super Admin)
// ──────────────────────────────────────────────
function saRenderPayments() {
  const listEl  = document.getElementById('adm-payments-list');
  if (!listEl) return;

  const query  = (document.getElementById('sa-pay-search')?.value  || '').toLowerCase();
  const statusF = document.getElementById('sa-pay-status-filter')?.value || 'all';

  let pays = JSON.parse(_LS.getItem(LS_PAYMENTS) || '[]');

  if (query)   pays = pays.filter(p =>
    (p.landlordName||'').toLowerCase().includes(query) ||
    (p.ref||p.id||'').toLowerCase().includes(query)
  );
  if (statusF !== 'all') pays = pays.filter(p => p.status === statusF);

  const allPays = JSON.parse(_LS.getItem(LS_PAYMENTS) || '[]');
  saSetEl('sa-pay-total',    allPays.length);
  saSetEl('sa-pay-pending',  allPays.filter(p => p.status==='pending').length);
  saSetEl('sa-pay-approved', allPays.filter(p => p.status==='approved').length);
  const revenue = allPays.filter(p=>p.status==='approved').reduce((s,p)=>s+(Number(p.amount)||0),0);
  saSetEl('sa-pay-revenue',  'K' + revenue.toLocaleString());

  if (!pays.length) {
    listEl.innerHTML = '<div style="text-align:center;padding:28px;color:var(--grey);">No transactions found.</div>';
    return;
  }

  const STATUS_PILLS = {
    pending:  '<span class="pill pill-yellow">⏳ Pending</span>',
    approved: '<span class="pill pill-green">✅ Approved</span>',
    rejected: '<span class="pill pill-red">❌ Rejected</span>',
    refunded: '<span class="pill pill-purple">↩️ Refunded</span>',
  };

  listEl.innerHTML = `<div class="admin-table-wrap"><table class="sa-table">
    <thead><tr><th>Landlord</th><th>Plan</th><th>Amount</th><th>Reference</th><th>Date</th><th>Status</th><th>Receipt</th><th>Actions</th></tr></thead>
    <tbody>` + pays.map(p => {
    const d = new Date(p.ts||p.date||Date.now()).toLocaleDateString();
    const receiptSrc = getReceipt(p);
    const receiptCell = receiptSrc
      ? `<img src="${receiptSrc}" alt="Receipt" style="width:48px;height:48px;object-fit:cover;border-radius:6px;border:1px solid var(--grey-light);cursor:pointer;" onclick="viewReceiptByKey('${escAttr(p.receiptKey||'')}','${escAttr(p.receipt||'')}','${escAttr(p.landlordName)} – K${p.amount}')">`
      : (p.hasReceipt
          ? `<span style="font-size:0.7rem;color:#854d0e;">⚠️ unavailable</span>`
          : `<span style="font-size:0.7rem;color:var(--grey);">—</span>`);
    return `<tr>
      <td><div style="font-weight:700;">${escHtml(p.landlordName||'—')}</div><div style="font-size:0.72rem;color:#6b7280;">${escHtml(p.landlordPhone||'')}</div></td>
      <td><span class="pill pill-blue">${escHtml(p.plan||'—')}</span></td>
      <td style="font-weight:700;color:var(--teal);">${p.currency==='USD'?'$':'K'}${Number(p.amount).toLocaleString()}</td>
      <td style="font-family:monospace;font-size:0.78rem;">${escHtml(p.ref||p.id||'—')}</td>
      <td style="font-size:0.78rem;color:#6b7280;">${d}</td>
      <td>${STATUS_PILLS[p.status]||STATUS_PILLS.pending}</td>
      <td>${receiptCell}</td>
      <td>
        <div class="sa-actions-cell">
          ${p.status==='pending'?`
            <button class="sa-btn approve" onclick="saApprovePayment('${p.id}')"><span class="wi-svg" data-lucide="check-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Approve</button>
            <button class="sa-btn reject"  onclick="saRejectPayment('${p.id}')"><span class="wi-svg" data-lucide="x-circle" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">❌</span> Reject</button>
          `:''}
          ${p.status==='approved'?`<button class="sa-btn" style="background:#ede9fe;color:#7c3aed;" onclick="saRefundPayment('${p.id}')">↩️ Refund</button>`:''}
          <button class="sa-btn danger" onclick="saDeletePayment('${p.id}')"><span class="wi-svg" data-lucide="trash-2" style="width:13px;height:13px;vertical-align:middle;"></span><span class="wi-emoji">🗑</span></button>
        </div>
      </td>
    </tr>`;
  }).join('') + `</tbody></table></div>`;
  wiRender();
}

function saApprovePayment(id) {
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const p = pays.find(x => x.id === id);
  if (!p) return;
  p.status = 'approved';
  p.adminNote = 'Approved by Super Admin';
  p.approvedAt = Date.now();
  p.reviewedAt = Date.now();
  resumePlanClock(p); // start this plan's billing clock now that it's going live
  _LS.setItem(LS_PAYMENTS, JSON.stringify(pays));
  // Also approve the linked listing (payment records store the listing id as `listingId`, not `propId`)
  const props = getProps();
  const prop  = props.find(x => x.id === p.listingId);
  if (prop) { prop.status = 'approved'; prop.paymentStatus = 'approved'; prop.liveState = 'live'; resetListingOnGoLive(prop); saveProps(props); }
  saLog('update', 'Payment approved by admin', `Ref: ${p.ref||id} · ${p.landlordName||''}`, 'superadmin');
  saRenderPayments(); renderAdminStats(); refreshAllGrids();
  showToast('Payment approved!', 'success');
}

function saRejectPayment(id) {
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const p = pays.find(x => x.id === id);
  if (!p) return;
  p.status = 'rejected';
  p.adminNote = 'Rejected by Super Admin';
  p.reviewedAt = Date.now();
  _LS.setItem(LS_PAYMENTS, JSON.stringify(pays));
  const props = getProps();
  const prop  = props.find(x => x.id === p.listingId);
  if (prop) {
    if (p.isReactivation) {
      // Reactivation rejected — listing already existed, just stays offline.
      prop.liveState = 'off';
    } else {
      prop.status = 'rejected';
      prop.paymentStatus = 'rejected';
    }
    saveProps(props);
  }
  saLog('update', 'Payment rejected by admin', `Ref: ${p.ref||id}`, 'superadmin');
  saRenderPayments(); renderAdminStats();
  showToast('Payment rejected.', 'error');
}

function saRefundPayment(id) {
  if (!confirm('Issue a refund for this payment? The listing will be set back to Pending.')) return;
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const p = pays.find(x => x.id === id);
  if (!p) return;
  p.status = 'refunded';
  p.adminNote = 'Refunded by Super Admin';
  p.refundedAt = Date.now();
  _LS.setItem(LS_PAYMENTS, JSON.stringify(pays));
  const props = getProps();
  const prop  = props.find(x => x.id === p.listingId);
  if (prop) { prop.status = 'pending'; prop.paymentStatus = 'pending'; saveProps(props); }
  saLog('update', 'Payment refunded', `Ref: ${p.ref||id} · ${p.landlordName||''}`, 'superadmin');
  saRenderPayments(); renderAdminStats(); refreshAllGrids();
  showToast('Refund issued.', 'success');
}

function saDeletePayment(id) {
  if (!confirm('Delete this payment record? Cannot be undone.')) return;
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]').filter(x => x.id !== id);
  _LS.setItem(LS_PAYMENTS, JSON.stringify(pays));
  saLog('delete', 'Payment record deleted', id, 'superadmin');
  saRenderPayments();
  showToast('Payment record deleted.', 'error');
}

function saExportPayments() {
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const headers = 'ID,Landlord,Phone,Plan,Amount,Currency,Reference,Status,Date';
  const rows = pays.map(p => {
    const d = new Date(p.ts||p.date||Date.now()).toLocaleDateString();
    return [p.id, p.landlordName||'', p.landlordPhone||'', p.plan||'', p.amount||0,
            p.currency||'PGK', p.ref||'', p.status||'pending', d]
           .map(v => '"'+String(v).replace(/"/g,'""')+'"').join(',');
  });
  const blob = new Blob([[headers,...rows].join('\n')],{type:'text/csv'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = 'wampac-payments-export.csv'; a.click(); URL.revokeObjectURL(a.href);
  showToast('Payments exported!', 'success');
}

// ── FINANCIAL REPORT ──────────────────────────────────────────────────────────
function saGetFinData(yearFilter) {
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const approved = pays.filter(p => p.status === 'approved');
  const refunded = pays.filter(p => p.status === 'refunded');

  const monthlyMap = {}; // key: "YYYY-MM"
  function ensureMonth(key) {
    if (!monthlyMap[key]) monthlyMap[key] = { gross: 0, refunded: 0, txCount: 0, refCount: 0 };
  }

  approved.forEach(p => {
    const d = new Date(p.ts || p.date || Date.now());
    const yr = d.getFullYear(); const mo = String(d.getMonth()+1).padStart(2,'0');
    if (yearFilter && yearFilter !== 'all' && String(yr) !== String(yearFilter)) return;
    const key = `${yr}-${mo}`;
    ensureMonth(key);
    monthlyMap[key].gross += Number(p.amount) || 0;
    monthlyMap[key].txCount += 1;
  });

  refunded.forEach(p => {
    const d = new Date(p.refundedAt || p.ts || p.date || Date.now());
    const yr = d.getFullYear(); const mo = String(d.getMonth()+1).padStart(2,'0');
    if (yearFilter && yearFilter !== 'all' && String(yr) !== String(yearFilter)) return;
    const key = `${yr}-${mo}`;
    ensureMonth(key);
    monthlyMap[key].refunded += Number(p.amount) || 0;
    monthlyMap[key].refCount += 1;
  });

  // Sort by date
  const sortedKeys = Object.keys(monthlyMap).sort();
  return sortedKeys.map(k => {
    const [yr, mo] = k.split('-');
    const d = new Date(Number(yr), Number(mo)-1, 1);
    const label = d.toLocaleString('default', { month: 'short', year: 'numeric' });
    const gross = monthlyMap[k].gross;
    const ref   = monthlyMap[k].refunded;
    return { key: k, label, yr: Number(yr), gross, refunded: ref, net: gross - ref, txCount: monthlyMap[k].txCount + monthlyMap[k].refCount };
  });
}

function saPopulateYearFilter() {
  const pays = JSON.parse(_LS.getItem(LS_PAYMENTS)||'[]');
  const years = [...new Set(pays.map(p => new Date(p.ts||p.date||Date.now()).getFullYear()))].sort((a,b)=>b-a);
  const sel = document.getElementById('fin-year-filter');
  if (!sel) return;
  // Keep "All Years" option, add year options if not already there
  const existing = new Set(Array.from(sel.options).map(o => o.value));
  years.forEach(y => {
    if (!existing.has(String(y))) {
      const opt = document.createElement('option');
      opt.value = y; opt.textContent = y;
      sel.appendChild(opt);
    }
  });
}

function saRenderFinReport() {
  saPopulateYearFilter();
  const yearFilter = document.getElementById('fin-year-filter')?.value || 'all';
  const rows = saGetFinData(yearFilter);

  // KPI strip
  const kpiEl = document.getElementById('fin-kpi-strip');
  if (kpiEl) {
    const totalGross = rows.reduce((s,r)=>s+r.gross,0);
    const totalNet   = rows.reduce((s,r)=>s+r.net,0);
    const totalRef   = rows.reduce((s,r)=>s+r.refunded,0);
    const totalTx    = rows.reduce((s,r)=>s+r.txCount,0);
    const bestMonth  = rows.length ? rows.reduce((best,r)=>r.net>best.net?r:best, rows[0]) : null;
    const kpis = [
      { icon:'💰', label:'Total Gross Income', val:`K${totalGross.toLocaleString()}`, color:'var(--teal)' },
      { icon:'✅', label:'Net Income', val:`K${totalNet.toLocaleString()}`, color:'#16a34a' },
      { icon:'↩️', label:'Total Refunded', val:`K${totalRef.toLocaleString()}`, color:'var(--coral)' },
      { icon:'🔢', label:'Total Transactions', val:totalTx, color:'#1a73e8' },
      { icon:'🏆', label:'Best Month', val: bestMonth ? bestMonth.label : '—', color:'var(--gold)' },
    ];
    kpiEl.innerHTML = kpis.map(k=>`
      <div style="background:var(--white);border-radius:12px;border:1.5px solid var(--grey-light);padding:16px 14px;">
        <div style="font-size:1.5rem;margin-bottom:6px;">${k.icon}</div>
        <div style="font-family:'Poppins',sans-serif;font-weight:800;font-size:1.15rem;color:${k.color};">${k.val}</div>
        <div style="font-size:0.72rem;color:var(--grey);font-weight:600;margin-top:3px;">${k.label}</div>
      </div>`).join('');
  }

  // Bar chart
  const chartEl = document.getElementById('fin-bar-chart');
  if (chartEl) {
    if (!rows.length) {
      chartEl.innerHTML = '<div style="color:var(--grey);font-size:0.85rem;width:100%;text-align:center;padding:40px 0;">No approved income data yet.</div>';
    } else {
      const maxNet = Math.max(...rows.map(r=>r.net), 1);
      chartEl.innerHTML = rows.map(r => {
        const pct = Math.max((r.net / maxNet) * 100, r.net > 0 ? 4 : 0);
        const color = r.net > 0 ? 'var(--teal)' : '#e5e7eb';
        return `<div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex:1;min-width:44px;max-width:64px;"
          title="${r.label}: K${r.net.toLocaleString()} net">
          <div style="font-size:0.64rem;font-weight:700;color:var(--teal);white-space:nowrap;">K${r.net>=1000?(r.net/1000).toFixed(1)+'k':r.net}</div>
          <div style="width:100%;background:${color};border-radius:5px 5px 0 0;height:${pct}%;min-height:${r.net>0?'6px':'2px'};transition:height 0.3s ease;"></div>
          <div style="font-size:0.62rem;color:var(--grey);white-space:nowrap;text-align:center;">${r.label}</div>
        </div>`;
      }).join('');
    }
  }

  // Table
  const tbody = document.getElementById('fin-report-tbody');
  const tfoot = document.getElementById('fin-report-tfoot');
  if (!tbody) return;

  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:28px;color:var(--grey);">No income data for the selected period.</td></tr>`;
    tfoot.innerHTML = '';
    return;
  }

  const totalGross = rows.reduce((s,r)=>s+r.gross,0);
  const totalNet   = rows.reduce((s,r)=>s+r.net,0);
  const totalRef   = rows.reduce((s,r)=>s+r.refunded,0);
  const totalTx    = rows.reduce((s,r)=>s+r.txCount,0);

  tbody.innerHTML = rows.map(r => {
    const sharePct = totalNet > 0 ? ((r.net / totalNet) * 100).toFixed(1) : '0.0';
    const shareWidth = totalNet > 0 ? Math.round((r.net / totalNet) * 80) : 0;
    return `<tr>
      <td style="font-weight:700;">${r.label}</td>
      <td style="text-align:center;">${r.txCount}</td>
      <td style="font-weight:600;color:var(--teal);">K${r.gross.toLocaleString()}</td>
      <td style="color:var(--coral);">${r.refunded > 0 ? '– K'+r.refunded.toLocaleString() : '<span style="color:var(--grey);">—</span>'}</td>
      <td style="font-weight:700;color:#16a34a;">K${r.net.toLocaleString()}</td>
      <td>
        <div style="display:flex;align-items:center;gap:6px;">
          <div style="background:var(--grey-light);border-radius:4px;height:8px;width:80px;overflow:hidden;">
            <div style="background:var(--teal);height:100%;width:${shareWidth}px;border-radius:4px;"></div>
          </div>
          <span style="font-size:0.75rem;color:var(--grey);">${sharePct}%</span>
        </div>
      </td>
    </tr>`;
  }).join('');

  tfoot.innerHTML = `<tr style="background:#f0fdf4;font-weight:700;">
    <td style="font-weight:800;color:var(--teal-dark);">TOTAL</td>
    <td style="text-align:center;">${totalTx}</td>
    <td style="color:var(--teal);font-weight:800;">K${totalGross.toLocaleString()}</td>
    <td style="color:var(--coral);">${totalRef > 0 ? '– K'+totalRef.toLocaleString() : '—'}</td>
    <td style="color:#15803d;font-weight:800;">K${totalNet.toLocaleString()}</td>
    <td><span style="font-size:0.78rem;color:var(--grey);">100%</span></td>
  </tr>`;
}

function renderOverviewFinKPI() {
  const el = document.getElementById('adm-overview-fin-kpi');
  if (!el) return;
  const rows = (typeof saGetFinData === 'function') ? saGetFinData('all') : [];
  if (!rows.length) {
    el.innerHTML = '<div style="font-size:0.82rem;color:var(--grey);padding:10px 0;">No approved payment data yet.</div>';
    return;
  }
  const totalGross = rows.reduce((s,r)=>s+r.gross,0);
  const totalNet   = rows.reduce((s,r)=>s+r.net,0);
  const totalRef   = rows.reduce((s,r)=>s+r.refunded,0);
  const totalTx    = rows.reduce((s,r)=>s+r.txCount,0);
  const bestMonth  = rows.reduce((best,r)=>r.net>best.net?r:best, rows[0]);
  const kpis = [
    { icon:'💰', label:'Total Gross',    val:`K${totalGross.toLocaleString()}`, color:'var(--teal)' },
    { icon:'✅', label:'Net Income',      val:`K${totalNet.toLocaleString()}`,   color:'#16a34a' },
    { icon:'↩️', label:'Refunded',        val:`K${totalRef.toLocaleString()}`,   color:'var(--coral)' },
    { icon:'🔢', label:'Transactions',    val:totalTx,                           color:'#1a73e8' },
    { icon:'🏆', label:'Best Month',      val:bestMonth.label,                   color:'var(--gold)' },
  ];
  el.innerHTML = kpis.map(k=>`
    <div style="background:var(--white);border-radius:10px;border:1.5px solid var(--grey-light);padding:14px 12px;">
      <div style="font-size:1.3rem;margin-bottom:4px;">${k.icon}</div>
      <div style="font-family:'Poppins',sans-serif;font-weight:800;font-size:1.05rem;color:${k.color};">${k.val}</div>
      <div style="font-size:0.7rem;color:var(--grey);font-weight:600;margin-top:2px;">${k.label}</div>
    </div>`).join('');
}

function saExportFinReportCSV() {
  const yearFilter = document.getElementById('fin-year-filter')?.value || 'all';
  const rows = saGetFinData(yearFilter);
  if (!rows.length) { showToast('No income data to export.', 'error'); return; }
  const headers = 'Month,Transactions,Gross Income (K),Refunded (K),Net Income (K),Share (%)';
  const totalNet = rows.reduce((s,r)=>s+r.net,0);
  const lines = rows.map(r => {
    const share = totalNet > 0 ? ((r.net/totalNet)*100).toFixed(2) : '0.00';
    return [r.label, r.txCount, r.gross, r.refunded, r.net, share]
      .map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',');
  });
  const totalGross = rows.reduce((s,r)=>s+r.gross,0);
  const totalRef   = rows.reduce((s,r)=>s+r.refunded,0);
  const totalTx    = rows.reduce((s,r)=>s+r.txCount,0);
  lines.push(['"TOTAL"', totalTx, totalGross, totalRef, totalNet, '100.00'].map(v=>'"'+v+'"').join(','));
  const blob = new Blob([[headers, ...lines].join('\n')], { type: 'text/csv' });
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = `wampac-financial-report-${yearFilter === 'all' ? 'all' : yearFilter}.csv`;
  a.click(); URL.revokeObjectURL(a.href);
  showToast('Financial report exported as CSV!', 'success');
}

function saExportFinReportPDF() {
  const yearFilter = document.getElementById('fin-year-filter')?.value || 'all';
  const rows = saGetFinData(yearFilter);
  if (!rows.length) { showToast('No income data to export.', 'error'); return; }
  const totalGross = rows.reduce((s,r)=>s+r.gross,0);
  const totalNet   = rows.reduce((s,r)=>s+r.net,0);
  const totalRef   = rows.reduce((s,r)=>s+r.refunded,0);
  const totalTx    = rows.reduce((s,r)=>s+r.txCount,0);
  const yearLabel  = yearFilter === 'all' ? 'All Years' : yearFilter;
  const now = new Date().toLocaleDateString('en-PG', { year:'numeric', month:'long', day:'numeric' });

  const tableRows = rows.map(r => {
    const share = totalNet > 0 ? ((r.net/totalNet)*100).toFixed(1) : '0.0';
    return `<tr>
      <td>${r.label}</td>
      <td>${r.txCount}</td>
      <td>K${r.gross.toLocaleString()}</td>
      <td>${r.refunded > 0 ? '–K'+r.refunded.toLocaleString() : '—'}</td>
      <td><strong>K${r.net.toLocaleString()}</strong></td>
      <td>${share}%</td>
    </tr>`;
  }).join('');

  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
  <title>Wampac Financial Report – ${yearLabel}</title>
  <style>
    body { font-family: Arial, sans-serif; color: #1a1a2e; padding: 40px; font-size: 13px; }
    h1 { font-size: 22px; color: #0D5C63; margin-bottom: 4px; }
    .meta { color: #6b7280; font-size: 12px; margin-bottom: 28px; }
    .kpi-row { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 28px; }
    .kpi { background: #f7f4ef; border-radius: 8px; padding: 14px 18px; min-width: 130px; }
    .kpi-val { font-size: 18px; font-weight: 800; color: #0D5C63; }
    .kpi-lbl { font-size: 11px; color: #6b7280; margin-top: 3px; }
    table { width: 100%; border-collapse: collapse; margin-top: 8px; }
    th { background: #0D5C63; color: #fff; padding: 10px 12px; text-align: left; font-size: 12px; }
    td { padding: 9px 12px; border-bottom: 1px solid #e5e7eb; }
    tr:nth-child(even) td { background: #f7f4ef; }
    tfoot td { background: #dcfce7; font-weight: 700; border-top: 2px solid #16a34a; }
    .footer { margin-top: 32px; font-size: 11px; color: #9ca3af; text-align: center; border-top: 1px solid #e5e7eb; padding-top: 16px; }
  </style></head><body>
  <h1>📈 Wampac Financial Report</h1>
  <div class="meta">Period: ${yearLabel} &nbsp;·&nbsp; Generated: ${now}</div>
  <div class="kpi-row">
    <div class="kpi"><div class="kpi-val">K${totalGross.toLocaleString()}</div><div class="kpi-lbl">Total Gross Income</div></div>
    <div class="kpi"><div class="kpi-val" style="color:#16a34a;">K${totalNet.toLocaleString()}</div><div class="kpi-lbl">Net Income</div></div>
    <div class="kpi"><div class="kpi-val" style="color:#e8543a;">K${totalRef.toLocaleString()}</div><div class="kpi-lbl">Refunded</div></div>
    <div class="kpi"><div class="kpi-val" style="color:#1a73e8;">${totalTx}</div><div class="kpi-lbl">Transactions</div></div>
  </div>
  <table>
    <thead><tr><th>Month</th><th>Transactions</th><th>Gross (K)</th><th>Refunded (K)</th><th>Net Income (K)</th><th>Share</th></tr></thead>
    <tbody>${tableRows}</tbody>
    <tfoot><tr><td>TOTAL</td><td>${totalTx}</td><td>K${totalGross.toLocaleString()}</td><td>${totalRef>0?'–K'+totalRef.toLocaleString():'—'}</td><td>K${totalNet.toLocaleString()}</td><td>100%</td></tr></tfoot>
  </table>
  <div class="footer">Wampac – Papua New Guinea's Real Estate Platform &nbsp;·&nbsp; Confidential</div>
  </body></html>`;

  const w = window.open('', '_blank');
  if (!w) { showToast('Pop-up blocked. Allow pop-ups and try again.', 'error'); return; }
  w.document.write(html);
  w.document.close();
  w.focus();
  setTimeout(() => { w.print(); }, 600);
  showToast('Opening PDF print dialog…', 'success');
}

function saRenderPayAudit() {
  const el = document.getElementById('sa-pay-audit-list');
  if (!el) return;
  const log = saGetAuditLog().filter(e =>
    e.action.toLowerCase().includes('payment') || e.action.toLowerCase().includes('refund')
  );
  if (!log.length) { el.innerHTML = '<div style="text-align:center;padding:28px;color:var(--grey);">No payment events logged yet.</div>'; return; }
  const TYPE_ICONS = { update:'✏️', create:'➕', delete:'🗑' };
  el.innerHTML = log.slice(0,50).map(e => {
    const d = new Date(e.ts);
    const ts = d.toLocaleDateString() + ' ' + d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
    return `<div class="sa-audit-row">
      <div class="sa-audit-icon audit-update">${TYPE_ICONS[e.type]||'💳'}</div>
      <div class="sa-audit-meta">
        <div class="sa-audit-action">${escHtml(e.action)}</div>
        <div class="sa-audit-detail">${escHtml(e.detail||'')} · by ${escHtml(e.userId||'system')}</div>
      </div>
      <div class="sa-audit-time">${ts}</div>
    </div>`;
  }).join('');
}

