function saSaveBankDetails() {
  const bank = {
    name:   document.getElementById('adm-bank-name')?.value.trim()  || '',
    acct:   document.getElementById('adm-acct-name')?.value.trim()  || '',
    num:    document.getElementById('adm-acct-num')?.value.trim()   || '',
    branch: document.getElementById('adm-acct-branch')?.value.trim()|| '',
    bsb:    document.getElementById('adm-acct-bsb')?.value.trim()   || '',
    swift:  document.getElementById('adm-acct-swift')?.value.trim() || '',
    notes:  document.getElementById('adm-bank-notes')?.value.trim() || '',
  };
  _LS.setItem('pom_bank', JSON.stringify(bank));
  saLog('system','Bank details updated', `Bank: ${bank.name}`, 'superadmin');
  const ok  = document.getElementById('adm-bank-success');
  const err = document.getElementById('adm-bank-error');
  if (err) err.style.display='none';
  if (ok) { ok.innerHTML='<span class="wi-svg" data-lucide="check-circle" style="width:14px;height:14px;vertical-align:middle;"></span><span class="wi-emoji">✅</span> Bank details saved!'; ok.style.display='block'; setTimeout(()=>ok.style.display='none',3000); }
  showToast('Bank details saved!', 'success');
}

function saLoadBankDetails() {
  try {
    const b = JSON.parse(_LS.getItem('pom_bank')||'{}');
    saSetInput('adm-bank-name',    b.name   || '');
    saSetInput('adm-acct-name',    b.acct   || '');
    saSetInput('adm-acct-num',     b.num    || '');
    saSetInput('adm-acct-branch',  b.branch || '');
    saSetInput('adm-acct-bsb',     b.bsb    || '');
    saSetInput('adm-acct-swift',   b.swift  || '');
    saSetInput('adm-bank-notes',   b.notes  || '');
  } catch(e) {}
}

// ──────────────────────────────────────────────
// DANGER ZONE ACTIONS
// ──────────────────────────────────────────────
function saDeleteDemoListings() {
  if (!confirm('Delete all demo/seed listings? Cannot be undone.')) return;
  const allProps = getProps();
  const live = allProps.filter(p => !p._isDemo && !p.seeded);
  const removed = allProps.length - live.length;
  saveProps(live);
  saLog('delete', `Cleared ${removed} demo listings`, '', 'superadmin');
  renderAdminStats(); refreshAllGrids();
  showToast(`${removed} demo listings removed.`, 'error');
}

function saDeleteAllUsers() {
  if (!confirm('DELETE ALL LANDLORD ACCOUNTS AND THEIR LISTINGS? This cannot be undone!')) return;
  if (!confirm('Are you absolutely sure? Type "YES" in the next prompt to confirm.')) return;
  saveUsers([]);
  saveProps([]);
  saveSuspended([]);
  saLog('delete', 'ALL landlord accounts deleted by Super Admin', '', 'superadmin');
  renderAdminStats(); refreshAllGrids();
  showToast('All user accounts deleted.', 'error');
}

function saDeleteAllListings() {
  if (!confirm('DELETE ALL LISTINGS permanently? Cannot be undone!')) return;
  saveProps([]);
  saLog('delete', 'ALL listings deleted by Super Admin', '', 'superadmin');
  renderAdminStats(); refreshAllGrids();
  showToast('All listings deleted.', 'error');
}

function saFullReset() {
  if (!confirm('⚠️ FULL PLATFORM RESET — wipes ALL data. This cannot be undone!')) return;
  if (!confirm('Final confirmation: delete all users, listings, payments, settings and audit log?')) return;
  const keysToKeep = [LS_ADMIN];
  const keysToRemove = [];
  for (let i = 0; i < _LS.length; i++) {
    const k = _LS.key(i);
    if (!keysToKeep.includes(k)) keysToRemove.push(k);
  }
  keysToRemove.forEach(k => _LS.removeItem(k));
  saLog('system', '⚠️ FULL PLATFORM RESET PERFORMED', 'All data wiped', 'superadmin');
  renderAdminStats(); refreshAllGrids();
  showToast('Platform reset to factory defaults.', 'error');
}

