function saSetInput(id, val) { const el=document.getElementById(id); if(el) el.value=val; }
function saGetCheck(id) { return document.getElementById(id)?.checked || false; }
function saSetCheck(id, val) { const el=document.getElementById(id); if(el) el.checked=!!val; }

