// PATCH switchAdminTab — extend for new tabs
// ──────────────────────────────────────────────
const _origSATab2 = switchAdminTab;
switchAdminTab = function(tab, el) {
  _origSATab2(tab, el);
  if (tab === 'payments') {
    saRenderPayments();
    renderAdminWaitlist();
    saLoadBankDetails();
    saRenderPayAudit();
  }
  if (tab === 'settings') {
    populateAdminSettingsTab();
    saLoadBankDetails();
  }
  if (tab === 'wizard') {
    wzLoadEditor();
  }
};

