// ══════════════════════════════════════════════════════════════════
//  PER-PROPERTY GO LIVE TOGGLE SYSTEM
//  Logic:
//  • Each PROPERTY (not the landlord) has its own live/offline state
//    and its own plan, tracked via a dedicated payment record keyed
//    by listingId.
//  • prop.liveState: 'live' | 'off' | 'pending'
//      - 'live'    → visible to tenants
//      - 'off'     → hidden, landlord switched it off (e.g. fully booked)
//      - 'pending' → landlord tapped "Go Live" and submitted payment,
//                     awaiting admin approval (shows orange badge)
//  • A plan's clock only runs while the property is actually live —
//    toggling off freezes it (liveMs / lastResumedAt, same mechanism
//    as before, just attached to the per-property payment record).
//  • Toggle OFF → just hides the property and FREEZES its plan clock
//                 (kept only for the "days banked" display).
//  • Toggle ON  → ALWAYS requires a fresh approved payment for THIS
//                 property, even if days remain banked on its old
//                 plan. Once admin approves, the new payment becomes
//                 that property's active plan and its clock starts
//                 running; the old plan's banked days are not carried
//                 over or refunded.
//  • A brand new listing's first payment approval makes it live
//    immediately (no separate toggle step needed the first time).
// ══════════════════════════════════════════════════════════════════

// Computes how many ms of a plan's clock have been "used up" so far.
//   pay.liveMs        = total ms accumulated while live, NOT counting
//                        the current live session (if any)
//   pay.lastResumedAt = timestamp the plan was last switched to live
//                        (null while currently offline/pending)
function getPlanUsedMs(pay) {
  let used = pay.liveMs || 0;
  if (pay.lastResumedAt != null) {
    used += Math.max(0, Date.now() - pay.lastResumedAt);
  }
  return used;
}

// Returns exact milliseconds remaining for an active/live plan
function getPlanRemainingMs(pay) {
  const totalMs = (pay.days || 0) * 86400000;
  return Math.max(0, totalMs - getPlanUsedMs(pay));
}

// ── Real-time countdown ticker ────────────────────────────────────────────────
// Scans for .plan-countdown elements with data-running="1" and ticks them.
let _cdTickerInterval = null;
let _cdExpireRenderTimer = null;
function _cdTick() {
  const badges = document.querySelectorAll('.plan-countdown[data-running="1"]');
  if (!badges.length) return;
  const now = Date.now();
  badges.forEach(el => {
    // data-ms stores the ms-remaining AT render time; data-rendered is when it was rendered
    let rendered = parseInt(el.dataset.rendered || '0', 10);
    if (!rendered) {
      el.dataset.rendered = now;
      rendered = now;
    }
    const startMs = parseInt(el.dataset.ms || '0', 10);
    const elapsed = now - rendered;
    const msLeft  = Math.max(0, startMs - elapsed);

    const totalSecs = Math.floor(msLeft / 1000);
    const d = Math.floor(totalSecs / 86400);
    const h = Math.floor((totalSecs % 86400) / 3600);
    const m = Math.floor((totalSecs % 3600) / 60);
    const s = totalSecs % 60;

    const pad = n => String(n).padStart(2, '0');

    const dEl = el.querySelector('[id$="-d"]');
    const hEl = el.querySelector('[id$="-h"]');
    const mEl = el.querySelector('[id$="-m"]');
    const sEl = el.querySelector('[id$="-s"]');
    if (dEl) dEl.textContent = d;
    if (hEl) hEl.textContent = pad(h);
    if (mEl) mEl.textContent = pad(m);
    if (sEl) sEl.textContent = pad(s);

    // Urgent styling when less than 24 hours left
    if (d === 0) el.classList.add('urgent');
    else         el.classList.remove('urgent');

    // Stop when expired
    if (msLeft <= 0) {
      el.dataset.running = '0';
      el.innerHTML = '🔴 Plan Expired';
      el.classList.add('urgent');
      // Auto-flip the listing off in storage, then re-render dashboard
      // so the UI shows the "EXPIRED — Pay to Renew" state immediately.
      const propId = el.id.replace(/^cd-/, '');
      if (propId) {
        const props = getProps();
        const prop  = props.find(p => p.id === propId);
        if (prop) {
          _autoExpireListing(prop);
          // Debounce: only re-render once even if multiple listings expire together
          clearTimeout(_cdExpireRenderTimer);
          _cdExpireRenderTimer = setTimeout(() => {
            renderDashboard();
            refreshAllGrids();
            showToast('⏰ Your plan for "' + prop.title + '" has expired. Purchase a new plan to go live again.', '');
          }, 400);
        }
      }
    }
  });
}
function startCdTicker() {
  if (_cdTickerInterval) return;
  _cdTickerInterval = setInterval(_cdTick, 1000);
  _cdTick(); // immediate first tick
}
// Auto-start when page is ready
document.addEventListener('DOMContentLoaded', startCdTicker);

// Call right before taking a property OFFLINE — banks the live time
// accumulated so far into liveMs and clears lastResumedAt (freezing the clock).
function freezePlanClock(pay) {
  if (pay.lastResumedAt != null) {
    pay.liveMs = (pay.liveMs || 0) + Math.max(0, Date.now() - pay.lastResumedAt);
    pay.lastResumedAt = null;
  }
}

// Call right after a property goes LIVE — starts the clock running again.
function resumePlanClock(pay) {
  if (pay.lastResumedAt == null) {
    pay.lastResumedAt = Date.now();
  }
}

// Returns the active plan for ONE property (not the whole landlord):
// the most recently approved payment tied to this listingId that still
// has days remaining on its own clock. Returns null if none / expired.
function getListingActivePlan(listingId) {
  const payments = getPayments().filter(p =>
    p.listingId === listingId && p.status === 'approved'
  );
  if (!payments.length) return null;
  for (const pay of payments.sort((a,b) => (b.approvedAt||b.submittedAt) - (a.approvedAt||a.submittedAt))) {
    const usedDays = getPlanUsedMs(pay) / 86400000;
    const remaining = pay.days - usedDays;
    if (remaining > 0) {
      return { pay, daysRemaining: Math.ceil(remaining) };
    }
    // else expired — keep checking older payments for this listing (rare, but safe)
  }
  return null;
}

// Returns 'live' | 'off' | 'pending' | 'noplan' | 'expired' | 'live-free' | 'off-free' for one property.
function getListingLiveState(prop) {
  if (prop.liveState === 'pending') return 'pending';
  // Free listings (admin has payments switched off) are never gated by a
  // plan — they're just a plain on/off switch the landlord controls directly.
  if (prop.paymentStatus === 'free') {
    return prop.liveState === 'off' ? 'off-free' : 'live-free';
  }
  const plan = getListingActivePlan(prop.id);
  if (!plan) {
    const anyApproved = getPayments().some(p => p.listingId === prop.id && p.status === 'approved');
    // Plan gone but liveState still says 'live' — auto-flip it now
    if (prop.liveState === 'live') _autoExpireListing(prop);
    return anyApproved ? 'expired' : 'noplan';
  }
  // Plan exists — check exact real-time ms (catches the moment it hits zero)
  const msLeft = getPlanRemainingMs(plan.pay);
  if (msLeft <= 0) {
    _autoExpireListing(prop);
    return 'expired';
  }
  return prop.liveState === 'off' ? 'off' : 'live';
}

// Silently flips a live listing to 'off' + freezes its plan clock when the
// plan expires. Never calls renderDashboard — caller handles UI refresh.
function _autoExpireListing(prop) {
  try {
    const pays = getPayments();
    const activePlan = getListingActivePlan(prop.id);
    if (activePlan) {
      const pay = pays.find(x => x.id === activePlan.pay.id);
      if (pay) { freezePlanClock(pay); savePayments(pays); }
    }
    const props = getProps();
    const p = props.find(x => x.id === prop.id);
    if (p && p.liveState === 'live') {
      p.liveState = 'off';
      saveProps(props);
      prop.liveState = 'off'; // update in-memory ref too
    }
  } catch(e) { /* silent — never crash UI */ }
}

// Renders the small live/offline control + status badge for one property
// card inside "My Listings". Returns an HTML string.
function renderListingGoLiveControl(prop) {
  const state = getListingLiveState(prop);
  const plan  = getListingActivePlan(prop.id);

  if (state === 'pending') {
    return `<div class="listing-golive-row">
      <span class="status-pill status-pending-pay">⏳ Approval Pending</span>
      <span style="font-size:0.72rem;color:#92400e;">We'll notify you once admin approves it.</span>
    </div>`;
  }

  if (state === 'live') {
    const cdId = 'cd-' + prop.id;
    const msRemaining = plan ? getPlanRemainingMs(plan.pay) : 0;
    const daysBadge = plan
      ? `<span class="plan-countdown" id="${cdId}" data-ms="${msRemaining}" data-running="1">
           <span class="cd-unit"><span class="cd-val" id="${cdId}-d">--</span><span class="cd-lbl">days</span></span>
           <span class="cd-sep">:</span>
           <span class="cd-unit"><span class="cd-val" id="${cdId}-h">--</span><span class="cd-lbl">hrs</span></span>
           <span class="cd-sep">:</span>
           <span class="cd-unit"><span class="cd-val" id="${cdId}-m">--</span><span class="cd-lbl">min</span></span>
           <span class="cd-sep">:</span>
           <span class="cd-unit"><span class="cd-val" id="${cdId}-s">--</span><span class="cd-lbl">sec</span></span>
         </span>`
      : '';
    return `<div class="listing-golive-row">
      <label class="live-switch live-switch-sm" title="Turn off when fully booked">
        <input type="checkbox" checked onchange="handleListingGoLiveToggle('${prop.id}', this.checked)">
        <div class="live-switch-track"></div>
        <div class="live-switch-thumb"></div>
      </label>
      <span class="golive-label-mini" style="color:#22c55e;">🟢 LIVE</span>
      ${daysBadge}
    </div>`;
  }

  if (state === 'off') {
    const daysBadge = plan ? `<span class="golive-days-mini">⏳ ${plan.daysRemaining} day${plan.daysRemaining!==1?'s':''} banked</span>` : '';
    return `<div class="listing-golive-row">
      <label class="live-switch live-switch-sm" title="Go live (requires payment)">
        <input type="checkbox" onchange="handleListingGoLiveToggle('${prop.id}', this.checked)">
        <div class="live-switch-track"></div>
        <div class="live-switch-thumb"></div>
      </label>
      <span class="golive-label-mini" style="color:#9ca3af;">⚫ OFFLINE</span>
      ${daysBadge}
    </div>`;
  }

  if (state === 'live-free') {
    return `<div class="listing-golive-row">
      <label class="live-switch live-switch-sm" title="Turn off when fully booked">
        <input type="checkbox" checked onchange="handleListingGoLiveToggle('${prop.id}', this.checked)">
        <div class="live-switch-track"></div>
        <div class="live-switch-thumb"></div>
      </label>
      <span class="golive-label-mini" style="color:#22c55e;">🟢 LIVE</span>
      <span class="golive-days-mini">Free listing</span>
    </div>`;
  }

  if (state === 'off-free') {
    return `<div class="listing-golive-row">
      <label class="live-switch live-switch-sm" title="Go live again">
        <input type="checkbox" onchange="handleListingGoLiveToggle('${prop.id}', this.checked)">
        <div class="live-switch-track"></div>
        <div class="live-switch-thumb"></div>
      </label>
      <span class="golive-label-mini" style="color:#9ca3af;">⚫ OFFLINE</span>
      <span class="golive-days-mini">Free listing</span>
    </div>`;
  }

  if (state === 'expired') {
    return `<div style="display:flex;flex-direction:column;gap:8px;">
      <div class="listing-golive-row" style="gap:8px;">
        <label class="live-switch live-switch-sm" style="opacity:0.35;cursor:not-allowed;" title="Plan expired — purchase a new plan to go live">
          <input type="checkbox" disabled>
          <div class="live-switch-track"></div>
          <div class="live-switch-thumb"></div>
        </label>
        <span class="golive-label-mini" style="color:#f43f5e;">🔴 EXPIRED</span>
      </div>
      <div style="background:linear-gradient(135deg,#fef2f2,#fff5f5);border:1.5px solid #fca5a5;border-radius:12px;padding:10px 14px;display:flex;flex-direction:column;gap:8px;">
        <div style="font-size:0.78rem;color:#991b1b;font-weight:700;line-height:1.4;">
          ⏰ Your plan has expired. This listing is no longer visible to the public.
        </div>
        <div style="font-size:0.74rem;color:#7f1d1d;line-height:1.4;">
          Purchase a new plan to make this property live again.
        </div>
        <button class="btn btn-sm" style="background:var(--teal);color:#fff;border-radius:20px;padding:8px 16px;font-size:0.8rem;font-weight:700;align-self:flex-start;display:flex;align-items:center;gap:6px;"
          onclick="handleListingGoLiveToggle('${prop.id}', true)">
          💳 Buy New Plan → Go Live
        </button>
      </div>
    </div>`;
  }

  // noplan — shouldn't normally happen for an approved listing, but just in case
  return `<div class="listing-golive-row">
    <label class="live-switch live-switch-sm" style="opacity:0.4;cursor:not-allowed;" title="No plan on this property yet">
      <input type="checkbox" disabled>
      <div class="live-switch-track"></div>
      <div class="live-switch-thumb"></div>
    </label>
    <span class="golive-label-mini" style="color:#f59e0b;">🟡 NO PLAN</span>
  </div>`;
}

// One listing's id, kept while the reactivation payment modal is open.
let pendingReactivationListingId = null;

function handleListingGoLiveToggle(listingId, wantsLive) {
  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (!prop || prop.landlordId !== currentUser.id) return;

  if (!wantsLive) {
    // Landlord is switching a live listing OFF — show the occupied-property
    // policy reminder first. The checkbox has already visually flipped via
    // the native onchange event, so if they back out we restore it to checked.
    occPolicyShow(listingId);
    return;
  }

  // Free listings (admin payments switched off) — plain on/off, no plan involved
  if (prop.paymentStatus === 'free') {
    prop.liveState = 'live';
    resetListingOnGoLive(prop);
    saveProps(props);
    renderDashboard();
    refreshAllGrids();
    showToast('🟢 Property is live again! The public can see it.', 'success');
    return;
  }

  // Going live always requires a fresh approved payment for THIS
  // property — even if it still has days banked from a previous plan.
  // Switching off effectively forfeits that plan; the banked-days badge
  // shown while offline is informational only.
  if (!isPaymentEnabled()) {
    // Admin has globally disabled payments — reactivate for free.
    activateListingLiveFree(listingId);
    return;
  }
  openListingReactivationPaymentModal(listingId);
}

// ── OCCUPIED PROPERTY POLICY POPUP ───────────────────────────────────
// Shown every time a landlord tries to switch a live listing OFF, to
// remind them of Wampac policy: only vacant properties may stay visible.
// They confirm the listing is occupied (→ proceed to turn it off) or back out.
let _occPolicyListingId = null;

function occPolicyShow(listingId) {
  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (!prop) return;
  _occPolicyListingId = listingId;
  const nameEl = document.getElementById('occ-policy-prop-name');
  if (nameEl) nameEl.textContent = prop.title || 'this property';
  document.getElementById('occ-policy-overlay').classList.add('open');
}

function occPolicyConfirmOff() {
  const listingId = _occPolicyListingId;
  document.getElementById('occ-policy-overlay').classList.remove('open');
  _occPolicyListingId = null;
  if (!listingId) return;

  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (!prop) return;

  if (prop.paymentStatus === 'free') {
    prop.liveState = 'off';
    saveProps(props);
    renderDashboard();
    refreshAllGrids();
    showToast('⚫ Property hidden from tenants.', 'success');
    return;
  }
  confirmListingGoLiveOff(listingId);
}

function occPolicyKeepLive() {
  document.getElementById('occ-policy-overlay').classList.remove('open');
  // Restore the toggle's visual state to ON since nothing actually changed.
  if (_occPolicyListingId) {
    renderDashboard();
    refreshAllGrids();
  }
  _occPolicyListingId = null;
}

// Used only when the admin has turned the payment system OFF globally.
function activateListingLiveFree(listingId) {
  const plan = getListingActivePlan(listingId);
  if (plan) {
    const pays = getPayments();
    const p = pays.find(x => x.id === plan.pay.id);
    if (p) { resumePlanClock(p); savePayments(pays); }
  }
  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (prop) {
    prop.liveState = 'live';
    prop.status = 'approved';
    resetListingOnGoLive(prop);
  }
  saveProps(props);
  renderDashboard();
  refreshAllGrids();
  showToast('🟢 This property is now LIVE! The public can see it.', 'success');
}

// Opens the payment modal in "reactivation" mode for ONE property — no
// new listing is created; on admin approval we flip just this property live.
function openListingReactivationPaymentModal(listingId) {
  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (!prop) return;

  pendingReactivationListingId = listingId;
  pendingListingData = null;
  try { _SS.removeItem('pom_pending_listing'); } catch(e){}

  document.getElementById('pay-target-listing-id').value = listingId;
  document.getElementById('pay-error').style.display = 'none';
  document.getElementById('pay-notes').value = '';
  receiptImageData = null;
  clearReceipt();
  const submitBtn = document.getElementById('submit-pay-btn');
  const indicator = document.getElementById('pay-submitting-indicator');
  if (submitBtn)  submitBtn.style.display  = 'block';
  if (indicator) indicator.style.display = 'none';
  const bank = getBankDetails();
  if (document.getElementById('pay-acct-name')) document.getElementById('pay-acct-name').textContent = bank.acctName;
  if (document.getElementById('pay-acct-num'))  document.getElementById('pay-acct-num').textContent  = bank.acctNum;
  const payCountry = (currentUser && currentUser.country) || 'Papua New Guinea';
  const countryObj = WORLD_COUNTRIES.find(c => c.name === payCountry);
  const payMethod = countryObj ? countryObj.payMethod : (payCountry === 'Papua New Guinea' ? 'bank' : 'visa');
  showPaymentSection(payMethod, payCountry);
  openModal('payment-modal');
  refreshPlanCards(); // ensure current days/prices shown
  const p = getPricingPNG();
  const basicCard = document.querySelector('.pricing-card[data-plan="basic"]');
  if (basicCard) selectPlan(basicCard, 'basic', p.basic, getPlanDaysPNG().basic);
}

function confirmListingGoLiveOff(listingId) {
  // Hide this one property. We freeze its active plan's clock (bank the
  // live-time used so far) so remaining days stop ticking down while
  // offline — nothing is cancelled or forfeited by switching off.
  const plan = getListingActivePlan(listingId);
  if (plan) {
    const pays = getPayments();
    const p = pays.find(x => x.id === plan.pay.id);
    if (p) { freezePlanClock(p); savePayments(pays); }
  }

  const props = getProps();
  const prop = props.find(p => p.id === listingId);
  if (prop) {
    prop.liveState = 'off';
  }
  saveProps(props);

  renderDashboard();
  refreshAllGrids();
  showToast('⚫ Property hidden from tenants. Its remaining plan days are safe.', 'success');
}

// ── RE-ACTIVATION RESET ───────────────────────────────────────────────────
// When a landlord turns a property back ON after being offline, we treat it
// as a fresh re-listing: publish date resets to right now and the view counter
// goes back to zero so tenants always see accurate, current information.
function resetListingOnGoLive(prop) {
  prop.publishedAt = Date.now();   // fresh publish date + time
  prop.views = 0;                  // reset view counter to zero
}

// Patch the listing filter to respect per-property liveState
function isListingPubliclyVisible(prop) {
  if (!prop) return false;
  if (prop.status !== 'approved' && prop.status) return false;
  if (prop.liveState === 'off' || prop.liveState === 'pending') return false;
  // Free listings are always visible when liveState is 'live'
  if (prop.paymentStatus === 'free') return true;
  // Even if liveState is 'live' (or unset, for legacy listings), hide it
  // if its plan has simply run out of days — check real-time ms.
  const plan = getListingActivePlan(prop.id);
  const everHadAPlan = getPayments().some(p => p.listingId === prop.id && p.status === 'approved');
  if (everHadAPlan && !plan) return false;
  if (plan && getPlanRemainingMs(plan.pay) <= 0) return false;
  return true;
}

const _baseGetProps = getProps;

function getPublicProps() {
  return _baseGetProps().filter(p => {
    if (p.hidden) return false;
    const approvedOrNoStatus = p.status === 'approved' || !p.status;
    if (!approvedOrNoStatus) return false;
    return isListingPubliclyVisible(p);
  });
}

// renderListings and renderAreaGrid now call isListingPubliclyVisible()
// directly in their own filter logic (fixed inline — no monkey-patch needed).



loadAnnouncement();
applySiteAppearance(getAppearance());
applyHeroBg();
applyListingsWallpaper();
applySalesWallpaper();
checkMaintenanceMode();
enforceSalesModeAvailability();
init();

// ══════════════════════════════════════════════════════════════════
//  HOW-TO GUIDE  — Finger points to REAL step-cards in the live DOM
// ══════════════════════════════════════════════════════════════════
(function () {

  // ── Inject the floating finger + ripple overlay into <body> ───
  // NOTE: the 👆 glyph's visible fingertip sits near the TOP-CENTER of its
  // emoji box (not the geometric center, and not the top-left corner).
  // FINGER_TIP_X/Y below describe, in px at font-size:2rem, where that tip
  // pixel sits relative to the element's top-left corner. We use these to
  // translate the finger element so the *tip* — not the box — lands
  // exactly on the target's centre point.
  const FINGER_TIP_X  = 16;  // tip is roughly centred horizontally
  const FINGER_TIP_Y  = 4;   // tip is near the very top of the glyph

  const finger = document.createElement('div');
  finger.id = 'htg-finger-el';
  finger.textContent = '👆';
  finger.style.cssText = `
    position:fixed; z-index:99999; font-size:2rem; line-height:1; pointer-events:none;
    opacity:0; transition:none;
    filter:drop-shadow(0 4px 10px rgba(0,0,0,0.5));
    transform-origin: ${FINGER_TIP_X}px ${FINGER_TIP_Y}px;
  `;
  document.body.appendChild(finger);

  const ripple = document.createElement('div');
  ripple.id = 'htg-ripple-el';
  ripple.style.cssText = `
    position:fixed; z-index:99998; width:44px; height:44px;
    border-radius:50%; pointer-events:none; opacity:0;
    border:2.5px solid rgba(244,169,28,0.85);
    box-shadow:0 0 0 0 rgba(244,169,28,0.4);
    transform:scale(0); transition:none;
  `;
  document.body.appendChild(ripple);

  // ── Helpers ───────────────────────────────────────────────────
  let timers = [];

  // ── Demo lifecycle state ────────────────────────────────────────
  // 'idle'    -> not started yet
  // 'running' -> finger is actively demoing
  // 'done'    -> finished naturally (ran once) or cancelled by a real tap
  let demoState = 'idle';
  let cancelled = false;

  function clear() { timers.forEach(clearTimeout); timers = []; }
  function wait(ms, fn) {
    const t = setTimeout(() => { if (!cancelled) fn(); }, ms);
    timers.push(t);
  }

  // Centre of an element in fixed (viewport) coords
  function centre(el) {
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  }

  // Smoothly move finger to fixed (x,y) — the TIP lands on (x,y) — then fire cb
  function moveTo(x, y, cb) {
    finger.style.transition =
      'left 0.55s cubic-bezier(0.34,1.4,0.64,1), top 0.55s cubic-bezier(0.34,1.4,0.64,1), opacity 0.3s';
    finger.style.left    = (x - FINGER_TIP_X) + 'px';
    finger.style.top     = (y - FINGER_TIP_Y) + 'px';
    finger.style.opacity = '1';
    wait(580, cb);
  }

  // Press-tap animation at fixed (x,y), flash card, fire cb
  function tap(x, y, cardEl, cb) {
    // Press down
    finger.style.transition = 'transform 0.1s ease-in, left 0.1s, top 0.1s';
    finger.style.transform  = 'scale(0.78)';

    // Position + burst ripple
    ripple.style.transition = 'none';
    ripple.style.left    = (x - 22) + 'px';
    ripple.style.top     = (y - 22) + 'px';
    ripple.style.opacity = '0';
    ripple.style.transform = 'scale(0)';
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (cancelled) return;
      ripple.style.transition = 'transform 0.5s ease-out, opacity 0.5s ease-out, box-shadow 0.5s';
      ripple.style.transform  = 'scale(2.8)';
      ripple.style.opacity    = '1';
      ripple.style.boxShadow  = '0 0 0 8px rgba(244,169,28,0)';
    }));

    // Flash the actual card
    if (cardEl) {
      const origBg     = cardEl.style.background;
      const origBorder = cardEl.style.border;
      const origShadow = cardEl.style.boxShadow;
      cardEl.style.transition  = 'background 0.15s, box-shadow 0.15s, transform 0.12s';
      cardEl.style.background  = 'rgba(244,169,28,0.22)';
      cardEl.style.boxShadow   = '0 0 0 3px rgba(244,169,28,0.7), 0 4px 20px rgba(244,169,28,0.25)';
      cardEl.style.transform   = 'scale(0.94)';
      wait(180, () => {
        cardEl.style.transform  = 'scale(1)';
        cardEl.style.background = origBg;
        cardEl.style.boxShadow  = origShadow;
      });
    }

    wait(150, () => {
      // Lift finger
      finger.style.transition = 'transform 0.18s ease-out';
      finger.style.transform  = 'scale(1)';
      // Fade ripple
      ripple.style.opacity = '0';
      wait(250, cb);
    });
  }

  // Lift & hide finger
  function hideFinger(cb) {
    finger.style.transition = 'opacity 0.3s, top 0.3s';
    finger.style.opacity    = '0';
    finger.style.top        = (parseFloat(finger.style.top || 0) - 40) + 'px';
    wait(320, cb);
  }

  // Update description text in the guide panel
  function setDesc(html) {
    const el = document.getElementById('htg-desc');
    if (!el) return;
    el.style.transition = 'opacity 0.25s';
    el.style.opacity = '0';
    wait(260, () => {
      el.innerHTML = html;
      el.style.opacity = '1';
    });
  }

  // Update pill label + progress dots
  function setPill(icon, label, dotIndex) {
    const pi = document.getElementById('htg-step-icon');
    const pl = document.getElementById('htg-step-label');
    if (pi) pi.textContent = icon;
    if (pl) pl.textContent = label;
    [0,1,2,3].forEach(i => {
      const d = document.getElementById('htg-dot-' + i);
      if (!d) return;
      d.style.transition  = 'all 0.35s';
      d.style.background  = i === dotIndex ? '#F4A91C' : 'rgba(255,255,255,0.25)';
      d.style.width       = i === dotIndex ? '20px' : '8px';
      d.style.borderRadius= '10px';
    });
  }

  // Scroll an element into view softly, then call cb
  function scrollTo(el, cb) {
    if (cancelled) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    wait(600, cb);
  }

  // ── Restore home page to province step WITHOUT opening the country splash ──
  // goBackToCountry() now calls splashReset() which pops up the full-screen
  // country overlay — wrong for the demo flow. This helper just ensures PNG
  // stays selected and step-province is visible so the tenant can browse.
  function htgRestoreHome() {
    // Demo + reset state is always Step 1: choose a country.
    browseCountry = null;
    try { _updateFooterBranding(null); } catch (e) {}
    const h1 = document.getElementById('hero-h1-el');
    if (h1) h1.innerHTML = '<span class="wel">Wel</span>come to<br><em>Wam</em>pac';
    const hp = document.getElementById('hero-p-el');
    if (hp) hp.textContent = 'Find apartments, houses, offices and more \u2014 choose your country below to start browsing.';
    const hh = document.getElementById('hero-search-hint-el');
    if (hh) hh.textContent = 'Scroll down and select your country';
    const sc = document.getElementById('step-country');
    const sp = document.getElementById('step-province');
    const sa = document.getElementById('step-area');
    if (sc) sc.style.display = 'block';
    if (sp) sp.style.display = 'none';
    if (sa) sa.style.display = 'none';
    const ov = document.getElementById('country-splash-overlay');
    if (ov) ov.style.display = 'none';
    try { renderCountryGrid(getAllowedCountries()); } catch (e) {}
  }

  // ── Cancel the demo the moment the tenant taps/scrolls/types for real ──
  // Restores the homepage to its normal, untouched state so the tenant can
  // take over immediately with no leftover highlights or demo state.
  function cancelDemo() {
    if (cancelled || demoState !== 'running') return;
    cancelled = true;
    demoState = 'done';
    clear();
    finger.style.transition = 'opacity 0.2s';
    finger.style.opacity = '0';
    ripple.style.transition = 'opacity 0.2s';
    ripple.style.opacity = '0';
    // Clean up any mid-flash card styling left over from a tap() in progress
    document.querySelectorAll('.step-card, .listing-card').forEach(c => {
      c.style.transition = '';
      c.style.transform   = '';
      c.style.background  = '';
      c.style.boxShadow   = '';
    });
    // If we were on the listings page, back out to the home step grids
    if (document.getElementById('page-listings') &&
        document.getElementById('page-listings').classList.contains('active')) {
      goBackFromListings();
    }
    htgRestoreHome();
    setDesc('Demo stopped — go ahead and browse! 👇');
  }

  // Wire up a one-shot listener: the FIRST genuine tap/scroll/keypress
  // anywhere on the page cancels the demo immediately so the tenant is
  // never fighting the animation for control of the screen.
  // (Tapping the Replay button itself first cancels via this same listener,
  // then htgReplay()'s click handler resets state and restarts right
  // after — so Replay still works exactly as expected.)
  ['pointerdown', 'touchstart', 'wheel', 'keydown'].forEach(evt => {
    document.addEventListener(evt, cancelDemo, { passive: true, capture: true });
  });

  // ── MAIN SEQUENCE ─────────────────────────────────────────────
  function run() {
    if (cancelled) return;
    demoState = 'running';
    htgRestoreHome();

    function findCard(gridId, test) {
      const g = document.getElementById(gridId);
      const cards = g ? Array.from(g.querySelectorAll('.step-card')) : [];
      return cards.find(test) || cards[0] || null;
    }
    function nameOf(c) { const n = c.querySelector('.sc-name'); return n ? n.textContent.trim().toLowerCase() : ''; }
    function tapCard(card, next) {
      scrollTo(card, () => {
        const p = centre(card);
        moveTo(p.x, p.y, () => {
          wait(700, () => {
            const p2 = centre(card);
            tap(p2.x, p2.y, card, () => { hideFinger(() => wait(200, next)); });
          });
        });
      });
    }

    // STEP 1 - Country
    setPill('\uD83C\uDF0D', 'Step 1 of 4', 0);
    setDesc('First, choose your <strong>Country</strong>. Tap <strong>Papua New Guinea</strong>.');
    wait(900, () => {
      const countryCard = findCard('country-grid', c => (c.getAttribute('onclick') || '').indexOf("'PG'") > -1);
      if (!countryCard) { finishDemo(); return; }
      tapCard(countryCard, () => {
        const m = (countryCard.getAttribute('onclick') || '').match(/selectCountry\('([A-Z]+)'\)/);
        selectCountry(m ? m[1] : 'PG');

        // STEP 2 - Province / State
        wait(700, () => {
          setPill('\uD83D\uDCCD', 'Step 2 of 4', 1);
          setDesc('Next, pick a <strong>Province or State</strong>. Tap <strong>NCD</strong> \u2014 the National Capital District.');
          const provCard = findCard('province-grid', c => nameOf(c).indexOf('ncd') > -1);
          if (!provCard) { finishDemo(); return; }
          tapCard(provCard, () => {
            selectProvince('NCD');

            // STEP 3 - Area / Suburb
            wait(700, () => {
              setPill('\uD83C\uDFD8\uFE0F', 'Step 3 of 4', 2);
              setDesc('Almost there! Choose a <strong>Suburb</strong> \u2014 tap <strong>Gerehu</strong> to see all listings!');
              const areaCard = findCard('area-grid', c => nameOf(c).indexOf('gerehu') > -1);
              if (!areaCard) { finishDemo(); return; }
              tapCard(areaCard, () => {
                showListings('Gerehu');

                // STEP 4 - Listings
                wait(700, () => {
                  setPill('\uD83C\uDFE0', 'Step 4 of 4', 3);
                  setDesc('Here are all the <strong>properties in Gerehu</strong> \u2014 scroll down to browse them!');
                  const lp = document.getElementById('page-listings');
                  if (!lp) { wait(2200, finishDemo); return; }
                  scrollTo(lp.querySelector('.listings-header') || lp, () => {
                    const grid = document.getElementById('listings-grid');
                    const cards = grid ? Array.from(grid.querySelectorAll('.listing-card')).slice(0, 3) : [];
                    if (!cards.length) { wait(2200, finishDemo); return; }
                    (function visit(i) {
                      if (i >= cards.length) { hideFinger(() => wait(1800, finishDemo)); return; }
                      scrollTo(cards[i], () => {
                        const p = centre(cards[i]);
                        moveTo(p.x, p.y, () => wait(650, () => {
                          const p2 = centre(cards[i]);
                          tap(p2.x, p2.y, cards[i], () => wait(150, () => visit(i + 1)));
                        }));
                      });
                    })(0);
                  });
                });
              });
            });
          });
        });
      });
    });
  }

  // Finish after one full pass: reset to the Country step and STOP.
  function finishDemo() {
    if (cancelled) return; // a real tap already took over — don't fight it
    demoState = 'done';
    // If we ended up on the listings page, go back through the step grids first
    if (document.getElementById('page-listings') &&
        document.getElementById('page-listings').classList.contains('active')) {
      goBackFromListings();
    }
    htgRestoreHome();
    setPill('\u2705', 'Demo complete', 3);
    setDesc('You\'ve got it! Choose your country below, then a province or state, to start browsing.');
    // Scroll the province step into view so they can take over right away
    const homeStep = document.getElementById('step-country') || document.getElementById('step-province');
    if (homeStep) homeStep.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // ── Public replay hook — the only intentional way to re-run the demo ──
  window.htgReplay = function () {
    clear();
    cancelled  = false;
    demoState  = 'idle';
    finger.style.opacity = '0';
    ripple.style.opacity = '0';
    if (document.getElementById('page-listings') &&
        document.getElementById('page-listings').classList.contains('active')) {
      goBackFromListings();
    }
    htgRestoreHome();
    const guide = document.getElementById('how-to-guide');
    if (guide) guide.scrollIntoView({ behavior: 'smooth', block: 'start' });
    wait(600, run);
  };

  // Auto-start removed — animation only plays when the user clicks
  // the "Show me how to find a property" / Replay button (htgReplay).

})();

// ─────────────────────────────────────────────────────────────────────────────
// "NEW HERE?" PROMPT — collapsed banner ⇄ expanded walkthrough panel
// ─────────────────────────────────────────────────────────────────────────────
const LS_HTG_DISMISSED = 'wampac_htg_dismissed';

// Tap "Show Me" / the banner itself: reveal the full panel and start the demo.
window.htgExpand = function () {
  const collapsed = document.getElementById('htg-collapsed');
  const expanded  = document.getElementById('how-to-guide') && document.getElementById('htg-expanded');
  if (collapsed) collapsed.style.display = 'none';
  if (expanded)  expanded.style.display  = 'block';
  if (typeof htgReplay === 'function') htgReplay();
};

// Tap "Hide" inside the expanded panel: go back to the slim banner.
window.htgCollapse = function () {
  const collapsed = document.getElementById('htg-collapsed');
  const expanded  = document.getElementById('htg-expanded');
  if (expanded)  expanded.style.display  = 'none';
  if (collapsed) collapsed.style.display = 'flex';
};

// Tap ✕ on the banner: hide the whole prompt and remember that choice
// per-device, same pattern as LS_PIN_GUIDE_SEEN elsewhere in the app.
window.htgDismiss = function (evt) {
  if (evt) evt.stopPropagation();
  const wrap = document.getElementById('how-to-guide');
  if (wrap) wrap.style.display = 'none';
  try { _LS.setItem(LS_HTG_DISMISSED, '1'); } catch (e) {}
};

// On load: a tenant who already dismissed the prompt shouldn't see it again.
document.addEventListener('DOMContentLoaded', () => {
  try {
    if (_LS.getItem(LS_HTG_DISMISSED) === '1') {
      const wrap = document.getElementById('how-to-guide');
      if (wrap) wrap.style.display = 'none';
    }
  } catch (e) {}
});

// ─────────────────────────────────────────────────────────────────────────────
// PROPERTY DETAIL MODAL (Facebook-style full detail view)
// ─────────────────────────────────────────────────────────────────────────────
// Swipeable photo gallery used by the Details sheet (rental + sales).
// openCall contains the token @I@ which becomes the photo index that was tapped.
function pdmGalleryHTML(imgs, title, openCall) {
  const slides = imgs.map((src, i) =>
    `<div class="wp-slide" onclick="${openCall.replace('@I@', i)}"><img src="${escAttr(src)}" alt="${escHtml(title)} – photo ${i + 1}" ${i ? 'loading="lazy"' : ''} draggable="false"></div>`
  ).join('');
  return `<div class="pdm-track">${slides}</div>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// PROPERTY DETAILS v2 — shared premium layout for rental + sales detail sheets
// ─────────────────────────────────────────────────────────────────────────────
const PD2_ICONS = {
  bed:    '<path d="M2 4v16"/><path d="M2 8h18a2 2 0 0 1 2 2v10"/><path d="M2 17h20"/><path d="M6 8v9"/>',
  bath:   '<path d="M9 6 6.5 3.5a1.5 1.5 0 0 0-1-.5C4.7 3 4 3.7 4 4.5V17a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/><path d="M10 5 8 7"/><path d="M2 12h20"/><path d="M7 19v2"/><path d="M17 19v2"/>',
  area:   '<path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/>',
  car:    '<path d="M19 17h2c.6 0 1-.4 1-1v-3c0-.9-.7-1.7-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3c-.5-.4-1.1-.7-1.8-.7H5c-.6 0-1.1.4-1.4.9l-1.4 2.9A3.7 3.7 0 0 0 2 12v4c0 .6.4 1 1 1h2"/><circle cx="7" cy="17" r="2"/><path d="M9 17h6"/><circle cx="17" cy="17" r="2"/>',
  home:   '<path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/>',
  pin:    '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',
  calendar:'<rect width="18" height="18" x="3" y="4" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
  phone:  '<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.7 2Z"/>',
  wallet: '<rect width="20" height="12" x="2" y="6" rx="2"/><circle cx="12" cy="12" r="2"/><path d="M6 12h.01M18 12h.01"/>',
  key:    '<circle cx="7.5" cy="15.5" r="5.5"/><path d="m21 2-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/>',
  sparkles:'<path d="m12 3 1.9 5.1L19 10l-5.1 1.9L12 17l-1.9-5.1L5 10l5.1-1.9z"/><path d="M19 3v4M17 5h4"/>',
  zap:    '<path d="M13 2 3 14h9l-1 8 10-12h-9z"/>',
  shield: '<path d="M20 13c0 5-3.5 7.5-7.7 8.9a1 1 0 0 1-.6 0C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.2-2.7a1.2 1.2 0 0 1 1.6 0C14.5 3.8 17 5 19 5a1 1 0 0 1 1 1z"/>',
  building:'<rect width="16" height="20" x="4" y="2" rx="2"/><path d="M9 22v-4h6v4M8 6h.01M12 6h.01M16 6h.01M8 10h.01M12 10h.01M16 10h.01M8 14h.01M12 14h.01M16 14h.01"/>',
  user:   '<path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',
  layers: '<path d="m12 2 10 5-10 5L2 7z"/><path d="m2 12 10 5 10-5"/><path d="m2 17 10 5 10-5"/>',
  check:  '<path d="M20 6 9 17l-5-5"/>',
  chev:   '<path d="m6 9 6 6 6-6"/>',
  nav:    '<polygon points="3 11 22 2 13 21 11 13 3 11"/>',
  tag:    '<path d="M12.6 2.6A2 2 0 0 0 11.2 2H4a2 2 0 0 0-2 2v7.2a2 2 0 0 0 .6 1.4l8.7 8.7a2.4 2.4 0 0 0 3.4 0l6.6-6.6a2.4 2.4 0 0 0 0-3.4z"/><circle cx="7.5" cy="7.5" r=".5" fill="currentColor"/>'
};
function pd2Icon(name) {
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PD2_ICONS[name] || PD2_ICONS.tag}</svg>`;
}

// Availability banner (rental, residential types only).
// Keeps the earlier rule: a plain "vacant" listing with no unit count shows no banner.
function pd2AvailHTML(avail, type) {
  if (!avail || typeof AVAIL_TYPES === 'undefined' || !AVAIL_TYPES.includes(type)) return '';
  const total = Number(avail.totalUnits) || 0;
  const units = avail.availUnits != null ? Number(avail.availUnits) : total;
  const noteNum = avail.note && /^\d+$/.test(String(avail.note).trim()) ? parseInt(avail.note, 10) : null;
  const unitsTxt = n => `${n} unit${n === 1 ? '' : 's'} available right now`;
  let tone = 'ok', title = '', sub = '';
  switch (avail.status) {
    case 'partial':
      tone = 'warn';
      title = total > 0 ? `${units} of ${total} unit${total === 1 ? '' : 's'} available` : 'Partially available';
      if (noteNum > 0) sub = unitsTxt(noteNum);
      break;
    case 'booked':
      tone = 'bad'; title = 'Fully booked'; sub = 'Join the waitlist to be notified';
      break;
    case 'soon':
      tone = 'info'; title = 'Coming soon';
      if (noteNum > 0) sub = unitsTxt(noteNum);
      break;
    default:
      if (noteNum > 0) title = unitsTxt(noteNum);
      else if (type === 'Apartment' && total > 1) title = `${units} unit${units === 1 ? '' : 's'} available`;
      else return '';
  }
  return `<div class="pd2-avail ${tone}"><span class="pd2-avail-dot"></span><div><div class="pd2-avail-tx">${escHtml(title)}</div>${sub ? `<div class="pd2-avail-sub">${escHtml(sub)}</div>` : ''}</div></div>`;
}

// Builds the whole body + hero badges (compact v3 layout).
function pd2Render(o) {
  // Facts box: pair cells in two columns; widen any cell that would leave a gap
  const all = (o.details || []).concat(o.listing || []);
  let col = 0;
  all.forEach((d, i) => {
    if (d.wide) { if (col === 1) all[i - 1].wide = true; col = 0; }
    else col = (col + 1) % 2;
  });
  if (col === 1) all[all.length - 1].wide = true;
  const cells = all.map(d => `
    <div class="pd2-cell${d.wide ? ' wide' : ''}${d.accent ? ' accent' : ''}">
      <div class="pd2-cell-l">${pd2Icon(d.icon)}${d.label}</div>
      <div class="pd2-cell-v">${d.val}</div>
    </div>`).join('');

  const statsHTML = o.stats && o.stats.length ? `<div class="pd2-stats">${o.stats.map(s => `
    <span class="pd2-stat"><span class="pd2-stat-ic">${pd2Icon(s.icon)}</span><b>${s.value}</b><small>${s.label}</small></span>`).join('')}</div>` : '';

  const descHTML = o.desc ? `
    <div class="pd2-sec">
      <div class="pd2-sec-h"><i></i>Overview</div>
      <div class="pd2-bubble" id="pd2-bubble" onclick="pd2ToggleDesc(this)">
        <div class="pdm-desc" id="pdm-desc-text">${escHtml(o.desc)}</div>
        <div class="pd2-bubble-hint" id="pdm-desc-toggle-btn"><span>Tap to view more</span>${pd2Icon('chev')}</div>
      </div>
    </div>` : '';

  const ownerHTML = o.owner ? `
    <div class="pd2-owner">
      <div class="pd2-owner-av">🏠<span class="pd2-verified">${pd2Icon('check').replace('stroke-width="2"', 'stroke-width="3.5"')}</span></div>
      <div>
        <div class="pd2-owner-name">${escHtml(o.owner.name)}</div>
        <div class="pd2-owner-sub">${escHtml(o.owner.sub)}</div>
      </div>
    </div>` : '';

  document.getElementById('pdm-body').innerHTML = `
    <div>
      <div class="pd2-price">${o.priceHTML}</div>
      ${o.priceSub ? `<div class="pd2-price-sub">${o.priceSub}</div>` : ''}
      <h2 class="pd2-title">${escHtml(o.title)}</h2>
      ${o.location ? `<div class="pd2-loc">${pd2Icon('pin')}<span>${o.location}</span></div>` : ''}
    </div>
    ${statsHTML || '<span></span>'}
    <div>${o.availHTML || ''}${o.noteHTML || ''}${o.waitlistHTML || ''}</div>
    ${descHTML || '<span></span>'}
    <div class="pd2-sec">
      <div class="pd2-sec-h"><i></i>Facts and features</div>
      <div class="pd2-box">${cells}</div>
    </div>
    ${ownerHTML}
  `;

  const hb = document.getElementById('pdm-hero-badges');
  if (hb) hb.innerHTML = (o.badges || []).map(b =>
    `<span class="pd2-hbadge ${b.cls || ''}">${b.icon ? pd2Icon(b.icon) : ''}${escHtml(b.text)}</span>`).join('');

  requestAnimationFrame(() => {
    // Pin the photo right under the sticky header
    const sheet = document.getElementById('prop-detail-sheet');
    const hdr = sheet && sheet.querySelector('.pdm-header');
    if (sheet && hdr) sheet.style.setProperty('--pd2-hdr', hdr.offsetHeight + 'px');
    // Only offer "tap to view more" when the text is actually clipped
    const el = document.getElementById('pdm-desc-text');
    const hint = document.getElementById('pdm-desc-toggle-btn');
    const bub = document.getElementById('pd2-bubble');
    if (el && hint && bub) {
      if (el.scrollHeight <= el.clientHeight + 2) { hint.style.display = 'none'; bub.removeAttribute('onclick'); }
      else bub.classList.add('tappable');
    }
  });
}

// Comment-style overview: tap the bubble to unfold / fold
function pd2ToggleDesc(bub) {
  const el = document.getElementById('pdm-desc-text');
  const hint = document.getElementById('pdm-desc-toggle-btn');
  if (!el || !hint || hint.style.display === 'none') return;
  const open = el.classList.toggle('expanded');
  bub.classList.toggle('open', open);
  hint.firstElementChild.textContent = open ? 'Tap to show less' : 'Tap to view more';
}

function openPropDetail(propId) {
  const p = getProps().find(x => x.id === propId);
  if (!p) return;

  // ── Header title ──
  document.getElementById('pdm-header-title').textContent = p.title;

  // ── Photos ──
  const photoWrap = document.getElementById('pdm-photo-inner');
  const photoCount = document.getElementById('pdm-photo-count');
  const photoTap = document.getElementById('pdm-photo-tap');
  if (p.images && p.images.length > 0) {
    photoWrap.innerHTML = pdmGalleryHTML(p.images, p.title, `openLightbox(getProps().find(x=>x.id==='${escAttr(p.id)}').images,@I@,'${escAttr(p.title)}')`);
    if (p.images.length > 1) {
      photoCount.innerHTML = `📷 <span class="pdm-count-n">1 / ${p.images.length}</span>`;
      photoCount.style.display = '';
      photoTap.style.display = 'none';
    } else {
      photoCount.style.display = 'none';
      photoTap.style.display = 'none';
    }
  } else {
    photoWrap.innerHTML = `<span style="font-size:5rem;">${(TYPE_EMOJI && TYPE_EMOJI[p.type]) || '🏠'}</span>`;
    photoCount.style.display = 'none';
    photoTap.style.display = 'none';
  }

  // ── Build Body ──
  const pub = typeof formatPublishedDate === 'function' ? formatPublishedDate(p.publishedAt || p.date) : '';
  const isRes = !p.isCommercial;
  const isCom = !!p.isCommercial;

  // ── Redesigned details (v2) ──
  const priceHTML = typeof buildPriceBlockHTML === 'function' ? buildPriceBlockHTML(p) : '';

  const stats = [];
  if (p.beds) {
    if (p.beds === 'Studio') stats.push({ icon: 'home', value: 'Studio', label: 'Layout' });
    else stats.push({ icon: 'bed', value: escHtml(p.beds), label: p.beds === '1' ? 'Bedroom' : 'Bedrooms' });
  }
  if (p.baths) stats.push({ icon: 'bath', value: escHtml(p.baths), label: p.baths === '1' ? 'Bathroom' : 'Bathrooms' });
  if (p.floorArea) stats.push({ icon: 'area', value: Number(p.floorArea).toLocaleString(), label: 'sqm' });
  if (p.carParks && p.carParks !== 'None') stats.push({ icon: 'car', value: escHtml(p.carParks), label: Number(p.carParks) === 1 ? 'Parking' : 'Parking' });

  const money = n => (p.country && p.country !== 'Papua New Guinea' ? '' : 'K') + Number(n).toLocaleString();
  const details = [];
  details.push({ icon: isCom ? 'building' : 'home', label: 'Type', val: escHtml(p.type || '—') });
  if (p.condition) details.push({ icon: 'sparkles', label: 'Condition', val: escHtml(p.condition) });
  if (p.leaseTerm) details.push({ icon: 'key', label: 'Lease term', val: escHtml(p.leaseTerm) });
  if (p.security)  details.push({ icon: 'shield', label: 'Security', val: escHtml(p.security) });
  if (p.transitRates) {
    details.push({ icon: 'wallet', label: 'Rates', wide: true, accent: true,
      val: `<div class="pd2-rates"><span><b>K${Number(p.transitRates.daily).toLocaleString()}</b> / day</span><span><b>K${Number(p.transitRates.weekly).toLocaleString()}</b> / week</span><span><b>K${Number(p.transitRates.monthly).toLocaleString()}</b> / month</span></div>` });
  }
  if (isCom && p.utilities) details.push({ icon: 'zap', label: 'Utilities', val: escHtml(p.utilities) });
  if (p.area) details.push({ icon: 'pin', label: 'Location', wide: !p.address, val: escHtml(p.area) + (p.province ? ', ' + escHtml(p.province) : '') });
  if (p.address) details.push({ icon: 'nav', label: 'Address', wide: true, val: escHtml(p.address) });
  if (p.availability && p.availability.status && isRes) {
    const statusMap = { available: 'Available', vacant: 'Vacant', partial: 'Partially available', occupied: 'Occupied', booked: 'Fully booked', soon: 'Coming soon' };
    const s0 = p.availability.status;
    details.push({ icon: 'check', label: 'Availability', val: statusMap[s0] || escHtml(s0) });
    if (p.availability.units != null) details.push({ icon: 'layers', label: 'Units left', val: p.availability.units + ' unit' + (p.availability.units === 1 ? '' : 's') });
  }

  const listing = [];
  if (pub) listing.push({ icon: 'calendar', label: 'Listed', val: escHtml(pub) });
  if (p.landlordPhone) listing.push({ icon: 'phone', label: 'Contact', val: escHtml(p.landlordPhone) });

  // Availability banner + free-text note
  const availHTML = pd2AvailHTML(p.availability, p.type);
  let noteHTML = '';
  if (p.availability && p.availability.note && !/^\d+$/.test(String(p.availability.note).trim())) {
    noteHTML = `<div class="pd2-note">${wi('pin','📌',14,'var(--teal)')} ${escHtml(p.availability.note)}</div>`;
  }

  // Waitlist
  let waitlistHTML = '';
  if (p.availability && p.availability.status === 'booked' && typeof AVAIL_TYPES !== 'undefined' && AVAIL_TYPES.includes(p.type)) {
    waitlistHTML = `<button class="pd2-waitlist" onclick="closePropDetail();openWaitlist('${escAttr(p.id)}')">📋 Join Waitlist — Get notified when available</button>`;
  }

  const badges = [{ icon: 'tag', text: isCom ? 'Commercial' : 'For Lease', cls: 'gold' }];
  if (p.type) badges.push({ text: ((TYPE_EMOJI && TYPE_EMOJI[p.type]) || '') + ' ' + p.type, cls: 'light' });

  pd2Render({
    priceHTML, priceSub: isCom && p.utilities ? 'Utilities: ' + escHtml(p.utilities) : '',
    title: p.title,
    location: escHtml([p.area, p.province].filter(Boolean).join(', ')),
    stats, availHTML, noteHTML, waitlistHTML, desc: p.desc,
    details, listing, badges,
    owner: { name: 'Verified Property Owner', sub: 'Contact via phone or email below' }
  });

  // ── Action buttons (fixed bottom) ──
  const hasDirs = !!(p.address || (p.lat != null && p.lng != null));
  const mapsUrl = hasDirs ? (typeof buildMapsUrl === 'function' ? buildMapsUrl(p.address, p.area, p.lat, p.lng) : '#') : '#';
  const dirBtn = hasDirs
    ? `<div class="pdm-dir-wrap">
         <div class="pdm-finger">👇</div>
         <a class="pd2-btn dir" href="${mapsUrl}" target="_blank" rel="noopener">${pd2Icon('nav')} Directions</a>
       </div>`
    : '';
  const contactBtn = `<button class="pd2-btn contact"
    onclick="closePropDetail();showContact('${escAttr(p.landlordName)}','${escAttr(p.landlordPhone)}','${escAttr(p.landlordEmail||'')}','${escAttr(p.title)}','${escAttr(p.address||'')}','${escAttr(p.area)}',${p.lat!=null?p.lat:'null'},${p.lng!=null?p.lng:'null'},'${escAttr(p.id)}')">
    ${pd2Icon('phone')} Contact
  </button>`;

  document.getElementById('pdm-actions').innerHTML = `${dirBtn}${contactBtn}`;

  // Render Lucide SVG icons inside the freshly-injected HTML
  wiRender();

  // Open overlay
  document.getElementById('prop-detail-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closePropDetail() {
  document.getElementById('prop-detail-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ── Expand / collapse the "About this property" description ──────────
function pdmToggleDesc(btn) {
  const el = document.getElementById('pdm-desc-text');
  if (!el) return;
  const expanded = el.classList.toggle('expanded');
  btn.innerHTML = expanded
    ? `Read less ${wi('chevron-up','⌃',13)}`
    : `Read more ${wi('chevron-down','⌄',13)}`;
  wiRender();
}

// ── Swipe-down-to-close on the property detail sheet ──────
// Mirrors the back/✕ buttons: a downward drag starting from the very top
// of the sheet's scroll position closes it, same as pressing back, and
// drops the user back on the listing grid (still scrolled where they left
// it) so they can keep browsing other properties. Only engages when the
// sheet itself is scrolled to top and the drag is mostly vertical, so it
// never fights with normal up/down scrolling through the listing content.
(function initPdmSwipeToClose() {
  const sheet = document.getElementById('prop-detail-sheet');
  if (!sheet) return;

  const DISMISS_PX = 110; // how far down before it counts as "close"
  let startY = 0, startX = 0, dy = 0, dragging = false;

  sheet.addEventListener('touchstart', e => {
    dragging = sheet.scrollTop <= 0;
    if (!dragging) return;
    startY = e.touches[0].clientY;
    startX = e.touches[0].clientX;
    dy = 0;
    sheet.style.transition = 'none';
  }, { passive: true });

  sheet.addEventListener('touchmove', e => {
    if (!dragging) return;
    const curY = e.touches[0].clientY;
    const curX = e.touches[0].clientX;
    dy = curY - startY;
    const dx = curX - startX;
    if (dy <= 0 || Math.abs(dx) > Math.abs(dy)) {
      // upward or mostly-horizontal movement — not a close gesture,
      // let the browser handle it (normal scroll / photo swipe)
      dy = 0;
      sheet.style.transform = '';
      return;
    }
    // Actively dragging the sheet down — take over the gesture so it
    // doesn't also trigger the browser's own pull-to-refresh/overscroll.
    e.preventDefault();
    sheet.style.transform = `translateY(${dy}px)`;
  }, { passive: false });

  sheet.addEventListener('touchend', () => {
    if (!dragging) return;
    dragging = false;
    sheet.style.transition = 'transform 0.25s ease';
    if (dy > DISMISS_PX) {
      sheet.style.transform = 'translateY(100%)';
      setTimeout(() => {
        closePropDetail();
        sheet.style.transition = '';
        sheet.style.transform = '';
      }, 200);
    } else {
      sheet.style.transform = '';
    }
    dy = 0;
  });

  sheet.addEventListener('touchcancel', () => {
    dragging = false;
    sheet.style.transition = 'transform 0.25s ease';
    sheet.style.transform = '';
    dy = 0;
  });
})();

// ── Sales property "View Full Details" — reuses the same modal shell as
// the rental property detail view (#prop-detail-overlay), just populated
// with sales-specific fields (price, type, address, seller contact).
function openSalesPropDetail(propId) {
  const p = getSalesProps().find(x => x.id === propId);
  if (!p) return;
  const imgs = getSalesPropImages(p.id);
  const emoji = TYPE_EMOJI[p.type] || '🏡';
  const fmtPrice = Number(p.price).toLocaleString();

  // ── Header title ──
  document.getElementById('pdm-header-title').textContent = p.title;

  // ── Photos ──
  const photoWrap = document.getElementById('pdm-photo-inner');
  const photoCount = document.getElementById('pdm-photo-count');
  const photoTap = document.getElementById('pdm-photo-tap');
  if (imgs.length > 0) {
    photoWrap.innerHTML = pdmGalleryHTML(imgs, p.title, `openLightbox(${JSON.stringify(imgs).replace(/"/g,'&quot;')},@I@,'${escAttr(p.title)}')`);
    if (imgs.length > 1) {
      photoCount.innerHTML = `📷 <span class="pdm-count-n">1 / ${imgs.length}</span>`;
      photoCount.style.display = '';
      photoTap.style.display = 'none';
    } else {
      photoCount.style.display = 'none';
      photoTap.style.display = 'none';
    }
  } else {
    photoWrap.innerHTML = `<span style="font-size:5rem;">${emoji}</span>`;
    photoCount.style.display = 'none';
    photoTap.style.display = 'none';
  }

  // ── Redesigned details (v2) ──
  const pub = formatPublishedDate(p.publishedAt || p.date);
  const stats = [];
  if (p.beds)  stats.push({ icon: 'bed',  value: escHtml(p.beds),  label: p.beds === '1' ? 'Bedroom' : 'Bedrooms' });
  if (p.baths) stats.push({ icon: 'bath', value: escHtml(p.baths), label: p.baths === '1' ? 'Bathroom' : 'Bathrooms' });
  if (p.floorArea) stats.push({ icon: 'area', value: Number(p.floorArea).toLocaleString(), label: 'sqm' });

  const locTxt = [p.province || '', (p.country && p.country !== 'Papua New Guinea') ? p.country : ''].filter(Boolean).join(', ');
  const details = [];
  details.push({ icon: 'home', label: 'Type', val: escHtml(p.type || 'Property') });
  if (p.condition) details.push({ icon: 'sparkles', label: 'Condition', val: escHtml(p.condition) });
  if (locTxt) details.push({ icon: 'pin', label: 'Location', wide: !p.address, val: escHtml(locTxt) });
  if (p.address) details.push({ icon: 'nav', label: 'Address', wide: true, val: escHtml(p.address) });

  const listing = [];
  if (pub) listing.push({ icon: 'calendar', label: 'Listed', val: escHtml(pub) });
  listing.push({ icon: 'user', label: 'Listed by', val: 'Seller' });
  if (p.phone) listing.push({ icon: 'phone', label: 'Contact', val: escHtml(p.phone) });

  pd2Render({
    priceHTML: escHtml(p.currency) + ' ' + fmtPrice,
    title: p.title,
    location: escHtml(p.address || locTxt),
    stats, desc: p.desc, details, listing,
    badges: [{ icon: 'tag', text: 'For Sale', cls: 'gold' }, { text: emoji + ' ' + (p.type || 'Property'), cls: 'light' }],
    owner: { name: 'Property Seller', sub: 'Contact the seller directly below' }
  });

  // ── Action buttons (fixed bottom) ──
  const hasDirs = !!(p.address || (p.lat != null && p.lng != null));
  const mapsUrl = hasDirs ? buildMapsUrl(p.address, p.province, p.lat, p.lng) : '#';
  const dirBtn = hasDirs
    ? `<a class="pd2-btn dir" href="${mapsUrl}" target="_blank" rel="noopener">${pd2Icon('nav')} Directions</a>`
    : '';
  const contactBtn = p.phone ? `<button class="pd2-btn contact"
    onclick="closePropDetail();trackSalesViews(['${escAttr(p.id)}']);showContact('Seller','${escAttr(p.phone)}','${escAttr(p.email||'')}','${escAttr(p.title)}','${escAttr(p.address||'')}','${escAttr(p.province||'')}',${p.lat != null ? p.lat : 'null'},${p.lng != null ? p.lng : 'null'},null)">
    ${pd2Icon('phone')} Contact
  </button>` : '';

  document.getElementById('pdm-actions').innerHTML = `${dirBtn}${contactBtn}`;

  wiRender();
  document.getElementById('prop-detail-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function pdmOverlayClick(e) {
  if (e.target === document.getElementById('prop-detail-overlay')) {
    closePropDetail();
  }
}

// ════════════════════════════════════════════════════════════════════
// WAMPAC LANDLORD ONBOARDING TOUR  v1.0
// Highlights key UI elements with a glowing spotlight + tooltip card.
// Automatically plays for brand-new landlords on first dashboard visit.
// Can be replayed anytime via the "🎓 Tour Guide" floating button.
// ════════════════════════════════════════════════════════════════════

const WT_KEY = 'wt_tour_seen_v1'; // _LS key

// ── Tour step definitions ────────────────────────────────────────────
// Each step: { targetFn, icon, title, desc, position }
// targetFn() returns the DOM element to spotlight (or null to skip).
// position: 'below' | 'above' — where the card appears relative to target.
function wtGetSteps() {
  return [
    {
      // Step 1 — My Dashboard button (nav)
      targetFn: () => { const b = document.getElementById('nav-btn-dashboard'); return (b && b.offsetParent !== null) ? b : null; },
      icon: '🏠',
      title: 'Home Screen ⇄ My Dashboard',
      desc: 'Tap here to visit the home screen and browse the app while staying logged in. On the home screen this same button becomes "My Dashboard" and brings you straight back to your listings, payments, and account overview.',
      position: 'below',
    },
    {
      // Step 2 — + List Property button (nav)
      targetFn: () => document.getElementById('nav-btn-list'),
      icon: '🏠',
      title: '+ List Property',
      desc: 'Tap here to post a new rental property. Fill in the details — location, price, photos — and submit for approval.',
      position: 'below',
    },
    {
      // Step 3 — + Add New Property (in My Listings header)
      targetFn: () => document.getElementById('dash-btn-add-property'),
      icon: '➕',
      title: '+ Add New Property',
      desc: 'Another quick way to add a listing — right from your listings section. Each property you post will appear here after approval.',
      position: 'below',
    },
    {
      // Step 4 — Live / Offline toggle (first listing card)
      // Targets the wrapper div we injected id="wt-target-golive" into
      targetFn: () => document.getElementById('wt-target-golive'),
      icon: '🟢',
      title: 'Live / Offline Switch',
      desc: 'This controls whether the public can see your listing right now. Turn it ON when vacant, and OFF the moment it\'s fully occupied — that\'s Wampac policy.',
      position: 'above',
    },
    {
      // Step 5 — Preview button (first listing card)
      targetFn: () => document.getElementById('wt-target-preview'),
      icon: '👁️',
      title: 'Preview',
      desc: 'See exactly how your listing looks to renters searching on Wampac. Use this to check everything looks great before going live.',
      position: 'above',
    },
    {
      // Step 6 — Location Set / Set Exact Location button
      targetFn: () => document.getElementById('wt-target-location'),
      icon: '📍',
      title: 'Set Exact Location',
      desc: 'Pin your property on a map so renters can see exactly where it is. A precise location gets 3× more enquiries than listings without one.',
      position: 'above',
    },
    {
      // Step 7 — Delete button
      targetFn: () => document.getElementById('wt-target-delete'),
      icon: '🗑️',
      title: 'Delete Listing',
      desc: 'Permanently removes this listing. Only do this if the property no longer exists — use the Live/Offline switch if it\'s just temporarily occupied.',
      position: 'above',
    },
    {
      // Step 8 — Update Status (availability pill, first listing card)
      targetFn: () => document.getElementById('wt-target-status'),
      icon: '✏️',
      title: 'Update Status',
      desc: 'Change the availability status of your listing — Available, Partially Available, or Fully Occupied — so renters always see accurate information.',
      position: 'above',
    },
  ];
}

// ── Core tour state ──────────────────────────────────────────────────
let _wtActive   = false;
let _wtStep     = 0;
let _wtSteps    = [];
let _wtResizeOb = null;
// When set, wtEnd() calls this instead of its normal dashboard-only
// cleanup (_LS flag, replay button, toast) — used by tours
// running inside a modal context, e.g. the location-pin button tour.
let _wtOnEndOverride = null;

// ── DOM helpers ──────────────────────────────────────────────────────
function _wtEl(id) { return document.getElementById(id); }

// ── Show 4-panel overlay + gold border ──────────────────────────────
function _wtShowOverlay(rect) {
  // rect = { top, left, width, height } — the spotlight hole
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const t  = rect.top;
  const l  = rect.left;
  const w  = rect.width;
  const h  = rect.height;

  function css(el, styles) { Object.assign(el.style, styles); }

  const pTop    = document.getElementById('wt-panel-top');
  const pBottom = document.getElementById('wt-panel-bottom');
  const pLeft   = document.getElementById('wt-panel-left');
  const pRight  = document.getElementById('wt-panel-right');
  const sp      = document.getElementById('wt-spotlight');

  // Top panel: full width, from top to spotlight top
  css(pTop,    { display:'block', top:'0',         left:'0',           width:vw+'px',     height: Math.max(0,t)+'px' });
  // Bottom panel: full width, from spotlight bottom to page bottom
  css(pBottom, { display:'block', top:(t+h)+'px',  left:'0',           width:vw+'px',     height: Math.max(0, vh - t - h)+'px' });
  // Left panel: between top and bottom panels, left of spotlight
  css(pLeft,   { display:'block', top: t+'px',     left:'0',           width: Math.max(0,l)+'px', height: h+'px' });
  // Right panel: between top and bottom panels, right of spotlight
  css(pRight,  { display:'block', top: t+'px',     left:(l+w)+'px',    width: Math.max(0, vw - l - w)+'px', height: h+'px' });

  // Gold border ring exactly over the hole
  css(sp, { display:'block', top:t+'px', left:l+'px', width:w+'px', height:h+'px' });
}

function _wtHideOverlay() {
  ['wt-panel-top','wt-panel-bottom','wt-panel-left','wt-panel-right','wt-spotlight'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
}

// ── Compute spotlight rect with padding ─────────────────────────────
function _wtRectFor(el, pad = 8) {
  const r = el.getBoundingClientRect();
  return {
    top:    r.top    - pad,
    left:   r.left   - pad,
    width:  r.width  + pad * 2,
    height: r.height + pad * 2,
    bottom: r.bottom + pad,
    right:  r.right  + pad,
  };
}

// ── Position the spotlight ring (kept for compat, now calls _wtShowOverlay) ──
function _wtPositionSpotlight(el) {
  _wtShowOverlay(_wtRectFor(el, 9));
}

// ── Position the tooltip card ────────────────────────────────────────
function _wtPositionCard(el, position) {
  const card    = _wtEl('wt-card');
  const r       = _wtRectFor(el, 9);
  const vw      = window.innerWidth;
  const vh      = window.innerHeight;
  const cW      = Math.min(340, vw - 32);
  const MARGIN  = 12;
  const CARD_H  = card.offsetHeight || 220;
  const ARROW_H = 18;

  card.className = ''; // reset arrow classes
  card.style.width = cW + 'px';

  // ── Determine vertical placement (above or below) ──
  let top;
  let arrowClass;

  if (position === 'below') {
    const belowTop = r.bottom + ARROW_H;
    if (belowTop + CARD_H <= vh - MARGIN) {
      top = belowTop;
      arrowClass = 'arrow-top';
    } else {
      top = r.top - ARROW_H - CARD_H;
      arrowClass = 'arrow-bottom';
    }
  } else {
    const aboveTop = r.top - ARROW_H - CARD_H;
    if (aboveTop >= MARGIN) {
      top = aboveTop;
      arrowClass = 'arrow-bottom';
    } else {
      top = r.bottom + ARROW_H;
      arrowClass = 'arrow-top';
    }
  }

  // Final vertical clamp
  if (top < MARGIN) top = MARGIN;
  if (top + CARD_H > vh - MARGIN) top = vh - MARGIN - CARD_H;

  card.classList.add(arrowClass);

  // ── Horizontal: center card on the spotlight element, clamp to viewport ──
  const elCenterX  = r.left + r.width / 2;
  let left = elCenterX - cW / 2;
  if (left + cW > vw - MARGIN) left = vw - MARGIN - cW;
  if (left < MARGIN) left = MARGIN;

  card.style.left = left + 'px';
  card.style.top  = top  + 'px';

  // ── Point the arrow at the spotlight centre horizontally ──
  // arrow-top/bottom is a ::before pseudo; we override left via CSS variable
  const arrowOffset = Math.round(elCenterX - left - 10); // 10 = half border width
  const clampedArrow = Math.max(16, Math.min(cW - 36, arrowOffset));
  card.style.setProperty('--wt-arrow-left', clampedArrow + 'px');
}

// ── Find nearest scrollable ancestor (excluding window) ──────────────
function _wtScrollParent(el) {
  let node = el.parentElement;
  while (node && node !== document.body) {
    const { overflowY } = window.getComputedStyle(node);
    if (overflowY === 'auto' || overflowY === 'scroll') return node;
    node = node.parentElement;
  }
  return null;
}

// ── Scroll element into view, returns a Promise that resolves after scroll settles ──
function _wtScrollToEl(el) {
  return new Promise(resolve => {
    const r  = el.getBoundingClientRect();
    const vh = window.innerHeight;

    // First: scroll the modal/container if element is inside one
    const scrollParent = _wtScrollParent(el);
    if (scrollParent) {
      const pr = scrollParent.getBoundingClientRect();
      const elTop    = r.top - pr.top + scrollParent.scrollTop;
      const targetContainerY = Math.max(0, elTop - 80); // 80px padding from top
      scrollParent.scrollTo({ top: targetContainerY, behavior: 'smooth' });
    }

    // Then: scroll the window if element is outside viewport
    const needsWindowScroll = r.top < 100 || r.bottom > vh - 300;
    if (!needsWindowScroll) {
      // Just wait for possible container scroll to settle
      setTimeout(resolve, scrollParent ? 350 : 0);
      return;
    }

    const targetY = Math.max(0, window.scrollY + r.top - Math.max(90, vh * 0.18));

    // Use onscrollend if available (Chrome 109+, Firefox 109+)
    if ('onscrollend' in window) {
      const onDone = () => { window.removeEventListener('scrollend', onDone); resolve(); };
      window.addEventListener('scrollend', onDone, { once: true });
      window.scrollTo({ top: targetY, behavior: 'smooth' });
      setTimeout(resolve, 700); // safety timeout
    } else {
      window.scrollTo({ top: targetY, behavior: 'smooth' });
      let lastY = -1, tries = 0;
      const poll = setInterval(() => {
        if (Math.abs(window.scrollY - lastY) < 1 || tries++ > 30) {
          clearInterval(poll);
          resolve();
        }
        lastY = window.scrollY;
      }, 30);
    }
  });
}

// ── Render dots ──────────────────────────────────────────────────────
function _wtRenderDots() {
  const dots = _wtEl('wt-dots');
  dots.innerHTML = _wtSteps.map((_, i) =>
    `<div class="wt-dot ${i < _wtStep ? 'done' : i === _wtStep ? 'active' : ''}"></div>`
  ).join('');
}

// ── Show a specific step ─────────────────────────────────────────────
async function _wtShowStep(idx) {
  if (idx >= _wtSteps.length) { wtEnd(); return; }

  const step = _wtSteps[idx];
  const el   = step.targetFn ? step.targetFn() : null;

  // Skip steps with no visible target
  if (!el) {
    _wtStep++;
    _wtShowStep(_wtStep);
    return;
  }

  _wtStep = idx;

  // Hide card while scrolling so it doesn't drift visibly
  const card = _wtEl('wt-card');
  card.style.display = 'none';

  // Wait for scroll to fully settle before measuring
  await _wtScrollToEl(el);

  // Extra rAF to let layout stabilise after scroll
  await new Promise(r => requestAnimationFrame(r));

  // Re-fetch element after scroll (in case it's inside a sticky/fixed container)
  const elFresh = step.targetFn ? step.targetFn() : el;
  if (!elFresh) { _wtStep++; _wtShowStep(_wtStep); return; }

  // Show 4-panel overlay + gold spotlight (uses current, accurate rect)
  _wtPositionSpotlight(elFresh);

  // Populate content
  // Map step icons to lucide names for desktop
  const _wtIconMap = {
    '📊':'bar-chart-2','🏠':'home','➕':'plus-circle','🟢':'circle-dot',
    '👁️':'eye','📍':'map-pin','🗑️':'trash-2','✏️':'pencil',
    '💬':'message-circle','🔑':'key-round','📝':'file-text','📋':'clipboard-list',
    '🎉':'party-popper','🚀':'rocket','⚙️':'settings','🌍':'globe',
  };
  const _lucideName = _wtIconMap[step.icon] || 'circle';
  _wtEl('wt-icon').innerHTML = wi(_lucideName, step.icon, 26);
  _wtEl('wt-title').textContent = step.title;
  // Support \n line breaks in desc — escape HTML then swap \n for <br>
  _wtEl('wt-desc').innerHTML = step.desc
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\n/g,'<br>');
  _wtEl('wt-step-label').textContent = `Step ${idx + 1} of ${_wtSteps.length}`;

  const isLast = idx === _wtSteps.length - 1;
  const btn    = _wtEl('wt-btn-next');
  btn.innerHTML = isLast ? `${wi('party-popper','🎉',15)} Done!` : 'Got it →';
  btn.className   = 'wt-btn-next' + (isLast ? ' finish' : '');
  wiRender();

  _wtRenderDots();

  // Force reflow so entrance animation re-triggers
  void card.offsetWidth;
  card.style.display = 'block';

  // Position card after content has been painted (so offsetHeight is accurate)
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      _wtPositionCard(elFresh, step.position || 'below');
    });
  });
}

// ── Advance to next step ─────────────────────────────────────────────
function wtNext() {
  _wtStep++;
  _wtShowStep(_wtStep);
}

// ── Skip / close tour ────────────────────────────────────────────────
function wtSkip() { wtEnd(); }

// ── End tour ─────────────────────────────────────────────────────────
function wtEnd() {
  _wtActive = false;
  _wtHideOverlay();
  const card = _wtEl('wt-card');
  if (card) card.style.display = 'none';

  if (_wtResizeOb) { _wtResizeOb.disconnect(); _wtResizeOb = null; }
  window.removeEventListener('resize', _wtOnResize);

  // A tour running inside a modal context (e.g. the location-pin button
  // tour) hands its own cleanup callback here instead of the dashboard
  // side-effects below — it has nothing to do with the landlord onboarding
  // flag, replay button, or toast.
  if (_wtOnEndOverride) {
    const cb = _wtOnEndOverride;
    _wtOnEndOverride = null;
    cb();
    return;
  }

  // Mark as seen (per-user key so each new landlord gets their first-time tour)
  try { _LS.setItem(_wtUserKey ? _wtUserKey() : WT_KEY, '1'); } catch(e) {}

  // Show replay button if still on dashboard
  const dash = document.getElementById('page-dashboard');
  if (dash && dash.classList.contains('active')) {
    const rb = _wtEl('wt-replay-btn');
    if (rb) { rb.style.display = 'flex'; }
  }

  showToast('Tour complete! Tap 🎓 Tour Guide anytime to replay.', 'success');
}

// ── Start tour ───────────────────────────────────────────────────────
function wtStart(manual = false) {
  // Only run for landlords on the dashboard
  const dash = document.getElementById('page-dashboard');
  if (!dash || !dash.classList.contains('active')) return;
  if (!currentUser) return;

  // Hide replay button while running
  const rb = _wtEl('wt-replay-btn');
  if (rb) rb.style.display = 'none';

  _wtActive = true;
  _wtStep   = 0;
  _wtSteps  = wtGetSteps();

  // Re-position spotlight on resize / scroll
  if (_wtResizeOb) _wtResizeOb.disconnect();
  _wtResizeOb = new ResizeObserver(() => {
    if (!_wtActive) return;
    requestAnimationFrame(() => { _wtRepositionCurrent(); });
  });
  _wtResizeOb.observe(document.body);

  window.addEventListener('resize', _wtOnResize);

  _wtShowStep(0);
}

function _wtRepositionCurrent() {
  const step = _wtSteps[_wtStep];
  if (!step) return;
  const el = step.targetFn ? step.targetFn() : null;
  if (el) {
    _wtPositionSpotlight(el);
    // Use double-rAF so card offsetHeight is current
    requestAnimationFrame(() => {
      _wtPositionCard(el, step.position || 'below');
    });
  }
}

function _wtOnResize() {
  if (!_wtActive) return;
  _wtRepositionCurrent();
}

// ════════════════════════════════════════════════════════════════════
// DESCRIPTION FIELD MINI-TOUR
// Fires once when the landlord taps the Description textarea.
// Shows a single focused tip with a real example of a great description.
// ════════════════════════════════════════════════════════════════════
const WT_POST_KEY = 'wt_post_tour_seen_v3';

// Per-modal-session flag — resets to false each time the post modal opens
let _wtDescTourShown = false;

function wtMaybeStartDescTour() {
  // Fire once per modal session (resets to false each time post modal opens)
  if (_wtDescTourShown) return;
  _wtDescTourShown = true;

  const el = document.getElementById('post-desc');
  if (!el) return;

  // Use the shared wt-card UI with a single step
  _wtSteps = [
    {
      targetFn: () => {
        const d = document.getElementById('post-desc');
        if (d) d.scrollIntoView({ behavior: 'smooth', block: 'center' });
        return d;
      },
      icon: '📝',
      title: 'Write a Great Description',
      desc: `This is your best chance to convince renters to choose your property. Here's a real example:\n\n📍 Kennedy Estate | K5,650/Month\n3-Bedroom Apartment (Ensuite)\n✅ 2x Toilets & Bathrooms\n✅ Newly built with all new white & brown goods\n✅ Aircon & ceiling fans installed\n✅ Enclosed laundry with washing machine\n✅ Spacious living area & verandah\n✅ Standby power & water backup\n✅ Ample parking & 24/7 security\n\nCover: size, amenities, security, power/water backup, transport access, and anything that makes yours special.`,
      position: 'above',
    }
  ];
  _wtStep   = 0;
  _wtActive = true;

  // Small delay so the keyboard doesn't fight the scroll
  setTimeout(() => {
    _wtShowStep(0);
  }, 350);
}

// Legacy stubs — kept so any old call sites don't throw
function wtStartPostTour() { wtMaybeStartDescTour(); }
function wtMaybeStartPostTour() { /* no-op — desc tour now fires on field focus */ }

// ── Auto-start for new landlords ─────────────────────────────────────
// Called from renderDashboard() ONLY when myProps.length > 0 (listing cards in DOM).
// Uses a per-user _LS key so every new landlord gets their own first-time tour.
function _wtUserKey() {
  // Derive a stable per-user key from their ID (falls back to WT_KEY for legacy)
  return currentUser && currentUser.id ? 'wt_tour_seen_' + currentUser.id : WT_KEY;
}

function wtMaybeAutoStart() {
  if (!currentUser) return;
  // Confirm we're on dashboard and listing cards actually exist
  const dash = document.getElementById('page-dashboard');
  if (!dash || !dash.classList.contains('active')) return;
  const hasCards = !!document.getElementById('wt-target-preview');
  if (!hasCards) return; // tour targets aren't in DOM yet — skip silently

  const key = _wtUserKey();
  try {
    const seen = _LS.getItem(key);
    if (seen) {
      // Already completed tour — show replay button only
      const rb = _wtEl('wt-replay-btn');
      if (rb) rb.style.display = 'flex';
      return;
    }
  } catch(e) {}

  // Brand-new landlord with at least one listing — auto-play the tour
  setTimeout(() => wtStart(false), 300);
}

// ── Hide replay button when navigating away from dashboard ───────────
(function _wtPageObserver() {
  const origShowPage = window.showPage;
  window.showPage = function(id) {
    origShowPage.apply(this, arguments);
    const rb = _wtEl('wt-replay-btn');
    if (!rb) return;
    if (id === 'dashboard') {
      // Only show replay button if this landlord has already completed the tour
      try {
        const key = _wtUserKey ? _wtUserKey() : WT_KEY;
        if (_LS.getItem(key)) rb.style.display = 'flex';
      } catch(e) {}
    } else {
      rb.style.display = 'none';
      // If tour is running and user navigates away, end it
      if (_wtActive) wtEnd();
    }
  };
})();
